# Client-side (browser) error tracking. Loaded async, only when a browser DSN is
# configured (SENTRY_JS_DSN — a separate public DSN from the server one). Empty
# string → injected nowhere, zero effect.
_sentry_js_dsn = os.environ.get("SENTRY_JS_DSN", "")
_SENTRY_JS_SNIPPET = ""
if _sentry_js_dsn:
    # Load Sentry off the critical path (at idle / after load) so its bundle
    # doesn't add to mobile Total Blocking Time during initial render. Runtime
    # errors after load are still captured; only the brief pre-idle window isn't.
    _SENTRY_JS_SNIPPET = (
        '<script>(function(){var done=false;function load(){if(done)return;done=true;'
        'var s=document.createElement("script");s.async=true;'
        's.src="https://browser.sentry-cdn.com/7.120.0/bundle.min.js";s.crossOrigin="anonymous";'
        's.onload=function(){try{window.Sentry&&Sentry.init({dsn:'
        + json.dumps(_sentry_js_dsn) +
        ',sampleRate:1.0});}catch(e){}};document.head.appendChild(s);}'
        'if("requestIdleCallback"in window){requestIdleCallback(load,{timeout:5000});}'
        'else{window.addEventListener("load",function(){setTimeout(load,2000);});}})();</script>'
    )

# Plotly is ~1 MB and was loaded on every page even without a chart. Define a
# global window.ensurePlotly() that injects it on demand (once, cached) and
# resolves when ready; chart code awaits it instead of relying on a global load.
_PLOTLY_LOADER = (
    '<script>window.ensurePlotly=function(){'
    'if(window._plotlyPromise)return window._plotlyPromise;'
    'window._plotlyPromise=new Promise(function(res,rej){'
    'if(window.Plotly){res(window.Plotly);return;}'
    'var s=document.createElement("script");'
    's.src="https://cdn.jsdelivr.net/npm/plotly.js-dist-min@2.35.2/plotly.min.js";'
    's.onload=function(){res(window.Plotly);};'
    's.onerror=function(){window._plotlyPromise=null;rej(new Error("plotly load failed"));};'
    'document.head.appendChild(s);});return window._plotlyPromise;};</script>'
)

DASHBOARD_CACHE = {}
# Bound the per-league cache. Each entry holds a full league context plus
# rendered page HTML, and on the public site any visitor can look up any league,
# so without eviction this dict grows without limit (a slow OOM on a
# long-running worker). Cap the entry count and evict the oldest ~10% when
# exceeded — the same bounded pattern used by _GAME_LOGS_CACHE below.
DASHBOARD_CACHE_MAX = 400


def _prune_dashboard_cache(keep: Optional[str] = None) -> None:
    """Evict the oldest ~10% of DASHBOARD_CACHE entries once it exceeds
    DASHBOARD_CACHE_MAX. Called on every entry-creation path so total memory
    stays bounded regardless of how many distinct leagues get looked up. ``keep``
    is the key about to be written; it is never evicted, so a caller updating a
    hot entry can't lose the ctx it's building on."""
    if len(DASHBOARD_CACHE) < DASHBOARD_CACHE_MAX:
        return

    def _age(k):
        e = DASHBOARD_CACHE.get(k) or {}
        ts = e.get("ts")
        if ts is not None:
            return ts
        # Entries created only via the page_html/awards setdefault paths carry
        # their timestamps one level down; use the most recent as the age.
        cand = [r[0] for r in (e.get("page_html") or {}).values() if isinstance(r, tuple)]
        aw = e.get("awards_agg")
        if isinstance(aw, tuple):
            cand.append(aw[0])
        return max(cand) if cand else 0.0

    candidates = [k for k in DASHBOARD_CACHE if k != keep]
    for k in sorted(candidates, key=_age)[:max(1, DASHBOARD_CACHE_MAX // 10)]:
        DASHBOARD_CACHE.pop(k, None)


def _prune_ttl_cache(cache: dict, max_entries: int) -> None:
    """Evict the oldest ~10% of a per-league/per-roster TTL cache once it exceeds
    ``max_entries``. These caches key on ids from an effectively unbounded space
    (any league/roster a visitor looks up), so a TTL alone doesn't cap memory —
    stale entries linger until their exact key is requested again. Handles both
    entry shapes used here: ``{'ts': float, ...}`` dicts and ``(ts, payload)``
    tuples."""
    if len(cache) < max_entries:
        return

    def _age(k):
        e = cache.get(k)
        if isinstance(e, dict):
            return e.get("ts", 0.0)
        if isinstance(e, tuple) and e and isinstance(e[0], (int, float)):
            return e[0]
        return 0.0

    for k in sorted(list(cache), key=_age)[:max(1, max_entries // 10)]:
        cache.pop(k, None)


# Per-key locks prevent simultaneous first-loads for the same league from both
# running the full build_league_context (~40 API calls) at the same time.
_CTX_LOCKS: dict = {}
_CTX_LOCKS_LOCK = threading.Lock()
# Short-lived cache for /api/league-rosters responses (pick-slot resolution is expensive).
_ROSTER_API_CACHE: dict = {}
_ROSTER_API_CACHE_TTL = 180  # seconds
_ROSTER_API_CACHE_MAX = 300  # entries; oldest ~10% evicted when exceeded

# Cache for Monte Carlo playoff simulation results (keyed by platform/league_id/season).
_PLAYOFF_SIM_CACHE: dict = {}
_PLAYOFF_SIM_CACHE_TTL = 3600  # 1 hour
_PLAYOFF_SIM_CACHE_MAX = 200  # entries; oldest ~10% evicted when exceeded


_PLAYOFF_SIM_BUILDING: set = set()
_PLAYOFF_SIM_BUILDING_LOCK = threading.Lock()


def _playoff_sim_cached(ctx: dict, platform: str, block: bool = True) -> list:
    """simulate_playoff_odds behind the module TTL cache (shared by the odds
    API, standings seeding, the trade-window card, and draft capital).

    block=False serves only a warm cache: on a miss it kicks the sim off in a
    background thread and returns [] immediately. Synchronous render paths
    (e.g. the dashboard's trade-window card) use that so a cold sim — several
    projection fetches plus a Monte Carlo run — never blocks a page paint;
    the surface simply appears on the next visit."""
    try:
        from data_building.simulate_playoff_odds import simulate_playoff_odds
        key = (
            platform,
            str(ctx.get("league_id") or ""),
            int(ctx.get("season") or ctx.get("current_season") or 0),
        )
        hit = _PLAYOFF_SIM_CACHE.get(key)
        if hit and time.time() - hit["ts"] < _PLAYOFF_SIM_CACHE_TTL:
            return hit["data"] or []

        def _run(snapshot=dict(ctx)):
            try:
                odds = simulate_playoff_odds(snapshot, platform=platform) or []
                _prune_ttl_cache(_PLAYOFF_SIM_CACHE, _PLAYOFF_SIM_CACHE_MAX)
                _PLAYOFF_SIM_CACHE[key] = {"data": odds, "ts": time.time()}
            except Exception:
                logger.debug("background playoff sim failed", exc_info=True)
            finally:
                with _PLAYOFF_SIM_BUILDING_LOCK:
                    _PLAYOFF_SIM_BUILDING.discard(key)

        if not block:
            with _PLAYOFF_SIM_BUILDING_LOCK:
                if key in _PLAYOFF_SIM_BUILDING:
                    return []
                _PLAYOFF_SIM_BUILDING.add(key)
            threading.Thread(target=_run, daemon=True).start()
            return []

        odds = simulate_playoff_odds(ctx, platform=platform) or []
        _prune_ttl_cache(_PLAYOFF_SIM_CACHE, _PLAYOFF_SIM_CACHE_MAX)
        _PLAYOFF_SIM_CACHE[key] = {"data": odds, "ts": time.time()}
        return odds
    except Exception:
        logger.debug("playoff sim failed", exc_info=True)
        return []

