# When this worker booted — a cheap "did the deploy actually restart me?" signal
# alongside the bundle hashes in /healthz/version.
_PROCESS_STARTED_AT = datetime.now(timezone.utc).isoformat()


@app.route("/healthz/version")
def healthz_version():
    """Deploy smoke-check: the content hashes of the bundles this process is
    actually serving, plus the git SHA when available. After a deploy, hit this
    and confirm the hashes changed / match the built files — so "is it live yet?"
    is a one-request answer instead of guessing at a stale cache. Cache-busting
    headers so an intermediary can never hand back a previous deploy's answer."""
    resp = jsonify({
        "app_js":       _APP_JS_V,
        "public_js":    _PUBLIC_JS_V,
        "rankings_js":  _RANKINGS_JS_V,
        "teams_js":     _TEAMS_JS_V,
        "redzone_js":   _REDZONE_JS_V,
        "css":          _CSS_V,
        "git_sha":      os.environ.get("RENDER_GIT_COMMIT") or os.environ.get("GIT_SHA") or "",
        "started_at":   _PROCESS_STARTED_AT,
    })
    resp.headers["Cache-Control"] = "no-store, max-age=0"
    return resp


@app.before_request
def _perf_start():
    # Cheap monotonic stamp; read back in _perf_record to time the request.
    g._perf_t0 = time.perf_counter()


@app.after_request
def _perf_record(response):
    """Fold each non-static request into the per-endpoint timing monitor, and
    log a one-line warning for anything slow so it also shows up in the error
    monitor and prod logs."""
    try:
        t0 = getattr(g, "_perf_t0", None)
        if t0 is not None and not request.path.startswith("/static/"):
            dur_ms = (time.perf_counter() - t0) * 1000.0
            from utils import perf_monitor
            perf_monitor.record(
                request.endpoint or request.path, request.method, dur_ms, response.status_code
            )
            if dur_ms >= perf_monitor.SLOW_MS:
                logger.warning(
                    "[slow] %s %s %.0fms status=%s",
                    request.method, request.path, dur_ms, response.status_code,
                )
    except Exception:
        logger.debug("perf record failed", exc_info=True)
    return response


@app.after_request
def _add_cache_headers(response):
    path = request.path
    if path.startswith("/static/"):
        # Versioned assets (e.g. ?v=123) can be cached aggressively; others
        # (logos, icons, fonts, manifest) rarely change, so a week beats 1 day
        # and satisfies the "efficient cache lifetimes" audit without versioning
        # every URL. Cloudflare honours this at the edge too.
        if request.args.get("v"):
            response.headers["Cache-Control"] = "public, max-age=31536000, immutable"
        else:
            response.headers["Cache-Control"] = "public, max-age=604800"
    return response


# ── Content-Security-Policy & security headers ──────────────────────────────
# The app serves large inline HTML with inline <script>, inline <style>, and
# ~140 inline on* event handlers. Nonces/hashes can't cover event-handler
# attributes, and a browser ignores 'unsafe-inline' the moment a nonce/hash is
# present, so script-src/style-src keep 'unsafe-inline'. The value we still buy
# is real: injecting <script src="evil.com">, <base>, <object>, plugin content,
# clickjacking frames, or hijacked form targets is all blocked, and the script
# origin allowlist is pinned to the CDNs we actually use.
#
# img-src uses https: (not an allowlist): ads and logos legitimately load from
# many Google/CDN image hosts, images can't execute, so a scheme allow is the
# pragmatic, non-breaking choice.
_CSP_POLICY = "; ".join([
    "default-src 'self'",
    # Google AdSense chain + Plotly (jsDelivr) + Sentry browser bundle.
    "script-src 'self' 'unsafe-inline' "
    "https://pagead2.googlesyndication.com https://*.googlesyndication.com "
    "https://*.googleadservices.com https://*.google.com https://*.gstatic.com "
    "https://*.doubleclick.net https://cdn.jsdelivr.net "
    "https://browser.sentry-cdn.com",
    "style-src 'self' 'unsafe-inline'",
    "img-src 'self' data: blob: https:",
    "font-src 'self' data:",
    # XHR/fetch/beacon: Sentry ingest + the ad chain's reporting endpoints.
    "connect-src 'self' https://*.sentry.io https://*.google.com "
    "https://*.googlesyndication.com https://*.doubleclick.net "
    "https://pagead2.googlesyndication.com https://cdn.jsdelivr.net",
    # Ads render inside iframes served from the Google ad hosts.
    "frame-src https://*.googlesyndication.com https://*.doubleclick.net "
    "https://*.google.com",
    "object-src 'none'",
    "base-uri 'self'",
    "form-action 'self'",
    "frame-ancestors 'self'",
    "upgrade-insecure-requests",
])

# Set CSP_REPORT_ONLY=1 in the environment to emit the same policy as
# Content-Security-Policy-Report-Only (observe violations in the console/Sentry
# without blocking) — useful to validate the allowlist before enforcing.
_CSP_HEADER_NAME = (
    "Content-Security-Policy-Report-Only"
    if os.environ.get("CSP_REPORT_ONLY", "").strip() in ("1", "true", "yes")
    else "Content-Security-Policy"
)

# HSTS: the app is HTTPS-only behind Render/Cloudflare. No includeSubDomains
# (avoids committing subdomains that may not be HTTPS) and no preload (a one-way
# door). 1 year satisfies the audit.
_STATIC_SECURITY_HEADERS = {
    "X-Content-Type-Options": "nosniff",
    "X-Frame-Options": "SAMEORIGIN",
    "Referrer-Policy": "strict-origin-when-cross-origin",
    "Permissions-Policy": "camera=(), microphone=(), geolocation=(), "
                          "browsing-topics=()",
    "Strict-Transport-Security": "max-age=31536000",
}


@app.after_request
def _add_security_headers(response):
    """Attach CSP + hardening headers to every response. Uses setdefault so any
    endpoint that intentionally set its own value (e.g. a stricter one) wins."""
    for name, value in _STATIC_SECURITY_HEADERS.items():
        response.headers.setdefault(name, value)
    # Don't clobber an endpoint-specific CSP if one was set deliberately.
    if _CSP_HEADER_NAME not in response.headers:
        response.headers[_CSP_HEADER_NAME] = _CSP_POLICY
    return response


@app.before_request
def _canonical_host_redirect():
    """301 the *.onrender.com URL to PRIMARY_DOMAIN.

    Dormant unless PRIMARY_DOMAIN is set. Only safe (GET/HEAD) requests are
    redirected so POST webhooks (Stripe, etc.) are never broken.

    NOTE: this deliberately does NOT touch the www. variant. Render performs the
    www<->apex redirect itself; if the app also redirected www->apex while Render
    redirected apex->www, the two would bounce forever (ERR_TOO_MANY_REDIRECTS).
    The www<->apex direction is owned entirely by Render's primary-domain setting.
    """
    if not PRIMARY_DOMAIN:
        return
    if request.method not in ("GET", "HEAD"):
        return
    # Never redirect the health-check endpoint — Render probes it on the
    # onrender.com host and treats a 301 as an unhealthy response.
    if request.path == "/health":
        return
    host = (request.host or "").split(":")[0].lower()
    # Only canonicalize the Render URL. Leave both apex and www to Render.
    if not host.endswith(".onrender.com"):
        return
    qs = request.query_string.decode("utf-8", "ignore")
    target = f"https://{PRIMARY_DOMAIN}{request.path}" + (f"?{qs}" if qs else "")
    return redirect(target, code=301)


# Canonical host for SEO. When set (e.g. "brfantasyfootball.com"), all traffic on
# other hosts (the *.onrender.com URL, the www. variant) is 301-redirected here and
# canonical tags point here. Left unset, the site behaves exactly as before.
PRIMARY_DOMAIN = os.environ.get("PRIMARY_DOMAIN", "").strip().lower()
if PRIMARY_DOMAIN.startswith("www."):
    PRIMARY_DOMAIN = PRIMARY_DOMAIN[4:]

_secret_key = os.environ.get('FLASK_SECRET_KEY', '')
_is_production = os.environ.get('PYTHON_ENV', '').strip().lower() == 'production'
if not _secret_key:
    if _is_production:
        # Fail closed: a known/default secret key lets anyone forge session
        # cookies (and thus any viewer identity + premium access).
        raise RuntimeError(
            "FLASK_SECRET_KEY is not set. Refusing to start in production with an "
            "insecure default key - set FLASK_SECRET_KEY in the environment."
        )
    logging.warning(
        "FLASK_SECRET_KEY is not set - using insecure development default. "
        "The app will refuse to start without it when PYTHON_ENV=production."
    )
    _secret_key = 'dev-secret-key-change-in-production'
app.secret_key = _secret_key
del _secret_key

# Harden session cookies. SECURE is enabled only in production so local HTTP
# development still works.
app.config.update(
    SESSION_COOKIE_HTTPONLY=True,
    SESSION_COOKIE_SAMESITE="Lax",
    SESSION_COOKIE_SECURE=_is_production,
    PERMANENT_SESSION_LIFETIME=timedelta(days=30),
)

# ── Rate limiting ─────────────────────────────────────────────────────────────
# The limiter itself lives in extensions.py (unbound) so route blueprints can
# import and use @limiter.limit without importing app.py; bind it here.
from extensions import limiter, LIMITER_BACKEND  # noqa: E402
limiter.init_app(app)
if LIMITER_BACKEND:
    logger.info("[limiter] Flask-Limiter enabled (%s backend)", LIMITER_BACKEND)
else:
    logger.warning("[limiter] Flask-Limiter not installed - rate limiting disabled")

# Response compression
if Compress is not None:
    _compress = Compress()
    app.config["COMPRESS_MIN_SIZE"] = 500          # only compress responses > 500 bytes
    app.config["COMPRESS_LEVEL"] = 6                # gzip level (1-9); 6 is a good balance
    app.config["COMPRESS_ALGORITHM"] = ["br", "gzip"]  # prefer brotli, fall back to gzip
    # Brotli quality (0-11). Requires the `brotli` package (in requirements.txt);
    # without it flask-compress silently serves gzip only. 6 is the balance point:
    # ~12% smaller JS/CSS and ~5% smaller HTML than gzip-6, ~4ms for a typical HTML
    # page. Higher levels (9-11) are far slower (q11 ≈ 1.7s on app.js) and only pay
    # off for large immutable statics, which are CDN/edge-cached after the first hit.
    app.config["COMPRESS_BR_LEVEL"] = 6
    _compress.init_app(app)

