def save_viewer_session(viewer: dict) -> None:
    session.permanent = True  # persist across browser restarts / notification taps (30-day lifetime)
    session["viewer_username"] = viewer.get("viewer_username")
    session["viewer_user_id"] = viewer.get("viewer_user_id")
    session["viewer_roster_id"] = viewer.get("viewer_roster_id")
    session["viewer_team_name"] = viewer.get("viewer_team_name")


_SEED_SEMAPHORE = threading.Semaphore(1)


def _background_seed_user(user_id: str, username: Optional[str]) -> None:
    """Fire-and-forget: record login and seed dynasty leagues for a Sleeper user."""
    from data_building.trade_intel.league_discovery import _save_users as _tiu_save_users
    try:
        _tiu_save_users([user_id], source="login", usernames={user_id: username} if username else None)
    except Exception:
        logger.warning("login: failed to save user to TIU index", exc_info=True)

    def _run():
        if not _SEED_SEMAPHORE.acquire(blocking=False):
            return  # another seed already running; skip rather than pile up
        try:
            _seed_user_leagues(user_id, username=username)
        except Exception:
            logger.warning("login: failed to seed user leagues", exc_info=True)
        finally:
            _SEED_SEMAPHORE.release()
    threading.Thread(target=_run, daemon=True).start()


def get_viewer_session_for_league(users: List[Dict], rosters: List[Dict]) -> dict:
    """Get viewer session resolved for the current league instead of stale session data."""
    session_viewer = get_viewer_session()
    username = session_viewer.get("viewer_username")

    if not username:
        return session_viewer

    # Pass user_id so resolution prefers the unambiguous numeric ID match
    stored_user_id = session_viewer.get("viewer_user_id")
    league_viewer = resolve_viewer_for_league(users, rosters, username, user_id=stored_user_id)

    if league_viewer:
        save_viewer_session(league_viewer)
        return league_viewer
    else:
        logger.info(f"[get_viewer_session_for_league] Could not resolve {username} in current league, returning session data")
        return session_viewer


def get_viewer_session() -> dict:
    try:
        viewer_data = {
            "viewer_username": session.get("viewer_username"),
            "viewer_user_id": session.get("viewer_user_id"),
            "viewer_roster_id": session.get("viewer_roster_id"),
            "viewer_team_name": session.get("viewer_team_name"),
        }
    except RuntimeError:
        # Called outside a request context (e.g. background thread) - no session available
        viewer_data = {
            "viewer_username": None,
            "viewer_user_id": None,
            "viewer_roster_id": None,
            "viewer_team_name": None,
        }
    return viewer_data


from utils.league_payload import format_sleeper_league_option  # noqa: E402


def _cache_key(platform: str, season: int, league_id: str):
    return str(platform).lower().strip(), int(season), str(league_id).strip()


def _page_html_tmp_path(platform: str, season: int, league_id: str, page: str) -> str:
    safe = f"{platform}_{season}_{league_id}_{page}".replace("/", "_")
    return f"/tmp/br_page_{safe}.html"


def get_page_html_from_cache(platform: str, season: int, league_id: str, page: str) -> Optional[str]:
    # Fast path: check in-process memory first
    entry = DASHBOARD_CACHE.get(_cache_key(platform, season, league_id))
    if entry:
        rec = entry.get("page_html", {}).get(page)
        if rec:
            ts, html = rec
            if time.time() - ts <= PAGE_HTML_TTL:
                return html

    # Cross-worker fallback: /tmp file - all gunicorn workers share the container fs
    try:
        path = _page_html_tmp_path(platform, season, league_id, page)
        if os.path.exists(path) and time.time() - os.path.getmtime(path) <= PAGE_HTML_TTL:
            html = open(path, encoding="utf-8").read()
            _ck = _cache_key(platform, season, league_id)
            _prune_dashboard_cache(keep=_ck)
            mem_entry = DASHBOARD_CACHE.setdefault(_ck, {})
            mem_entry.setdefault("page_html", {})[page] = (time.time(), html)
            return html
    except Exception:
        logger.debug("suppressed exception", exc_info=True)

    return None


def store_page_html(platform: str, season: int, league_id: str, page: str, html: str) -> None:
    _k = _cache_key(platform, season, league_id)
    _prune_dashboard_cache(keep=_k)
    entry = DASHBOARD_CACHE.setdefault(_k, {})
    entry.setdefault("page_html", {})[page] = (time.time(), html)
    try:
        path = _page_html_tmp_path(platform, season, league_id, page)
        tmp = path + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            f.write(html)
        os.replace(tmp, path)  # atomic - readers never see a partial file
    except Exception:
        logger.debug("suppressed exception", exc_info=True)

def get_awards_agg_from_cache(platform: str, season: int, league_id: str):
    entry = DASHBOARD_CACHE.get(_cache_key(platform, season, league_id))
    if not entry:
        return None
    rec = entry.get("awards_agg")
    if not rec:
        return None
    ts, payload = rec
    if time.time() - ts > PAGE_HTML_TTL:
        return None
    return payload


def store_awards_agg(platform: str, season: int, league_id: str, payload) -> None:
    _k = _cache_key(platform, season, league_id)
    _prune_dashboard_cache(keep=_k)
    entry = DASHBOARD_CACHE.setdefault(_k, {})
    entry["awards_agg"] = (time.time(), payload)


# -------- global NFL data caches (shared across leagues) --------
_PLAYERS_GLOBAL = None
_PLAYERS_INDEX_GLOBAL = None
_players_global_lock = threading.Lock()
_players_index_lock = threading.Lock()


def get_players_global():
    global _PLAYERS_GLOBAL
    if _PLAYERS_GLOBAL is None:
        with _players_global_lock:
            if _PLAYERS_GLOBAL is None:
                _PLAYERS_GLOBAL = get_nfl_players()
    return _PLAYERS_GLOBAL


def get_players_index_global():
    global _PLAYERS_INDEX_GLOBAL
    if _PLAYERS_INDEX_GLOBAL is None:
        with _players_index_lock:
            if _PLAYERS_INDEX_GLOBAL is None:
                _PLAYERS_INDEX_GLOBAL = load_players_index()
    return _PLAYERS_INDEX_GLOBAL


def run_daily_data_async(season: int, week: int) -> None:
    """Start daily data build in a background thread."""
    thread = threading.Thread(
        target=build_daily_data,
        args=(season, week),
        daemon=True,
    )
    thread.start()


def _weeks_hash(weeks):
    raw = ",".join(str(w) for w in weeks)
    return hashlib.sha1(raw.encode()).hexdigest()[:10]


_HISTORY_SEASONS_CACHE: dict = {}
_HISTORY_SEASONS_TTL = 600  # 10 minutes


def get_available_history_seasons(platform: str, league_id: str, current_season: int) -> List[int]:
    """
    Returns completed seasons only (excludes current season).
    Results are cached for 10 minutes to avoid redundant league-chain traversal.
    """
    _key = (platform, league_id, int(current_season))
    _cached = _HISTORY_SEASONS_CACHE.get(_key)
    if _cached and time.time() - _cached[1] < _HISTORY_SEASONS_TTL:
        return _cached[0]

    seasons = sorted(
        build_league_history_map(platform, league_id, current_season).keys(),
        reverse=True,
    )

    # remove current season
    seasons = [s for s in seasons if int(s) < int(current_season)]
    _HISTORY_SEASONS_CACHE[_key] = (seasons, time.time())

    return seasons


from utils.history_seasons import get_default_history_season  # noqa: E402


def _games_scheduled_today(season, week) -> bool:
    """True if the given week's schedule has any game dated today (local time).

    Drives the LIVE/Redzone affordances (weekly LIVE badge, Redzone nav dot,
    Redzone page polling) off the real schedule rather than a day-of-week guess.
    Past seasons never match today's date, so they resolve to False.
    """
    try:
        if not season or not week:
            return False
        today = datetime.now().strftime("%Y%m%d")
        sched = load_week_schedule(int(season), int(week)) or []
        return any(
            str(g.get("gameDate")) == today
            for g in sched if isinstance(g, dict)
        )
    except Exception as _e:
        logger.info(f"[games-today] check failed (s{season} w{week}): {_e}")
        return False



