# Every league page the mobile dock can point at: key -> (icon, endpoint, suffix).
# The key matches the `active` string build_nav() sets, so the dock, the top nav
# and the More sheet all agree on where you are. Any page here can be pulled into
# the dock's last slot when you're on it (see _mobile_nav), so the bar never shows
# a page with no active tab.
_NAV_PAGE_META = {
    "dashboard":         ("home",      "page_dashboard",            ""),
    "players":           ("bars",      "page_players",              ""),
    "weekly":            ("swords",    "page_weekly",               ""),
    "teams":             ("users",     "page_teams",                ""),
    "draft":             ("clipboard", "tool_pages.page_draft_room", ""),
    "keeper":            ("shield",    "tool_pages.page_keeper",    ""),
    "standings":         ("trophy",    "league_pages.page_standings",            ""),
    "activity":          ("activity",  "page_activity",             ""),
    "league_health":     ("pulse",     "page_commissioner",         ""),
    "recap":             ("news",      "page_recap",                ""),
    "scout":             ("swords",    "page_weekly",               "?tab=scout"),
    "optimal":           ("bars2",     "page_weekly",               "?tab=optimal"),
    "redzone":           ("pulse",     "page_redzone",              ""),
    "waivers":           ("list",      "league_pages.page_waivers",              ""),
    "schedule":          ("list",      "page_schedule",             ""),
    "trade":             ("swap",      "trade.page_trade",          ""),
    "trade-suggestions": ("swap",      "trade.page_trade",          "?tab=suggestions"),
    "trade-database":    ("swap",      "trade.page_trade_database", ""),
    "trade-intel":       ("radar",     "trade.page_trade_intel",    ""),
    "compare":           ("bars",      "seo_pages.page_compare",    ""),
    "top-movers":        ("bars2",     "seo_pages.top_movers_page", ""),
    "advanced-metrics":  ("bars2",     "page_advanced_metrics",     ""),
    "breakouts":         ("radar",     "page_breakouts",            ""),
    "prospects":         ("award",     "page_prospects",            ""),
    "draft-history":     ("history",   "tool_pages.page_draft_history", ""),
    "awards":            ("award",     "page_awards",               ""),
    "graphs":            ("bars2",     "page_graphs",               ""),
    "history":           ("history",   "page_history",              ""),
}

# Short labels for the dock (the sheet uses full labels at each call site).
_DOCK_LABELS = {
    "dashboard": "Home", "players": "Rankings", "weekly": "Matchups", "teams": "Teams",
    "draft": "Draft", "keeper": "Keeper", "standings": "Standings", "activity": "Activity",
    "league_health": "Health", "recap": "Recap", "scout": "Scout", "optimal": "Lineup",
    "redzone": "Redzone", "waivers": "Waivers", "schedule": "Schedule", "trade": "Trades",
    "trade-suggestions": "Trades", "trade-database": "Trades", "trade-intel": "Intel",
    "compare": "Compare", "top-movers": "Movers", "advanced-metrics": "Metrics",
    "breakouts": "Breakouts", "prospects": "Prospects", "draft-history": "History",
    "awards": "Awards", "graphs": "Graphs", "history": "History",
}


def _nav_show_keeper(platform, league_id, season) -> bool:
    """Should the offseason dock surface a Keeper tab?

    Only for keeper leagues: Sleeper type 1 (keeper), or any league with a keeper
    limit configured. Dynasty leagues (type 2) keep their whole roster, so there
    is no keeper decision and the dock never shows Keeper for them even when
    Sleeper reports a max_keepers value; pure redraft (type 0, no limit) does not
    either. Reads the cached league settings, so it costs nothing extra to check
    at render time. The Keeper Assistant still lives in the More sheet regardless."""
    settings = {}
    try:
        ctx = get_league_ctx_from_cache(platform, league_id, season) or {}
        settings = (ctx.get("league_settings")
                    or (ctx.get("league") or {}).get("settings")
                    or ctx.get("settings") or {})
    except Exception:
        settings = {}
    def _i(v):
        try:
            return int(v)
        except (TypeError, ValueError):
            return None
    type_code = _i(settings.get("type"))
    max_keepers = _i(settings.get("max_keepers")) or 0
    if type_code == 2:               # dynasty: whole-roster keep, no dock tab
        return False
    return type_code == 1 or max_keepers > 0


def _mobile_nav(active: str, league_id, platform, season) -> str:
    """Mobile navigation: a dynamic bottom dock plus a full "More" sheet.

    On phones this replaces the top nav entirely (CSS slims the top bar to the
    logo on the dashboard and hides it everywhere else). The dock keeps Home and
    More fixed; the three middle slots change with the season and with the page
    you are on:
      - In season:       Matchups, Trades, Teams.
      - Offseason keeper: Draft, Trades, Keeper.
      - Offseason other:  Draft, Trades, Teams.
    Whatever page you open takes the last middle slot if it is not already a tab,
    so the active state is never lost. Everything else (every page, plus Search,
    Watchlist, the league switcher and Settings) lives in the More sheet. The
    interactive widgets are relocated into the sheet by app.js, so their existing
    handlers keep working; here we render their mount points."""
    if not (league_id and platform and season):
        return ""

    # Normalize active exactly as build_nav does so the dock/sheet highlight the
    # right item on ?tab= sub-pages.
    active_norm = active
    _tab = request.args.get("tab", "")
    if active == "trade" and _tab == "suggestions":
        active_norm = "trade-suggestions"
    if active == "weekly" and _tab in ("scout", "optimal"):
        active_norm = _tab

    nfl_state = get_nfl_state() or {}
    offseason = ((nfl_state.get("season_type") or "").lower() in ("off", "pre")) and (
        int(nfl_state.get("season") or datetime.now().year) == int(season or 0)
    )
    draft_ended = has_draft_ended(league_id, platform, season)

    def _href(ep, suffix):
        return url_for(ep, platform=platform, season=season, league_id=league_id) + suffix

    # ── Dynamic dock ──────────────────────────────────────────────────────────
    show_keeper = _nav_show_keeper(platform, league_id, season)
    if not offseason:
        middle = ["weekly", "trade", "teams"]
    elif show_keeper:
        middle = ["draft", "trade", "keeper"]
    else:
        middle = ["draft", "trade", "teams"]

    dock_keys = ["dashboard"] + middle
    # The page you're on always earns a tab: if it's a real page and not already
    # in the dock, it takes over the last middle slot.
    if active_norm in _NAV_PAGE_META and active_norm != "dashboard" and active_norm not in dock_keys:
        middle = middle[:-1] + [active_norm]
        dock_keys = ["dashboard"] + middle

    items = ""
    active_index = -1
    for i, key in enumerate(dock_keys):
        icon, ep, suffix = _NAV_PAGE_META[key]
        label = _DOCK_LABELS.get(key, key.title())
        on = key == active_norm
        if on:
            active_index = i
        cls = "br-tabbar-item" + (" active" if on else "")
        aria = " aria-current='page'" if on else ""
        items += (
            f"<a class='{cls}'{aria} href='{_href(ep, suffix)}'>"
            f"{_nav_icon(icon, size=22)}<span class='br-tabbar-lbl'>{label}</span></a>"
        )
    items += (
        "<button type='button' class='br-tabbar-item br-more-tab' id='brMoreTab' "
        "aria-label='More' aria-haspopup='true' aria-expanded='false'>"
        f"{_nav_icon('more', size=22)}<span class='br-tabbar-lbl'>More</span></button>"
    )
    # Sliding active-pill indicator: --n tabs wide, sitting at slot --i. Rendered
    # at the active slot so it rests correctly with no flash; app.js animates a
    # change of --i on dock navigation so it glides between tabs.
    n_tabs = len(dock_keys) + 1
    ind_hidden = "" if active_index >= 0 else " data-hidden='1'"
    indicator = (
        f"<span class='br-tabbar-ind'{ind_hidden} aria-hidden='true' "
        f"style='--n:{n_tabs};--i:{max(active_index, 0)}'></span>"
    )
    dock = f"<nav class='br-tabbar' aria-label='Primary'>{indicator}{items}</nav>"

    # ── More sheet ────────────────────────────────────────────────────────────
    def _sl(key, label, pro=False):
        icon, ep, suffix = _NAV_PAGE_META[key]
        on = " active" if key == active_norm else ""
        aria = " aria-current='page'" if key == active_norm else ""
        pro_html = "<span class='br-sheet-pro'>PRO</span>" if pro else ""
        return (
            f"<a class='br-sheet-link{on}'{aria} href='{_href(ep, suffix)}'>"
            f"{_nav_icon(icon, size=20)}<span>{label}</span>{pro_html}</a>"
        )

    def _sec(title, rows):
        return (f"<h3 class='br-sheet-h'>{title}</h3>"
                f"<div class='br-sheet-group'>{''.join(rows)}</div>")

    # Search is a row like the others; tapping it opens the full-screen search
    # screen (app.js moves the real search widget into it). Watchlist is a plain
    # link to the full watchlist page.
    find_html = (
        "<h3 class='br-sheet-h'>Find</h3>"
        "<div class='br-sheet-group'>"
        "<button type='button' class='br-sheet-link' id='brSheetSearchRow'>"
        f"{_nav_icon('search', size=20)}<span>Search players</span></button>"
        "<a class='br-sheet-link' href='/watchlist'>"
        "<i class='fa-solid fa-star br-sheet-fa' aria-hidden='true'></i>"
        "<span>Watchlist</span></a>"
        "</div>"
    )

    weekly_html = ""
    if draft_ended or not offseason:
        rows = [
            _sl("weekly", "Matchups"), _sl("recap", "Weekly Recap"),
            _sl("scout", "Opponent Scout"), _sl("optimal", "Lineup Efficiency"),
            _sl("waivers", "Waivers & Start/Sit"), _sl("schedule", "Schedule Assistant"),
        ]
        if platform == "sleeper" and not offseason:
            rows.append(_sl("redzone", "Redzone"))
        weekly_html = _sec("Weekly", rows)

    league_html = _sec("League", [
        _sl("standings", "Standings"), _sl("teams", "Teams"),
        _sl("activity", "Activity"), _sl("league_health", "League Health"),
    ])

    trade_rows = [
        _sl("trade", "Trade Calculator"), _sl("trade-suggestions", "Suggestions", pro=True),
        _sl("trade-database", "Trade Database"),
    ]
    if platform != "espn":
        trade_rows.append(_sl("trade-intel", "Trade Intel", pro=True))
    trades_html = _sec("Trades", trade_rows)

    players_html = _sec("Players", [
        _sl("players", "Player Rankings"), _sl("compare", "Compare Players"),
        _sl("top-movers", "Top Movers"), _sl("advanced-metrics", "Advanced Metrics"),
        _sl("breakouts", "Breakout Engine", pro=True), _sl("prospects", "Prospect Rankings"),
    ])

    _draft_rows = [_sl("draft", "Draft Room")]
    if show_keeper:                                   # keeper leagues only
        _draft_rows.append(_sl("keeper", "Keeper Assistant"))
    _draft_rows.append(_sl("draft-history", "Draft History"))
    draft_html = _sec("Draft", _draft_rows)

    stats_html = _sec("Stats", [
        _sl("awards", "Awards"), _sl("graphs", "Graphs"), _sl("history", "History"),
    ])

    portfolio_link = ""
    if session.get("viewer_username"):
        portfolio_link = (
            f"<a class='br-sheet-link' "
            f"href='/portfolio?from_league={league_id}&platform={platform}&season={season}'>"
            f"{_nav_icon('users', size=20)}<span>My Leagues</span></a>"
        )
    # Refresh + Discord live in the sheet on mobile (they're floating pills only
    # on desktop, where there's no bottom dock to crowd). The freshness time is
    # filled in by app.js from the page's cache timestamp.
    refresh_row = (
        "<button type='button' class='br-sheet-link' id='brSheetRefresh'>"
        f"{_nav_icon('refresh', size=20)}<span>Refresh data</span>"
        "<span class='br-sheet-time' id='brSheetRefreshTime' aria-hidden='true'></span></button>"
    )
    discord_row = (
        "<a class='br-sheet-link' href='https://discord.gg/7aZrs7qfur' target='_blank' rel='noopener noreferrer'>"
        "<img src='/static/images/discord-brands-solid.png' alt='' class='br-sheet-icon-img'>"
        "<span>Join the Discord</span></a>"
    )
    account_html = (
        "<h3 class='br-sheet-h'>Account</h3>"
        "<div class='br-sheet-group'>"
        f"{portfolio_link}"
        f"{refresh_row}{discord_row}"
        "<div class='br-sheet-mount' id='brSheetAccount'></div>"
        "</div>"
    )

    # Section order mirrors the desktop nav bar (Trades, Weekly, League, Players,
    # Draft, Stats) so the two navs read the same. Find (search) and Account are
    # mobile-only, so they bookend the list — Find on top, Account last.
    sheet = (
        "<div class='br-sheet-scrim' id='brSheetScrim'></div>"
        "<nav class='br-sheet' id='brMoreSheet' aria-label='More' aria-hidden='true'>"
        "  <div class='br-sheet-grip' aria-hidden='true'></div>"
        f"  {find_html}{trades_html}{weekly_html}{league_html}{players_html}"
        f"  {draft_html}{stats_html}{account_html}"
        "</nav>"
    )

    # Full-screen search: the Search row opens this; app.js relocates the real
    # player-search widget (input + results) into the mount so its handlers work.
    search_screen = (
        "<div class='br-search-screen' id='brSearchScreen' aria-hidden='true'>"
        "  <div class='br-search-bar'>"
        "    <div class='br-search-mount' id='brSearchMount'></div>"
        "    <button type='button' class='br-search-cancel' id='brSearchCancel'>Cancel</button>"
        "  </div>"
        "</div>"
    )
    return dock + sheet + search_screen


# Guest (no-league) dock: the four global sections a logged-out visitor browses.
# (key, icon, href, short label). Mirrors the league dock's Home + middle slots.
_GUEST_DOCK_TABS = (
    ("home",    "home",      "/",        "Home"),
    ("trade",   "swap",      "/trade",   "Trades"),
    ("players", "bars",      "/players", "Rankings"),
    ("draft",   "clipboard", "/draft",   "Draft"),
)

# Sub-page active key -> which guest dock tab lights up (so e.g. Prospects or
# Compare keep the Players tab active, matching how the desktop dropdowns group).
_GUEST_ACTIVE_PARENT = {
    "home": "home",
    "trade": "trade", "trade-suggestions": "trade",
    "trade-database": "trade", "trade-intel": "trade",
    "players": "players", "compare": "players", "top-movers": "players",
    "advanced-metrics": "players", "breakouts": "players", "prospects": "players",
    "draft": "draft", "draft-history": "draft",
}


def _mobile_nav_guest(active: str) -> str:
    """Mobile bottom dock + More sheet for logged-out (no-league) visitors.

    Reuses the exact markup, ids and CSS of the league dock (`_mobile_nav`) so
    guests get the same thumb-reachable bottom dock and slide-up More sheet on the
    public pages, and the shared app.js/public.js controller wires it up unchanged.
    Links are the global (league-less) routes, including the landing page (Home)."""
    parent = _GUEST_ACTIVE_PARENT.get(active)

    # ── Dock ────────────────────────────────────────────────────────────────
    items = ""
    active_index = -1
    for i, (key, icon, href, label) in enumerate(_GUEST_DOCK_TABS):
        on = key == parent
        if on:
            active_index = i
        cls = "br-tabbar-item" + (" active" if on else "")
        aria = " aria-current='page'" if on else ""
        items += (
            f"<a class='{cls}'{aria} href='{href}'>"
            f"{_nav_icon(icon, size=22)}<span class='br-tabbar-lbl'>{label}</span></a>"
        )
    items += (
        "<button type='button' class='br-tabbar-item br-more-tab' id='brMoreTab' "
        "aria-label='More' aria-haspopup='true' aria-expanded='false'>"
        f"{_nav_icon('more', size=22)}<span class='br-tabbar-lbl'>More</span></button>"
    )
    n_tabs = len(_GUEST_DOCK_TABS) + 1
    ind_hidden = "" if active_index >= 0 else " data-hidden='1'"
    indicator = (
        f"<span class='br-tabbar-ind'{ind_hidden} aria-hidden='true' "
        f"style='--n:{n_tabs};--i:{max(active_index, 0)}'></span>"
    )
    dock = f"<nav class='br-tabbar' aria-label='Primary'>{indicator}{items}</nav>"

    # ── More sheet ──────────────────────────────────────────────────────────
    def _gl(href, label, key, pro=False):
        icon = _NAV_PAGE_META.get(key, ("bars", "", ""))[0]
        on = " active" if key == active else ""
        aria = " aria-current='page'" if key == active else ""
        pro_html = "<span class='br-sheet-pro'>PRO</span>" if pro else ""
        return (
            f"<a class='br-sheet-link{on}'{aria} href='{href}'>"
            f"{_nav_icon(icon, size=20)}<span>{label}</span>{pro_html}</a>"
        )

    def _sec(title, rows):
        return (f"<h3 class='br-sheet-h'>{title}</h3>"
                f"<div class='br-sheet-group'>{''.join(rows)}</div>")

    find_html = (
        "<h3 class='br-sheet-h'>Find</h3>"
        "<div class='br-sheet-group'>"
        "<button type='button' class='br-sheet-link' id='brSheetSearchRow'>"
        f"{_nav_icon('search', size=20)}<span>Search players</span></button>"
        "<a class='br-sheet-link' href='/watchlist'>"
        "<i class='fa-solid fa-star br-sheet-fa' aria-hidden='true'></i>"
        "<span>Watchlist</span></a>"
        "</div>"
    )

    trades_html = _sec("Trades", [
        _gl("/trade", "Trade Calculator", "trade"),
        _gl("/trade?tab=suggestions", "Suggestions", "trade-suggestions", pro=True),
        _gl("/trade-database", "Trade Database", "trade-database"),
        _gl("/trade-intel", "Trade Intel", "trade-intel", pro=True),
    ])
    players_html = _sec("Players", [
        _gl("/players", "Player Rankings", "players"),
        _gl("/compare", "Compare Players", "compare"),
        _gl("/top-movers", "Top Movers", "top-movers"),
        _gl("/metrics", "Advanced Metrics", "advanced-metrics"),
        _gl("/breakouts", "Breakout Engine", "breakouts", pro=True),
        _gl("/prospects", "Prospect Rankings", "prospects"),
    ])
    draft_html = _sec("Draft", [
        _gl("/draft", "Draft Room", "draft"),
        _gl("/draft/history", "Draft History", "draft-history"),
    ])

    portfolio_link = ""
    if session.get("viewer_username"):
        portfolio_link = (
            "<a class='br-sheet-link' href='/portfolio'>"
            f"{_nav_icon('users', size=20)}<span>My Leagues</span></a>"
        )
    discord_row = (
        "<a class='br-sheet-link' href='https://discord.gg/7aZrs7qfur' target='_blank' rel='noopener noreferrer'>"
        "<img src='/static/images/discord-brands-solid.png' alt='' class='br-sheet-icon-img'>"
        "<span>Join the Discord</span></a>"
    )
    # brSheetAccount is the mount app.js relocates the settings menu (dark mode
    # etc.) into on mobile, exactly as the league sheet does.
    account_html = (
        "<h3 class='br-sheet-h'>Account</h3>"
        "<div class='br-sheet-group'>"
        f"{portfolio_link}{discord_row}"
        "<div class='br-sheet-mount' id='brSheetAccount'></div>"
        "</div>"
    )

    sheet = (
        "<div class='br-sheet-scrim' id='brSheetScrim'></div>"
        "<nav class='br-sheet' id='brMoreSheet' aria-label='More' aria-hidden='true'>"
        "  <div class='br-sheet-grip' aria-hidden='true'></div>"
        f"  {find_html}{trades_html}{players_html}{draft_html}{account_html}"
        "</nav>"
    )
    search_screen = (
        "<div class='br-search-screen' id='brSearchScreen' aria-hidden='true'>"
        "  <div class='br-search-bar'>"
        "    <div class='br-search-mount' id='brSearchMount'></div>"
        "    <button type='button' class='br-search-cancel' id='brSearchCancel'>Cancel</button>"
        "  </div>"
        "</div>"
    )
    return dock + sheet + search_screen


def _nav_icon(name: str, cls: str = "", style: str = "", size: int = 16) -> str:
    body = _NAV_ICON_PATHS.get(name, "")
    cls_attr = f" {cls}" if cls else ""
    style_attr = f" style='{style}'" if style else ""
    return (
        f"<svg class='nav-svg-icon{cls_attr}' width='{size}' height='{size}' viewBox='0 0 24 24' "
        f"fill='none' stroke='currentColor' stroke-width='1.75' stroke-linecap='round' "
        f"stroke-linejoin='round' aria-hidden='true'{style_attr}>{body}</svg>"
    )


def build_nav(league_id: Optional[str], active: str, platform: str, season: int) -> str:
    """
    active (league pages): 'dashboard','standings','power','weekly','teams','activity','injuries','trade','graphs'
    active (global pages): 'home','privacy','faq','contact','support'
    """
    # Refine active key based on ?tab= param so sub-tab nav items highlight correctly
    _tab_param = request.args.get("tab", "")
    if active == "trade" and _tab_param == "suggestions":
        active = "trade-suggestions"
    # Scout Report and Optimal Lineup live as tabs on the Matchups (weekly) page,
    # not their own pages, so ?tab=scout/optimal highlights the right nav item.
    if active == "weekly" and _tab_param in ("scout", "optimal"):
        active = _tab_param

    nfl_state = get_nfl_state() or {}
    offseason_mode = ((nfl_state.get("season_type") or "").lower() in ("off", "pre")) and (
            int(nfl_state.get("season") or datetime.now().year) == int(season or 0)
    )
    # Exposed for client code (e.g. the player-modal Redzone tab, which hides in
    # the offseason). Uses the same condition that gates the Redzone nav item.
    season_active_flag = f"<script>window.__seasonActive={'false' if offseason_mode else 'true'};</script>"

    # Changelog bell (used in both home and league nav)
    changelog_bell = (
        "<div class='changelog-bell-wrapper'>"
        "  <button type='button' id='changelogBell' class='changelog-bell-btn' aria-label='Recent Updates'>"
        "    " + _nav_icon("bell") +
        "  </button>"
        "  <div class='changelog-dot changelog-dot-hidden'></div>"
        "  <div id='changelogDropdown' class='changelog-dropdown' style='display:none;'></div>"
        "</div>"
    )

    # Dark mode toggle button HTML (used in settings dropdown)
    dark_mode_toggle_html = (
        "<button type='button' class='settings-menu-item' id='settingsDarkModeBtn'>"
        "  " + _nav_icon("moon", cls="settings-menu-icon theme-icon light-icon") +
        "  " + _nav_icon("sun", cls="settings-menu-icon theme-icon dark-icon", style="display:none;") +
        "  <span class='settings-menu-label theme-text'>Dark Mode</span>"
        "</button>"
    )

    # Site tour trigger - league pages only (the tour spotlights the league nav)
    tour_menu_item = (
        "<button type='button' class='settings-menu-item' id='settingsTourBtn'>"
        "  " + _nav_icon("sparkles", cls="settings-menu-icon") +
        "  <span class='settings-menu-label'>Site Tour</span>"
        "</button>"
    ) if league_id else ""

    # Build settings dropdown content (minimal for logged-out users)
    settings_content = dark_mode_toggle_html

    # Settings gear dropdown (used in both home and league nav)
    settings_gear = (
        "<div class='settings-gear-wrapper'>"
        "  <button type='button' id='settingsGearBtn' class='utility-icon-btn' "
        "          aria-label='Settings' title='Settings'>"
        "    " + _nav_icon("gear") +
        "  </button>"
        "  <span id='gearDot' class='nav-notif-dot' style='display:none'></span>"
        f"  <div id='settingsDropdown' class='settings-dropdown' style='display:none;'>"
        f"    {settings_content}"
        "  </div>"
        "</div>"
    )

    if not league_id:
        def simple_pill(label: str, href: str, key: str) -> str:
            cls = "nav-pill active" if key == active else "nav-pill"
            aria = " aria-current='page'" if key == active else ""
            return f"<a class='{cls}'{aria} href='{href}'>{label}</a>"

        def simple_dropdown(label: str, items: list, active_keys: list, dropdown_id: str = "playersNavDropdown") -> str:
            is_active = active in active_keys
            btn_cls = "nav-pill active" if is_active else "nav-pill"
            item_html = ""
            for item_label, href, item_key in items:
                item_cls = "nav-pill-dropdown-item active" if item_key == active else "nav-pill-dropdown-item"
                aria_cur = " aria-current='page'" if item_key == active else ""
                item_html += f"<a class='{item_cls}'{aria_cur} href='{href}'>{item_label}</a>"
            btn_id  = dropdown_id.replace("Dropdown", "Btn")
            menu_id = dropdown_id.replace("Dropdown", "Menu")
            return (
                f"<div class='nav-pill-dropdown-wrapper' id='{dropdown_id}'>"
                f"  <button type='button' class='{btn_cls}' id='{btn_id}' aria-expanded='false' aria-haspopup='true' onclick='toggleNavDropdown(event,\"{dropdown_id}\")'>"
                f"    {label} <span class='nav-pill-chevron' aria-hidden='true'>&#x25BE;</span>"
                f"  </button>"
                f"  <div class='nav-pill-dropdown-menu' id='{menu_id}' role='menu'>"
                f"    {item_html}"
                f"  </div>"
                f"</div>"
            )

        pills = [
            simple_pill("Home", "/", "home"),
        ]
        pills += [
            simple_dropdown("Trades", [
                ("Trade Calculator", "/trade",          "trade"),
                ("Suggestions <span class='nav-pro-badge'>PRO</span>", "/trade?tab=suggestions", "trade-suggestions"),
                ("Trade Database",   "/trade-database", "trade-database"),
                ("Trade Intel <span class='nav-pro-badge'>PRO</span>",      "/trade-intel",    "trade-intel"),
            ], ["trade", "trade-database", "trade-intel"], "tradesNavDropdown"),
            simple_dropdown("Players", [
                ("Player Rankings", "/players",   "players"),
                ("Compare Players", "/compare", "compare"),
                ("Top Movers", "/top-movers", "top-movers"),
                ("Advanced Metrics", "/metrics", "advanced-metrics"),
                ("Breakout Engine <span class='nav-pro-badge'>PRO</span>",   "/breakouts", "breakouts"),
                ("Prospects",       "/prospects",   "prospects"),
            ], ["players", "prospects", "breakouts", "top-movers", "compare"], "playersNavDropdown"),
            simple_dropdown("Draft", [
                ("Draft Room",    "/draft",         "draft"),
                ("Draft History", "/draft/history", "draft-history"),
            ], ["draft", "draft-history"], "draftNavDropdown"),
        ]
        # Portfolio was only reachable from inside a league's nav; signed-in
        # users should be able to get to their leagues from global pages too.
        if session.get("viewer_username"):
            pills.append(simple_pill("My Leagues", "/portfolio", "portfolio"))

        player_search_html = (
            "<div class='nav-search-wrapper' id='navSearchWrapper'>"
            "  <div class='nav-search-inner'>"
            "    " + _nav_icon("search", cls="nav-search-icon") +
            "    <input type='text' id='navPlayerSearch' class='nav-search-input'"
            "           placeholder='Search players…' autocomplete='off' spellcheck='false' aria-label='Search players'/>"
            "    <button type='button' class='nav-search-clear' id='navSearchClear' aria-label='Clear search'>×</button>"
            "  </div>"
            "  <div class='nav-search-dropdown' id='navSearchDropdown'></div>"
            "</div>"
        )

        # Build utility bar for home screen (just settings gear with dark mode)
        home_utility_bar = (
            "<div class='nav-utility-bar'>"
            f"  {player_search_html}"
            f"  {changelog_bell}"
            f"  {settings_gear}"
            "  <button class='nav-hamburger utility-icon-btn' id='navToggle' aria-label='Menu'>"
            "    " + _nav_icon("menu") +
            "  </button>"
            "</div>"
        )

        # Build pills container
        pills_html = ''.join(pills)
        home_pills_container = (
            "<div class='nav-pills-container'>"
            "  <span class='nav-pill-ind' aria-hidden='true'></span>"
            f"  {pills_html}"
            "</div>"
        )

        # On phones the guest dock (_mobile_nav_guest) is the primary nav on every
        # public page (including the landing page), so slim this bar to the logo
        # (br-mnav), exactly as the league nav does. Search/settings still live
        # here in the DOM; app.js relocates them into the dock's More sheet.
        return (
            "<nav class='top-nav br-mnav' aria-label='Main navigation'>"
            "  <div class='nav-left'>"
            "    <a href='/' aria-label='BR Fantasy home'>"
            "      <img src='/static/Website_Logo.png' alt='BR Fantasy' class='site-logo'/>"
            "    </a>"
            "  </div>"
            "  <div class='nav-center'>"
            f"    {home_pills_container}"
            "  </div>"
            "  <div class='nav-right'>"
            f"    {home_utility_bar}"
            "  </div>"
            "</nav>"
            f"{season_active_flag}"
        )

    # -------- League nav (with league_id) --------

    def nav_pill(label: str, endpoint: str, key: str) -> str:
        cls = "nav-pill active" if key == active else "nav-pill"
        aria = " aria-current='page'" if key == active else ""
        href = url_for(endpoint, platform=platform, season=season, league_id=league_id)
        return f"<a class='{cls}'{aria} href='{href}'>{label}</a>"

    def nav_pill_dropdown(label: str, items: list, active_keys: list, dropdown_id: str = "playersNavDropdown", btn_extra_cls: str = "") -> str:
        """Build a dropdown nav pill. items = list of (label, endpoint_or_none, key, disabled, href_suffix)."""
        is_active = active in active_keys
        btn_cls = "nav-pill active" if is_active else "nav-pill"
        if btn_extra_cls:
            btn_cls += " " + btn_extra_cls
        item_html = ""
        for item_tuple in items:
            item_label, endpoint, item_key = item_tuple[0], item_tuple[1], item_tuple[2]
            disabled = item_tuple[3] if len(item_tuple) > 3 else False
            href_suffix = item_tuple[4] if len(item_tuple) > 4 else ""
            if disabled:
                item_html += (
                    f"<span class='nav-pill-dropdown-item disabled'>"
                    f"{item_label} <span style='font-size:10px;margin-left:4px;'>Soon</span>"
                    f"</span>"
                )
            else:
                href = url_for(endpoint, platform=platform, season=season, league_id=league_id) + href_suffix
                item_active = " active" if item_key == active else ""
                item_cls = f"nav-pill-dropdown-item{item_active}"
                aria_cur = " aria-current='page'" if item_key == active else ""
                item_html += f"<a class='{item_cls}'{aria_cur} href='{href}'>{item_label}</a>"
        btn_id  = dropdown_id.replace("Dropdown", "Btn")
        menu_id = dropdown_id.replace("Dropdown", "Menu")
        return (
            f"<div class='nav-pill-dropdown-wrapper' id='{dropdown_id}'>"
            f"  <button type='button' class='{btn_cls}' id='{btn_id}' aria-expanded='false' aria-haspopup='true' onclick='toggleNavDropdown(event,\"{dropdown_id}\")'>"
            f"    {label} <span class='nav-pill-chevron' aria-hidden='true'>&#x25BE;</span>"
            f"  </button>"
            f"  <div class='nav-pill-dropdown-menu' id='{menu_id}' role='menu'>"
            f"    {item_html}"
            f"  </div>"
            f"</div>"
        )

    # Generate dashboard URL for logo link
    dashboard_url = url_for("page_dashboard", platform=platform, season=season, league_id=league_id)

    # Navigation pills (no utilities)
    nav_pills = []
    nav_pills.append(nav_pill("Dashboard", "page_dashboard", "dashboard"))
    _is_espn = (platform == "espn")
    nav_pills.append(nav_pill_dropdown("Trades", [
        ("Trade Calculator", "trade.page_trade",          "trade",          False),
        ("Suggestions <span class='nav-pro-badge'>PRO</span>", "trade.page_trade", "trade-suggestions", False, "?tab=suggestions"),
        ("Trade Database",   "trade.page_trade_database", "trade-database", False),
        # Trade Intel uses Sleeper trade data - not applicable for ESPN
        *([("Trade Intel <span class='nav-pro-badge'>PRO</span>", "trade.page_trade_intel", "trade-intel", False)] if not _is_espn else []),
    ], ["trade", "trade-database", "trade-intel"], "tradesNavDropdown"))
    # Weekly dropdown is available as soon as the draft is done
    draft_ended = has_draft_ended(league_id, platform, season)
    if draft_ended or not offseason_mode:
        _weekly_items = [
            ("Matchups",     "page_weekly", "weekly", False),
            ("Weekly Recap", "page_recap",  "recap",  False),
            ("Opponent Scout", "page_weekly", "scout", False, "?tab=scout"),
            ("Lineup Efficiency", "page_weekly", "optimal", False, "?tab=optimal"),
            # Roster/lineup tools live with the other weekly tools, not Players.
            ("Waivers & Start/Sit", "league_pages.page_waivers", "waivers", False),
            ("Schedule Assistant",  "page_schedule", "schedule", False),
        ]
        # Redzone lives inside the Weekly dropdown. When a game is actually
        # scheduled for today the Weekly button glows and the Redzone item
        # pulses with a live dot. Only available during the active season.
        _rz_pulse = ""
        if not offseason_mode:
            # Live when the current NFL week's schedule has a game dated today.
            _rz_week = nfl_state.get("week") or nfl_state.get("display_week")
            _rz_live = _games_scheduled_today(nfl_state.get("season") or season, _rz_week)
            _rz_label = (
                "<span class='rz-nav-live'><span class='rz-nav-dot'></span>Redzone</span>"
                if _rz_live else "Redzone"
            )
            # Redzone live tracking relies on the Sleeper player index + Tank01
            # boxscores, so it only works for Sleeper leagues. Hide it elsewhere
            # rather than showing a broken, name-less live view.
            if platform == "sleeper":
                _weekly_items.append((_rz_label, "page_redzone", "redzone", False))
                if _rz_live:
                    _rz_pulse = "nav-pill-redzone-live"
        nav_pills.append(nav_pill_dropdown(
            "Weekly", _weekly_items,
            ["weekly", "recap", "redzone", "scout", "optimal", "waivers", "schedule"],
            "weeklyNavDropdown", btn_extra_cls=_rz_pulse,
        ))
    nav_pills.append(nav_pill_dropdown("League", [
        ("Standings",       "league_pages.page_standings",    "standings",    False),
        ("Teams",           "page_teams",        "teams",        False),
        ("Activity",        "page_activity",     "activity",     False),
        ("League Health",   "page_commissioner", "league_health", False),
    ], ["standings", "teams", "activity", "league_health"], "teamsNavDropdown"))
    nav_pills.append(nav_pill_dropdown("Players", [
        ("Player Rankings",   "page_players",   "players",   False),
        ("Compare Players", "seo_pages.page_compare", "compare", False),
        ("Top Movers", "seo_pages.top_movers_page", "top-movers", False),
        ("Advanced Metrics", "page_advanced_metrics", "advanced-metrics", False),
        ("Breakout Engine <span class='nav-pro-badge'>PRO</span>",   "page_breakouts",  "breakouts", False),
        ("Prospect Rankings", "page_prospects",  "prospects", False),
    ], ["players", "prospects", "breakouts", "top-movers", "compare"], "playersNavDropdown"))
    # Keeper Assistant only applies to keeper leagues; hide it for dynasty and
    # plain redraft leagues.
    _draft_items = [("Draft Room", "tool_pages.page_draft_room", "draft", False)]
    if _nav_show_keeper(platform, league_id, season):
        _draft_items.append(("Keeper Assistant", "tool_pages.page_keeper", "keeper", False))
    _draft_items.append(("Draft History", "tool_pages.page_draft_history", "draft-history", False))
    nav_pills.append(nav_pill_dropdown("Draft", _draft_items,
        ["draft", "draft-history", "keeper"], "draftNavDropdown"))
    nav_pills.append(nav_pill_dropdown("Stats", [
        ("Awards",   "page_awards",   "awards",   False),
        ("Graphs",   "page_graphs",   "graphs",   False),
        ("History",  "page_history",  "history",  False),
    ], ["awards", "graphs", "history"], "statsNavDropdown"))
    if session.get("viewer_username"):
        _portfolio_cls = "nav-pill active" if active == "portfolio" else "nav-pill"
        _portfolio_href = f"/portfolio?from_league={league_id}&platform={platform}&season={season}"
        nav_pills.append(f"<a class='{_portfolio_cls}' href='{_portfolio_href}'>My Leagues</a>")

    # Changelog bell
    # League switcher dropdown (if user is logged in)
    # Single switcher for settings dropdown (works on both desktop and mobile)
    league_switcher_html = ""
    viewer_username = session.get("viewer_username")
    # Show the full logged-in menu (incl. Sign Out) for anyone with a resolved
    # viewer, and for every ESPN league page: ESPN "sign-in" is entering the
    # league itself (team-name matching is optional, so viewer_username is often
    # unset), so there's no separate logged-in flag to key off. The league
    # switcher stays gated to non-ESPN viewers below.
    if viewer_username or platform == "espn":
        # ESPN has no username-based league list, so it gets no league switcher.
        if viewer_username and platform != "espn":
            league_switcher_html = (
                f"<div class='league-switcher-wrapper'>"
                f"  <select id='leagueSwitcher' class='league-switcher' "
                f"          data-current-league='{league_id}' "
                f"          data-current-platform='{platform}' "
                f"          data-current-season='{season}' "
                f"          data-current-username='{viewer_username}'>"
                f"    <option value=''>Loading leagues...</option>"
                f"  </select>"
                f"</div>"
            )

        # Update settings dropdown content for logged-in users with full menu
        settings_content = (
            "<button type='button' class='settings-menu-item' id='settingsChangelogBtn'>"
            "  " + _nav_icon("bell", cls="settings-menu-icon") +
            "  <span class='settings-menu-label'>Notifications</span>"
            "  <span id='settingsNotifDot' class='settings-notif-dot' style='display:none'></span>"
            "</button>"
            f"{dark_mode_toggle_html}"
            f"{tour_menu_item}"
            f"{league_switcher_html}"
            "<a href='/logout' class='settings-menu-item settings-menu-logout'>"
            "  " + _nav_icon("logout", cls="settings-menu-icon") +
            "  <span class='settings-menu-label'>Sign Out</span>"
            "</a>"
        )

        # Rebuild settings gear with updated content
        settings_gear = (
            "<div class='settings-gear-wrapper'>"
            "  <button type='button' id='settingsGearBtn' class='utility-icon-btn' "
            "          aria-label='Settings' title='Settings'>"
            "    " + _nav_icon("gear") +
            "  </button>"
            "  <span id='gearDot' class='nav-notif-dot' style='display:none'></span>"
            f"  <div id='settingsDropdown' class='settings-dropdown' style='display:none;'>"
            f"    {settings_content}"
            "  </div>"
            "</div>"
        )
    else:
        # Logged-out user on a league page - offer quick sign-in
        signin_item = (
            "<button type='button' class='settings-menu-item' "
            "        onclick='document.getElementById(\"signinModal\").style.display=\"flex\"'>"
            "  " + _nav_icon("logout", cls="settings-menu-icon", style="transform:scaleX(-1);") +
            "  <span class='settings-menu-label'>Sign In</span>"
            "</button>"
        )
        settings_content = signin_item + dark_mode_toggle_html + tour_menu_item
        settings_gear = (
            "<div class='settings-gear-wrapper'>"
            "  <button type='button' id='settingsGearBtn' class='utility-icon-btn' "
            "          aria-label='Settings' title='Settings'>"
            "    " + _nav_icon("gear") +
            "  </button>"
            "  <span id='gearDot' class='nav-notif-dot' style='display:none'></span>"
            f"  <div id='settingsDropdown' class='settings-dropdown' style='display:none;'>"
            f"    {settings_content}"
            "  </div>"
            "</div>"
        )

    watchlist_btn = (
        "<div class='watchlist-nav-wrapper'>"
        "  <button type='button' id='watchlistNavBtn' class='utility-icon-btn' "
        "          aria-label='Watchlist' title='Watchlist' onclick='toggleWatchlistPanel()'>"
        "    <span class='watchlist-star' aria-hidden='true'>&#9734;</span>"
        "  </button>"
        "  <span id='watchlistNavAlert' class='watchlist-alert-dot' style='display:none' "
        "        title='A watched player has a value move or injury' aria-hidden='true'></span>"
        "  <div id='watchlistNavPanel' class='watchlist-nav-panel' style='display:none;'>"
        "    <div class='watchlist-nav-header'>"
        "      <span class='watchlist-nav-title'>Watchlist"
        "        <span id='watchlistNavHeaderCount' class='watchlist-nav-count'></span></span>"
        "      <button type='button' id='watchlistClearBtn' class='watchlist-clear-btn' "
        "              onclick='_wlClearAll()' style='display:none'>Clear all</button>"
        "    </div>"
        "    <div id='watchlistNavList'></div>"
        "    <a class='watchlist-page-link' href='/watchlist'>Open full watchlist &rarr;</a>"
        "  </div>"
        "</div>"
    )

    player_search_html = (
        "<div class='nav-search-wrapper' id='navSearchWrapper'>"
        "  <div class='nav-search-inner'>"
        "    " + _nav_icon("search", cls="nav-search-icon") +
        "    <input type='text' id='navPlayerSearch' class='nav-search-input'"
        "           placeholder='Search players…' autocomplete='off' spellcheck='false' aria-label='Search players'/>"
        "    <button type='button' class='nav-search-clear' id='navSearchClear' aria-label='Clear search'>×</button>"
        "  </div>"
        "  <div class='nav-search-dropdown' id='navSearchDropdown'></div>"
        "</div>"
    )

    # Build utility bar (desktop right side, mobile header)
    utility_bar = (
        "<div class='nav-utility-bar'>"
        f"  {player_search_html}"
        f"  {watchlist_btn}"
        f"  {changelog_bell}"
        f"  {settings_gear}"
        "  <button class='nav-hamburger utility-icon-btn' id='navToggle' aria-label='Menu'>"
        "    " + _nav_icon("menu") +
        "  </button>"
        "</div>"
    )

    # Build pills container (includes league switcher and logout for mobile menu)
    pills_html = ''.join(nav_pills)
    pills_container = (
        "<div class='nav-pills-container'>"
        "  <span class='nav-pill-ind' aria-hidden='true'></span>"
        f"  {pills_html}"
        "</div>"
    )

    _is_espn = (platform == "espn")
    _signin_sub  = "Enter your ESPN team name to restore personalized features." if _is_espn else "Enter your Sleeper username to restore personalized features."
    _signin_ph   = "Your ESPN team name" if _is_espn else "Sleeper username"
    signin_modal = (
        f"<div id='signinModal' class='signin-modal-overlay'>"
        f"  <div class='signin-modal-box'>"
        f"    <h3 class='signin-modal-title'>Sign in to your team</h3>"
        f"    <p class='signin-modal-sub'>{_signin_sub}</p>"
        f"    <form method='POST' action='/set-viewer'>"
        f"      <input type='hidden' name='platform' value='{platform}'>"
        f"      <input type='hidden' name='season' value='{season}'>"
        f"      <input type='hidden' name='league_id' value='{league_id}'>"
        f"      <input type='hidden' name='next' value='{request.path + ('?' + request.query_string.decode() if request.query_string else '')}'>"
        f"      <input class='signin-modal-input' type='text' name='username' aria-label='Username or team name' placeholder='{_signin_ph}' autocomplete='username' autofocus>"
        f"      <div class='signin-modal-actions'>"
        f"        <button class='signin-modal-submit' type='submit'>Sign In</button>"
        f"        <button class='signin-modal-cancel' type='button'"
        f"                onclick='document.getElementById(\"signinModal\").style.display=\"none\"'>Cancel</button>"
        f"      </div>"
        f"    </form>"
        f"  </div>"
        f"</div>"
    )

    # On phones the mobile dock (_mobile_nav) is the primary nav, so this top bar
    # is slimmed to the logo on the dashboard and hidden on every other league
    # page. `br-mnav` marks "the dock is present"; `br-mnav-home` marks the one
    # page that keeps a (logo-only) top bar.
    _mnav_cls = "top-nav br-mnav" + (" br-mnav-home" if active == "dashboard" else "")
    return (
        f"<nav class='{_mnav_cls}' aria-label='Main navigation'>"
        "  <div class='nav-left'>"
        f"    <a href='{dashboard_url}' aria-label='BR Fantasy dashboard'>"
        "      <img src='/static/Website_Logo.png' alt='BR Fantasy' class='site-logo'/>"
        "    </a>"
        "  </div>"
        "  <div class='nav-center'>"
        f"    {pills_container}"
        "  </div>"
        "  <div class='nav-right'>"
        f"    {utility_bar}"
        "  </div>"
        "</nav>"
        f"{signin_modal}"
        f"{season_active_flag}"
    )


# The AdSense library is the biggest controllable mobile-perf drain: in the
# <head> it competes for bandwidth on the critical path and runs on the main
# thread (Total Blocking Time). We now load it lazily (see _AD_INIT) on first
# user interaction or at idle, so it's off the initial render path. The ad <ins>
# slots still reserve their fixed height, so deferring the fill causes no CLS.
_AD_SCRIPT = ''
_AD_TOP = """<div class="ad-container ad-top-banner"><ins class="adsbygoogle" style="display:block;overflow:hidden;" data-ad-client="ca-pub-9164153092633845" data-ad-slot="5233061286" data-ad-format="horizontal" data-full-width-responsive="false"></ins></div>"""
_AD_BOTTOM = """<div class="ad-container ad-bottom-content"><ins class="adsbygoogle" style="display:block;overflow:hidden;" data-ad-client="ca-pub-9164153092633845" data-ad-slot="5233061286" data-ad-format="horizontal" data-full-width-responsive="false"></ins></div>"""
_AD_INIT = """(function(){
  var loaded = false;
  function loadAds(){
    if (loaded) return; loaded = true;
    var s = document.createElement('script');
    s.async = true;
    s.src = 'https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-pub-9164153092633845';
    s.crossOrigin = 'anonymous';
    s.onload = function(){
      try {
        var slots = document.querySelectorAll('ins.adsbygoogle');
        for (var i = 0; i < slots.length; i++) {
          (adsbygoogle = window.adsbygoogle || []).push({});
        }
      } catch(e) { console.warn('AdSense init error:', e); }
    };
    // Ad script blocked or unreachable: collapse the reserved slots so they
    // don't sit as empty grey bands (CSS hides [data-ads-blocked] containers).
    s.onerror = function(){
      document.querySelectorAll('.ad-container').forEach(function(c){
        c.setAttribute('data-ads-blocked', '1');
      });
    };
    document.head.appendChild(s);
  }
  var evts = ['scroll','pointerdown','keydown','touchstart','mousemove'];
  function onFirstInteract(){
    evts.forEach(function(e){ window.removeEventListener(e, onFirstInteract); });
    loadAds();
  }
  evts.forEach(function(e){ window.addEventListener(e, onFirstInteract, { passive: true }); });
  // Fallback so ads still load without any interaction, but well after first paint.
  if ('requestIdleCallback' in window) { requestIdleCallback(loadAds, { timeout: 4000 }); }
  else { window.addEventListener('load', function(){ setTimeout(loadAds, 3500); }); }
})();"""


def _recap_ready_banner(league_id: str, platform: str, season: int) -> str:
    """Dismissible weekly 'Recap is ready' banner.

    Shown on Tuesdays during the NFL season (Sep–Jan) only.
    Dismissal resets each week via an ISO-week-scoped localStorage key,
    so the banner reappears the following Tuesday.
    """
    import datetime as _dt
    now = _dt.datetime.now()
    if now.weekday() != 1:                            # Tuesday only (0=Mon … 6=Sun)
        return ""
    if now.month not in {9, 10, 11, 12, 1}:          # NFL season only
        return ""
    if not (league_id and platform and season):
        return ""

    recap_url = f"/{platform}/{season}/{league_id}/recap"
    # Week-scoped key - dismissal resets automatically the following Tuesday
    iso_week = now.isocalendar()[1]
    dismiss_key = f"recap-banner-{now.year}-w{iso_week}"

    return f"""
<style>
@keyframes recapSlideUp {{
  from {{ opacity:0; transform:translateY(16px); }}
  to   {{ opacity:1; transform:translateY(0); }}
}}
#recapReadyBanner {{ animation: recapSlideUp .3s ease forwards; }}
</style>
<div id="recapReadyBanner" style="
     display:none;
     position:fixed;bottom:24px;right:24px;z-index:9999;
     background:var(--card);
     border:1px solid var(--border);
     border-top:3px solid var(--accent);
     border-radius:14px;box-shadow:0 12px 40px rgba(0,0,0,.22);
     padding:18px 20px;width:300px;
     flex-direction:column;gap:12px;">
  <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:8px;">
    <div style="display:flex;align-items:center;gap:8px;">
      <i class="fa-solid fa-newspaper" style="font-size:15px;color:var(--accent);margin-top:1px;"></i>
      <span style="font-size:14px;font-weight:700;color:var(--text);">Recap is ready</span>
    </div>
    <button id="recapReadyClose"
            style="background:none;border:none;color:var(--muted);font-size:18px;line-height:1;
                   cursor:pointer;padding:0;flex-shrink:0;"
            aria-label="Dismiss">&times;</button>
  </div>
  <p style="margin:0;font-size:13px;color:var(--muted);line-height:1.45;">
    This week's recap is ready. See who scored big, who got cooked, and where things stand.
  </p>
  <a id="recapReadyLink" href="{recap_url}"
     style="display:block;text-align:center;background:var(--accent);color:#fff;
            font-weight:700;font-size:13px;text-decoration:none;
            padding:9px 0;border-radius:8px;">
    View Recap
  </a>
</div>
<script>
(function(){{
  var key = '{dismiss_key}';
  var el  = document.getElementById('recapReadyBanner');
  if (!el) return;

  function dismiss() {{
    el.style.display = 'none';
    localStorage.setItem(key, '1');
    var dot = document.getElementById('recapNavDot');
    if (dot) dot.remove();
  }}

  function addNavDot() {{
    var weekly = Array.from(document.querySelectorAll('.nav-pill, .nav-dropdown-btn'))
                      .find(function(n) {{ return n.textContent.trim().startsWith('Weekly'); }});
    if (!weekly) return;
    var dot = document.createElement('span');
    dot.id = 'recapNavDot';
    dot.style.cssText = 'width:7px;height:7px;border-radius:50%;background:#ef4444;'
                      + 'display:inline-block;margin-left:5px;vertical-align:middle;'
                      + 'position:relative;top:-1px;flex-shrink:0;';
    weekly.appendChild(dot);
  }}

  if (!localStorage.getItem(key)) {{
    el.style.display = 'flex';
    addNavDot();
  }}

  document.getElementById('recapReadyClose').addEventListener('click', dismiss);
  document.getElementById('recapReadyLink').addEventListener('click', dismiss);
}})();
</script>"""


_DRAFT_IMMINENT_BANNER_HTML = r"""
<div id="drImminentBanner" class="drgb" style="display:none;"></div>
<style>
.drgb { margin: 10px 14px 0; border-radius: 12px; border: 1px solid var(--accent,#38bdf8); overflow: hidden;
  background: linear-gradient(90deg, rgba(56,189,248,.18), rgba(56,189,248,.05)); }
.drgb.is-live { border-color: #22c55e; background: linear-gradient(90deg, rgba(34,197,94,.18), rgba(34,197,94,.05)); }
.drgb-inner { display: flex; align-items: center; gap: 12px; padding: 11px 16px; }
.drgb-ic { font-size: 20px; flex-shrink: 0; display: inline-flex; align-items: center; }
.drgb-ic-live { animation: drgbPulse 1.4s ease-in-out infinite; }
@keyframes drgbPulse { 0%,100% { opacity: 1; } 50% { opacity: .4; } }
.drgb-txt { display: flex; flex-direction: column; line-height: 1.3; min-width: 0; flex: 1; }
.drgb-txt b { font-size: 14px; font-weight: 800; color: var(--text); }
.drgb-txt span { font-size: 12px; color: var(--text-muted); }
.drgb-cd { font-variant-numeric: tabular-nums; }
.drgb-join { flex-shrink: 0; display: inline-flex; align-items: center; gap: 7px; white-space: nowrap;
  background: var(--accent,#38bdf8); color: #fff; font-weight: 700; font-size: 13px; text-decoration: none; padding: 8px 14px; border-radius: 8px; }
.drgb.is-live .drgb-join { background: #22c55e; }
.drgb-join i { font-size: 11px; }
.drgb-x { flex-shrink: 0; background: none; border: none; color: var(--text-muted); font-size: 19px; line-height: 1; cursor: pointer; padding: 0 2px; }
</style>
<script>
(function(){
  var CFG = __DR_BANNER_CFG__;
  var el = document.getElementById('drImminentBanner');
  if (!el || !CFG.leagueId) return;
  // Don't duplicate the in-page banner on the Draft Room itself.
  if (/(^|\/)draft$/.test(location.pathname.replace(/\/+$/, ''))) return;
  var WINDOW_MS = 15 * 60 * 1000;
  var cur = null;
  function dkey(id, st){ return 'drgb:' + id + ':' + st; }
  function fmtCd(ms){
    var t = Math.max(0, Math.floor(ms / 1000));
    var h = Math.floor(t / 3600), m = Math.floor((t % 3600) / 60), s = t % 60;
    return (h > 0 ? h + ':' + (m < 10 ? '0' : '') : '') + m + ':' + (s < 10 ? '0' : '') + s;
  }
  function pick(drafts){
    var live = null, soon = null;
    (drafts || []).forEach(function(d){
      if (d.status === 'drafting'){ if (!live) live = d; }
      else if (d.status === 'pre_draft' && d.start_time){
        var ms = Number(d.start_time) - Date.now();
        if (ms > 0 && ms <= WINDOW_MS && (!soon || Number(d.start_time) < Number(soon.start_time))) soon = d;
      }
    });
    return live || soon;
  }
  function render(){
    if (!cur){ el.style.display = 'none'; return; }
    if (localStorage.getItem(dkey(cur.id, cur.state))){ el.style.display = 'none'; return; }
    var isLive = cur.state === 'live';
    el.className = 'drgb' + (isLive ? ' is-live' : '');
    var icon = isLive ? '<i class="fa-solid fa-bolt"></i>' : '<i class="fa-solid fa-calendar-days"></i>';
    var title = isLive ? 'Your draft is live now'
                       : 'Your draft starts in <span class="drgb-cd">' + fmtCd(cur.start - Date.now()) + '</span>';
    var sub = isLive ? 'Jump into the Draft Room for live picks, best-available, and grades.'
                     : 'Open the Draft Room and get your board ready.';
    el.innerHTML = '<div class="drgb-inner">'
      + '<span class="drgb-ic' + (isLive ? ' drgb-ic-live' : '') + '">' + icon + '</span>'
      + '<div class="drgb-txt"><b>' + title + '</b><span>' + sub + '</span></div>'
      + '<a class="drgb-join" href="' + CFG.draftUrl + '?connect=' + encodeURIComponent(cur.id) + '">Join Draft Room <i class="fa-solid fa-arrow-right-long"></i></a>'
      + '<button class="drgb-x" aria-label="Dismiss">&times;</button>'
      + '</div>';
    el.style.display = '';
    el.querySelector('.drgb-x').addEventListener('click', function(){
      localStorage.setItem(dkey(cur.id, cur.state), '1');
      el.style.display = 'none';
    });
  }
  function tick(){
    if (!cur || cur.state !== 'soon') return;
    var ms = cur.start - Date.now();
    if (ms <= 0){ refresh(); return; }   // crossed start time: re-detect for the live state
    var cd = el.querySelector('.drgb-cd');
    if (cd) cd.textContent = fmtCd(ms);
  }
  function apply(drafts){
    var d = pick(drafts);
    if (!d){ cur = null; el.style.display = 'none'; return; }
    cur = { id: d.draft_id, state: (d.status === 'drafting' ? 'live' : 'soon'), start: Number(d.start_time || 0) };
    render();
  }
  function refresh(){
    // When a draft is imminent/live, poll harder so a pushed-back start time
    // (e.g. moved back 15 min or an hour) is reflected within ~30s.
    var throttle = cur ? 25000 : 60000;
    try {
      var c = JSON.parse(sessionStorage.getItem('drgbCache') || 'null');
      if (c && (Date.now() - c.ts) < throttle){ apply(c.drafts); return; }   // throttle across page navigations
    } catch(e){}
    fetch(CFG.detectUrl, { cache: 'no-store' }).then(function(r){ return r.json(); }).then(function(resp){
      var drafts = (resp && resp.drafts) || [];
      try { sessionStorage.setItem('drgbCache', JSON.stringify({ ts: Date.now(), drafts: drafts })); } catch(e){}
      apply(drafts);
    }).catch(function(){});
  }
  setInterval(tick, 1000);
  setInterval(refresh, 30000);   // re-detect every 30s; the throttle above keeps far-out checks cheap
  refresh();
})();
</script>
"""


def _draft_imminent_banner(league_id: str, platform: str, season: int, active: str) -> str:
    """Site-wide, dismissible banner shown on every page (except the Draft Room
    itself) when the user's Sleeper league has a draft that is live or starting
    within 15 minutes. Detection + countdown run client-side so page loads stay
    fast; dismissal persists per draft + state in localStorage."""
    if active == "draft":
        return ""
    if not (league_id and platform and season):
        return ""
    if str(platform).lower() != "sleeper":
        return ""
    cfg = json.dumps({
        "platform": platform,
        "leagueId": league_id,
        "season": int(season),
        "draftUrl": f"/{platform}/{season}/{league_id}/draft",
        "detectUrl": f"/api/draft/detect?platform={platform}&league_id={league_id}&season={int(season)}",
    })
    return _DRAFT_IMMINENT_BANNER_HTML.replace("__DR_BANNER_CFG__", cfg)


