DEFAULT_META_DESCRIPTION = (
    "BR Fantasy is a free fantasy football toolkit: a dynasty and redraft trade "
    "calculator, daily-updated player trade values, real-trade market data, breakout "
    "candidate rankings, and advanced metrics for Sleeper, ESPN, and Yahoo leagues."
)


def _build_seo_meta_tags(
        description: str,
        canonical: Optional[str],
        noindex: Optional[bool],
        is_league_scoped: bool,
) -> str:
    """Assemble <meta description>, robots, and canonical tags for the page head.

    League-scoped (personalized) pages default to noindex,follow so the thousands
    of per-league URL variants don't dilute the canonical public tool pages.
    """
    # Default: noindex personalized league pages unless a caller overrides.
    do_noindex = noindex if noindex is not None else is_league_scoped

    parts = []
    desc = (description or DEFAULT_META_DESCRIPTION).strip()
    parts.append(f"<meta name=\"description\" content=\"{html.escape(desc, quote=True)}\">")

    if do_noindex:
        parts.append("<meta name=\"robots\" content=\"noindex, follow\">")
    else:
        parts.append("<meta name=\"robots\" content=\"index, follow\">")
        canon = canonical
        if not canon:
            try:
                if PRIMARY_DOMAIN:
                    canon = f"https://{PRIMARY_DOMAIN}{request.path}"
                else:
                    canon = request.base_url
            except Exception:
                canon = ""
        if canon:
            parts.append(f"<link rel=\"canonical\" href=\"{html.escape(canon, quote=True)}\">")

    return "\n    ".join(parts)


def _site_origin() -> str:
    """Absolute origin (https://host) for building canonical/social URLs."""
    try:
        if PRIMARY_DOMAIN:
            return f"https://{PRIMARY_DOMAIN}"
        return request.host_url.rstrip("/")
    except Exception:
        return ""


def _default_social_tags(title: str, description: str) -> str:
    """Baseline Open Graph + Twitter Card tags for pages that don't supply
    their own. Gives every public page a proper link preview when shared."""
    origin = _site_origin()
    desc = (description or DEFAULT_META_DESCRIPTION).strip()
    image = f"{origin}/static/BR_Logo.png" if origin else "/static/BR_Logo.png"
    t = html.escape(title, quote=True)
    d = html.escape(desc, quote=True)
    img = html.escape(image, quote=True)
    url = ""
    try:
        url = html.escape(f"{origin}{request.path}" if origin else request.url, quote=True)
    except Exception:
        url = img
    return (
        f"<meta property=\"og:site_name\" content=\"BR Fantasy\">"
        f"<meta property=\"og:type\" content=\"website\">"
        f"<meta property=\"og:title\" content=\"{t}\">"
        f"<meta property=\"og:description\" content=\"{d}\">"
        f"<meta property=\"og:url\" content=\"{url}\">"
        f"<meta property=\"og:image\" content=\"{img}\">"
        f"<meta name=\"twitter:card\" content=\"summary\">"
        f"<meta name=\"twitter:title\" content=\"{t}\">"
        f"<meta name=\"twitter:description\" content=\"{d}\">"
        f"<meta name=\"twitter:image\" content=\"{img}\">"
    )


def _site_json_ld() -> str:
    """Site-wide JSON-LD structured data (Organization + WebSite with search
    action) for richer search-engine understanding and sitelinks search box."""
    import json as _json
    origin = _site_origin()
    base = origin or ""
    data = [
        {
            "@context": "https://schema.org",
            "@type": "Organization",
            "name": "BR Fantasy",
            "url": base or "/",
            "logo": f"{base}/static/BR_Logo.png",
        },
        {
            "@context": "https://schema.org",
            "@type": "WebSite",
            "name": "BR Fantasy",
            "url": base or "/",
            "potentialAction": {
                "@type": "SearchAction",
                "target": f"{base}/players?q={{search_term_string}}",
                "query-input": "required name=search_term_string",
            },
        },
    ]
    return (
        "<script type=\"application/ld+json\">"
        + _json.dumps(data, separators=(",", ":"))
        + "</script>"
    )


def render_page(
        title: str,
        league_id: Optional[str],
        active: str,
        body_html: str,
        platform: Optional[str] = None,
        season: Optional[int] = None,
        *args,
        og_tags: str = "",
        description: str = "",
        canonical: Optional[str] = None,
        noindex: Optional[bool] = None,
        **kwargs,
) -> str:
    if league_id and platform and season:
        session["last_league_id"] = league_id
        session["last_platform"] = platform
        session["last_season"] = season
    # For public pages (no league context), inherit the session's last league so
    # SIGNED-IN visitors keep their league nav. A logged-out visitor gets the
    # guest nav even if the session still remembers a league from a public/shared
    # view — otherwise a one-time league peek sticks them with league chrome.
    _nav_lid      = league_id or session.get("last_league_id") or None
    _nav_platform = platform  or session.get("last_platform")  or None
    _nav_season_raw = session.get("last_season") if not season else None
    _nav_season   = season or (int(_nav_season_raw) if _nav_season_raw else None)
    _signed_in    = bool(session.get("viewer_username"))
    # League chrome (top nav + bottom dock) on real league pages, and on public
    # pages only for signed-in users with a remembered league. Everyone logged out
    # gets the guest chrome so the top nav and the dock always agree.
    _league_chrome = bool(
        _nav_lid and _nav_platform and _nav_season and (bool(league_id) or _signed_in)
    )
    nav_html = (build_nav(_nav_lid, active, _nav_platform, _nav_season)
                if _league_chrome
                else build_nav(None, active, _nav_platform, _nav_season))

    # Lightweight public pages (lite_js=True) serve the slim public.js to
    # logged-out visitors to cut mobile parse/Total-Blocking-Time. Logged-in
    # users always get the full app.js (they need modals, trade tools, etc.).
    _use_lite = bool(kwargs.get("lite_js")) and not session.get("viewer_username")
    _page_js_file = _PUBLIC_JS_FILE if _use_lite else _APP_JS_FILE
    _page_js_v = _PUBLIC_JS_V if _use_lite else _APP_JS_V

    meta_tags = _build_seo_meta_tags(
        description, canonical, noindex,
        is_league_scoped=bool(league_id and platform and season),
    )

    # Pages may pass their own richer og_tags; otherwise emit sensible defaults
    # so every shared link gets a preview card.
    if not og_tags:
        og_tags = _default_social_tags(title, description)
    json_ld = _site_json_ld()

    banner_html = _discord_banner()
    if session.get("viewer_username"):
        banner_html += _recap_ready_banner(league_id or "", platform or "", season or 0)
        banner_html += _draft_imminent_banner(
            _nav_lid or "", _nav_platform or "", _nav_season or 0, active,
        )

    wrapped_body = f"<div class='page-shell' data-page='{active}'>{body_html}</div>"
    # Mobile navigation: dynamic bottom dock + full "More" sheet (phones only,
    # league pages only). Appended as fixed siblings; CSS reserves space so the
    # dock never overlaps content. `.has-tabbar` also carries the active key so
    # CSS can keep the top bar (logo only) on the dashboard and hide it elsewhere.
    # The dock renders OUTSIDE #page-root (in the {bottom_nav} slot) so a soft-nav
    # swap of #page-root never destroys and repaints it - the JS reconciles its
    # active tab in place instead (mirrors how the desktop top nav persists). The
    # .has-tabbar wrapper stays inside page-root to reserve space for the fixed dock.
    _bottom = _mobile_nav(active, _nav_lid, _nav_platform, _nav_season) if _league_chrome else ""
    # Logged-out visitors get the league-less dock (incl. the landing page), so
    # every public page has the same bottom nav on phones as the league pages do.
    if not _bottom:
        _bottom = _mobile_nav_guest(active)
    if _bottom:
        wrapped_body = f"<div class='has-tabbar' data-active='{active}'>{wrapped_body}</div>"

    user_id = session.get("viewer_username")
    is_premium = has_premium_for_viewer(user_id, session.get("viewer_user_id"), league_id, platform or "sleeper", season)

    # Viewer context for client JS (player-modal roster context, etc.)
    viewer_roster_id = session.get("viewer_roster_id") or ""
    viewer_user_id   = session.get("viewer_user_id") or ""

    import json as _json
    html = BASE_HTML.format(
        title=title,
        meta_tags=meta_tags,
        og_tags=og_tags,
        json_ld=json_ld,
        nav=nav_html,
        recap_banner=banner_html,
        body=wrapped_body,
        bottom_nav=_bottom,
        cache_ts=int(time.time() * 1000),
        user_premium="true" if is_premium else "false",
        adsense_script="" if is_premium else _AD_SCRIPT,
        ad_top="" if is_premium else _AD_TOP,
        ad_bottom="" if is_premium else _AD_BOTTOM,
        adsense_init="" if is_premium else _AD_INIT,
        about_url=f"/{platform}/{season}/{league_id}/about" if (league_id and platform and season) else "/about",
        guides_url=f"/{platform}/{season}/{league_id}/guides" if (league_id and platform and season) else "/guides",
        privacy_url=f"/{platform}/{season}/{league_id}/privacy" if (league_id and platform and season) else "/privacy",
        terms_url=f"/{platform}/{season}/{league_id}/terms" if (league_id and platform and season) else "/terms",
        faq_url=f"/{platform}/{season}/{league_id}/faq" if (league_id and platform and season) else "/faq",
        support_url=f"/{platform}/{season}/{league_id}/support" if (league_id and platform and season) else "/support",
        contact_url=f"/{platform}/{season}/{league_id}/contact" if (league_id and platform and season) else "/contact",
        yt_url="https://youtube.com/@hoodiekj",
        app_js_file=_page_js_file,
        sentry_js=_SENTRY_JS_SNIPPET,
        plotly_loader=_PLOTLY_LOADER,
        app_js_v=_page_js_v,
        paywall_js_v=_PAYWALL_JS_V,
        css_file=_CSS_FILE,
        css_v=_CSS_V,
        fa_v=_FA_V,
        icons_v=_ICONS_V,
        viewer_roster_id_js=_json.dumps(str(viewer_roster_id)),
        viewer_user_id_js=_json.dumps(str(viewer_user_id)),
        signed_in_js="true" if session.get("viewer_username") else "false",
    )
    resp = make_response(html)
    resp.headers['Cache-Control'] = 'no-store, no-cache, must-revalidate, max-age=0'
    resp.headers['Pragma'] = 'no-cache'
    return resp


from utils.validation import (  # noqa: E402
    safe_int as _safe_int,
    validate_league_id,
)


def has_draft_ended(league_id: str, platform: str, season: int) -> bool:
    """
    Check if the draft has ended for a given league/season.
    Returns True if draft ended, False if not yet started or in progress.
    """
    try:
        ctx = get_league_ctx_from_cache(platform, league_id, season)
        if not ctx:
            return False

        latest_draft = ctx.get("latest_draft")
        league = ctx.get("league")

        draft_ts_ms = None
        if isinstance(latest_draft, dict):
            draft_ts_ms = _safe_int(latest_draft.get("start_time"))
        if draft_ts_ms is None:
            draft_ts_ms = _safe_int(league.get("draft_day"))

        if not draft_ts_ms:
            return False

        draft_dt = datetime.fromtimestamp(draft_ts_ms / 1000, tz=EASTERN)
        now_dt = datetime.now(EASTERN)
        return now_dt > draft_dt
    except Exception:
        return False


