def ensure_weekly_bits(ctx: dict) -> None:
    """
    Lazily populate projections, statuses, matchups, and df_weekly['proj']
    into the ctx. Only used by Dashboard + Weekly Hub + related APIs.
    """

    if ctx.get("offseason_mode"):
        # Load pre-season projections for all 18 weeks
        ctx["proj_by_week"] = build_projections_by_week(int(ctx["season"]), 18, ctx.get("raw_scoring_settings"))
        ctx["statuses"] = {}
        if "matchups_by_week" not in ctx:
            try:
                ctx["matchups_by_week"] = build_matchups_by_week(
                    ctx.get("resolved_league_id", ctx["league_id"]),
                    range(1, 19),
                    ctx.get("roster_map") or {},
                    ctx.get("players") or {},
                    int(ctx["season"]),
                    ctx["platform"],
                )
            except Exception:
                ctx["matchups_by_week"] = {}
        # Compute projected team totals so highlights / matchup preview work
        try:
            ctx["proj_by_roster"] = compute_team_projections_for_weeks(
                ctx["matchups_by_week"],
                {},  # no statuses in offseason
                ctx["proj_by_week"],
                ctx.get("roster_map") or {},
            )
        except Exception:
            ctx["proj_by_roster"] = {}
        return

    def _apply_proj_column() -> None:
        df = ctx.get("df_weekly")
        proj_by_roster = ctx.get("proj_by_roster", {})

        if df is None or df.empty:
            return

        if "week" not in df.columns or "roster_id" not in df.columns:
            return

        key_series = list(zip(df["week"].astype(int), df["roster_id"].astype(str)))
        df = df.copy()
        df["proj"] = [proj_by_roster.get(k, float("nan")) for k in key_series]
        ctx["df_weekly"] = df

    # If already populated, just ensure df_weekly has proj
    if all(k in ctx for k in ("proj_by_week", "statuses", "matchups_by_week", "proj_by_roster")):
        if "proj" not in ctx.get("df_weekly", pd.DataFrame()).columns:
            _apply_proj_column()
        return

    viewed_season = int(ctx["season"])
    weeks = int(ctx["weeks"])
    platform = ctx["platform"]
    league_id = ctx.get("resolved_league_id", ctx["league_id"])
    players = ctx["players"]
    players_index = ctx["players_index"]
    teams_index = ctx["teams_index"]
    roster_map = ctx["roster_map"]

    roster_counts = count_roster_positions(get_roster_positions())
    has_idp = any(k in roster_counts for k in ["DL", "LB", "DB", "IDP_FLEX"])

    proj_by_week = build_projections_by_week(viewed_season, weeks, ctx.get("raw_scoring_settings"))

    if has_idp:
        statuses = build_status_by_week(
            viewed_season,
            weeks,
            players_index,
            teams_index,
            load_idp_index(),
        )
    else:
        statuses = build_status_by_week(
            viewed_season,
            weeks,
            players_index,
            teams_index,
        )

    matchups_by_week = build_matchups_by_week(
        league_id,
        range(1, weeks + 1),
        roster_map,
        players,
        viewed_season,
        platform,
    )

    proj_by_roster = compute_team_projections_for_weeks(
        matchups_by_week,
        statuses,
        proj_by_week,
        roster_map,
    )

    ctx["proj_by_week"] = proj_by_week
    ctx["statuses"] = statuses
    ctx["matchups_by_week"] = matchups_by_week
    ctx["proj_by_roster"] = proj_by_roster

    _apply_proj_column()


def refresh_league_ctx_section(platform: str, league_id: str, page: str, season: int,
                               full: bool = False) -> dict:
    """Refresh the cached league context. By default only the sections the given
    page needs are re-fetched; with ``full=True`` every page's sections are
    rebuilt and all cached page HTML is cleared, so a single refresh makes the
    whole site fresh (the other pages you navigate to next, too)."""
    key = _cache_key(platform, season, league_id)
    entry = DASHBOARD_CACHE.get(key)

    if not entry:
        ctx = build_league_context(platform, league_id, season)
        _prune_dashboard_cache()
        DASHBOARD_CACHE[key] = {"ctx": ctx, "ts": time.time(), "page_html": {}}
        return ctx

    ctx = entry["ctx"]

    viewed_season = int(ctx.get("season") or season)
    current_season = int(ctx.get("current_season") or viewed_season)
    current_week = int(ctx.get("current_week") or 0)
    weeks = int(ctx.get("weeks") or 0)
    season_type = (ctx.get("season_type") or "").lower()
    season_complete = bool(ctx.get("season_complete", False))
    offseason_mode = bool(ctx.get("offseason_mode", False))
    resolved_league_id = ctx.get("resolved_league_id", league_id)

    # ---------- Always refresh core league objects ----------
    # Clear TTL caches so rosters/traded picks reflect the latest transactions
    # on every refresh, not just the teams page.
    try:
        clear_activity_cache_for_league(resolved_league_id)
    except Exception:
        logger.debug("suppressed exception", exc_info=True)

    league = get_league(platform, resolved_league_id, viewed_season)
    users = get_users(platform, resolved_league_id, viewed_season)
    rosters = get_rosters(platform, resolved_league_id, viewed_season)

    traded = None
    if platform == "sleeper":
        try:
            traded = get_traded_picks(platform, resolved_league_id, viewed_season)
        except Exception:
            traded = ctx.get("traded")

    try:
        drafts = get_drafts(platform, resolved_league_id, viewed_season) or []
        latest_draft = get_most_recent_valid_draft_for_season(drafts, viewed_season)
    except Exception:
        drafts = ctx.get("drafts") or []
        latest_draft = ctx.get("latest_draft")

    ctx["league"] = league
    ctx["users"] = users
    ctx["rosters"] = rosters
    ctx["traded"] = traded
    ctx["drafts"] = drafts
    ctx["latest_draft"] = latest_draft

    players = ctx["players"]
    players_map = ctx["players_map"]
    players_index = ctx["players_index"]
    teams_index = ctx["teams_index"]

    # ---------- Rebuild roster_map every refresh ----------
    ctx["roster_map"] = _build_roster_map(users, rosters)

    # ---------- League settings / refs that can matter to multiple pages ----------
    sync_league_globals(platform, resolved_league_id, viewed_season)
    try:
        ctx["scoring_settings"] = get_effective_scoring_settings()
    except Exception as e:
        logger.info(f"[ctx] scoring_settings failed: {e}")

    try:
        ctx["roster_positions"] = get_roster_positions()
    except Exception as e:
        logger.info(f"[ctx] roster_positions failed: {e}")

    try:
        ctx["league_settings"] = get_league_settings()
    except Exception as e:
        logger.info(f"[ctx] league_settings failed: {e}")

    try:
        ctx["total_rosters"] = get_total_rosters()
    except Exception as e:
        logger.info(f"[ctx] total_rosters failed, falling back to len(rosters): {e}")
        ctx["total_rosters"] = len(rosters)

    roster_counts = count_roster_positions(get_roster_positions())
    has_idp = any(k in roster_counts for k in ["DL", "LB", "DB", "IDP_FLEX"])

    # ---------- Shared live / reference data ----------
    try:
        scores_body = get_nfl_scores_for_date(date.today().strftime("%Y%m%d"))
        ctx["team_game_lookup"] = build_team_game_lookup(scores_body)
    except Exception:
        logger.debug("suppressed exception", exc_info=True)

    # ---------- Standings / dashboard / weekly core tables ----------
    if full or page in ("standings", "dashboard", "weekly"):
        if offseason_mode:
            ctx["df_weekly"] = pd.DataFrame()
            ctx["team_stats"] = pd.DataFrame()
            ctx["standings_map"] = {}
        else:
            df_weekly, team_stats, fresh_roster_map = build_tables(
                league_id=resolved_league_id,
                max_week=weeks,
                players=players,
                users=users,
                rosters=rosters,
                season=viewed_season,
                platform=platform,
            )

            # Prefer fresh roster_map from build_tables if returned
            if isinstance(fresh_roster_map, dict) and fresh_roster_map:
                ctx["roster_map"] = fresh_roster_map
                roster_map = fresh_roster_map

            ctx["df_weekly"] = df_weekly
            ctx["team_stats"] = team_stats

            if team_stats is not None and not team_stats.empty and {"Wins", "PF"}.issubset(team_stats.columns):
                ctx["standings_map"] = build_standings_map(team_stats, roster_map)
            else:
                ctx["standings_map"] = {}

    # ---------- Activity / injuries ----------
    if full or page in ("activity", "dashboard"):
        clear_activity_cache_for_league(resolved_league_id)

        ctx["activity_df"] = build_week_activity(
            resolved_league_id,
            platform,
            viewed_season,
            players_map,
        )

        if has_idp:
            statuses = build_status_by_week(
                viewed_season,
                weeks,
                players_index,
                teams_index,
                load_idp_index(),
            )
        else:
            statuses = build_status_by_week(
                viewed_season,
                weeks,
                players_index,
                teams_index,
            )

        ctx["statuses"] = statuses

        ctx["injury_df"] = build_injury_report(
            resolved_league_id,
            players,
            roster_map,
            rosters,
            "America/New_York",
            False,
        )

    # ---------- Weekly / dashboard projections & matchups ----------
    if full or page in ("weekly", "dashboard"):
        clear_weekly_cache_for_league(resolved_league_id)

        if offseason_mode:
            ctx["proj_by_week"] = build_projections_by_week(viewed_season, 18, ctx.get("raw_scoring_settings"))
            ctx["statuses"] = {}
            ctx["matchups_by_week"] = build_matchups_by_week(
                resolved_league_id,
                range(1, 19),
                roster_map,
                players,
                viewed_season,
                platform,
            )
            ctx["proj_by_roster"] = {}
        else:
            should_refresh_live_week = (
                    viewed_season == current_season
                    and not season_complete
                    and not offseason_mode
                    and current_week > 0
                    and season_type != "off"
            )

            if should_refresh_live_week:
                try:
                    live_game_ids = get_live_game_ids_for_today(
                        load_week_schedule(current_season, current_week)
                    )
                    build_and_save_week_stats_for_league(
                        load_teams_index(),
                        current_season,
                        current_week,
                        live_game_ids,
                    )
                except Exception as e:
                    logger.info(f"[refresh] live week stats refresh skipped: {e}")

                try:
                    get_week_projections_cached(
                        current_season,
                        current_week,
                        fetch_week_projections,
                        force_refresh=True,
                    )
                except Exception as e:
                    logger.info(f"[refresh] live projections refresh skipped: {e}")

            ctx["proj_by_week"] = build_projections_by_week(viewed_season, weeks, ctx.get("raw_scoring_settings"))

            if has_idp:
                ctx["statuses"] = build_status_by_week(
                    viewed_season,
                    weeks,
                    players_index,
                    teams_index,
                    load_idp_index(),
                )
            else:
                ctx["statuses"] = build_status_by_week(
                    viewed_season,
                    weeks,
                    players_index,
                    teams_index,
                )

            ctx["matchups_by_week"] = build_matchups_by_week(
                resolved_league_id,
                range(1, weeks + 1),
                roster_map,
                players,
                viewed_season,
                platform,
            )

            proj_by_roster = compute_team_projections_for_weeks(
                ctx["matchups_by_week"],
                ctx["statuses"],
                ctx["proj_by_week"],
                roster_map,
            )
            ctx["proj_by_roster"] = proj_by_roster

            df = ctx.get("df_weekly")
            if df is not None and not df.empty and "week" in df.columns and "roster_id" in df.columns:
                key_series = list(zip(df["week"].astype(int), df["roster_id"].astype(str)))
                df = df.copy()
                df["proj"] = [proj_by_roster.get(k, float("nan")) for k in key_series]
                ctx["df_weekly"] = df

    # ---------- Teams page ----------
    if full or page == "teams":
        # Rosters/traded already re-fetched from cleared cache in core section above.
        ctx["model_value_table"] = ctx.get("model_value_table") or list(get_model_value_table_cached() or [])

        if platform == "sleeper":
            try:
                _teams_draft_ts = None
                if isinstance(latest_draft, dict):
                    _teams_draft_ts = _safe_int(latest_draft.get("start_time"))
                if _teams_draft_ts is None:
                    _teams_draft_ts = _safe_int(league.get("draft_day"))
                _teams_draft_ended = (
                    datetime.now(EASTERN) > datetime.fromtimestamp(_teams_draft_ts / 1000, tz=EASTERN)
                    if _teams_draft_ts else False
                )
                ctx["picks_by_roster"] = build_picks_by_roster(
                    num_future_seasons=3,
                    league=league,
                    rosters=rosters,
                    traded=traded,
                    draft_ended=_teams_draft_ended,
                )
            except Exception as e:
                logger.info(f"[refresh] teams picks refresh skipped: {e}")

    # ---------- Trade page ----------
    if full or page == "trade":
        # Keep the shared table fresh so the trade calc reflects newest values
        ctx["model_value_table"] = ctx.get("model_value_table") or list(get_model_value_table_cached() or [])

        # also refresh global model-value API cache used by /api/trade-eval
        global _MODEL_VALUE_CACHE, _MODEL_VALUE_CACHE_TS
        _MODEL_VALUE_CACHE = ctx["model_value_table"]
        _MODEL_VALUE_CACHE_TS = time.time()

    # ---------- Offseason dashboard refresh ----------
    if (full or page == "dashboard") and offseason_mode:
        ctx["model_value_table"] = ctx.get("model_value_table") or list(get_model_value_table_cached() or [])

        if platform == "sleeper":
            try:
                _ref_draft_ts = None
                if isinstance(latest_draft, dict):
                    _ref_draft_ts = _safe_int(latest_draft.get("start_time"))
                if _ref_draft_ts is None:
                    _ref_draft_ts = _safe_int(league.get("draft_day"))
                _ref_draft_ended = (
                    datetime.now(EASTERN) > datetime.fromtimestamp(_ref_draft_ts / 1000, tz=EASTERN)
                    if _ref_draft_ts else False
                )
                ctx["picks_by_roster"] = build_picks_by_roster(
                    num_future_seasons=3,
                    league=league,
                    rosters=rosters,
                    traded=traded,
                    draft_ended=_ref_draft_ended,
                )
            except Exception as e:
                logger.info(f"[refresh] picks refresh skipped: {e}")

        # These aren't strictly required because build_offseason_dashboard_body can rebuild
        # from ctx, but keeping them fresh helps consistency if reused elsewhere.
        try:
            ctx["teams_overview"] = build_teams_overview(
                rosters=rosters,
                users_list=users,
                picks_by_roster=ctx.get("picks_by_roster", {}),
                players=players_map,
                players_index=players_index,
                teams_index=teams_index,
                platform=platform,
            )
        except Exception as e:
            logger.info(f"[refresh] teams overview refresh skipped: {e}")

    # ---------- Invalidate rendered HTML cache for refreshable pages ----------
    page_html = entry.setdefault("page_html", {})
    if full or page == "dashboard":
        for p in ("dashboard", "activity", "teams", "graphs", "standings", "weekly"):
            page_html.pop(p, None)
    else:
        page_html.pop(page, None)

    entry["ts"] = time.time()
    return ctx


def render_standings_compact(team_stats, length=None, movement=None) -> str:
    """Narrow standings for the dashboard left rail: Rank · Team · Record · PF.

    The full render_standings table has 8 columns and is too wide for a 340px
    sidebar; this trims to the essentials so it fits. ``movement`` is an optional
    {owner: delta} map (positive = climbed since last week) rendered as a small
    arrow next to the rank.
    """
    if team_stats is None or team_stats.empty:
        return "<div class='muted' style='padding:12px 14px;'>No standings data yet.</div>"

    movement = movement or {}
    df = team_stats.copy()
    df = df.sort_values(by=["Wins", "PF", "PA"], ascending=[False, False, True]).reset_index(drop=True)
    df["Rank"] = df.index + 1

    rows = []
    for _, row in df.iterrows():
        record = f"{int(row['Wins'])}-{int(row['Losses'])}"
        if int(row.get("Ties", 0) or 0):
            record += f"-{int(row['Ties'])}"
        avatar = row.get("avatar", "")
        img = (
            f"<img class='avatar sm' src='{avatar}' alt='' loading='lazy' decoding='async' onerror=\"this.style.display='none'\">"
            if avatar else ""
        )
        _mv = movement.get(str(row["owner"]))
        mv_html = ""
        if _mv:
            if _mv > 0:
                mv_html = f"<span class='rank-move up' title='Up {_mv} since last week'>&#9650;{_mv}</span>"
            elif _mv < 0:
                mv_html = f"<span class='rank-move down' title='Down {abs(_mv)} since last week'>&#9660;{abs(_mv)}</span>"
        rows.append(f"""
            <tr>
              <td class="num">{int(row['Rank'])}{mv_html}</td>
              <td class="team">{img} {html.escape(str(row['owner']))}</td>
              <td>{record}</td>
              <td>{row['PF']:.0f}</td>
            </tr>""")

    if length:
        rows = rows[:length]

    return f"""
        <table class="standings-table standings-compact" data-page="standings">
          <thead>
            <tr><th scope='col'>#</th><th scope='col'>Team</th><th scope='col'>Rec</th><th scope='col'>PF</th></tr>
          </thead>
          <tbody>
            {''.join(rows)}
          </tbody>
        </table>
    """


def _ord_str(n) -> str:
    """Ordinal string: 1 -> '1st', 2 -> '2nd', 11 -> '11th'. Delegates to the
    shared, unit-tested utils.format.ordinal (kept as a thin alias so existing
    call sites don't change)."""
    from utils.format import ordinal
    return ordinal(n)


def _all_play_from_df_weekly(df_weekly) -> dict:
    """All-play / luck analysis keyed by owner name, from finalized weeks."""
    try:
        if df_weekly is None or df_weekly.empty or "finalized" not in df_weekly.columns:
            return {}
        fin = df_weekly[df_weekly["finalized"] == True]
        if fin.empty:
            return {}
        weekly_scores: dict = {}
        actual_wins: dict = {}
        for _, r in fin.iterrows():
            wk = int(r["week"])
            owner = str(r["owner"])
            weekly_scores.setdefault(wk, {})[owner] = float(r["points"] or 0)
            actual_wins[owner] = actual_wins.get(owner, 0.0) + float(r["win"] or 0)
        from utils.all_play import all_play_analysis
        return all_play_analysis(weekly_scores, actual_wins)
    except Exception:
        logger.debug("all-play analysis failed", exc_info=True)
        return {}


def render_standings(team_stats, length, all_play: dict = None,
                     playoff_spots: int = None, total_regular_weeks: int = None,
                     movement: dict = None) -> str:
    if team_stats is None or team_stats.empty:
        return """
        <div class="card-body">
          <p>No standings data available for this season yet.</p>
        </div>
        """

    rows = []

    df = team_stats.copy()
    df["WinPct"] = df["Win%"].astype(float)
    df = (
        df.sort_values(
            by=["Wins", "PF", "PA"],
            ascending=[False, False, True],
        )
        .reset_index(drop=True)
    )

    df["Rank"] = df.index + 1

    # ── Playoff picture (optional; enriches rows with clinch/seed status) ──────
    pic_by_name: dict = {}
    ctx_line = ""
    _spots = None
    if playoff_spots and total_regular_weeks:
        try:
            from utils.playoff_picture import compute_playoff_picture, bye_count
            _teams = [
                {"id": str(rr["owner"]), "name": str(rr["owner"]),
                 "wins": int(rr["Wins"]), "losses": int(rr["Losses"]),
                 "ties": int(rr.get("Ties", 0) or 0), "pf": float(rr["PF"])}
                for _, rr in df.iterrows()
            ]
            _pic = compute_playoff_picture(_teams, int(playoff_spots), int(total_regular_weeks))
            pic_by_name = {p["name"]: p for p in _pic}
            _spots = int(playoff_spots)
            _byes = bye_count(_spots)
            _left = max((p["games_left"] for p in _pic), default=0)
            _bye_txt = f" · top {_byes} get a bye" if _byes else ""
            _left_txt = f" · {_left} to play" if _left else " · regular season complete"
            ctx_line = (
                "<div class='pp-ctx'>"
                f"<span class='pp-ctx-main'>Top {_spots} advance{_bye_txt}{_left_txt}</span>"
                "<span class='pp-legend'>"
                "<span class='pp-lg'><i class='pp-dot pp-d-bye'></i>Bye</span>"
                "<span class='pp-lg'><i class='pp-dot pp-d-in'></i>Clinched / In</span>"
                "<span class='pp-lg'><i class='pp-dot pp-d-bub'></i>Bubble</span>"
                "<span class='pp-lg'><i class='pp-dot pp-d-out'></i>Eliminated</span>"
                "</span></div>"
            )
        except Exception:
            logger.debug("[standings] playoff picture skipped", exc_info=True)
            pic_by_name, _spots = {}, None

    _STATUS_CLS = {"bye": "pp-bye", "clinched": "pp-clinched", "in": "pp-in",
                   "bubble": "pp-bubble", "eliminated": "pp-out"}

    def _pp_tag(p):
        st = p["status"]
        if st == "bye":
            return "<span class='pp-tag pp-t-bye'>BYE</span>"
        if st == "clinched":
            return "<span class='pp-tag pp-t-in'>CLINCHED</span>"
        if st == "eliminated":
            return "<span class='pp-tag pp-t-out'>OUT</span>"
        if st == "bubble":
            if p["seed"] > (_spots or 0) and p["games_back"] > 0:
                return f"<span class='pp-tag pp-t-bub'>{p['games_back']:g} GB</span>"
            return "<span class='pp-tag pp-t-bub'>BUBBLE</span>"
        return ""  # "in" carries the green accent, no tag needed

    for _, row in df.iterrows():
        record = f"{int(row['Wins'])}-{int(row['Losses'])}"
        if int(row.get("Ties", 0)):
            record += f"-{int(row['Ties'])}"

        streak = row.get("Streak", "")
        avatar = row.get("avatar", "")

        img = (
            f"<img class='avatar sm' src='{avatar}' alt='' loading='lazy' decoding='async' "
            "onerror=\"this.style.display='none'\">"
            if avatar else ""
        )

        _ap = (all_play or {}).get(str(row['owner'])) or {}
        _luck = _ap.get('luck_delta')
        if _luck is None:
            _luck_cell = "<span class='muted'>&ndash;</span>"
        else:
            _lcls = 'luck-pos' if _luck >= 1 else ('luck-neg' if _luck <= -1 else 'luck-neu')
            _lsign = '+' if _luck > 0 else ''
            _luck_cell = f"<span class='luck-chip {_lcls}' title='Actual wins minus expected wins from all-play'>{_lsign}{_luck:.1f}</span>"
        _seed = _ap.get('expected_seed')
        _seed_cell = _ord_str(_seed) if _seed else "<span class='muted'>&ndash;</span>"

        owner = str(row['owner'])
        _p = pic_by_name.get(owner)
        _trcls = ""
        _tdcls = "team"
        _mo_attr = ""
        if _p:
            _trcls = _STATUS_CLS.get(_p["status"], "")
            _tdcls = "team pp-team-cell"
            _tag = _pp_tag(_p)
            # Clinch moment: a team that has locked a playoff spot gets a green
            # stamp + glow the first time its row scrolls into view.
            if _p["status"] in ("clinched", "bye"):
                _mo_attr = ' data-br-moment="clinch"'
            # Flex line: the name ellipsizes, the status tag never clips (wraps
            # under the name on very tight widths rather than getting cut off).
            team_cell = (
                f"<div class='pp-teamline'>{img}"
                f"<span class='pp-team-name'>{html.escape(owner)}</span>{_tag}</div>"
            )
        else:
            team_cell = f"{img} {html.escape(owner)}"

        # Week-over-week seed movement (positive = climbed). Same arrows as the
        # compact standings; blank when there's no prior week to compare.
        _mv = (movement or {}).get(owner)
        mv_html = ""
        if _mv:
            if _mv > 0:
                mv_html = f"<span class='rank-move up' title='Up {_mv} since last week'>&#9650;{_mv}</span>"
            elif _mv < 0:
                mv_html = f"<span class='rank-move down' title='Down {abs(_mv)} since last week'>&#9660;{abs(_mv)}</span>"

        rows.append(f"""
            <tr class="{_trcls}"{_mo_attr} data-rk-key="{html.escape(owner, quote=True)}">
              <td class="num rank-cell">{rank_mark(int(row['Rank']), size=28, ring_others=False)}{mv_html}</td>
              <td class="{_tdcls}">{team_cell}</td>
              <td>{record}</td>
              <td>{row['PF']:.1f}</td>
              <td>{row['PA']:.1f}</td>
              <td>{streak}</td>
              <td>{_luck_cell}</td>
              <td>{_seed_cell}</td>
              <td>{row.get('past_sos', 0.0):.1f}</td>
              <td>{row.get('ros_sos', 0.0):.1f}</td>
            </tr>
        """)

        # Clinch scenario for the teams straddling the line: one full-width row
        # under the team, so the sentence never wraps inside the narrow cell.
        if (_p and _p.get("scenario") and _p["status"] == "bubble"
                and _p["seed"] in (_spots, (_spots or 0) + 1)):
            rows.append(
                "<tr class='pp-scnrow'><td colspan='10'>"
                f"<div class='pp-scn'>{html.escape(_p['scenario'])}</div></td></tr>"
            )

        # Draw the playoff cutoff line right below the last team that advances.
        if _spots and int(row['Rank']) == _spots and _spots < len(df):
            rows.append(
                "<tr class='pp-cutrow'><td colspan='10'>"
                "<div class='pp-cut'>Playoff line</div></td></tr>"
            )

    if _spots:
        total_rows = rows          # cutoff rows shift the count; show every team
    else:
        total_rows = rows[:length] if len(rows) != length else rows

    return f"""
        {ctx_line}
        <table class="standings-table" data-page="standings">
          <thead>
            <tr>
              <th scope="col">Seed</th>
              <th scope="col">Team</th>
              <th scope="col">Record</th>
              <th scope="col">PF</th>
              <th scope="col">PA</th>
              <th scope="col">Streak</th>
              <th scope="col" title="Actual wins minus expected wins (from all-play). + = luckier than your scoring earned.">Luck</th>
              <th scope="col" title="Where you'd be seeded by all-play record instead of actual wins.">Exp. Seed</th>
              <th scope="col">SOS Past</th>
              <th scope="col">SOS Future</th>
            </tr>
          </thead>
          <tbody>
            {''.join(total_rows)}
          </tbody>
        </table>
    """


def _section_title_link(title: str, endpoint: str, platform, season, league_id) -> str:
    """Render a collapsible section's <h2> title as the link to its full page.

    Replaces the older pattern of a plain title plus a separate 'view the full
    page' link in the header: the title itself is now the single, larger click
    target, so there's no redundant button. Falls back to a plain (unlinked)
    title if the URL can't be built, so callers can use it without guarding.
    """
    safe_title = html.escape(title)
    try:
        href = url_for(endpoint, platform=platform, season=season, league_id=str(league_id))
    except Exception:
        return f'<h2 class="os-section-title">{safe_title}</h2>'
    return (
        '<h2 class="os-section-title">'
        f'<a class="os-section-title-link" href="{html.escape(href)}">{safe_title}'
        ' <span class="os-section-title-arrow" aria-hidden="true">&rarr;</span></a></h2>'
    )


def _standings_movement(df_weekly) -> dict:
    """Week-over-week standings-rank movement per owner, from finalized weeks.

    Ranks teams by (cumulative wins, cumulative points-for) through the last
    finalized week and through the week before, returning {owner: prev_rank -
    cur_rank} where positive means the team climbed. Empty until 2+ finalized
    weeks exist. Arrows are decorative, so any failure returns {} quietly.
    """
    try:
        fin = df_weekly[df_weekly["finalized"] == True]
        if fin.empty:
            return {}
        weeks = sorted(int(w) for w in fin["week"].unique())
        if len(weeks) < 2:
            return {}
        cur_w, prev_w = weeks[-1], weeks[-2]

        def _rank_through(wk):
            sub = fin[fin["week"] <= wk]
            agg = (
                sub.groupby("owner")
                .agg(W=("win", "sum"), PF=("points", "sum"))
                .reset_index()
                .sort_values(by=["W", "PF"], ascending=[False, False])
                .reset_index(drop=True)
            )
            return {str(r["owner"]): i + 1 for i, r in agg.iterrows()}

        cur = _rank_through(cur_w)
        prev = _rank_through(prev_w)
        return {o: (prev[o] - cur[o]) for o in cur if o in prev}
    except Exception:
        logger.debug("standings movement failed", exc_info=True)
        return {}


def _render_usage_movers(ctx: dict, viewer_roster_id) -> str:
    """Compact strip of the viewer's rostered players whose recent usage is
    rising fastest — last-3-week average vs season average of the position's
    key volume stat (QB snap %, RB touches, WR/TE targets). Returns '' when
    there's nothing meaningful to show."""
    if not viewer_roster_id:
        return ""
    try:
        rosters = ctx.get("rosters") or []
        roster = next(
            (r for r in rosters if str(r.get("roster_id")) == str(viewer_roster_id)),
            None,
        )
        if not roster:
            return ""
        pids = {
            str(p) for p in (roster.get("players") or [])
            if str(p) not in {"0", "", "None"}
        }
        if not pids:
            return ""

        season = int(ctx.get("current_season") or 0)
        from data_building.weekly_metrics import get_usage_trends
        trends = get_usage_trends(season) or {}
        players_index = ctx.get("players_index") or {}
        _stat_lbl = {"snap_pct": "snap%", "touches": "touches", "targets": "targets"}

        movers = []
        for pid in pids:
            t = trends.get(pid)
            if not t:
                continue
            delta = t.get("delta")
            # Genuine risers only (matches the card title); ignore noise and
            # players without enough weeks to trust the trend.
            if delta is None or delta < 1.5 or int(t.get("weeks_played") or 0) < 3:
                continue
            pmeta = players_index.get(pid) or {}
            name = pmeta.get("full_name") or pmeta.get("name") or f"Player {pid}"
            movers.append((float(delta), str(name), t))
        if not movers:
            return ""
        movers.sort(key=lambda x: x[0], reverse=True)
        movers = movers[:3]  # concise: top risers only

        rows = []
        for delta, name, t in movers:
            stat = _stat_lbl.get(t.get("stat"), t.get("stat") or "")
            avg = float(t.get("season_avg") or 0)
            recent = float(t.get("recent_avg") or 0)
            rows.append(f"""
              <li class="usage-mover">
                <span class="um-name">{html.escape(name)}</span>
                <span class="um-detail">{stat} {avg:g}&rarr;{recent:g}</span>
                <span class="um-delta up">&#9650;{delta:g}</span>
              </li>""")

        return f"""
        <section class="os-card usage-movers-card">
          <div class="os-section-head">
            <div class="os-section-head-content">
              <h2 class="os-section-title">Usage risers</h2>
              <div class="os-section-subtitle">Your players trending up in snaps &amp; touches</div>
            </div>
          </div>
          <ul class="usage-movers-list">{''.join(rows)}</ul>
        </section>"""
    except Exception:
        logger.debug("usage movers failed", exc_info=True)
        return ""


def _viewer_lineup_alert_html(ctx: dict, viewer_roster_id) -> str:
    """Warning strip for the Season Hub when the viewer's current starters have
    problems: empty slots, serious injury designations, or byes. Empty string
    when the lineup is clean or the viewer has no team."""
    if not viewer_roster_id:
        return ""
    try:
        from utils.lineup_issues import find_lineup_issues

        rosters = ctx.get("rosters") or []
        roster = next(
            (r for r in rosters if str(r.get("roster_id")) == str(viewer_roster_id)),
            None,
        )
        if not roster:
            return ""
        starters = [str(p) for p in (roster.get("starters") or [])]
        if not starters:
            return ""

        season = int(ctx.get("current_season") or 0)
        current_week = int(ctx.get("current_week") or 0)
        players_map = ctx.get("players_map") or {}

        # Injury designations live only on the full Sleeper players feed.
        try:
            full_players = get_players_global() or {}
        except Exception:
            full_players = {}

        player_info = {}
        for pid in starters:
            base = players_map.get(pid) or {}
            full = full_players.get(pid) or {}
            player_info[pid] = {
                "name": base.get("name") or full.get("full_name") or "",
                "team": base.get("team") or full.get("team") or "",
                "injury_status": full.get("injury_status") or "",
            }

        # Teams with a game this week; empty set skips bye detection.
        teams_playing = set()
        try:
            for g in (load_week_schedule(season, current_week) or []):
                for side in ("home", "away"):
                    t = str(g.get(side) or "").upper()
                    if t:
                        teams_playing.add(t)
        except Exception:
            teams_playing = set()

        issues = find_lineup_issues(starters, player_info, teams_playing)

        # Projection-based upgrades: bench players out-projecting a starter at
        # the same position this week (legal like-for-like swaps only).
        try:
            from utils.lineup_issues import projection_upgrades

            proj_map = {
                str(k): v
                for k, v in (
                    ((ctx.get("proj_by_week") or {}).get(current_week) or {}).get("projections") or {}
                ).items()
            }
            reserve_set = {str(p) for p in (roster.get("reserve") or [])}
            taxi_set = {str(p) for p in (roster.get("taxi") or [])}
            eligible = [
                str(p) for p in (roster.get("players") or [])
                if str(p) not in reserve_set and str(p) not in taxi_set
            ]
            pos_map = {
                pid: str((players_map.get(pid) or {}).get("pos")
                         or (full_players.get(pid) or {}).get("position") or "")
                for pid in eligible
            }
            roster_positions = ctx.get("roster_positions")
            if roster_positions is not None and hasattr(roster_positions, "tolist"):
                roster_positions = roster_positions.tolist()
            swaps = projection_upgrades(
                starters, eligible, proj_map, pos_map, roster_positions or []
            )
            for s in swaps:
                _in_name = (players_map.get(s["in"]) or {}).get("name") or f"Player {s['in']}"
                _out_name = (players_map.get(s["out"]) or {}).get("name") or f"Player {s['out']}"
                _in_proj = float(proj_map.get(s["in"]) or 0)
                _out_proj = float(proj_map.get(s["out"]) or 0)
                issues.append({
                    "kind": "projection", "pid": s["in"], "name": _in_name,
                    "detail": (
                        f"{_in_name} projects {_in_proj:.1f} on your bench; "
                        f"{_out_name} is starting at {_out_proj:.1f}"
                    ),
                })
        except Exception:
            logger.debug("projection upgrades failed", exc_info=True)

        if not issues:
            return ""

        platform = ctx.get("platform", "sleeper")
        league_id = ctx.get("league_id", "")
        fix_url = url_for(
            "league_pages.page_waivers", platform=platform, season=season, league_id=league_id
        ) + "?tab=startsit"
        n = len(issues)
        title = f"{n} lineup issue" + ("s" if n > 1 else "")
        items = "".join(
            f"<li>{html.escape(i['detail'])}</li>" for i in issues[:6]
        )
        return f"""
        <section class="os-card lineup-alert-card">
          <div class="lineup-alert-head">
            <span class="lineup-alert-title">{title} for Week {current_week}</span>
            <a class="os-section-link" href="{fix_url}">Fix your lineup &rarr;</a>
          </div>
          <ul class="lineup-alert-list">{items}</ul>
        </section>"""
    except Exception:
        logger.debug("lineup alert failed", exc_info=True)
        return ""


def _roster_moves_alert_html(ctx: dict, viewer_roster_id) -> str:
    """Roster-efficiency card for the Season Hub: IR-eligible players wasting
    active spots, recovered players stuck in IR slots, and open taxi slots with
    stashable rookies. Empty string when the roster is fully efficient."""
    if not viewer_roster_id:
        return ""
    try:
        from utils.roster_compliance import roster_compliance_issues

        rosters = ctx.get("rosters") or []
        roster = next(
            (r for r in rosters if str(r.get("roster_id")) == str(viewer_roster_id)),
            None,
        )
        if not roster:
            return ""

        settings = (ctx.get("league") or {}).get("settings") or {}
        reserve_slots = int(settings.get("reserve_slots") or 0)
        taxi_slots = int(settings.get("taxi_slots") or 0)
        if reserve_slots <= 0 and taxi_slots <= 0:
            return ""  # league has neither IR nor taxi slots

        players_map = ctx.get("players_map") or {}
        try:
            full_players = get_players_global() or {}
        except Exception:
            full_players = {}

        pids = [str(p) for p in (roster.get("players") or [])]
        player_info = {}
        for pid in pids:
            base = players_map.get(pid) or {}
            full = full_players.get(pid) or {}
            player_info[pid] = {
                "name": base.get("name") or full.get("full_name") or "",
                "injury_status": full.get("injury_status") or "",
                "years_exp": full.get("years_exp"),
            }

        issues = roster_compliance_issues(
            players=pids,
            starters=[str(p) for p in (roster.get("starters") or [])],
            reserve=[str(p) for p in (roster.get("reserve") or [])],
            taxi=[str(p) for p in (roster.get("taxi") or [])],
            player_info=player_info,
            reserve_slots=reserve_slots,
            taxi_slots=taxi_slots,
        )
        if not issues:
            return ""

        n = len(issues)
        title = f"{n} roster move" + ("s" if n > 1 else "") + " available"
        items = "".join(
            f"<li>{html.escape(i['detail'])}</li>" for i in issues[:5]
        )
        return f"""
        <section class="os-card lineup-alert-card roster-moves-card">
          <div class="lineup-alert-head">
            <span class="lineup-alert-title">{title}</span>
          </div>
          <ul class="lineup-alert-list">{items}</ul>
        </section>"""
    except Exception:
        logger.debug("roster moves alert failed", exc_info=True)
        return ""


def _trade_window_card_html(ctx: dict, viewer_roster_id) -> str:
    """Buy/sell trade-window advisor for the Season Hub: playoff odds plus
    roster-age standing plus the trade deadline, with partners on the opposite
    side of the market. Empty string when it has nothing confident to say."""
    if not viewer_roster_id:
        return ""
    try:
        from utils.trade_window import trade_partners, trade_window_verdict

        platform = ctx.get("platform", "sleeper")
        # Warm-cache only: a cold sim must never block the dashboard paint.
        odds = _playoff_sim_cached(ctx, platform, block=False)
        if not odds:
            return ""
        me = next(
            (r for r in odds if str(r.get("roster_id")) == str(viewer_roster_id)),
            None,
        )
        if not me or me.get("is_complete"):
            return ""
        pct = float(me.get("playoff_pct") or 0)

        settings = (ctx.get("league") or {}).get("settings") or {}
        current_week = int(ctx.get("current_week") or 0)
        try:
            deadline = int(settings.get("trade_deadline") or 0)
        except (TypeError, ValueError):
            deadline = 0
        weeks_to = None
        if 0 < deadline < 30:
            if current_week > deadline:
                return ""  # deadline passed; the window is closed
            weeks_to = deadline - current_week

        # Roster-age standing: average age of each team's 8 most valuable players.
        age_rank = None
        n_teams = len(odds)
        try:
            values_by_id = {
                str(row["id"]): row
                for row in (get_model_value_table_cached() or [])
                if isinstance(row, dict) and row.get("id") is not None
            }
            team_ages: dict = {}
            for r in ctx.get("rosters") or []:
                rid = str(r.get("roster_id"))
                core = sorted(
                    (
                        (float(v.get("value") or 0), float(v.get("age") or 0))
                        for p in (r.get("players") or [])
                        if (v := values_by_id.get(str(p))) and float(v.get("age") or 0) > 0
                    ),
                    reverse=True,
                )[:8]
                if core:
                    team_ages[rid] = sum(a for _, a in core) / len(core)
            if str(viewer_roster_id) in team_ages and len(team_ages) >= 4:
                _order = sorted(team_ages.items(), key=lambda kv: -kv[1])
                age_rank = next(
                    i + 1 for i, (rid, _) in enumerate(_order) if rid == str(viewer_roster_id)
                )
                n_teams = len(team_ages)
        except Exception:
            logger.debug("trade window age rank failed", exc_info=True)

        vw = trade_window_verdict(pct, weeks_to, age_rank, n_teams)
        partners = trade_partners(
            [
                {
                    "name": r.get("team_name"),
                    "playoff_pct": r.get("playoff_pct"),
                    "is_viewer": str(r.get("roster_id")) == str(viewer_roster_id),
                }
                for r in odds
            ],
            vw["verdict"],
        )

        verdict = vw["verdict"]
        titles = {"buy": "Buy window", "sell": "Sell window", "hold": "Hold"}
        lines = []
        if weeks_to is not None:
            when = "this week" if weeks_to == 0 else (
                "next week" if weeks_to == 1 else f"{weeks_to} weeks away")
            lines.append(f"Week {deadline} trade deadline, {when}.")
        _odds_line = f"You're at {pct:.0f}% playoff odds"
        if age_rank and n_teams:
            _sfx = "th" if 10 <= age_rank % 100 <= 20 else {1: "st", 2: "nd", 3: "rd"}.get(age_rank % 10, "th")
            _odds_line += f" with the {age_rank}{_sfx}-oldest core of {n_teams}"
        lines.append(_odds_line + ".")
        mod_lines = {
            "all_in": "Your core is old and you're contending. The window is now.",
            "youth": "Your core is young. Stay patient and keep stacking picks.",
            "aging_bubble": "Aging core on the playoff bubble. Pick a direction before the deadline.",
        }
        if vw["modifier"] in mod_lines:
            lines.append(mod_lines[vw["modifier"]])
        if partners:
            who = "Sellers to call" if verdict == "buy" else "Buyers to call"
            lines.append(f"{who}: {', '.join(html.escape(p) for p in partners)}.")

        items = "".join(f"<li>{line}</li>" for line in lines)
        urgent_cls = " tw-urgent" if vw["urgent"] and verdict != "hold" else ""
        return f"""
        <section class="os-card trade-window-card tw-{verdict}{urgent_cls}">
          <div class="lineup-alert-head">
            <span class="lineup-alert-title">Trade window: {titles[verdict]}</span>
            <a class="os-section-link" href="/trade?tab=suggestions">Trade suggestions &rarr;</a>
          </div>
          <ul class="lineup-alert-list">{items}</ul>
        </section>"""
    except Exception:
        logger.debug("trade window card failed", exc_info=True)
        return ""


def _render_season_review_card(ctx: dict, viewer_roster_id, df_weekly, team_stats) -> str:
    """Season-in-review card for the viewer's team: record, scoring, best/worst
    week, longest win streak, and the luck read (all-play record, luck delta,
    expected vs actual seed). Empty string until there are finalized weeks."""
    if not viewer_roster_id:
        return ""
    try:
        from utils.season_review import season_review

        roster_map = ctx.get("roster_map") or {}
        owner = str(roster_map.get(str(viewer_roster_id)) or (ctx.get("viewer") or {}).get("viewer_team_name") or "")
        if not owner:
            return ""

        if df_weekly is None or df_weekly.empty or "finalized" not in df_weekly.columns:
            return ""
        fin = df_weekly[df_weekly["finalized"] == True]
        mine = fin[fin["owner"] == owner]
        if mine.empty:
            return ""
        weekly = [
            {"week": int(r["week"]), "points": float(r["points"] or 0), "win": float(r["win"] or 0)}
            for _, r in mine.iterrows()
        ]

        all_play = _all_play_from_df_weekly(df_weekly)
        ap_entry = all_play.get(owner)

        # Finish rank and PF rank from the standings frame.
        finish_rank = pf_rank = num_teams = None
        if team_stats is not None and not team_stats.empty and "owner" in team_stats.columns:
            _ts = team_stats.copy()
            num_teams = len(_ts)
            _ord = _ts.sort_values(by=["Wins", "PF", "PA"], ascending=[False, False, True]).reset_index(drop=True)
            _match = _ord.index[_ord["owner"] == owner].tolist()
            if _match:
                finish_rank = int(_match[0]) + 1
            _pf = _ts.sort_values(by=["PF"], ascending=[False]).reset_index(drop=True)
            _pfm = _pf.index[_pf["owner"] == owner].tolist()
            if _pfm:
                pf_rank = int(_pfm[0]) + 1

        r = season_review(weekly, all_play_entry=ap_entry, finish_rank=finish_rank,
                          num_teams=num_teams, pf_rank=pf_rank)
        if not r:
            return ""

        def _stat(label, value, sub=""):
            sub_html = f"<div class='sr-stat-sub'>{sub}</div>" if sub else ""
            return (f"<div class='sr-stat'><div class='sr-stat-label'>{html.escape(label)}</div>"
                    f"<div class='sr-stat-value'>{value}</div>{sub_html}</div>")

        stats = []
        _rec = html.escape(r["record"])
        _finish = f"{_ord_str(r['finish_rank'])}" + (f" of {r['num_teams']}" if r.get("num_teams") else "") if r.get("finish_rank") else ""
        stats.append(_stat("Record", _rec, _finish))
        stats.append(_stat("Points For", f"{r['points_for']:.0f}",
                           (f"{_ord_str(r['pf_rank'])} in scoring" if r.get("pf_rank") else f"{r['avg_points']:.1f}/wk")))
        stats.append(_stat("Best Week", f"{r['best_week']['points']:.0f}", f"Week {r['best_week']['week']}"))
        stats.append(_stat("Worst Week", f"{r['worst_week']['points']:.0f}", f"Week {r['worst_week']['week']}"))
        if r.get("longest_win_streak"):
            stats.append(_stat("Longest Streak", f"{r['longest_win_streak']}W", ""))
        if r.get("all_play_record"):
            _ld = r.get("luck_delta")
            _luck_sub = ""
            if _ld is not None:
                if _ld >= 1:
                    _luck_sub = f"Lucky (+{_ld:.1f} wins)"
                elif _ld <= -1:
                    _luck_sub = f"Unlucky ({_ld:.1f} wins)"
                else:
                    _luck_sub = "About deserved"
            stats.append(_stat("All-Play", html.escape(r["all_play_record"]), _luck_sub))
        if r.get("expected_seed") and r.get("finish_rank"):
            _seed_sub = "Matched your seed" if r["expected_seed"] == r["finish_rank"] else f"Finished {_ord_str(r['finish_rank'])}"
            stats.append(_stat("Deserved Seed", _ord_str(r["expected_seed"]), _seed_sub))

        return f"""
        <section class="os-card sr-card">
          <div class="os-section-head">
            <div class="os-section-head-content">
              <h2 class="os-section-title">Season in Review</h2>
              <div class="os-section-subtitle">{html.escape(owner)} &middot; through {len(weekly)} week{'s' if len(weekly) != 1 else ''}</div>
            </div>
          </div>
          <div class="sr-grid">{''.join(stats)}</div>
        </section>"""
    except Exception:
        logger.debug("season review card failed", exc_info=True)
        return ""


def _render_bench_check(ctx: dict, viewer_roster_id, last_final_week: int) -> str:
    """One-line post-week feedback: how many points the viewer's optimal lineup
    left on the bench in the last finalized week, linking to the Lineup
    Efficiency page. Empty string when there's nothing to say."""
    if not viewer_roster_id or not last_final_week:
        return ""
    try:
        matchups_by_week = ctx.get("matchups_by_week") or {}
        team = None
        for m in matchups_by_week.get(last_final_week, []):
            for side in ("left", "right"):
                t = m.get(side) or {}
                if str(t.get("roster_id", "")) == str(viewer_roster_id):
                    team = t
                    break
            if team:
                break
        if not team:
            return ""

        starters = team.get("starters") or []
        bench = team.get("bench") or []
        if not starters:
            return ""
        pts_map = {p["pid"]: float(p.get("pts") or 0) for p in starters + bench}
        pos_map = {p["pid"]: str(p.get("pos") or "") for p in starters + bench}
        actual = sum(float(p.get("pts") or 0) for p in starters)

        roster_positions = ctx.get("roster_positions")
        if roster_positions is not None and hasattr(roster_positions, "tolist"):
            roster_positions = roster_positions.tolist()
        if not roster_positions:
            return ""

        from utils.optimal_lineup import compute_optimal_lineup
        _opt_set, opt_pts = compute_optimal_lineup(
            pts_map, pos_map, roster_positions, list(pts_map)
        )
        if not opt_pts:
            return ""
        left_on_bench = opt_pts - actual

        platform = ctx.get("platform", "sleeper")
        season = ctx.get("current_season")
        league_id = ctx.get("league_id", "")
        eff_url = url_for(
            "page_weekly", platform=platform, season=season, league_id=league_id
        ) + "?tab=optimal"
        if left_on_bench < 1.0:
            msg = (
                f"Week {last_final_week} bench check: you started your optimal "
                f"lineup. Nothing left on the bench."
            )
        else:
            msg = (
                f"Week {last_final_week} bench check: your optimal lineup scored "
                f"{opt_pts:.1f}. You scored {actual:.1f} and left "
                f"{left_on_bench:.1f} points on the bench."
            )
        return f"""
        <section class="os-card bench-check-card">
          <div class="bench-check-row">
            <span class="bench-check-msg">{html.escape(msg)}</span>
            <a class="os-section-link" href="{eff_url}">Lineup efficiency &rarr;</a>
          </div>
        </section>"""
    except Exception:
        logger.debug("bench check failed", exc_info=True)
        return ""


def build_dashboard_body(ctx: dict) -> str:
    league_id = ctx["league_id"]
    season = ctx["current_season"]
    platform = ctx.get("platform", "sleeper")
    rosters = ctx["rosters"]
    users = ctx["users"]
    current_week = ctx["current_week"]
    players_map = ctx["players_map"]
    df_weekly = ctx["df_weekly"]
    team_stats = ctx["team_stats"]
    players_index = ctx["players_index"]
    teams_index = ctx["teams_index"]
    statuses = ctx["statuses"]
    proj_by_week = ctx["proj_by_week"]
    matchups_by_week = ctx["matchups_by_week"]
    picks_by_roster = ctx["picks_by_roster"]
    team_game_lookup = ctx["team_game_lookup"]

    viewer = ctx.get("viewer") or {}
    viewer_roster_id = viewer.get("viewer_roster_id")

    gm_memo_html = ""

    if viewer_roster_id:
        try:
            gm_memo_html = get_team_gm_memo(ctx, str(viewer_roster_id))
        except Exception:
            logger.debug("dashboard: gm memo failed", exc_info=True)

    standings_html = render_standings_compact(
        team_stats, movement=_standings_movement(df_weekly)
    )
    usage_movers_html = _render_usage_movers(ctx, viewer_roster_id)
    lineup_alert_html = _viewer_lineup_alert_html(ctx, viewer_roster_id)
    roster_moves_html = _roster_moves_alert_html(ctx, viewer_roster_id)
    trade_window_html = _trade_window_card_html(ctx, viewer_roster_id)
    season_review_html = _render_season_review_card(ctx, viewer_roster_id, df_weekly, team_stats)

    finalized_df = df_weekly[df_weekly["finalized"] == True].copy()
    if not finalized_df.empty:
        last_final_week = int(finalized_df["week"].max())
    else:
        last_final_week = 0  # no finalized weeks yet → show projections for current week

    bench_check_html = _render_bench_check(ctx, viewer_roster_id, last_final_week)

    # Waiver Wire Targets card (same builder as the offseason hub). Uses the
    # live model-value cache rather than the ctx copy, which can go stale.
    waiver_card_html = ""
    try:
        _wv_table = list(get_model_value_table_cached() or []) or (ctx.get("model_value_table") or [])
        _wv_rows = _build_waiver_targets_rows(ctx, _wv_table)
        if _wv_rows:
            waiver_card_html = f"""
        <section class="os-card os-col-fill">
          <div class="os-section-head">
            <div class="os-section-head-content">
              {_section_title_link("Waiver Wire Targets", "league_pages.page_waivers", platform, season, league_id)}
              <div class="os-section-subtitle">Smart pickups based on value + trend + breakout potential</div>
            </div>
            <div class="os-section-head-actions">
              <button type="button" class="card-collapse-toggle" aria-label="Toggle section" aria-expanded="true" data-target="dash-waiver-body">&#9660;</button>
            </div>
          </div>
          <div class="os-waiver-list card-collapsible-body" id="dash-waiver-body">
            {_wv_rows}
          </div>
        </section>"""
    except Exception:
        logger.debug("dashboard waiver card failed", exc_info=True)

    _fpts_against_dash = _compute_fpts_against(season)
    _dash_vid = str(viewer_roster_id or "")
    _dash_matchups = sorted(
        matchups_by_week.get(current_week, []),
        key=lambda m: 0 if _dash_vid and _dash_vid in (str((m.get("left") or {}).get("roster_id", "")), str((m.get("right") or {}).get("roster_id", ""))) else 1,
    )
    slides = [
        render_matchup_slide(
            season,
            m,
            current_week,
            last_final_week,
            status_by_pid=statuses[current_week].get("statuses", {}),
            projections=proj_by_week,
            players=players_index,
            teams=teams_index,
            team_game_lookup=team_game_lookup,
            fpts_against=_fpts_against_dash,
        )
        for m in _dash_matchups
    ]
    slides_by_week = {current_week: "".join(slides)}
    matchup_html = render_matchup_carousel_weeks(
        slides_by_week,
        dashboard=True,
        active_week=current_week,
    )

    awards = compute_awards_season(finalized_df, players_map, league_id, platform, season, users, rosters)
    awards_html = render_awards_section(awards)

    teams_ctx = build_teams_overview(
        rosters=rosters,
        users_list=users,
        picks_by_roster=picks_by_roster,
        players=players_map,
        players_index=players_index,
        teams_index=teams_index,
        platform=platform,
    )
    teams_sidebar_html = render_teams_sidebar(teams_ctx)

    gm_card_html = ""
    if gm_memo_html:
        gm_card_html = f"""
        <div class="card gm-card">
          <div class="card-header">
            <h2>Front Office Report</h2>
            <div class="subtle-label">{viewer.get("viewer_team_name") or "Your Team"}</div>
          </div>
          <div class="card-body">
            {gm_memo_html}
          </div>
        </div>
        """

    # ---- Hero stat cards — mirror the offseason hub's hero card ----
    from utils.format import ordinal as _dash_ord

    _hero_cards: list = []
    try:
        _hs = team_stats.copy()
        _hs = _hs.sort_values(by=["Wins", "PF", "PA"], ascending=[False, False, True]).reset_index(drop=True)
        _hs["Rank"] = _hs.index + 1
        _n_teams = len(_hs)
        _vname = str(viewer.get("viewer_team_name") or "")
        _vmask = (_hs["owner"].astype(str) == _vname) if _vname else None
        if _vname and _vmask is not None and bool(_vmask.any()):
            _vrow = _hs[_vmask].iloc[0]
            _rec = f"{int(_vrow['Wins'])}-{int(_vrow['Losses'])}"
            if int(_vrow.get("Ties", 0) or 0):
                _rec += f"-{int(_vrow['Ties'])}"
            _hero_cards.append(("Your record", _rec, _dash_ord(int(_vrow['Rank']))))
            _pf = _hs.sort_values("PF", ascending=False).reset_index(drop=True)
            _pf_rank = int(_pf.index[_pf["owner"].astype(str) == _vname][0]) + 1
            _hero_cards.append(("Points for", f"{float(_vrow['PF']):.0f}", _dash_ord(_pf_rank)))
            _streak = str(_vrow.get("Streak") or "").strip()
            # Win probability for the viewer's matchup, from the same model the
            # matchup slides' win bar uses. Only for a live/upcoming week.
            _win_sub = ""
            try:
                if _dash_matchups and current_week > last_final_week:
                    _m0 = _dash_matchups[0]
                    _l0 = _m0.get("left") or {}
                    _r0 = _m0.get("right") or {}
                    if _dash_vid and _dash_vid in (str(_l0.get("roster_id", "")), str(_r0.get("roster_id", ""))):
                        _wp_proj = (proj_by_week.get(current_week) or {}).get("projections") or {}
                        _wp_status = (statuses.get(current_week) or {}).get("statuses", {})
                        _wp = compute_win_prob(_l0, _r0, _wp_status, _wp_proj)
                        if str(_r0.get("roster_id", "")) == _dash_vid:
                            _wp = 1.0 - _wp
                        _win_sub = f"{round(_wp * 100)}% to win"
            except Exception:
                logger.debug("hero win prob failed", exc_info=True)
            if _win_sub and _streak:
                _tw_sub = f"{_streak} streak, {_win_sub}"
            elif _win_sub:
                _tw_sub = _win_sub
            elif _streak:
                _tw_sub = f"{_streak} streak"
            else:
                _tw_sub = f"{len(_dash_matchups)} matchups"
            _hero_cards.append(("This week", f"Week {current_week}", _tw_sub))
        else:
            _top = _hs.iloc[0]
            _hero_cards.append(("League leader", str(_top["owner"]),
                                f"{int(_top['Wins'])}-{int(_top['Losses'])} record"))
            _hi = _hs.sort_values("PF", ascending=False).iloc[0]
            _hero_cards.append(("Most points", f"{float(_hi['PF']):.0f}", str(_hi["owner"])))
            _hero_cards.append(("This week", f"Week {current_week}", f"{len(_dash_matchups)} matchups"))
    except Exception:
        logger.debug("dashboard hero stats failed", exc_info=True)
        _hero_cards = [("This week", f"Week {current_week}", "Live scoring & standings")]

    _hero_tiles = [
        f"""<div class="os-stat-card">
              <div class="os-stat-label">{html.escape(str(_lbl))}</div>
              <div class="os-stat-value">{html.escape(str(_val))}</div>
              <div class="os-stat-sub">{html.escape(str(_sub))}</div>
            </div>"""
        for _lbl, _val, _sub in _hero_cards
    ]

    # Playoff-odds tile — the Monte Carlo sim is heavy and cached behind the
    # /api/playoff-odds endpoint, so render a placeholder and fill it client-side
    # to keep first paint fast. Only meaningful when the viewer owns a team.
    if viewer_roster_id:
        _playoff_tile_html = f"""<div class="os-stat-card os-stat-playoff" id="dash-playoff-tile"
              data-platform="{html.escape(str(platform))}"
              data-league="{html.escape(str(league_id))}"
              data-season="{html.escape(str(season))}"
              data-roster="{html.escape(str(viewer_roster_id))}">
              <div class="os-stat-label">Playoff odds</div>
              <div class="os-stat-value" id="dash-playoff-val">-</div>
              <div class="os-stat-sub" id="dash-playoff-sub">Simulating&hellip;</div>
            </div>"""
        # Slot right after the first (record) tile so it reads prominently.
        _hero_tiles.insert(1, _playoff_tile_html)

    _hero_stats_html = "".join(_hero_tiles)

    _viewer_team = viewer.get("viewer_team_name")
    _hero_copy = (
        f"Welcome back, {html.escape(str(_viewer_team))}. Your matchup, standings, and moves at a glance."
        if _viewer_team else
        "Your matchups, standings, and weekly moves at a glance."
    )

    body = f"""
    <div class="os-layout">
      <aside class="os-left-col">
        <section class="os-card os-col-fill">
          <div class="os-section-head">
            <div class="os-section-head-content">
              {_section_title_link("Standings", "league_pages.page_standings", platform, season, league_id)}
              <div class="os-section-subtitle">Where every team sits right now</div>
            </div>
            <div class="os-section-head-actions">
              <button type="button" class="card-collapse-toggle" aria-label="Toggle section" aria-expanded="true" data-target="dash-standings-body">&#9660;</button>
            </div>
          </div>
          <div class="card-collapsible-body" id="dash-standings-body">
            {standings_html}
          </div>
        </section>
        {awards_html}
      </aside>

      <main class="os-main-col">
        <section class="os-hero-card">
          <div class="os-hero-top">
            <div>
              <div class="os-hero-kicker">Viewing {season} season &middot; Week {current_week}</div>
              <h1 class="os-hero-title">Season Hub</h1>
              <p class="os-hero-copy">{_hero_copy}</p>
            </div>
          </div>
          <div class="os-hero-stats">
            {_hero_stats_html}
          </div>
        </section>

        <nav class="os-jump-nav" aria-label="Jump to section">
          <button type="button" class="active" data-jump="os-jump-report">Report</button>
          <button type="button" data-jump="os-jump-waivers">Waivers</button>
          <button type="button" data-jump="os-jump-teams">Team Values</button>
        </nav>

        <div id="sinceLastVisitCard" class="slv-wrap" data-slv-init="1"></div>

        <div id="os-jump-report" class="os-tab-panel os-tab-active">
          {lineup_alert_html}
          {roster_moves_html}
          {gm_card_html}
          {trade_window_html}
          {usage_movers_html}

          {matchup_html}
          {bench_check_html}
          {season_review_html}
        </div>

        <div id="os-jump-waivers" class="os-tab-panel">
          {waiver_card_html}
        </div>
      </main>

      <aside class="os-right-col os-tab-panel" id="os-jump-teams">
        <div class="os-sidebar-shell">
          {teams_sidebar_html}
        </div>
      </aside>
    </div>
    <script>
    (function(){{
      var nav = document.querySelector('.os-jump-nav');
      if (!nav) return;
      var ids = Array.prototype.map.call(nav.querySelectorAll('[data-jump]'), function(b){{ return b.getAttribute('data-jump'); }});
      function activate(id){{
        ids.forEach(function(pid){{
          var p = document.getElementById(pid);
          if (p) p.classList.toggle('os-tab-active', pid === id);
        }});
        nav.querySelectorAll('button').forEach(function(x){{ x.classList.toggle('active', x.getAttribute('data-jump') === id); }});
      }}
      nav.querySelectorAll('[data-jump]').forEach(function(btn){{
        btn.addEventListener('click', function(){{ activate(btn.getAttribute('data-jump')); }});
      }});
      var init = nav.querySelector('button.active') || nav.querySelector('button');
      if (init) activate(init.getAttribute('data-jump'));
    }})();
    </script>
    <script>
    (function() {{
      var el = document.getElementById('dash-playoff-tile');
      if (!el) return;
      var rid = el.getAttribute('data-roster');
      var qs = 'platform=' + encodeURIComponent(el.getAttribute('data-platform')) +
               '&league_id=' + encodeURIComponent(el.getAttribute('data-league')) +
               '&season=' + encodeURIComponent(el.getAttribute('data-season'));
      fetch('/api/playoff-odds?' + qs)
        .then(function(r) {{ return r.ok ? r.json() : null; }})
        .then(function(d) {{
          var odds = (d && d.odds) || [];
          var row = null;
          for (var i = 0; i < odds.length; i++) {{
            if (String(odds[i].roster_id) === String(rid)) {{ row = odds[i]; break; }}
          }}
          if (!row) {{ el.remove(); return; }}
          var pct = Math.round(row.playoff_pct || 0);
          var valEl = document.getElementById('dash-playoff-val');
          var subEl = document.getElementById('dash-playoff-sub');
          if (valEl) {{
            if (window.brCountUp) window.brCountUp(valEl, {{ to: pct, dp: 0, suffix: '%', dur: 800 }});
            else valEl.textContent = pct + '%';
          }}
          var sub;
          if (d.is_complete || row.is_complete) {{
            sub = pct >= 100 ? 'Clinched' : (pct <= 0 ? 'Eliminated' : 'Playoff bound');
          }} else {{
            var first = Math.round(row.first_seed_pct || 0);
            var bye = Math.round(row.bye_pct || 0);
            sub = first > 0 ? (first + '% top seed')
                : (bye > 0 ? (bye + '% first-round bye') : 'to make the playoffs');
          }}
          if (subEl) subEl.textContent = sub;
          el.classList.add('is-loaded');
        }})
        .catch(function() {{ el.remove(); }});
    }})();
    </script>
    """

    return body


def render_power_and_playoffs(
    team_stats,
    roster_map: Dict[str, str],
    league_id: str,
    platform,
    season,
    bracket_override=None,
    seed_map_override=None,
    power_rankings=None,
) -> str:
    """
    Single card that shows:
      - Power Rankings (by PowerScore if present)
      - Playoff Picture (using bracket)
    bracket_override: pre-built bracket list; skips API fetch when provided.
    seed_map_override: {roster_id: seed_int}; skips seed_top6 calculation.
    power_rankings: list of team dicts from build_power_rankings_context()
        ({"team_name", "power_score", "rank"}). When provided, the podium's
        order and PowerScore are taken from here so this card matches the
        Teams page "Power Rankings" tab exactly.
    """
    if team_stats is None or team_stats.empty:
        return ""

    team_stats = team_stats.copy()

    # ---- Align with the Teams page Power Rankings tab when provided ----
    # Override PowerScore (and therefore ordering) using the canonical
    # build_power_rankings_context() output, matched by team name.
    if power_rankings:
        pr_score_by_name = {
            str(t.get("team_name")): float(t.get("power_score") or 0.0)
            for t in power_rankings
        }
        if "owner" in team_stats.columns:
            team_stats["PowerScore"] = team_stats["owner"].map(
                lambda o: pr_score_by_name.get(str(o), 0.0)
            )

    # ---- Sort by PowerScore, with PF as tiebreaker if available ----
    has_power = "PowerScore" in team_stats.columns
    has_pf = "PF" in team_stats.columns

    if has_power:
        if has_pf:
            pr_sorted = team_stats.sort_values(
                ["PowerScore", "PF"],
                ascending=[False, False],
            ).reset_index(drop=True)
        else:
            pr_sorted = team_stats.sort_values(
                "PowerScore",
                ascending=False,
            ).reset_index(drop=True)
    else:
        if has_pf:
            pr_sorted = team_stats.sort_values("PF", ascending=False).reset_index(drop=True)
        else:
            pr_sorted = team_stats.reset_index(drop=True)

    top3 = pr_sorted.head(3)

    # ---- Weekly movement arrows (vs the previous week's snapshot) ----
    movement: Dict[str, Optional[int]] = {}
    try:
        from dashboard_services.power_rank_history import record_and_movement
        _nfl_state = get_nfl_state() or {}
        _wk = int(_nfl_state.get("week") or 0)
        _is_current_season = str(_nfl_state.get("season") or "") == str(season)
        if _wk > 0 and _is_current_season:
            _ranks = {
                str(row.get("owner", "")): i + 1
                for i, (_, row) in enumerate(pr_sorted.iterrows())
            }
            movement = record_and_movement(str(league_id), int(season), _wk, _ranks)
    except Exception:
        movement = {}

    def move_arrow(owner_name) -> str:
        delta = movement.get(str(owner_name))
        if delta is None:
            return ""
        if delta > 0:
            return f"<span class='pr-move pr-move-up' title='Up {delta} from last week'>&#9650;{delta}</span>"
        if delta < 0:
            return f"<span class='pr-move pr-move-down' title='Down {abs(delta)} from last week'>&#9660;{abs(delta)}</span>"
        return "<span class='pr-move pr-move-flat' title='No change from last week'>&ndash;</span>"

    # width scaling based on PowerScore range
    if has_power:
        p = pr_sorted["PowerScore"].astype(float)
        pmin, pmax = float(p.min()), float(p.max())
    else:
        p = None
        pmin = pmax = 0.0

    def pct_width(v: float) -> float:
        """Convert a PowerScore into a 2–100% bar width."""
        if p is None:
            return 100.0
        span = abs(pmax - pmin)
        if span == 0:
            return 100.0
        return max(2.0, min(100.0, (float(v) - min(pmin, pmax)) / span * 100.0))

    def safe_int(val, default=0):
        try:
            return int(val)
        except (TypeError, ValueError):
            return default

    def safe_float(val, default=0.0):
        try:
            return float(val)
        except (TypeError, ValueError):
            return default

    def podium_slot(rank: int, row) -> str:
        name = row.get("owner", "Unknown")

        # record
        wins = safe_int(row.get("Wins"), 0)
        games = safe_int(row.get("G"), 0)
        losses = max(games - wins, 0)
        ties_val = safe_int(row.get("Ties"), 0)
        rec = f"{wins}-{losses}" + (f"-{ties_val}" if ties_val else "")

        base_cls = {1: "first", 2: "second", 3: "third"}[rank]

        power_val = safe_float(row.get("PowerScore"), 0.0)
        w = pct_width(power_val)

        # streak bits
        streak_chip = row.get("Streak", "")  # e.g., "W3", "L2"
        streak_frame_cls = streak_class(row)  # assumes you already have this helper
        avatar_url = row.get("avatar")
        avatar_html = (
            f"<img class='avatar' src='{avatar_url}' alt='' loading='lazy' decoding='async' "
            "onerror=\"this.style.display='none'\">"
            if avatar_url else ""
        )

        # PF/G, PA/G, diff
        pf = safe_float(row.get("PF"), 0.0)
        pa = safe_float(row.get("PA"), 0.0)
        g = games if games > 0 else 1
        pfpg_v = pf / g
        papg_v = pa / g
        diff_v = pfpg_v - papg_v
        diff_class = "diff-pos" if diff_v > 0 else "diff-neg" if diff_v < 0 else ""

        chips_html = "<div class='chips'>"
        chips_html += f"<span class='chip'>PF/G {pfpg_v:.1f}</span>"
        chips_html += f"<span class='chip'>PA/G {papg_v:.1f}</span>"
        chips_html += f"<span class='chip {diff_class}'>{diff_v:+.1f}</span>"
        if streak_chip and streak_frame_cls == "streak-hot":
            chips_html += f"<span class='chip chip-streak'><i class='fa-solid fa-fire'></i>{streak_chip}</span>"
        elif streak_chip and streak_frame_cls == "streak-cold":
            chips_html += f"<span class='chip chip-streak'><i class='fa-solid fa-snowflake'></i>{streak_chip}</span>"
        chips_html += "</div>"

        return f"""
          <div class="slot {base_cls} {streak_frame_cls}" data-rk-key="{html.escape(str(name), quote=True)}">
            <div class="wrap">
              <div class='podium-header'>
                <h3>#{rank} {move_arrow(name)}</h3>
                {avatar_html}
              </div>
              <div class="name">{name}</div>
              <div class="rec">{rec}</div>
              <div class="bar"><div style="width:{w:.1f}%"></div></div>
              {chips_html}
            </div>
          </div>
        """

    # ---- Top 3 podium ----
    podium_html = """
      <div class="podium">
        {slot1}
        {slot2}
        {slot3}
      </div>
    """.format(
        slot1=podium_slot(1, top3.iloc[0]) if len(top3) > 0 else "",
        slot2=podium_slot(2, top3.iloc[1]) if len(top3) > 1 else "",
        slot3=podium_slot(3, top3.iloc[2]) if len(top3) > 2 else "",
    )

    # ---- Remaining ranks list ----
    others = pr_sorted.iloc[3:].reset_index(drop=True)
    rank_cards = []
    for i, row in others.iterrows():
        pos = i + 4
        team = row.get("owner", "Unknown")

        wins = safe_int(row.get("Wins"), 0)
        games = safe_int(row.get("G"), 0)
        losses = max(games - wins, 0)
        ties_val = safe_int(row.get("Ties"), 0)
        record = f"{wins}-{losses}" + (f"-{ties_val}" if ties_val else "")

        power_val = safe_float(row.get("PowerScore"), 0.0)
        bar_w = pct_width(power_val)

        # per-row PF/G, PA/G, diff
        pf = safe_float(row.get("PF"), 0.0)
        pa = safe_float(row.get("PA"), 0.0)
        g = games if games > 0 else 1
        pfpg_v = pf / g
        papg_v = pa / g
        diff_v = pfpg_v - papg_v
        diff_class = "diff-pos" if diff_v > 0 else "diff-neg" if diff_v < 0 else ""

        streak_chip = row.get("Streak", "")
        chips_html = (
            f"<span class='chip'>PF/G {pfpg_v:.1f}</span>"
            f"<span class='chip'>PA/G {papg_v:.1f}</span>"
        )
        css_cls = streak_class(row)
        if streak_chip and css_cls == "streak-hot":
            chips_html += f"<span class='chip chip-streak'><i class='fa-solid fa-fire'></i>{streak_chip}</span>"
        elif streak_chip and css_cls == "streak-cold":
            chips_html += f"<span class='chip chip-streak'><i class='fa-solid fa-snowflake'></i>{streak_chip}</span>"
        chips_html += f"<span class='chip {diff_class}'>{diff_v:+.1f}</span>"

        avatar_url = row.get("avatar")
        img = (
            f"<img class='avatar sm' src='{avatar_url}' alt='' loading='lazy' decoding='async' "
            "onerror=\"this.style.display='none'\">"
            if avatar_url else ""
        )

        rank_cards.append(
            f"<div class='rank-item {css_cls}' data-rk-key='{html.escape(str(team), quote=True)}'>"
            f"<span class='pos'>#{pos}</span>"
            f"{move_arrow(team)}"
            f"{img}"
            f"<span class='name'>{team}</span>"
            f"<div class='bar'><div style='width:{bar_w:.1f}%'></div></div>"
            f"<div class='chips'>{chips_html}</div>"
            f"<span class='rec'>{record}</span>"
            f"</div>"
        )

    rankings_html = "<div class='rank-grid'>" + "".join(rank_cards) + "</div>"

    # ---- Playoff bracket ----
    wb = bracket_override if bracket_override is not None else get_bracket(platform, league_id, "winners", season)
    roster_avatar_map = {
        str(owner): av
        for owner, av in zip(team_stats["owner"], team_stats["avatar"])
        if pd.notna(owner)
    }

    seed_map = seed_map_override if seed_map_override is not None else seed_top6_from_team_stats(team_stats, roster_map)

    bracket_html = playoff_bracket(
        wb,
        roster_name_map=roster_map,
        roster_avatar_map=roster_avatar_map,
        seed_map=seed_map,
    )

    # Check if playoff bracket is available
    has_playoff_bracket = not bracket_html.strip().startswith('<div class=\'po-empty\'>')

    # Build tab buttons conditionally
    playoff_tab_html = ""
    playoff_panel_html = ""
    
    if has_playoff_bracket:
        playoff_tab_html = '<button class="tab-btn" data-tab="playoff">Playoff Picture</button>'
        playoff_panel_html = f'<div class="tab-panel" data-tab="playoff">{bracket_html}</div>'

    podium_card = f"""
          <div class="card power" data-section="overview">
            <div class="card-tabs" data-card="power">
              <div class="tab-strip">
                <button class="tab-btn active" data-tab="power">Power Rankings</button>
                {playoff_tab_html}
                <button class="tab-btn" data-tab="playoff-odds"
                        data-league-id="{league_id}"
                        data-platform="{platform}"
                        data-season="{season}">Playoff Odds</button>
              </div>
              <div class="tab-panels">
                <div class="tab-panel active" data-tab="power">
                  {podium_html}
                  {rankings_html}
                </div>
                {playoff_panel_html}
                <div class="tab-panel" data-tab="playoff-odds" id="playoffOddsPanel">
                  <div class="playoff-odds-loading">
                    <div class="loading-spinner-sm"></div>
                    <span>Running simulation…</span>
                  </div>
                </div>
              </div>
            </div>
          </div>
        """

    return podium_card


def render_standings_sidebar(team_stats) -> str:
    if team_stats is None or team_stats.empty:
        return ""

    ts = team_stats.copy()

    # --------------------
    # Best Offense / Defense
    # --------------------
    best_off = ts.loc[ts["PF"].idxmax()] if "PF" in ts.columns else None
    best_def = ts.loc[ts["PA"].idxmin()] if "PA" in ts.columns else None

    # --------------------
    # Hottest / Coldest Streaks
    # --------------------
    hottest = None
    coldest = None
    if "StreakLen" in ts.columns and "StreakType" in ts.columns:
        hot_df = ts[ts["StreakType"] == "W"]
        cold_df = ts[ts["StreakType"] == "L"]

        if not hot_df.empty:
            hottest = hot_df.loc[hot_df["StreakLen"].idxmax()]
        if not cold_df.empty:
            coldest = cold_df.loc[cold_df["StreakLen"].idxmax()]

    cards = []

    # --------------------
    # Best Offense Card
    # --------------------
    if best_off is not None:
        cards.append(f"""
        <div class="card small">
          <div class="card-header">
            <h3>Best Offense</h3>
            <h3>{best_off['PF']:.1f} PF</h3>
          </div>
          <div class="card-body">
            <div class="highlight-game-card">
              <div class="hg-row">
                <div class="hg-team">
                  <span class="hg-name">{best_off['owner']}</span>
                </div>
              </div>
            </div>
          </div>
        </div>
        """)

    # --------------------
    # Best Defense Card
    # --------------------
    if best_def is not None:
        cards.append(f"""
        <div class="card small">
          <div class="card-header">
            <h3>Best Defense</h3>
            <h3>{best_def['PA']:.1f} PA</h3>
          </div>
          <div class="card-body">
            <div class="highlight-game-card">
              <div class="hg-row">
                <div class="hg-team">
                  <span class="hg-name">{best_def['owner']}</span>
                </div>
              </div>
            </div>
          </div>
        </div>
        """)

    # --------------------
    # Hottest Team Card
    # --------------------
    if hottest is not None:
        cards.append(f"""
        <div class="card small hottest-card">
          <div class="card-header">
            <h3>Hottest Team</h3>
            <h3><i class="fa-solid fa-fire"></i> {hottest['Streak']}</h3>
          </div>
          <div class="card-body">
            <div class="highlight-game-card">
              <div class="hg-row">
                <div class="hg-team">
                  <span class="hg-name">{hottest['owner']}</span>
                </div>
              </div>
            </div>
          </div>
        </div>
        """)

    # --------------------
    # Coldest Team Card
    # --------------------
    if coldest is not None:
        cards.append(f"""
        <div class="card small coldest-card">
          <div class="card-header">
            <h3>Coldest Team</h3>
            <h3><i class="fa-solid fa-snowflake"></i> {coldest['Streak']}</h3>
          </div>
          <div class="card-body">
            <div class="highlight-game-card">
              <div class="hg-row">
                <div class="hg-team">
                  <span class="hg-name">{coldest['owner']}</span>
                </div>
              </div>
            </div>
          </div>
        </div>
        """)

    return "".join(cards)


def render_team_stats(team_stats, df_weekly) -> str:
    if team_stats is None or team_stats.empty or df_weekly is None or df_weekly.empty:
        return """
        <div class="card-body">
          <p>No detailed stats available for this season yet.</p>
        </div>
        """

    best = df_weekly.groupby("owner")["points"].max().rename("Best Week")
    worst = df_weekly.groupby("owner")["points"].min().rename("Worst Week")

    stats_tbl = (
        team_stats.rename(columns={"owner": "Team", "AVG": "Average", "STD": "Std Dev", "Win%": "Win %"})
        .merge(best, left_on="Team", right_index=True, how="left")
        .merge(worst, left_on="Team", right_index=True, how="left")
    )

    cols = ["Team", "Win %", "PF", "PA", "Average", "Std Dev", "Best Week", "Worst Week"]
    stats_tbl = stats_tbl[cols].copy()

    for c in ["Win %", "PF", "PA", "Average", "Std Dev", "Best Week", "Worst Week"]:
        stats_tbl[c] = stats_tbl[c].astype(float).round(3 if c == "Win %" else 2)

    body_rows = []
    for _, r in stats_tbl[cols].iterrows():
        avatar = r.get("avatar", "")
        img = (
            f"<img class='avatar sm' src='{avatar}' alt='' loading='lazy' decoding='async' "
            "onerror=\"this.style.display='none'\">"
            if avatar else ""
        )
        body_rows.append("<tr>" + "".join([
            f"<td class='team'>{img} {r['Team']}</td>",
            f"<td class='num'>{r['Win %']:.3f}</td>",
            f"<td class='num'>{float(r['PF']):.2f}</td>",
            f"<td class='num'>{float(r['PA']):.2f}</td>",
            f"<td class='num'>{float(r['Average']):.2f}</td>",
            f"<td class='num'>{float(r['Std Dev']):.2f}</td>",
            f"<td class='num'>{float(r['Best Week']):.2f}</td>",
            f"<td class='num'>{float(r['Worst Week']):.2f}</td>",
        ]) + "</tr>")

    table_html = f"""
        <table id="stats" class="standings-table">
          <thead><tr>{"".join([f"<th data-col='{i}'>{c}</th>" for i, c in enumerate(cols)])}</tr></thead>
          <tbody>{''.join(body_rows)}</tbody>
        </table>
    """
    return table_html


def _build_offseason_standings_body(ctx: dict) -> str:
    """
    Offseason standings: left = dynasty rankings table, right = power rankings
    cards (same order as the Teams page) + Playoff Odds.
    """
    roster_map        = ctx["roster_map"]
    rosters           = ctx["rosters"]
    users             = ctx.get("users") or []
    # Read the live cached model table directly (same source as the player modal)
    # so standings/team values don't lag behind after a value rebuild.
    model_value_table = list(get_model_value_table_cached() or []) or (ctx.get("model_value_table") or [])
    picks_by_roster   = ctx.get("picks_by_roster") or {}
    platform          = ctx["platform"]
    season            = ctx["season"]
    league_id_str     = str(ctx.get("resolved_league_id") or ctx.get("league_id") or "")

    # ── dynasty value lookup ──────────────────────────────────────────────────
    values_by_id: dict[str, float] = {}
    for row in model_value_table:
        if isinstance(row, dict) and row.get("id") is not None:
            try:
                values_by_id[str(row["id"])] = float(row.get("value") or 0)
            except Exception:
                logger.debug("suppressed exception", exc_info=True)

    pick_by_key: dict[str, float] = load_pick_value_table() or {}

    # ── avatar lookup from users ──────────────────────────────────────────────
    user_by_id = {str(u.get("user_id", "")): u for u in users}
    rid_to_avatar: dict[str, str] = {}
    for r in rosters:
        rid      = str(r.get("roster_id"))
        owner_id = str(r.get("owner_id") or "")
        u        = user_by_id.get(owner_id) or {}
        u_meta   = u.get("metadata") or {}
        u_av     = u.get("avatar") or ""
        av_raw   = u_meta.get("avatar") or (
            f"https://sleepercdn.com/avatars/{u_av}" if platform == "sleeper" and u_av else u_av
        )
        rid_to_avatar[rid] = avatar_url(av_raw) or ""

    # ── build per-team data ───────────────────────────────────────────────────
    team_rows: list[dict] = []
    for r in rosters:
        rid      = str(r.get("roster_id"))
        name     = roster_map.get(rid, f"Roster {rid}")
        pids     = [str(p) for p in (r.get("players") or [])]
        player_v = sum(values_by_id.get(p, 0.0) for p in pids)
        picks    = picks_by_roster.get(rid, []) if isinstance(picks_by_roster, dict) else []
        pick_v   = _team_pick_value(picks, pick_by_key, platform=platform,
                                    league_id=league_id_str, season=_safe_int(season, 0))
        total    = player_v + pick_v
        team_rows.append({
            "rid": rid, "name": name,
            "player_v": player_v, "pick_v": pick_v,
            "total": total, "n_players": len(pids), "n_picks": len(picks),
            "avatar": rid_to_avatar.get(rid, ""),
        })

    team_rows.sort(key=lambda x: x["total"], reverse=True)

    # ── Compute value share and projected production share ─────────────────────
    league_value_total = sum(r["total"] for r in team_rows) or 1.0
    # Projected scoring using same Sleeper-first PPG source as playoff odds page
    rid_to_proj: dict[str, float] = {}
    try:
        from data_building.simulate_playoff_odds import build_ppg_map, _estimate_from_rosters
        _ppg_map, _pos_map = build_ppg_map(ctx)
        est_teams = _estimate_from_rosters(ctx, ppg_map=_ppg_map, pos_map=_pos_map)
        for t in est_teams:
            rid_to_proj[str(t["roster_id"])] = float(t.get("avg") or 0.0)
    except Exception:
        logger.debug("suppressed exception", exc_info=True)
    proj_total = sum(rid_to_proj.values()) or 1.0
    for r in team_rows:
        r["value_pct"] = r["total"] / league_value_total * 100
        r["prod_pct"]  = rid_to_proj.get(r["rid"], 0.0) / proj_total * 100

    # ── normalize to a PPG-like scale (100–160) matching Teams page formula ──
    raw_vals = [r["total"] for r in team_rows]
    raw_max  = max(raw_vals) if raw_vals else 1
    for r in team_rows:
        r["power_score"] = round(100.0 + r["total"] / max(raw_max, 1) * 60.0, 2)

    # ── synthetic team_stats DataFrame for render_power_and_playoffs ─────────
    df_rows = []
    for i, r in enumerate(team_rows):
        df_rows.append({
            "owner":      r["name"],
            "Wins":       0,
            "Losses":     0,
            "Ties":       0,
            "G":          0,
            "Win%":       0.0,
            "PF":         0.0,
            "PA":         0.0,
            "PowerScore": r["power_score"],
            "Streak":     "",
            "StreakLen":  0,
            "StreakType": "",
            "avatar":     r["avatar"],
        })
    synthetic_ts = pd.DataFrame(df_rows)

    # ── seed map from playoff odds simulation and projected bracket ──────────
    settings      = ctx.get("league_settings") or {}
    playoff_teams = int(settings.get("playoff_teams") or 6)

    # Run the Monte Carlo sim to get odds-based seedings (same data as the
    # Playoff Odds tab), sort by first_seed → bye → overall playoff probability
    try:
        from data_building.simulate_playoff_odds import simulate_playoff_odds
        _sim_key = (platform, str(ctx.get("league_id") or ""), int(ctx.get("season") or 0))
        _sim_cached = _PLAYOFF_SIM_CACHE.get(_sim_key)
        if _sim_cached and time.time() - _sim_cached["ts"] < _PLAYOFF_SIM_CACHE_TTL:
            odds_list = _sim_cached["data"]
        else:
            odds_list = simulate_playoff_odds(ctx, platform=platform) or []
            _PLAYOFF_SIM_CACHE[_sim_key] = {"data": odds_list, "ts": time.time()}
    except Exception:
        odds_list = []

    if odds_list:
        odds_list_sorted = sorted(
            odds_list,
            key=lambda o: (
                -o.get("first_seed_pct", 0),
                -o.get("bye_pct", 0),
                -o.get("playoff_pct", 0),
                -o.get("avg_final_wins", 0),
            ),
        )
        seeded_rids = [str(o["roster_id"]) for o in odds_list_sorted[:playoff_teams]]
    else:
        # Fallback: use dynasty value order
        name_to_rid = {v: k for k, v in roster_map.items()}
        seeded_rids = [
            str(name_to_rid[r["name"]])
            for r in team_rows
            if r["name"] in name_to_rid
        ][:playoff_teams]

    seed_map_override: dict = {rid: i + 1 for i, rid in enumerate(seeded_rids)}

    def _rid(seed: int):
        """Return int roster_id for 1-based seed, or None if not enough teams."""
        if seed <= len(seeded_rids):
            v = seeded_rids[seed - 1]
            try:
                return int(v)
            except Exception:
                return v
        return None

    # Build a standard projected bracket for the configured playoff size
    # Seeding: 1,2 get byes; R1 pairings are 3v(N), 4v(N-1), …
    synthetic_bracket: list[dict] = []
    match_id = 1

    if playoff_teams == 6:
        # R1: 3v6, 4v5 → R2 (Semis): 1 vs W(4v5), 2 vs W(3v6) → R3 Finals
        synthetic_bracket = [
            {"m": 1, "r": 1, "t1": _rid(3), "t2": _rid(6), "t1_from": None, "t2_from": None, "w": {"m": 3}},
            {"m": 2, "r": 1, "t1": _rid(4), "t2": _rid(5), "t1_from": None, "t2_from": None, "w": {"m": 4}},
            {"m": 3, "r": 2, "t1": _rid(1), "t2": None,    "t1_from": None, "t2_from": {"w": 2}, "w": {"m": 5}},
            {"m": 4, "r": 2, "t1": _rid(2), "t2": None,    "t1_from": None, "t2_from": {"w": 1}, "w": {"m": 5}},
            {"m": 5, "r": 3, "t1": None,    "t2": None,    "t1_from": {"w": 3}, "t2_from": {"w": 4}},
        ]
    elif playoff_teams == 4:
        # R1 (Semis): 1v4, 2v3 → Finals
        synthetic_bracket = [
            {"m": 1, "r": 1, "t1": _rid(1), "t2": _rid(4), "t1_from": None, "t2_from": None, "w": {"m": 3}},
            {"m": 2, "r": 1, "t1": _rid(2), "t2": _rid(3), "t1_from": None, "t2_from": None, "w": {"m": 3}},
            {"m": 3, "r": 2, "t1": None,    "t2": None,    "t1_from": {"w": 1}, "t2_from": {"w": 2}},
        ]
    elif playoff_teams == 8:
        # R1: 1v8, 4v5 (top half) + 2v7, 3v6 (bottom half) → Semis → Finals
        synthetic_bracket = [
            {"m": 1, "r": 1, "t1": _rid(1), "t2": _rid(8), "t1_from": None, "t2_from": None, "w": {"m": 5}},
            {"m": 2, "r": 1, "t1": _rid(4), "t2": _rid(5), "t1_from": None, "t2_from": None, "w": {"m": 5}},
            {"m": 3, "r": 1, "t1": _rid(2), "t2": _rid(7), "t1_from": None, "t2_from": None, "w": {"m": 6}},
            {"m": 4, "r": 1, "t1": _rid(3), "t2": _rid(6), "t1_from": None, "t2_from": None, "w": {"m": 6}},
            {"m": 5, "r": 2, "t1": None,    "t2": None,    "t1_from": {"w": 1}, "t2_from": {"w": 2}, "w": {"m": 7}},
            {"m": 6, "r": 2, "t1": None,    "t2": None,    "t1_from": {"w": 3}, "t2_from": {"w": 4}, "w": {"m": 7}},
            {"m": 7, "r": 3, "t1": None,    "t2": None,    "t1_from": {"w": 5}, "t2_from": {"w": 6}},
        ]
    else:
        # Generic: no bracket available
        synthetic_bracket = []

    # Use the same ranking source as the Teams page "Power Rankings" tab so the
    # offseason podium matches it exactly (ranks by roster value when no games
    # have been played).
    try:
        from dashboard_services.ai.context_builders import build_power_rankings_context
        _pr_teams = (build_power_rankings_context(ctx) or {}).get("teams") or []
    except Exception:
        _pr_teams = []
    power_playoffs_html = render_power_and_playoffs(
        synthetic_ts, roster_map, league_id_str, platform, season,
        bracket_override=synthetic_bracket,
        seed_map_override=seed_map_override,
        power_rankings=_pr_teams,
    )

    # ── left-column dynasty rankings table ───────────────────────────────────
    _max_total = max((r["total"] for r in team_rows), default=0) or 1
    table_rows_html = ""
    for i, row in enumerate(team_rows, 1):
        av = row["avatar"]
        img = (
            f"<img class='avatar sm' src='{av}' alt='' loading='lazy' decoding='async' onerror=\"this.style.display='none'\">"
            if av else ""
        )
        first_rd = sum(
            1 for pk in (picks_by_roster.get(row["rid"], []) if isinstance(picks_by_roster, dict) else [])
            if int(pk.get("round") or 0) == 1
        )
        picks_label = f"{first_rd} 1st" if first_rd else f"{row['n_picks']} picks" if row["n_picks"] else "–"
        picks_td = "" if platform == "espn" else f"<td class='num'>{picks_label}</td>"
        # Medal rank for the top 3; a value bar scaled to the leader so magnitude
        # reads at a glance (scoped to .dynasty-table so other tables are unchanged).
        rank_cls = f" rank-{i}" if i <= 3 else ""
        tr_cls = " class='is-top3'" if i <= 3 else ""
        bar_pct = max(4, min(100, round(row["total"] / _max_total * 100)))
        table_rows_html += (
            f"<tr{tr_cls}>"
            f"<td class='num'><span class='dyn-rank{rank_cls}'>{i}</span></td>"
            f"<td class='team'>{img} {row['name']}</td>"
            f"<td class='num dyn-val-cell'><span class='dyn-val'>{row['total']:.0f}</span>"
            f"<span class='dyn-bar'><span style='width:{bar_pct}%'></span></span></td>"
            f"<td class='num'>{row['player_v']:.0f}</td>"
            f"{picks_td}"
            f"<td class='num dyn-pct'>{row['value_pct']:.1f}%</td>"
            f"<td class='num dyn-pct'>{row['prod_pct']:.1f}%</td>"
            f"</tr>"
        )

    draft_capital_th = "" if platform == "espn" else "<th>Draft Capital</th>"
    standings_footer = (
        "Roster value · players ranked by dynasty trade market value"
        if platform == "espn"
        else "Dynasty value · players + draft picks · no games played yet"
    )
    table_html = f"""
        <div class="table-wrap">
          <table class="standings-table dynasty-table">
            <thead>
              <tr>
                <th>Rank</th>
                <th>Team</th>
                <th>Value</th>
                <th>Players</th>
                {draft_capital_th}
                <th>Val%</th>
                <th>Proj%</th>
              </tr>
            </thead>
            <tbody>{table_rows_html}</tbody>
          </table>
        </div>
        <div class="footer">{standings_footer}</div>
    """

    return f"""
    <nav class="os-jump-nav std-jump-nav" aria-label="Jump to section">
      <button type="button" class="active" data-jump="os-std-value">Value Rankings</button>
      <button type="button" data-jump="os-std-power">Power &amp; Playoffs</button>
    </nav>
    <div class="standings-main two-col-standings">
      <div class="standings-col os-tab-panel os-tab-active" id="os-std-value">
        <div class="card">
          <div class="card-tabs">
            <div class="tab-strip dynasty-value-strip">
              <button class="tab-btn active" data-tab="standings">Value Rankings</button>
              <div class="tab-panels">
                <div class="tab-panel active" data-tab="standings">
                  {table_html}
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
      <div class="standings-col os-tab-panel" id="os-std-power">
        {power_playoffs_html}
      </div>
    </div>
    <script>
    (function(){{
      var nav = document.querySelector('.std-jump-nav');
      if (!nav) return;
      var ids = Array.prototype.map.call(nav.querySelectorAll('[data-jump]'), function(b){{ return b.getAttribute('data-jump'); }});
      function activate(id){{
        ids.forEach(function(pid){{
          var p = document.getElementById(pid);
          if (p) p.classList.toggle('os-tab-active', pid === id);
        }});
        nav.querySelectorAll('button').forEach(function(x){{ x.classList.toggle('active', x.getAttribute('data-jump') === id); }});
      }}
      nav.querySelectorAll('[data-jump]').forEach(function(btn){{
        btn.addEventListener('click', function(){{ activate(btn.getAttribute('data-jump')); }});
      }});
      var init = nav.querySelector('button.active') || nav.querySelector('button');
      if (init) activate(init.getAttribute('data-jump'));
    }})();
    </script>
    """


def render_share_rankings(ctx: dict) -> str:
    """
    Table showing each team's value share and production share within the league.
    Value share  = roster value / total league value (dynasty player_values).
    Production share = team PF / total league PF.
    """
    team_stats = ctx.get("team_stats")
    rosters    = ctx.get("rosters") or []
    roster_map = ctx.get("roster_map") or {}
    df_weekly  = ctx.get("df_weekly")

    if team_stats is None or team_stats.empty or not rosters:
        return '<div class="otc-movers-empty">Not enough data to compute shares.</div>'

    # ── owner → roster_id map ─────────────────────────────────────
    if df_weekly is not None and not df_weekly.empty and "roster_id" in df_weekly.columns and "owner" in df_weekly.columns:
        owner_to_rid = (df_weekly[["owner", "roster_id"]]
                        .drop_duplicates("owner")
                        .set_index("owner")["roster_id"]
                        .astype(str).to_dict())
    else:
        owner_to_rid = {v: k for k, v in roster_map.items()}

    # ── Value: load from player_values DB ─────────────────────────
    roster_positions = ctx.get("roster_positions") or []
    is_sf = any(str(p).upper() in {"SUPER_FLEX", "SFLEX"} for p in roster_positions)
    val_col = "value_sf" if is_sf else "value_1qb"

    values_by_pid: Dict[str, float] = {}
    try:
        from dashboard_services.db import get_conn
        with get_conn() as _conn:
            rows = _conn.execute(
                f"SELECT player_id, {val_col} AS v FROM player_values WHERE {val_col} IS NOT NULL"
            ).fetchall()
        for r in rows:
            values_by_pid[str(r["player_id"])] = float(r["v"] or 0)
    except Exception:
        logger.debug("suppressed exception", exc_info=True)

    rid_to_roster = {str(r.get("roster_id")): r for r in rosters}

    # ── Roster value per team ─────────────────────────────────────
    rid_to_value: Dict[str, float] = {}
    for rid, r in rid_to_roster.items():
        pids = [str(p) for p in (r.get("players") or [])]
        rid_to_value[rid] = sum(values_by_pid.get(pid, 0.0) for pid in pids)

    league_value_total = sum(rid_to_value.values()) or 1.0

    # ── Production: actual PF in-season, projected avg offseason ─────────────
    league_pf_total = float(team_stats["PF"].sum()) if "PF" in team_stats.columns else 0.0
    is_offseason    = league_pf_total == 0.0
    prod_label      = "Proj. Production Share" if is_offseason else "Production Share"

    # Offseason: use the same Sleeper-first PPG source as the playoff odds page
    rid_to_proj: Dict[str, float] = {}
    if is_offseason:
        try:
            from data_building.simulate_playoff_odds import build_ppg_map, _estimate_from_rosters
            _ppg_map2, _pos_map2 = build_ppg_map(ctx)
            est_teams = _estimate_from_rosters(ctx, ppg_map=_ppg_map2, pos_map=_pos_map2)
            for t in est_teams:
                rid_to_proj[str(t["roster_id"])] = float(t.get("avg") or 0.0)
        except Exception:
            logger.debug("suppressed exception", exc_info=True)

    # ── Build rows ────────────────────────────────────────────────────────────
    if is_offseason:
        proj_total = sum(rid_to_proj.values()) or 1.0
    else:
        proj_total = league_pf_total or 1.0

    rows_data = []
    for _, row in team_stats.iterrows():
        owner = row.get("owner", "")
        pf    = float(row.get("PF", 0) or 0)
        rid   = str(owner_to_rid.get(owner, ""))
        rval  = rid_to_value.get(rid, 0.0)

        if is_offseason:
            prod_val = rid_to_proj.get(rid, 0.0)
        else:
            prod_val = pf

        prod_pct  = prod_val / proj_total  * 100
        value_pct = rval     / league_value_total * 100
        rows_data.append({"owner": owner, "prod_val": prod_val, "roster_value": rval,
                          "prod_pct": prod_pct, "value_pct": value_pct})

    rows_data.sort(key=lambda x: -x["value_pct"])
    league_teams = len(rows_data) or 1
    fair_share   = 100.0 / league_teams

    def bar(pct: float) -> str:
        width = min(pct / (fair_share * 2) * 100, 100)
        color = "var(--accent)" if pct > fair_share else "var(--text-muted)"
        return (f'<div style="height:6px;border-radius:3px;background:var(--border);flex:1;">'
                f'<div style="height:100%;width:{width:.1f}%;border-radius:3px;background:{color};"></div></div>')

    rows_html = ""
    for i, d in enumerate(rows_data):
        rows_html += f"""
        <tr>
          <td style="width:24px;color:var(--text-muted);font-size:11px;text-align:center;">{i+1}</td>
          <td style="font-weight:600;font-size:13px;">{d['owner']}</td>
          <td>
            <div style="display:flex;align-items:center;gap:8px;">
              {bar(d['value_pct'])}
              <span style="font-size:12px;font-weight:700;min-width:38px;text-align:right;">{d['value_pct']:.1f}%</span>
            </div>
          </td>
          <td>
            <div style="display:flex;align-items:center;gap:8px;">
              {bar(d['prod_pct'])}
              <span style="font-size:12px;font-weight:700;min-width:38px;text-align:right;">{d['prod_pct']:.1f}%</span>
            </div>
          </td>
        </tr>"""

    proj_note = " · projected from roster" if is_offseason else ""
    fair_pct  = f"{fair_share:.1f}%"
    return f"""
    <div style="padding:4px 0 8px;font-size:11px;color:var(--text-muted);">
      Fair share per team: {fair_pct}{proj_note} &nbsp;·&nbsp; bar fills to 2× fair share
    </div>
    <table style="width:100%;border-collapse:collapse;">
      <thead>
        <tr style="font-size:11px;color:var(--text-muted);text-transform:uppercase;letter-spacing:.05em;">
          <th style="width:24px;"></th>
          <th style="text-align:left;padding:0 8px 6px 0;">Team</th>
          <th style="text-align:left;padding:0 8px 6px 0;min-width:160px;">Value Share</th>
          <th style="text-align:left;padding:0 0 6px 0;min-width:160px;">{prod_label}</th>
        </tr>
      </thead>
      <tbody style="border-top:1px solid var(--border);">
        {rows_html}
      </tbody>
    </table>"""


def _standings_available_weeks(ctx: dict) -> list:
    """Finalized regular-season weeks available to the standings week-selector,
    ascending. Empty when there aren't enough weeks to compare."""
    df_weekly = ctx.get("df_weekly")
    try:
        if df_weekly is None or df_weekly.empty or "finalized" not in df_weekly.columns:
            return []
        fin = df_weekly[df_weekly["finalized"] == True]
        return sorted(int(w) for w in fin["week"].unique())
    except Exception:
        return []


def _standings_playoff_params(ctx: dict, team_stats):
    """(_pp_spots, _pp_weeks) for render_standings, or (None, None) when the
    playoff race isn't meaningful yet or the format is unknown. Uses the games
    actually played in team_stats, so it stays correct for a week-capped view."""
    _pp_spots = _pp_weeks = None
    try:
        _settings = ctx.get("league_settings") or {}
        _pws = int(_settings.get("playoff_week_start") or 0)
        if _pws > 1:
            _reg_weeks = _pws - 1
            _played = int((team_stats["Wins"] + team_stats["Losses"]
                           + team_stats.get("Ties", 0)).max())
            if 6 <= _played <= _reg_weeks:
                _pp_spots = int(_settings.get("playoff_teams") or 6)
                _pp_weeks = _reg_weeks
    except Exception:
        _pp_spots = _pp_weeks = None
    return _pp_spots, _pp_weeks


def _standings_panels(ctx: dict, power_rankings=None) -> dict:
    """Render the four swappable standings surfaces from ctx. Shared by the
    standings page and the week-selector endpoint, so a "through week N" view is
    just this called with a week-capped ctx (see build_standings_as_of_week).

    power_rankings: value-blended list from build_power_rankings_context to match
    the Teams page (current view); None ranks by the performance PowerScore in
    team_stats, which is what a historical week can reconstruct faithfully."""
    team_stats = ctx["team_stats"]
    roster_map = ctx["roster_map"]
    df_weekly = ctx["df_weekly"]
    rosters = ctx["rosters"]
    num_teams = len({str(r.get("roster_id")) for r in rosters})

    _all_play = _all_play_from_df_weekly(df_weekly)
    _pp_spots, _pp_weeks = _standings_playoff_params(ctx, team_stats)

    standings_html = render_standings(
        team_stats, num_teams, all_play=_all_play,
        playoff_spots=_pp_spots, total_regular_weeks=_pp_weeks,
        movement=_standings_movement(df_weekly),
    )

    if (
            df_weekly is not None
            and not df_weekly.empty
            and "finalized" in df_weekly.columns
    ):
        detailed_df = df_weekly[df_weekly["finalized"] == True].copy()
    else:
        detailed_df = pd.DataFrame()
    details_html = render_team_stats(team_stats, detailed_df)

    power_html = render_power_and_playoffs(
        team_stats,
        roster_map,
        ctx.get("resolved_league_id", ctx["league_id"]),
        ctx["platform"],
        ctx["season"],
        power_rankings=power_rankings,
    )
    sidebar_html = render_standings_sidebar(team_stats)
    return {
        "standings": standings_html,
        "details": details_html,
        "power": power_html,
        "sidebar": sidebar_html,
    }


def build_standings_as_of_week(ctx: dict, week: int) -> dict:
    """Shallow-copied ctx whose team_stats and df_weekly are recomputed through
    the given finalized week, so the standings/power surfaces render as they
    stood then. Values come straight from the weekly scores, so the record,
    PF/PA, streaks and performance PowerScore are all exact for that point."""
    from dashboard_services.service import finalize_team_stats

    df_weekly = ctx["df_weekly"]
    wk = pd.to_numeric(df_weekly["week"], errors="coerce")
    fin = df_weekly[(df_weekly["finalized"] == True) & (wk <= int(week))].copy()

    owner_avatar = {}
    if "owner" in df_weekly.columns and "avatar" in df_weekly.columns:
        owner_avatar = dict(zip(df_weekly["owner"].astype(str), df_weekly["avatar"]))

    team_stats = finalize_team_stats(
        fin, owner_avatar,
        ctx.get("matchups_by_week") or {},
        ctx.get("users") or [],
        int(week),
    )

    new_ctx = dict(ctx)
    new_ctx["team_stats"] = team_stats
    new_ctx["df_weekly"] = fin
    return new_ctx


def _standings_week_selector(ctx: dict, weeks: list) -> str:
    """A 'Through Week N' selector (mirrors the Matchups hub week picker) plus
    the JS that swaps the standings/power/sidebar panels via /api/standings-week.
    Returns '' when there aren't at least two finalized weeks to scrub."""
    if len(weeks) < 2:
        return ""
    latest = weeks[-1]
    opts = "".join(
        f"<option value='{w}'{' selected' if w == latest else ''}>"
        f"Week {w}{' · latest' if w == latest else ''}</option>"
        for w in weeks
    )
    platform_js = json.dumps(str(ctx["platform"]))
    season_js = json.dumps(str(ctx["season"]))
    league_js = json.dumps(str(ctx["league_id"]))
    return f"""
    <div class="standings-week-bar">
      <label for="standingsWeek" class="standings-week-label">Standings through</label>
      <select id="standingsWeek" class="search standings-week-select">{opts}</select>
      <span class="standings-week-hint">See the standings &amp; power ranking as they stood after any week</span>
    </div>
    <script>
    (function() {{
      var sel = document.getElementById('standingsWeek');
      if (!sel || sel.__stBound) return;
      sel.__stBound = true;
      var seq = 0, ctrl = null;
      function panels() {{
        return {{
          standings: document.getElementById('stStandingsInner'),
          details:   document.getElementById('stDetailsInner'),
          power:     document.getElementById('stPowerInner'),
          sidebar:   document.getElementById('stSidebarInner')
        }};
      }}
      function setLoading(on) {{
        var p = panels();
        Object.keys(p).forEach(function(k) {{
          if (p[k]) p[k].classList.toggle('st-week-loading', on);
        }});
      }}
      sel.addEventListener('change', function() {{
        var w = String(sel.value || '');
        if (!w) return;
        var my = ++seq;
        if (ctrl) {{ try {{ ctrl.abort(); }} catch (e) {{}} }}
        ctrl = (typeof AbortController !== 'undefined') ? new AbortController() : null;
        setLoading(true);
        var url = '/api/standings-week?platform=' + encodeURIComponent({platform_js}) +
          '&season=' + encodeURIComponent({season_js}) +
          '&league_id=' + encodeURIComponent({league_js}) +
          '&week=' + encodeURIComponent(w);
        fetch(url, {{ signal: ctrl ? ctrl.signal : undefined }})
          .then(function(r) {{ if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); }})
          .then(function(data) {{
            if (my !== seq || !data || !data.ok) return;
            var p = panels();
            var map = {{ standings: data.standings_html, details: data.details_html,
                        power: data.power_html, sidebar: data.sidebar_html }};
            Object.keys(map).forEach(function(k) {{
              if (p[k] && typeof map[k] === 'string') {{
                if (window.brSwapRanks) {{ window.brSwapRanks(p[k], map[k]); }}
                else {{ p[k].innerHTML = map[k]; }}
                if (window.initPageRoot) window.initPageRoot(p[k]);
                if (window.brInitMoments) window.brInitMoments(p[k]);
              }}
            }});
          }})
          .catch(function(err) {{ if (err && err.name === 'AbortError') return; }})
          .finally(function() {{ if (my === seq) setLoading(false); }});
      }});
    }})();
    </script>
    """

def build_standings_body(ctx: dict) -> str:
    # Value-blended power ranking (matches the Teams page "Power Rankings" tab)
    # for the live view; the week-selector re-renders with the performance
    # PowerScore, which is what past weeks can reconstruct faithfully.
    try:
        from dashboard_services.ai.context_builders import build_power_rankings_context
        _pr_teams = (build_power_rankings_context(ctx) or {}).get("teams") or []
    except Exception:
        _pr_teams = []

    panels = _standings_panels(ctx, power_rankings=_pr_teams)
    share_html = render_share_rankings(ctx)
    week_bar = _standings_week_selector(ctx, _standings_available_weeks(ctx))

    body = f"""
    {week_bar}
    <div class="standings-main two-col-standings">
      <div class="standings-col">
        <div class="card">
          <div class="card-tabs">
            <div class="tab-strip">
              <button class="tab-btn active" data-tab="standings">Standings</button>
              <button class="tab-btn" data-tab="details">Detailed Stats</button>
              <div class="tab-panels">
                <div class="tab-panel active" data-tab="standings">
                  <div id="stStandingsInner">{panels['standings']}</div>
                </div>
                <div class="tab-panel" data-tab="details">
                  <div id="stDetailsInner">{panels['details']}</div>
                  <div class="footer">
                    Default sort: Win% ↓ then PF ↓. Click headers to sort.
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
      <div class="standings-col">
        <div id="stPowerInner">{panels['power']}</div>
      </div>
    </div>
    <div class="card standings-shares-card">
      <h3 class="standings-shares-title">Value &amp; Production Share</h3>
      {share_html}
    </div>
    <aside class="overview-sidebar">
      <div id="stSidebarInner">{panels['sidebar']}</div>
    </aside>
    """

    return body


from utils.waiver_score import (  # noqa: E402
    WAIVER_PRIME_MAX as _WAIVER_PRIME_MAX,
    WEIGHTS,
    adaptive_trend_thresholds as _adaptive_trend_thresholds,
    build_depth_index as _build_depth_index,
    depth_analysis_for_player as _depth_analysis_for_player,
    need_multiplier as _need_multiplier,
    positional_need_scores as _positional_need_scores,
    replacement_levels as _replacement_levels,
    scarcity_multiplier as _scarcity_multiplier,
    strip_bye_weeks as _strip_bye_weeks,
    waiver_pickup_score as _waiver_pickup_score,
    waiver_signal as _waiver_signal,
    weeks_out_from_projections as _weeks_out_from_projections,
)


def _build_waiver_targets_rows(ctx: dict, model_value_table: list, limit: int = 10) -> str:
    """Row markup for the Waiver Wire Targets card, shared by the offseason hub
    and the in-season Season Hub.

    Ranking + signal labels are shared with the /api/waiver-candidates surface
    (utils.waiver_score) so both order and badge players identically. This card
    has no weekly usage data, so the usage-spike term is simply a no-op here.
    Returns '' when no candidates are available.
    """
    rosters = ctx.get("rosters") or []
    players_index = ctx.get("players_index") or {}

    rostered_ids = {
        str(pid)
        for r in rosters
        for pid in (r.get("players") or [])
    }

    # Build a set of sleeper_ids for this year's rookie class from DB.
    _rookie_sids: set[str] = set()
    try:
        from data_building.rookie_pipeline.pipeline import get_active_rookie_class as _arc
        _ry = _arc()
        from dashboard_services.db import get_conn as _gc_w
        with _gc_w() as _wc:
            _rr = _wc.execute(
                "SELECT sleeper_id FROM rookie_prospects WHERE draft_class_year = %s AND sleeper_id IS NOT NULL",
                (_ry,),
            ).fetchall()
        _rookie_sids = {str(r["sleeper_id"]) for r in _rr if r["sleeper_id"]}
    except Exception:
        logger.debug("suppressed exception", exc_info=True)

    # Rookies are only waiver-eligible after the fantasy rookie draft is complete.
    # Detect by checking if any rookie from this year's class is already rostered.
    _rookie_draft_done = bool(_rookie_sids and any(sid in rostered_ids for sid in _rookie_sids))

    # Auto-apply the league's TE premium to waiver values, like elsewhere.
    _tep_dash = te_premium_from_settings(ctx.get("scoring_settings"))

    waiver_candidates = []
    for row in model_value_table:
        if not isinstance(row, dict):
            continue
        pid = str(row.get("id") or "")
        pos = str(row.get("position") or row.get("pos") or "").upper()
        team = str(row.get("team") or players_index.get(pid, {}).get("team") or "").strip().upper()
        if not pid or pid in rostered_ids:
            continue
        if team in ("", "FA", "FREE AGENT"):
            continue
        if pos not in {"QB", "RB", "WR", "TE"}:
            continue
        if pid in _rookie_sids and not _rookie_draft_done:
            continue
        try:
            val = float(row.get("value") or 0.0)
        except Exception:
            val = 0.0
        val = apply_te_premium(val, pos, _tep_dash)
        if val <= 0:
            continue

        try:
            age = float(row.get("age") or 0)
        except Exception:
            age = 0.0

        rank_change = row.get("rank_change_7d")

        # Prioritize name from the current value table row, then fallback to players_index
        player_name = (
            row.get("name") or
            players_index.get(pid, {}).get("name") or
            f"Player {pid}"  # More informative fallback than "Unknown"
        )

        waiver_candidates.append({
            "player_id": pid,
            "name": player_name,
            "position": pos,
            "team": row.get("team") or players_index.get(pid, {}).get("team") or "",
            "value": val,
            "age": age,
            "pos_rank_label": row.get("pos_rank_label") or "",
            "rank_change_7d": rank_change,
        })

    # Bulk-fetch breakout scores for waiver candidates from DB
    # Breakout scores that align with the Breakout Engine page (same season
    # resolution + eligibility gate), so the "Breakout" waiver signal never tags
    # a player the engine wouldn't call a breakout.
    waiver_breakout: dict = {}
    try:
        _db_url = os.getenv("DATABASE_URL", "").strip()
        if _db_url and not any(t in _db_url for t in ("USER", "PASSWORD", "HOST")):
            from dashboard_services.breakout_api import aligned_breakout_scores as _abs
            _bo_season = ctx.get("season") or ctx.get("current_season")
            waiver_breakout = _abs(
                [c["player_id"] for c in waiver_candidates[:100]],
                int(_bo_season) if _bo_season else None,
            )
    except Exception:
        logger.debug("suppressed exception", exc_info=True)

    waiver_candidates.sort(
        key=lambda c: _waiver_pickup_score(c, waiver_breakout, _WAIVER_PRIME_MAX),
        reverse=True,
    )

    waiver_html = []
    _shown_waivers = waiver_candidates[:limit]
    # Badge trend relative to the shown set so a trend-sorted list doesn't read
    # "Rising Fast" on every row.
    _wv_fast_thr, _wv_up_thr = _adaptive_trend_thresholds(
        [c.get("rank_change_7d") for c in _shown_waivers]
    )
    for p in _shown_waivers:
        sub_bits = [p["position"]]
        if p["team"]:
            sub_bits.append(p["team"])
        if p["pos_rank_label"]:
            sub_bits.append(p["pos_rank_label"])
        if p["age"]:
            sub_bits.append(f"Age {p['age']:.1f}")
        subline = " • ".join(sub_bits)

        sig_cls, sig_label = _waiver_signal(
            p, waiver_breakout, _WAIVER_PRIME_MAX,
            fast_thr=_wv_fast_thr, up_thr=_wv_up_thr,
        )

        waiver_html.append(
            f"""
            <div class="os-waiver-row">
              <div class="os-waiver-main">
                <div class="os-waiver-name-row">
                  <span class="os-waiver-name player-clickable" style="cursor:pointer;font-weight:600;" data-player-id='{p['player_id']}' data-player-name='{p['name']}'>{p['name']}</span>
                </div>
                <div class="os-waiver-sub">{subline}</div>
              </div>
              <div class="os-waiver-right">
                <span class="chip chip--sm {sig_cls}">{sig_label}</span>
                <span class="os-waiver-value">{p['value']:.0f}</span>
              </div>
            </div>
            """
        )

    return "".join(waiver_html)


_WEEK1_KICKOFF_CACHE: dict = {}      # season -> (fetched_at, ts_ms | None)
_WEEK1_KICKOFF_TTL = 6 * 3600        # 6h — the schedule is static once published


def _nfl_regular_season_kickoff_ms(season: int):
    """Epoch-ms kickoff of the FIRST NFL *regular-season* game of `season`.

    Reads the app's schedule data (Tank01 Week 1, seasonType='reg') and takes the
    earliest game start, so the countdown targets the real Week 1 opener — never a
    preseason game. Falls back to the Thursday-after-Labor-Day opener (~8:20 PM
    ET) if the schedule isn't published yet. Cached (6h) and fail-soft.
    """
    import time as _t
    now = _t.time()
    hit = _WEEK1_KICKOFF_CACHE.get(season)
    if hit and now - hit[0] < _WEEK1_KICKOFF_TTL:
        return hit[1]

    ts_ms = None
    try:
        from dashboard_services.api import get_nfl_games_for_week_raw
        games = get_nfl_games_for_week_raw(1, int(season), "reg") or []
        epochs = []
        for g in games:
            if not isinstance(g, dict):
                continue
            _e = g.get("gameTime_epoch") or g.get("gameTimeEpoch")
            try:
                ev = float(_e)
            except (TypeError, ValueError):
                continue
            if ev > 0:
                epochs.append(ev)
        if epochs:
            ts_ms = int(min(epochs) * 1000)
    except Exception:
        logger.debug("[offseason] week 1 schedule fetch failed", exc_info=True)

    if ts_ms is None:
        # Deterministic opener: the Thursday after Labor Day (first Monday of Sep).
        try:
            _sep1 = date(int(season), 9, 1)
            _labor = _sep1 + timedelta(days=(0 - _sep1.weekday()) % 7)
            _kick = _labor + timedelta(days=3)
            ts_ms = int(datetime(_kick.year, _kick.month, _kick.day, 20, 20,
                                 tzinfo=EASTERN).timestamp() * 1000)
        except Exception:
            ts_ms = None

    _WEEK1_KICKOFF_CACHE[season] = (now, ts_ms)
    return ts_ms


def build_offseason_dashboard_body(ctx: dict) -> str:
    league = ctx["league"]
    platform = ctx["platform"]
    season = ctx["season"]
    rosters = ctx["rosters"]
    users = ctx["users"]
    roster_map = ctx["roster_map"]
    picks_by_roster = ctx.get("picks_by_roster", {})
    players_index = ctx["players_index"]
    players_map = ctx["players_map"]
    # Read the live cached model table directly (the same source the player modal
    # uses) instead of ctx["model_value_table"], which gets pinned into the
    # longer-lived league-context cache and goes stale — making the waiver list
    # and roster values disagree with the modal after a value rebuild.
    model_value_table = list(get_model_value_table_cached() or []) or (ctx.get("model_value_table") or [])

    viewer = ctx.get("viewer") or {}
    viewer_roster_id = viewer.get("viewer_roster_id")

    # Season-in-review of the just-completed season (renders nothing if the
    # offseason ctx has no finalized weekly data for the viewer).
    season_review_html = _render_season_review_card(
        ctx, viewer_roster_id, ctx.get("df_weekly"), ctx.get("team_stats")
    )

    latest_draft = ctx.get("latest_draft")
    countdown_label = "Draft countdown"
    draft_text = "Draft date not set"
    countdown_text = "TBD"
    draft_subtext = "Set once your league schedules the draft."

    # First NFL regular-season game kickoff (from the app's schedule), not the
    # preseason — used for the no-draft-scheduled tile and the post-draft
    # countdown alike. See _nfl_regular_season_kickoff_ms.
    _week1_delta = None
    _week1_date_txt = ""
    _week1_ts_ms = _nfl_regular_season_kickoff_ms(int(season))
    if _week1_ts_ms:
        try:
            _week1_dt = datetime.fromtimestamp(_week1_ts_ms / 1000, tz=EASTERN)
            _week1_delta = (_week1_dt.date() - datetime.now(EASTERN).date()).days
            _week1_date_txt = _week1_dt.strftime("%b %d, %Y")
        except Exception as e:
            logger.info(f"[offseason] kickoff parse failed: {e}")

    draft_ts_ms = None

    if isinstance(latest_draft, dict):
        draft_ts_ms = _safe_int(latest_draft.get("start_time"))

    if draft_ts_ms is None:
        draft_ts_ms = _safe_int(league.get("draft_day"))

    # The timestamp the card counts down to: the draft while it's upcoming, then
    # NFL Week 1 kickoff once the draft is done. JS mirrors this (see below).
    _target_ts_ms = draft_ts_ms or 0
    _draft_status = (
        str((latest_draft or {}).get("status") or "").lower()
        if isinstance(latest_draft, dict) else ""
    )

    if draft_ts_ms:
        try:
            draft_dt = datetime.fromtimestamp(draft_ts_ms / 1000, tz=EASTERN)
            now_dt = datetime.now(EASTERN)
            delta_days = (draft_dt.date() - now_dt.date()).days
            # "Done" = the draft is complete, or its scheduled time is in the past.
            draft_done = _draft_status == "complete" or delta_days < 0

            if not draft_done:
                # Draft hasn't happened yet — count down to it.
                countdown_label = "Draft countdown"
                countdown_text = "Today!" if delta_days == 0 else f"{delta_days} days"
                draft_text = draft_dt.strftime("%b %d, %Y at %I:%M %p %Z")
                draft_subtext = "Countdown to your next league draft."
                _target_ts_ms = draft_ts_ms
            else:
                # Draft is finished — count down to NFL Week 1 kickoff, and show
                # the Week 1 date (not the stale draft date) as the sub-line.
                countdown_label = "Season kickoff"
                _target_ts_ms = _week1_ts_ms or 0
                if _week1_delta is not None:
                    if _week1_delta > 0:
                        countdown_text = f"{_week1_delta} days"
                        draft_text = f"Week 1 kicks off {_week1_date_txt}"
                        draft_subtext = "Countdown to Week 1 kickoff."
                    elif _week1_delta == 0:
                        countdown_text = "Today!"
                        draft_text = "Week 1 starts today"
                        draft_subtext = "Week 1 starts today!"
                    else:
                        countdown_text = "Season started"
                        draft_text = f"Week 1 kicked off {_week1_date_txt}"
                        draft_subtext = "Week 1 is underway!"
                else:
                    countdown_text = "Draft complete"
                    draft_text = "Draft has finished"
                    draft_subtext = "Awaiting season start date."
        except Exception:
            logger.debug("suppressed exception", exc_info=True)
    elif _week1_delta is not None and _week1_delta >= 0:
        # No draft on the calendar: count down to the season itself instead of
        # sitting on a dead "TBD" tile all summer.
        countdown_label = "Season kickoff"
        _target_ts_ms = _week1_ts_ms or 0
        if _week1_delta == 0:
            countdown_text = "Today!"
            draft_text = "Week 1 starts today"
        else:
            countdown_text = f"{_week1_delta} days"
            draft_text = f"Week 1 kicks off {_week1_date_txt}"
        draft_subtext = "Draft date not set - schedule it before kickoff."

    teams_ctx = build_teams_overview(
        rosters=rosters,
        users_list=users,
        picks_by_roster=picks_by_roster,
        players=players_map,
        players_index=players_index,
        teams_index=ctx["teams_index"],
        platform=platform,
    )
    teams_sidebar_html = render_teams_sidebar(teams_ctx)

    values_by_id = {}
    for row in model_value_table:
        if isinstance(row, dict) and row.get("id") is not None:
            try:
                values_by_id[str(row["id"])] = float(row.get("value") or 0.0)
            except Exception:
                values_by_id[str(row["id"])] = 0.0

    # Build pick-value lookup from WLS-derived table (overlays FantasyCalc/DynastyProcess)
    pick_by_key: Dict[str, float] = load_pick_value_table() or {}

    # TE-premium scaling so the snapshot total matches the team modal (and the
    # trade calculator / activity feed), which scale TE values up for leagues
    # that award bonus points per TE reception.
    _tep_snap = te_premium_from_settings(ctx.get("scoring_settings"))

    roster_cards = []

    for r in rosters:
        rid = str(r.get("roster_id"))
        team_name = roster_map.get(rid, f"Roster {rid}")
        player_ids = [str(pid) for pid in (r.get("players") or [])]
        roster_value = sum(
            apply_te_premium(
                values_by_id.get(pid, 0.0),
                (players_index.get(pid) or {}).get("pos"),
                _tep_snap,
            )
            for pid in player_ids
        )
        team_picks = picks_by_roster.get(rid, []) if isinstance(picks_by_roster, dict) else []
        pick_count = len(team_picks)

        # Add pick values to total roster value
        league_id_str = str(ctx.get("league_id") or "")
        roster_value += _team_pick_value(
            team_picks, pick_by_key,
            platform=platform, league_id=league_id_str, season=_safe_int(season, 0),
        )

        first_round_count = 0
        for pk in team_picks:
            try:
                if int(pk.get("round") or 0) == 1:
                    first_round_count += 1
            except Exception:
                logger.debug("suppressed exception", exc_info=True)

        roster_cards.append({
            "team_name": team_name,
            "roster_value": roster_value,
            "pick_count": pick_count,
            "first_round_count": first_round_count,
            "roster_id": rid,
        })

    roster_cards.sort(key=lambda x: x["roster_value"], reverse=True)

    # Value leaderboard: rank medallion (gold/silver/bronze for the top 3), a bar
    # scaled to the leader so magnitudes read at a glance, and canonical chips.
    max_value = roster_cards[0]["roster_value"] if roster_cards and roster_cards[0]["roster_value"] > 0 else 1
    ranked_snapshot_html = []
    for idx, card in enumerate(roster_cards, start=1):
        rv = card["roster_value"]
        pct = max(4, min(100, round(rv / max_value * 100)))
        fr = card["first_round_count"]
        pc = card["pick_count"]
        chips = []
        if fr > 0:
            chips.append(f"<span class='chip chip--sm'>{fr} first{'s' if fr != 1 else ''}</span>")
        if pc > 0:
            chips.append(f"<span class='chip chip--sm'>{pc} future pick{'s' if pc != 1 else ''}</span>")
        chips_html = f"<div class=\"os-snap-chips\">{''.join(chips)}</div>" if chips else ""
        medal_cls = f"is-{idx}" if idx <= 3 else ""
        ranked_snapshot_html.append(
            f"""
            <div class="os-snap-row {medal_cls} team-clickable" style="cursor:pointer;" data-roster-id="{card['roster_id']}" data-team-name="{card['team_name']}">
              <div class="os-snap-medal">{idx}</div>
              <div class="os-snap-body">
                <div class="os-snap-head">
                  <div class="os-snap-name">{card['team_name']}</div>
                  <div class="os-snap-valblock">
                    <div class="os-snap-value">{rv:,.0f}</div>
                    <div class="os-snap-kicker">Total value</div>
                  </div>
                </div>
                <div class="os-snap-bar"><span style="width:{pct}%"></span></div>
                {chips_html}
              </div>
            </div>
            """
        )

    roster_cards_html = "".join(ranked_snapshot_html)

    roster_leader = roster_cards[0]["team_name"] if roster_cards else "N/A"
    highest_roster_value = f"{roster_cards[0]['roster_value']:,.0f}" if roster_cards else "0"
    
    # Calculate total draft capital across all rosters
    total_draft_capital = 0.0
    for roster in rosters:
        roster_id = str(roster.get("roster_id"))
        player_ids = [str(pid) for pid in (roster.get("players") or [])]
        roster_value = sum(values_by_id.get(pid, 0.0) for pid in player_ids)
        team_picks = picks_by_roster.get(roster_id, []) if isinstance(picks_by_roster, dict) else []
        pick_count = len(team_picks)
        
