@app.route("/api/waiver-candidates")
def api_waiver_candidates():
    """
    Returns scored waiver wire candidates for a league.
    Query params: platform, league_id, season, position (optional filter)
    """
    platform = (request.args.get("platform") or "sleeper").strip().lower()
    league_id = (request.args.get("league_id") or "").strip()
    season = int(request.args.get("season") or datetime.now().year)
    position_filter = (request.args.get("position") or "").strip().upper()

    if not league_id:
        return jsonify({"error": "league_id required"}), 400

    try:
        ctx = get_league_ctx_from_cache(platform, league_id, season)
    except Exception as e:
        return _api_err("Request failed", e)

    rosters = ctx.get("rosters") or []
    rostered_ids = {
        str(pid)
        for r in rosters
        for pid in (r.get("players") or [])
    }

    # Detect whether the rookie draft has happened by checking if any
    # current-year rookie Sleeper ID is already on a roster
    _rookie_sids_wv: set[str] = set()
    try:
        from data_building.rookie_pipeline.pipeline import get_active_rookie_class as _grc_wv
        from dashboard_services.db import get_conn as _gc_wv
        _ry_wv = _grc_wv()
        with _gc_wv() as _cc_wv:
            _rr_wv = _cc_wv.execute(
                "SELECT sleeper_id FROM rookie_prospects WHERE draft_class_year = %s AND sleeper_id IS NOT NULL",
                (_ry_wv,),
            ).fetchall()
        _rookie_sids_wv = {str(r["sleeper_id"]) for r in _rr_wv if r["sleeper_id"]}
    except Exception:
        logger.debug("suppressed exception", exc_info=True)
    _rookie_draft_done_wv = bool(_rookie_sids_wv and any(sid in rostered_ids for sid in _rookie_sids_wv))

    players_index = ctx.get("players_index") or {}
    model_value_table = list(get_model_value_table_cached() or [])

    _rp_wv = ctx.get("roster_positions") or []
    _is_sf_wv = any(str(s).upper() in {"SUPER_FLEX", "SFLEX"} for s in _rp_wv)
    _vf_wv = "sf_value" if _is_sf_wv else "value"
    # Auto-apply the league's TE premium, exactly like Superflex auto-picks the
    # value column: a no-op for non-TE-premium leagues / non-TEs.
    _tep_wv = te_premium_from_settings(ctx.get("scoring_settings"))

    candidates = []
    for row in model_value_table:
        if not isinstance(row, dict):
            continue
        pid = str(row.get("id") or "")
        pos = str(row.get("position") or row.get("pos") or "").upper()
        team = str(row.get("team") or players_index.get(pid, {}).get("team") or "").strip().upper()
        if not pid or pid in rostered_ids:
            continue
        if pid in _rookie_sids_wv and not _rookie_draft_done_wv:
            continue
        if team in ("", "FA", "FREE AGENT"):
            continue
        if pos not in {"QB", "RB", "WR", "TE"}:
            continue
        try:
            val = float(row.get(_vf_wv) or row.get("value") or 0.0)
        except Exception:
            val = 0.0
        val = apply_te_premium(val, pos, _tep_wv)
        if val <= 0:
            continue
        pmeta_wv = players_index.get(pid, {})
        precise_age_wv = age_from_bday(pmeta_wv.get("bDay"))
        try:
            age = precise_age_wv if precise_age_wv is not None else float(row.get("age") or 0)
        except Exception:
            age = 0.0
        player_name = (
            row.get("name")
            or pmeta_wv.get("name")
            or f"Player {pid}"
        )
        candidates.append({
            "player_id": pid,
            "name": player_name,
            "position": pos,
            "team": row.get("team") or players_index.get(pid, {}).get("team") or "",
            "value": val,
            "age": age,
            "pos_rank_label": row.get("pos_rank_label") or "",
            "rank_change_7d": row.get("rank_change_7d"),
        })

    # Breakout scores that align with the Breakout Engine page (same season
    # resolution + eligibility gate), so the "Breakout" waiver signal never tags
    # a player the engine wouldn't call a breakout.
    waiver_breakout: dict = {}
    try:
        _db_url = os.getenv("DATABASE_URL", "").strip()
        if _db_url and not any(t in _db_url for t in ("USER", "PASSWORD", "HOST")):
            from dashboard_services.breakout_api import aligned_breakout_scores as _abs
            waiver_breakout = _abs(
                [c["player_id"] for c in candidates[:100]],
                int(season) if season else None,
            )
    except Exception:
        logger.debug("suppressed exception", exc_info=True)

    # Weekly usage trends: recent role growth is the strongest waiver signal.
    # Usage trends are a live in-season signal: last-3-week average vs season
    # average. In the offseason the only data is last season's final weeks, which
    # reads as if it were current activity ("Usage Spike / +6 touches" in July),
    # so we hide usage entirely until real games return. Value/breakout signals
    # ("Breakout", "Trending Up" from value-rank movement) still show.
    usage_trends: dict = {}
    try:
        from data_building.weekly_metrics import get_usage_trends
        _nfl_wv = get_nfl_state() or {}
        if str(_nfl_wv.get("season_type") or "").lower() != "off":
            usage_trends = get_usage_trends(int(_nfl_wv.get("season") or season))
    except Exception:
        usage_trends = {}

    # Depth-chart injury vacancies: an injured player ahead of a candidate on
    # the same team+position frees up the role directly. The reduced players_index
    # cache lacks depth_chart_order / injury_status, so pull the full Sleeper
    # players feed (get_players_global) and index it once per request.
    _depth_idx_wv: dict = {}
    _full_players_wv: dict = {}
    try:
        _full_players_wv = get_players_global() or {}
        _depth_idx_wv = _build_depth_index(_full_players_wv)
    except Exception:
        logger.debug("suppressed exception", exc_info=True)

    # Recent PPR points-per-game as a rest-of-season production proxy (#5), also
    # reused to size injury vacancies by the vacated role's production (#7).
    _ppg_by_pid_wv: dict = {}
    try:
        from utils.utils import load_usage_table
        for _u in (load_usage_table() or []):
            if isinstance(_u, dict):
                _upid = str(_u.get("player_id") or _u.get("id") or "")
                if _upid:
                    _ppg_by_pid_wv[_upid] = _u.get("ppr_ppg")
    except Exception:
        logger.debug("suppressed exception", exc_info=True)

    # Season projected PPG — the *healthy* production of a role, used to value an
    # injury vacancy (the injured player projects ~0 while hurt, so their own
    # recent ppg understates the role).
    _season_ppg_wv: dict = {}
    try:
        from data_building.fetch_projections import fetch_fp_season_projections
        _nfl_pj = get_nfl_state() or {}
        _pj_season = int(_nfl_pj.get("season") or season)
        for _pid, _row in (fetch_fp_season_projections(_pj_season, "ppr") or {}).items():
            if isinstance(_row, dict) and _row.get("ppg") is not None:
                _season_ppg_wv[str(_pid)] = _row.get("ppg")
    except Exception:
        logger.debug("suppressed exception", exc_info=True)

    # Upcoming weekly projections — a player projected for ~0 points across the
    # next N weeks IS the projection provider's read on how long they're out, so
    # count the leading zero-run to get the injury timeline directly (#: weeks
    # out from projections rather than guessing from the injury label).
    _future_week_projs_wv: list = []
    _future_week_teams_wv: list = []   # parallel: set of teams playing each week
    try:
        from utils.utils import load_week_projection, load_week_schedule
        _nfl_wk = get_nfl_state() or {}
        _proj_season = int(_nfl_wk.get("season") or season)
        _cur_week = int(_nfl_wk.get("week") or _nfl_wk.get("display_week") or 1)
        _horizon = int(round(float(WEIGHTS.injury_horizon_weeks))) + 2
        for _w in range(_cur_week, _cur_week + _horizon):
            _wp = load_week_projection(_proj_season, _w) or {}
            _future_week_projs_wv.append(_wp if isinstance(_wp, dict) else {})
            _teams = set()
            for _g in (load_week_schedule(_proj_season, _w) or []):
                if isinstance(_g, dict):
                    for _side in ("away", "home"):
                        _t = str(_g.get(_side) or "").upper()
                        if _t:
                            _teams.add(_t)
            _future_week_teams_wv.append(_teams)
    except Exception:
        logger.debug("suppressed exception", exc_info=True)

    def _week_pts_wv(week_map, pid):
        """Extract a numeric weekly projection for pid from a (possibly
        variant-nested) week projection map; None when absent."""
        v = (week_map or {}).get(str(pid))
        if isinstance(v, dict):
            for _k in ("ppr", "pts", "points", "proj", "half_ppr", "std"):
                if _k in v:
                    v = v[_k]
                    break
        try:
            return float(v) if v is not None and not isinstance(v, dict) else None
        except (TypeError, ValueError):
            return None

    def _weeks_out_wv(pid):
        """Projection-derived weeks-out for an injured player, or None if the
        weekly projections aren't available. Bye weeks (team not scheduled) are
        stripped first so a bye isn't mistaken for a missed game."""
        if not _future_week_projs_wv:
            return None
        _pm = _full_players_wv.get(str(pid)) or players_index.get(str(pid)) or {}
        _team = str(_pm.get("team") or "").upper()
        series = [_week_pts_wv(_wm, pid) for _wm in _future_week_projs_wv]
        plays = [
            (_team in _tset) if (_tset and _team) else True
            for _tset in _future_week_teams_wv
        ]
        series = _strip_bye_weeks(series, plays)
        if all(x is None for x in series):
            return None
        return _weeks_out_from_projections(series)

    def _forward_ppg_wv(pid):
        """Mean of a player's own upcoming (non-bye) weekly projections — a
        forward-looking production estimate (#1), better than backward ppg."""
        if not _future_week_projs_wv:
            return None
        _pm = _full_players_wv.get(str(pid)) or players_index.get(str(pid)) or {}
        _team = str(_pm.get("team") or "").upper()
        vals = []
        for _i, _wm in enumerate(_future_week_projs_wv):
            _tset = _future_week_teams_wv[_i] if _i < len(_future_week_teams_wv) else set()
            if _tset and _team and _team not in _tset:
                continue  # bye
            _p = _week_pts_wv(_wm, pid)
            if _p is not None:
                vals.append(max(0.0, _p))
        return (sum(vals) / len(vals)) if vals else None

    # Upcoming schedule ease per position (#3): a soft slate nudges a candidate up.
    _matchup_by_pos_wv: dict = {}
    try:
        for _mp in ("QB", "RB", "WR", "TE"):
            _rmap, _mtot, _minfo, _mz = _matchup_rank_table(season, _mp)
            _matchup_by_pos_wv[_mp] = (_rmap or {}, int(_mtot or 0))
    except Exception:
        logger.debug("suppressed exception", exc_info=True)

    # Positional scarcity / value-over-replacement (#4): value above the position's
    # replacement level is worth more where the drop-off is steeper.
    _repl_by_pos_wv: dict = {}
    try:
        _vals_by_pos = {}
        for _row in model_value_table:
            if isinstance(_row, dict):
                _rpos = str(_row.get("position") or _row.get("pos") or "").upper()
                if _rpos in ("QB", "RB", "WR", "TE"):
                    try:
                        _vals_by_pos.setdefault(_rpos, []).append(float(_row.get("value") or 0.0))
                    except (TypeError, ValueError):
                        pass
        _teams_n = len(rosters) or 12
        _repl_cutoffs = {"QB": _teams_n * 2, "RB": _teams_n * 3,
                         "WR": _teams_n * 3, "TE": _teams_n * 1}
        _repl_by_pos_wv = _replacement_levels(_vals_by_pos, _repl_cutoffs)
    except Exception:
        logger.debug("suppressed exception", exc_info=True)

    # Viewer roster need (#4): a position the viewer is short on is worth more.
    _need_scores_wv: dict = {}
    try:
        _rp_counts = {}
        for _s in _rp_wv:
            _rp_counts[str(_s).upper()] = _rp_counts.get(str(_s).upper(), 0) + 1
        _flex_n = _rp_counts.get("FLEX", 0)
        _sf_n = _rp_counts.get("SUPER_FLEX", 0) + _rp_counts.get("SFLEX", 0)
        _starter_reqs = {
            "QB": _rp_counts.get("QB", 0) + _sf_n + 1,
            "RB": _rp_counts.get("RB", 0) + _flex_n + _sf_n + 1,
            "WR": _rp_counts.get("WR", 0) + _flex_n + _sf_n + 1,
            "TE": _rp_counts.get("TE", 0) + 1,
        }
        _vsess = get_viewer_session_for_league(ctx.get("users") or [], rosters)
        _vrid = str((_vsess or {}).get("viewer_roster_id") or "")
        if _vrid:
            _vros = next((r for r in rosters if str(r.get("roster_id")) == _vrid), None)
            if _vros:
                _counts = {}
                for _pid in (_vros.get("players") or []):
                    _pp = _full_players_wv.get(str(_pid)) or players_index.get(str(_pid)) or {}
                    _ppos = str(_pp.get("position") or _pp.get("pos") or "").upper()
                    if _ppos in ("QB", "RB", "WR", "TE"):
                        _counts[_ppos] = _counts.get(_ppos, 0) + 1
                _need_scores_wv = _positional_need_scores(_counts, _starter_reqs)
    except Exception:
        logger.debug("suppressed exception", exc_info=True)

    _now_ms_wv = time.time() * 1000.0

    def _freshness_wv(injured_pids):
        # Proxy for injury recency via Sleeper's last_modified (ms): a role that
        # went stale weeks ago is largely already absorbed by whoever replaced it.
        lms = [
            _full_players_wv.get(str(p), {}).get("last_modified")
            for p in (injured_pids or [])
        ]
        lms = [x for x in lms if isinstance(x, (int, float)) and x > 0]
        if not lms:
            return 1.0
        days_old = (_now_ms_wv - max(lms)) / 86400000.0
        return max(0.6, min(1.0, 1.0 - max(0.0, days_old - 10.0) / 60.0))

    # Attach every signal the shared scorer/labeler in utils.waiver_score reads,
    # so ranking + badge reflect: usage spikes, depth-chart injury vacancies
    # (proximity/volume/freshness weighted), the candidate's own health, roster
    # need, and rest-of-season production — not just static dynasty value.
    for c in candidates:
        # Safe defaults so a failed signal-join for one candidate can't 500 the
        # whole response (or the sort / result-building below that read these).
        c.setdefault("usage_delta", None)
        c.setdefault("usage_stat", None)
        c["injured_ahead"] = c.get("injured_ahead") or []
        c.setdefault("healthy_ahead", None)
        c["vacated"] = c.get("vacated") or []
        c.setdefault("injury_freshness", None)
        c.setdefault("self_status", "")
        c.setdefault("own_proj_ppg", None)
        c.setdefault("ros_ppg", None)
        c.setdefault("need_mult", 1.0)
        c.setdefault("schedule_ease_rank", None)
        c.setdefault("schedule_total", 0)
        c.setdefault("scarcity_mult", 1.0)
        try:
            ut = usage_trends.get(c["player_id"]) or {}
            c["usage_delta"] = ut.get("delta")
            c["usage_stat"] = ut.get("stat")

            _da = _depth_analysis_for_player(c["player_id"], _full_players_wv, _depth_idx_wv)
            _inj_pids = _da.get("injured_pids_ahead") or []
            c["injured_ahead"] = _da.get("injured_ahead") or []
            c["healthy_ahead"] = _da.get("healthy_ahead") or 0
            # Value each vacancy from the injured player's role production (healthy
            # season projected ppg, else recent ppg) and, crucially, from how long
            # they're projected to be out (leading zero-run in the weekly
            # projections) rather than a fixed guess by injury label.
            _vac = _da.get("vacated") or []
            for _v in _vac:
                _vpid = str(_v.get("pid"))
                _v["proj_ppg"] = _season_ppg_wv.get(_vpid) or _ppg_by_pid_wv.get(_vpid)
                _v["weeks_out"] = _weeks_out_wv(_vpid)
            c["vacated"] = _vac
            c["injury_freshness"] = _freshness_wv(_inj_pids)

            _self = _full_players_wv.get(c["player_id"]) or {}
            c["self_status"] = _self.get("injury_status") or _self.get("status") or ""

            # Forward projected ppg for this candidate (#1) — used for production
            # and, via the transfer guard (#2), to fade injury upside taken.
            _fwd_ppg = _forward_ppg_wv(c["player_id"])
            c["own_proj_ppg"] = _fwd_ppg
            c["ros_ppg"] = _fwd_ppg if _fwd_ppg is not None else _ppg_by_pid_wv.get(c["player_id"])

            c["need_mult"] = _need_multiplier(c["position"], _need_scores_wv)

            # Upcoming schedule ease (#3).
            _team_up = str(_self.get("team") or players_index.get(c["player_id"], {}).get("team")
                           or c.get("team") or "").upper()
            _rmap_s, _tot_s = _matchup_by_pos_wv.get(c["position"], ({}, 0))
            c["schedule_ease_rank"] = _rmap_s.get(_team_up)
            c["schedule_total"] = _tot_s

            # Positional scarcity (#4).
            c["scarcity_mult"] = _scarcity_multiplier(c["position"], c["value"], _repl_by_pos_wv)
        except Exception:
            logger.exception("[waiver-candidates] signal join failed for %s", c.get("player_id"))
            continue

    def _safe_pickup_score(c):
        try:
            return _waiver_pickup_score(c, waiver_breakout, _WAIVER_PRIME_MAX)
        except Exception:
            logger.exception("[waiver-candidates] pickup score failed for %s", c.get("player_id"))
            return 0.0

    candidates.sort(key=_safe_pickup_score, reverse=True)
    if position_filter and position_filter in {"QB", "RB", "WR", "TE"}:
        candidates = [c for c in candidates if c["position"] == position_filter]

    result = []
    _shown = candidates[:30]
    # Badge trend relative to the shown set so the (trend-sorted) list doesn't
    # read "Rising Fast" on every row.
    _fast_thr, _up_thr = _adaptive_trend_thresholds([c.get("rank_change_7d") for c in _shown])

    # Suggested FAAB bid band (% of budget). Only the top targets warrant real
    # money; a player who fills the viewer's own roster need is nudged up. A band
    # rather than a number because league budgets differ ($100 / $1000 / rolling);
    # the % reads the same regardless. Gated client-side on the league using FAAB.
    # Strict FAAB detection. Sleeper defaults waiver_budget to 100 even for
    # rolling / reverse-priority leagues, so a budget alone is a false positive -
    # the only reliable Sleeper FAAB signal is waiver_type == 2. ESPN uses an
    # explicit acquisition budget. Fail closed when FAAB can't be confirmed so a
    # non-FAAB league never sees a bid % it can't use.
    _wv_settings = (ctx.get("league") or {}).get("settings") or {}
    _faab_enabled = (
        _safe_int(_wv_settings.get("waiver_type"), -1) == 2          # Sleeper FAAB
        or _safe_int(_wv_settings.get("acquisition_budget"), 0) > 0  # ESPN FAAB
    )
    _wv_scores = [_safe_pickup_score(c) for c in _shown]
    _wv_smin = min(_wv_scores) if _wv_scores else 0.0
    _wv_srng = ((max(_wv_scores) - _wv_smin) if _wv_scores else 1.0) or 1.0

    def _faab_band(_c):
        _t = (_safe_pickup_score(_c) - _wv_smin) / _wv_srng          # 0..1 within shown set
        _center = 1.0 + (_t ** 1.7) * 34.0                           # top target ~35%, tapers fast
        _center *= 1.0 + min(max((_c.get("need_mult") or 1.0) - 1.0, 0.0), 0.35)  # fills your need → bid up
        return max(0, int(round(_center * 0.78))), min(70, int(round(_center * 1.12)) + 1)

    # ── Add/drop pairing: for each target, the best player on the viewer's own
    # roster to cut to make room. Prefer thinning a position where the viewer is
    # deep (esp. the add's own position); only ever suggest a drop that's a value
    # downgrade from the add, so the pairing is always a genuine upgrade. Needs
    # the viewer's roster, passed as ?rid= (the shared page cache means the client
    # supplies it, matching the window._viewerRid personalization pattern).
    _rid = (request.args.get("rid") or "").strip()
    _mvt_by_id = {str(r.get("id")): r for r in model_value_table
                  if isinstance(r, dict) and r.get("id")}
    _KEEP = {"QB": 2, "RB": 5, "WR": 6, "TE": 2}   # keep-depth before a spot is "spare"

    def _roster_val(pid: str) -> float:
        row = _mvt_by_id.get(pid) or {}
        try:
            return apply_te_premium(
                float(row.get(_vf_wv) or row.get("value") or 0.0),
                str(row.get("position") or "").upper(), _tep_wv)
        except Exception:
            return 0.0

    _drop_pool: list = []
    _pos_counts: dict = {}
    _viewer_roster = next((r for r in rosters if str(r.get("roster_id")) == _rid), None) if _rid else None
    if _viewer_roster:
        for pid in (_viewer_roster.get("players") or []):
            pid = str(pid)
            row = _mvt_by_id.get(pid) or {}
            meta = players_index.get(pid, {})
            pos = str(row.get("position") or meta.get("pos") or "").upper()
            name = row.get("name") or meta.get("name") or f"Player {pid}"
            _pos_counts[pos] = _pos_counts.get(pos, 0) + 1
            # Never suggest cutting a current-class rookie — those are usually
            # deliberate stashes (dynasty picks / upside bench holds), not spare
            # parts. Keep them in the position counts (they do take a roster spot)
            # but out of the droppable pool.
            if pid in _rookie_sids_wv:
                continue
            _drop_pool.append({"player_id": pid, "name": name, "position": pos,
                               "value": _roster_val(pid)})
        _drop_pool.sort(key=lambda d: d["value"])   # weakest first

    def _drop_for(_c):
        if not _drop_pool:
            return None
        add_val = _c.get("value") or 0.0
        add_pos = _c.get("position") or ""
        elig = [d for d in _drop_pool if d["value"] < add_val]
        if not elig:
            return None   # everyone you'd cut is worth more than the add — hold
        same_pos = [d for d in elig
                    if d["position"] == add_pos and _pos_counts.get(add_pos, 0) > _KEEP.get(add_pos, 3)]
        deep = [d for d in elig if _pos_counts.get(d["position"], 0) > _KEEP.get(d["position"], 3)]
        pick = (same_pos or deep or elig)[0]
        return {"name": pick["name"], "position": pick["position"], "value": round(pick["value"])}

    for c in _shown:
        try:
            sig_cls, sig_label = _waiver_signal(
                c, waiver_breakout, _WAIVER_PRIME_MAX,
                fast_thr=_fast_thr, up_thr=_up_thr,
            )
            bscore = waiver_breakout.get(c["player_id"], 0.0)
            ut = usage_trends.get(c["player_id"]) or {}
            _flo, _fhi = _faab_band(c)
            result.append({
                "player_id": c["player_id"],
                "name": c["name"],
                "position": c["position"],
                "team": c["team"],
                "value": c["value"],
                "age": c["age"],
                "pos_rank_label": c["pos_rank_label"],
                "rank_change_7d": c["rank_change_7d"],
                "breakout_score": bscore,
                "signal": sig_label,
                "signal_class": sig_cls,
                "composite_score": _safe_pickup_score(c),
                "usage_delta": ut.get("delta"),
                "usage_stat": ut.get("stat"),
                "usage_series": ut.get("series"),
                "injured_ahead": len(c.get("injured_ahead") or []),
                "healthy_ahead": c.get("healthy_ahead"),
                "ros_ppg": round(c["ros_ppg"], 1) if c.get("ros_ppg") is not None else None,
                "roster_need": round((c.get("need_mult") or 1.0) - 1.0, 3),
                "scarcity": round((c.get("scarcity_mult") or 1.0) - 1.0, 3),
                "schedule_ease_rank": c.get("schedule_ease_rank"),
                "faab_low": _flo,
                "faab_high": _fhi,
                "drop": _drop_for(c),
            })
        except Exception:
            logger.exception("[waiver-candidates] result row failed for %s", c.get("player_id"))
            continue

    return jsonify({"candidates": result, "total": len(result), "faab_enabled": _faab_enabled})


_TRENDING_ADDS_CACHE: dict = {}
_TRENDING_ADDS_TTL = 1800  # 30 min; a league-wide signal shared by all viewers


def _sleeper_trending_adds(limit: int = 25, lookback_hours: int = 48) -> list:
    """Sleeper's league-wide most-added players (add count over a lookback
    window). Cached 30 min; this is a global signal, not per-league, so every
    viewer shares one fetch. Best-effort: any failure returns []."""
    key = (limit, lookback_hours)
    hit = _TRENDING_ADDS_CACHE.get(key)
    if hit and (time.time() - hit[0]) < _TRENDING_ADDS_TTL:
        return hit[1]
    try:
        from dashboard_services.api import fetch_json
        data = fetch_json(
            f"/players/nfl/trending/add?lookback_hours={lookback_hours}&limit={limit}"
        )
        result = data if isinstance(data, list) else []
    except Exception:
        logger.debug("suppressed exception", exc_info=True)
        result = []
    if result:
        _TRENDING_ADDS_CACHE[key] = (time.time(), result)
    return result


@app.route("/api/trending-adds")
def api_trending_adds():
    """Trending waiver adds across all Sleeper leagues, filtered to players the
    viewer's league can still add (not already rostered), with our value + pos
    rank joined on. Feeds the 'Trending across leagues' strip on Waivers."""
    platform = (request.args.get("platform") or "sleeper").strip().lower()
    league_id = (request.args.get("league_id") or "").strip()
    season = int(request.args.get("season") or datetime.now().year)
    if not league_id:
        return jsonify({"trending": []})

    # Trending is a Sleeper signal; other platforms just get an empty strip.
    if platform != "sleeper":
        return jsonify({"trending": []})

    trend = _sleeper_trending_adds()
    if not trend:
        return jsonify({"trending": []})

    try:
        ctx = get_league_ctx_from_cache(platform, league_id, season)
    except Exception:
        ctx = {}
    rostered_ids = {
        str(pid)
        for r in (ctx.get("rosters") or [])
        for pid in (r.get("players") or [])
    }
    players_index = ctx.get("players_index") or get_players_index_global() or {}
    _mvt = {str(r.get("id")): r for r in (get_model_value_table_cached() or [])
            if isinstance(r, dict) and r.get("id")}

    out = []
    for row in trend:
        pid = str(row.get("player_id") or "")
        if not pid or pid in rostered_ids:
            continue                              # can't add what you already own
        meta = players_index.get(pid) or {}
        val_row = _mvt.get(pid) or {}
        # Skip players we can't resolve in our index anywhere (neither the league
        # players index nor the value table). These render as a nameless
        # "Player 12345" card, which is noise — drop them entirely.
        if not meta and not val_row:
            continue
        pos = str(val_row.get("position") or meta.get("pos") or "").upper()
        if pos == "DEF":
            name = f"{(meta.get('team') or pid)} D/ST"
        else:
            name = val_row.get("name") or meta.get("name") or f"Player {pid}"
        out.append({
            "player_id": pid,
            "name": name,
            "position": pos,
            "team": (val_row.get("team") or meta.get("team") or "").upper(),
            "value": round(float(val_row.get("value") or 0)),
            "pos_rank_label": val_row.get("pos_rank_label") or "",
            "adds": int(row.get("count") or 0),
        })
        if len(out) >= 12:
            break
    return jsonify({"trending": out})


@app.route("/api/streaming-options")
def api_streaming_options():
    """Matchup-based streaming targets for D/ST and K: free-agent defenses ranked
    by how weak the offense they face is (opponent Vegas implied total), and
    free-agent kickers ranked by their own team's implied total. Reuses the same
    schedule + Vegas plumbing as Start/Sit. Empty in the offseason and gated to
    the positions the league actually starts."""
    _empty = {"defense": [], "kicker": [], "in_season": False}
    platform = (request.args.get("platform") or "sleeper").strip().lower()
    league_id = (request.args.get("league_id") or "").strip()
    season = int(request.args.get("season") or datetime.now().year)
    if not league_id:
        return jsonify(_empty)
    try:
        ctx = get_league_ctx_from_cache(platform, league_id, season)
    except Exception:
        return jsonify(_empty)

    current_week = int(ctx.get("current_week") or 0)
    if current_week < 1 or ctx.get("offseason_mode"):
        return jsonify(_empty)

    # League's started positions gate which streamers are relevant at all.
    rpos = [str(s).upper() for s in (ctx.get("roster_positions") or [])]
    uses_def = any(s in ("DEF", "DST", "D/ST") for s in rpos)
    uses_k = "K" in rpos
    if not (uses_def or uses_k):
        return jsonify({"defense": [], "kicker": [], "in_season": True})

    # ── Schedule → opponent map + games for the Vegas lookup ──────────────────
    opponent_map: dict = {}
    week_games: list = []
    teams: set = set()
    try:
        from utils.utils import load_week_sched
        for g in (load_week_sched(season, current_week) or []):
            home = str(g.get("home") or "").upper()
            away = str(g.get("away") or "").upper()
            if home and away:
                opponent_map[home] = away
                opponent_map[away] = home
                week_games.append((home, away, str(g.get("gameDate") or "")))
                teams.add(home)
                teams.add(away)
    except Exception:
        logger.debug("suppressed exception", exc_info=True)
    if not teams:
        return jsonify({"defense": [], "kicker": [], "in_season": True})

    conditions: dict = {}
    try:
        from utils.game_conditions import build_week_conditions
        conditions = build_week_conditions(season, current_week, week_games) or {}
    except Exception:
        logger.debug("suppressed exception", exc_info=True)

    def _implied(team):
        v = (conditions.get(team) or {}).get("implied_total")
        try:
            return float(v) if v is not None else None
        except (TypeError, ValueError):
            return None

    def _matchup(team):
        opp = opponent_map.get(team)
        if not opp:
            return "", None
        # home_team_of not tracked here; label as "vs OPP" (venue is secondary).
        return f"vs {opp}", opp

    rostered = {
        str(pid)
        for r in (ctx.get("rosters") or [])
        for pid in (r.get("players") or [])
    }
    players_index = ctx.get("players_index") or get_players_index_global() or {}

    # ── Defenses: one per team, pid == team abbr in Sleeper. Best matchup is the
    # weakest opposing offense (lowest opponent implied total). ────────────────
    defense = []
    if uses_def:
        rows = []
        for t in teams:
            if t in rostered:
                continue
            label, opp = _matchup(t)
            rows.append({
                "player_id": t, "name": f"{t} D/ST", "position": "DEF", "team": t,
                "opponent": opp, "matchup": label, "opp_implied": _implied(opp),
            })
        rows.sort(key=lambda d: (d["opp_implied"] is None,
                                 d["opp_implied"] if d["opp_implied"] is not None else 99.0))
        defense = rows[:8]

    # ── Kickers: free-agent Ks on teams playing this week, ranked by their own
    # implied total (more team scoring → more FGs/XPs). One per team. ──────────
    kicker = []
    if uses_k:
        cand = []
        for pid, meta in players_index.items():
            if str(meta.get("pos") or "").upper() != "K":
                continue
            pid = str(pid)
            t = str(meta.get("team") or "").upper()
            if not t or t not in teams or pid in rostered:
                continue
            cand.append((pid, meta.get("name") or f"Player {pid}", t, _implied(t)))
        cand.sort(key=lambda x: (x[3] is None, -(x[3] if x[3] is not None else 0.0)))
        seen_team = set()
        for pid, name, t, imp in cand:
            if t in seen_team:
                continue
            seen_team.add(t)
            label, opp = _matchup(t)
            kicker.append({
                "player_id": pid, "name": name, "position": "K", "team": t,
                "opponent": opp, "matchup": label, "own_implied": imp,
            })
            if len(kicker) >= 8:
                break

    return jsonify({"defense": defense, "kicker": kicker, "in_season": True})


_WEEKLY_PTS_CACHE: dict = {}
_WEEKLY_PTS_TTL = 900  # 15 min; weekly stat files change at most once a week


def _load_season_weekly_points(season: int, scoring_settings: dict) -> dict:
    """{player_id: [weekly fantasy points]} for a season's played games.

    Reads the cached Sleeper weekly stat files and scores each with the league's
    settings. Only weeks a player has a stat line count as games played (byes /
    inactives are absent). Cached by (season, scoring signature). Never raises.
    """
    import hashlib
    sig = hashlib.md5(
        json.dumps(scoring_settings or {}, sort_keys=True, default=str).encode()
    ).hexdigest()[:10]
    key = (int(season), sig)
    hit = _WEEKLY_PTS_CACHE.get(key)
    if hit and time.time() - hit[0] < _WEEKLY_PTS_TTL:
        return hit[1]
    out: dict = {}
    try:
        # Absolute cache path: a relative "cache" glob silently yields nothing
        # when the server's working directory isn't the repo root.
        pattern = os.path.join(CACHE_DIR, "sleeper_stats", f"sleeper_stats_s{season}_w*.json")
        for wf in glob.glob(pattern):
            try:
                with open(wf) as f:
                    week_stats = json.load(f)
            except Exception:
                continue
            if not isinstance(week_stats, dict):
                continue
            for pid, st in week_stats.items():
                if not isinstance(st, dict):
                    continue
                try:
                    out.setdefault(str(pid), []).append(round(float(_score_stats(st, scoring_settings)), 2))
                except Exception:
                    continue
    except Exception:
        logger.debug("[start-sit] weekly points load failed", exc_info=True)
    _WEEKLY_PTS_CACHE[key] = (time.time(), out)
    return out


def _ss_game_env(home_team: "Optional[str]", week: int) -> "Optional[dict]":
    """Compact game-environment chip for a start/sit row, or None.

    Only returns a tag when there's actual lineup signal - an indoor
    (weather-proof) venue or a cold-weather outdoor site in the late-season
    window. Warm/mild outdoor games stay unmarked to avoid chip clutter.
    """
    if not home_team:
        return None
    try:
        from utils.nfl_stadiums import game_environment
        env = game_environment(home_team, week)
    except Exception:
        return None
    if not env:
        return None
    if env.get("dome"):
        return {"label": "Dome", "kind": "dome", "note": env.get("note")}
    if env.get("cold"):
        return {"label": "Cold", "kind": "cold", "note": env.get("note")}
    return None


@app.route("/api/start-sit-options")
def api_start_sit_options():
    """
    Returns roster options grouped by position for the viewing user.
    Query params: platform, league_id, season
    """
    platform = (request.args.get("platform") or "sleeper").strip().lower()
    league_id = (request.args.get("league_id") or "").strip()
    season = int(request.args.get("season") or datetime.now().year)

    if not league_id:
        return jsonify({"error": "league_id required"}), 400

    try:
        ctx = get_league_ctx_from_cache(platform, league_id, season)
    except Exception as e:
        return _api_err("Request failed", e)

    viewer = ctx.get("viewer") or {}
    viewer_roster_id = viewer.get("viewer_roster_id")

    if not viewer_roster_id:
        return jsonify({"positions": {}})

    rosters = ctx.get("rosters") or []
    viewer_roster = next(
        (r for r in rosters if str(r.get("roster_id")) == str(viewer_roster_id)),
        None,
    )
    if not viewer_roster:
        return jsonify({"positions": {}})

    player_ids = [str(pid) for pid in (viewer_roster.get("players") or [])]
    players_index = ctx.get("players_index") or {}
    players_full = ctx.get("players") or {}
    model_value_table = list(get_model_value_table_cached() or [])

    lineup_requirements: dict = ctx.get("lineup_requirements") or {}
    if not lineup_requirements:
        roster_positions = ctx.get("roster_positions") or []
        for slot in roster_positions:
            s = str(slot).upper()
            if s in {"QB", "RB", "WR", "TE", "FLEX", "SUPER_FLEX", "SFLEX", "K", "DEF"}:
                lineup_requirements[s] = lineup_requirements.get(s, 0) + 1

    _rp_ss = ctx.get("roster_positions") or []
    _is_sf_ss = any(str(s).upper() in {"SUPER_FLEX", "SFLEX"} for s in _rp_ss)
    _vf_ss = "sf_value" if _is_sf_ss else "value"

    rows_by_id: dict = {}
    for row in model_value_table:
        if not isinstance(row, dict):
            continue
        pid = str(row.get("id") or "")
        if pid:
            rows_by_id[pid] = row

    current_week = int(ctx.get("current_week") or 1)  # default week 1 in offseason

    # ── FPTS-against data (for "Def vs pos" pts/gm display) ──────────────────
    fpts_against: dict = {}
    try:
        fpts_against = _compute_fpts_against(season)
    except Exception:
        logger.debug("suppressed exception", exc_info=True)

    # ── Z-score matchup rank tables (rank 1 = easiest, one per position) ─────
    _z_rank_tables: dict = {}
    _z_total_map: dict = {}
    for _zpos in ("QB", "RB", "WR", "TE"):
        try:
            _rm, _tot, _ri, _iz = _matchup_rank_table(season, _zpos)
            _z_rank_tables[_zpos] = _rm
            _z_total_map[_zpos] = _tot
        except Exception:
            _z_rank_tables[_zpos] = {}
            _z_total_map[_zpos] = 32

    # Fallback rank cache (fpts-against) used when z-score data is absent
    _def_rank_cache: dict = {}
    def _get_def_rank_fallback(team: str, pos: str):
        if pos not in _def_rank_cache:
            vals = [(t, fpts_against.get(t, {}).get(pos, 0.0)) for t in fpts_against]
            vals.sort(key=lambda x: x[1], reverse=True)
            _def_rank_cache[pos] = {t: i + 1 for i, (t, _) in enumerate(vals)}
        rank  = _def_rank_cache.get(pos, {}).get(team)
        total = len(fpts_against) or 32
        return rank, total

    # ── Opponent map from current week schedule ───────────────────────────────
    opponent_map: dict = {}
    opp_label_map: dict = {}
    home_team_of: dict = {}   # team abbr -> the HOME team of its game (for venue)
    week_games: list = []     # (home, away, gameDate) for Vegas + weather lookups
    try:
        from utils.utils import load_week_sched as _lsched
        if current_week > 0:
            sched = _lsched(season, current_week) or []
            for game in sched:
                home = str(game.get("home") or "").upper()
                away = str(game.get("away") or "").upper()
                if home and away:
                    opponent_map[home] = away
                    opponent_map[away] = home
                    opp_label_map[home] = f"vs {away}"
                    opp_label_map[away] = f"@ {home}"
                    home_team_of[home] = home
                    home_team_of[away] = home
                    week_games.append((home, away, str(game.get("gameDate") or "")))
    except Exception:
        logger.debug("suppressed exception", exc_info=True)

    # ── Live game conditions: Vegas implied team totals + weather ─────────────
    # Cached and fully best-effort; on any failure rows just fall back to the
    # static dome/cold venue tags.
    game_conditions: dict = {}
    try:
        from utils.game_conditions import build_week_conditions
        if week_games:
            game_conditions = build_week_conditions(season, current_week, week_games)
    except Exception:
        logger.debug("suppressed exception", exc_info=True)

    # ── Weekly consistency / boom-bust profiles (from actual weekly scores) ──
    # Start from last completed season and mold toward the current one as games
    # come in (see blended_consistency_profile). Last season is loaded per-player:
    # as long as any rostered player is still inside the crossfade window it's
    # pulled in, so a player who has missed time keeps blending even after the
    # league leaders have reached a full current-season sample.
    weekly_pts_map: dict = {}
    prior_pts_map: dict = {}
    prior_season: Optional[int] = None
    try:
        from dashboard_services.api import SCORING_DEFAULTS as _SD_SS
        from utils.consistency import BLEND_FULL_SEASON as _BLEND_FULL
        _eff_ss = {**_SD_SS, **(ctx.get("raw_scoring_settings") or {})}
        weekly_pts_map = _load_season_weekly_points(season, _eff_ss)
        # Per-player gate: load last season while ANY rostered player is still
        # inside the crossfade window (fewer than a full crossfade's worth of
        # current games), so a low-games player keeps blending even midseason
        # after the league leaders have gone pure-current.
        _needs_prior = any(
            len(weekly_pts_map.get(str(_pid)) or []) < _BLEND_FULL for _pid in player_ids
        )
        if _needs_prior:
            for _py in (season - 1, season - 2):
                _pm = _load_season_weekly_points(_py, _eff_ss)
                if max((len(v) for v in _pm.values()), default=0) >= 3:
                    prior_pts_map, prior_season = _pm, _py
                    break
    except Exception:
        logger.debug("suppressed exception", exc_info=True)

    def _resolve_consistency(pid: str, pos: str):
        return _blended_consistency(
            weekly_pts_map.get(pid) or [], prior_pts_map.get(pid) or [], pos,
            prior_season=prior_season,
        )

    # ── Weekly projections - SAME source as the player modal & matchups page ───
    # build_projections_by_week() returns Tank01 weekly values (variant-adjusted,
    # with per-player median outlier correction) and FantasyPros season PPG as a
    # fallback for players with no weekly data. Reuse the cached ctx bundle when
    # present so start/sit shows the exact number the modal/matchups show.
    proj_by_week = ctx.get("proj_by_week")
    if not proj_by_week:
        try:
            proj_by_week = build_projections_by_week(
                season, 18, ctx.get("raw_scoring_settings")
            )
        except Exception:
            proj_by_week = {}
    _wk_proj = ((proj_by_week or {}).get(current_week) or {}).get("projections") or {}
    def _lookup_proj(pid: str):
        v = _wk_proj.get(pid)
        if v is None:
            v = _wk_proj.get(str(pid))
        try:
            return round(float(v), 1) if v is not None else 0.0
        except (TypeError, ValueError):
            return 0.0

    # ── Season-long and recent-form PPG from Sleeper stat files ───────────────
    season_ppg: dict = {}
    recent_ppg_map: dict = {}   # last 4 weeks
    try:
        import glob as _glob
        _stat_files = sorted(_glob.glob(
            os.path.join(CACHE_DIR, "sleeper_stats", f"sleeper_stats_s{season}_w*.json")
        ))
        _season_pts: dict = {}
        _recent_files = _stat_files[-4:]   # last 4 weeks for form
        _recent_pts: dict = {}
        for _sf in _stat_files:
            try:
                _sdata = json.load(open(_sf))
                for pid, stats in _sdata.items():
                    pts = float(stats.get("pts_ppr") or 0)
                    if pts > 0:
                        _season_pts.setdefault(str(pid), []).append(pts)
                        if _sf in _recent_files:
                            _recent_pts.setdefault(str(pid), []).append(pts)
            except Exception:
                continue
        season_ppg = {pid: round(sum(v) / len(v), 1) for pid, v in _season_pts.items() if v}
        recent_ppg_map = {pid: round(sum(v) / len(v), 1) for pid, v in _recent_pts.items() if v}
    except Exception:
        logger.debug("suppressed exception", exc_info=True)

    # ── Weekly usage trends: rising/falling role nudges close calls ──────────
    _ss_usage_trends: dict = {}
    try:
        from data_building.weekly_metrics import get_usage_trends as _get_ut
        _ss_usage_trends = _get_ut(int(season))
    except Exception:
        _ss_usage_trends = {}

    positions_out: dict = {"QB": [], "RB": [], "WR": [], "TE": []}
    for pid in player_ids:
        row  = rows_by_id.get(pid) or {}
        meta = players_index.get(pid) or {}
        pos  = str(row.get("position") or row.get("pos") or meta.get("pos") or "").upper()
        if pos not in positions_out:
            continue
        player_name   = row.get("name") or meta.get("name") or f"Player {pid}"
        team          = (row.get("team") or meta.get("team") or "").upper()
        opponent      = opponent_map.get(team, "")
        # Only mark as BYE/on-bye when the schedule actually loaded (opponent_map non-empty)
        on_bye    = bool(opponent_map) and team not in opponent_map
        opp_label = opp_label_map.get(team, "BYE" if on_bye else "")

        s_ppg      = season_ppg.get(pid, 0.0)
        recent_ppg = recent_ppg_map.get(pid, 0.0)
        # Projection = exact value the player modal / matchups page show for this
        # week (Tank01 weekly w/ median correction → FantasyPros season PPG).
        proj_pts   = _lookup_proj(pid)
        if proj_pts <= 0 and s_ppg > 0:
            proj_pts = round(s_ppg, 1)

        fpts_vs = round(fpts_against.get(opponent, {}).get(pos, 0.0), 1) if opponent else 0.0
        # Z-score matchup rank (rank 1 = easiest); fall back to fpts-against rank.
        # Shown as the matchup chip for context - the weekly projection already
        # reflects the opponent, so it is NOT re-applied to the start/sit score.
        _z_opp = _norm_sched_team(opponent) if opponent else ""
        _z_map = _z_rank_tables.get(pos, {})
        if _z_opp and _z_map:
            def_rank  = _z_map.get(_z_opp) or _z_map.get(opponent)
            def_total = _z_total_map.get(pos, 32)
        elif opponent:
            def_rank, def_total = _get_def_rank_fallback(opponent, pos)
        else:
            def_rank, def_total = None, 32

        full_player  = players_full.get(pid) or {}
        raw_status   = str(full_player.get("injury_status") or full_player.get("status") or "").strip()
        injury_status = None if raw_status in {"", "active", "Active", "ACT"} else raw_status
        _imp_ss = (game_conditions.get(team) or {}).get("implied_total") if not on_bye else None

        # ── Start/sit score: projection × form × matchup × usage × availability ──
        # Projection is the dominant signal. Form (±10%), matchup (±10%), and
        # usage trend (±5%) influence close calls but can't flip a meaningful
        # projection gap (e.g. 12.8 vs 9.8 stays the same regardless). Availability
        # can, and should: an OUT/IR/Doubtful player must never win a start, a
        # Questionable one takes a haircut, and a game's Vegas implied total fades
        # (low) or nudges (high) everyone in it — turning context chips into an
        # actual recommendation instead of decoration.
        _ut_ss = _ss_usage_trends.get(pid) or {}
        usage_delta = _ut_ss.get("delta")
        demotion = None
        if on_bye:
            score = 0.0
        else:
            # Recent form: capped ±10%
            _form = 1.0
            if recent_ppg > 0 and s_ppg > 0:
                _form = min(1.10, max(0.90, recent_ppg / s_ppg))

            # Matchup ease: rank 1=easiest → +10%, rank 32=hardest → -10%
            _mu = 1.0
            if def_rank and def_total and def_total > 1:
                _ease = (def_total - def_rank) / (def_total - 1)  # 0–1
                _mu = 0.90 + _ease * 0.20  # 0.90–1.10

            # Usage trend: last-3-week role vs season avg, capped ±5%. A rising
            # role means the trailing PPG (form) understates this week's
            # opportunity; a shrinking one means it overstates it.
            _ug = 1.0
            if usage_delta is not None and _ut_ss.get("season_avg"):
                _rel = usage_delta / max(float(_ut_ss["season_avg"]), 1.0)
                _ug = min(1.05, max(0.95, 1.0 + _rel * 0.25))

            # Availability + game-environment.
            _avail = 1.0
            _st_up = (injury_status or "").upper()
            if any(k in _st_up for k in ("OUT", "IR", "SUSP", "DOUBT", "PUP", "DNP")):
                _avail = 0.0
                demotion = "out"
            elif "QUESTION" in _st_up or _st_up in ("GTD", "Q"):
                _avail = 0.85
                demotion = "questionable"
            if _imp_ss is not None:
                if _imp_ss <= 17:
                    _avail *= 0.94
                    demotion = demotion or "low_total"
                elif _imp_ss >= 27:
                    _avail *= 1.04

            score = proj_pts * _form * _mu * _ug * _avail

        positions_out[pos].append({
            "player_id":     pid,
            "name":          player_name,
            "team":          team,
            "opponent":      opp_label,
            "opponent_team": opponent,
            "on_bye":        on_bye,
            "season_ppg":    round(s_ppg, 1),
            "recent_ppg":    recent_ppg,
            "proj_pts":      proj_pts,
            "fpts_against":  fpts_vs,
            "def_rank":      def_rank,
            "def_total":     def_total,
            "pos_rank_label": row.get("pos_rank_label") or "",
            "injury_status": injury_status,
            "usage_delta":   usage_delta,
            "usage_stat":    _ut_ss.get("stat"),
            "game_env":      _ss_game_env(home_team_of.get(team), current_week) if not on_bye else None,
            "implied_total": _imp_ss,
            "weather":       (game_conditions.get(team) or {}).get("weather") if not on_bye else None,
            "consistency":   _resolve_consistency(pid, pos),
            "demotion":      demotion,
            "_score":        score,
        })

    flex_slots = lineup_requirements.get("FLEX") or 0
    sflex_slots = (lineup_requirements.get("SUPER_FLEX") or 0) + (lineup_requirements.get("SFLEX") or 0)

    for pos in positions_out:
        positions_out[pos].sort(key=lambda x: (not x["on_bye"], x["_score"]), reverse=True)
        n_start = lineup_requirements.get(pos, 1)
        eligible_for_flex = pos in ("RB", "WR", "TE")
        for i, p in enumerate(positions_out[pos]):
            p["start"] = i < n_start and not p["on_bye"]
            p["flex_start"] = False
            p["flex_eligible"] = eligible_for_flex and i >= n_start and not p["on_bye"]

    if flex_slots:
        all_flex = sorted(
            [p for pos in positions_out for p in positions_out[pos] if p["flex_eligible"]],
            key=lambda x: x["_score"], reverse=True
        )
        for p in all_flex[:flex_slots]:
            p["start"] = True
            p["flex_start"] = True

    if sflex_slots:
        sflex_cands = sorted(
            [p for pos in positions_out for p in positions_out[pos]
             if not p["start"] and not p["on_bye"] and pos in ("QB", "RB", "WR", "TE")],
            key=lambda x: x["_score"], reverse=True
        )
        for p in sflex_cands[:sflex_slots]:
            p["start"] = True
            p["flex_start"] = True

    # ── Win-probability on the closest call at each position ─────────────────
    # The real start/sit tension is the marginal pair: the last player in a
    # starting slot vs the first one on the bench. Model each as Normal(proj, σ)
    # — σ from the player's own boom/bust std when we have it, else a CV-based
    # fallback — and report P(starter outscores the guy you'd bench). Surfaced
    # only when it's genuinely close, so a blowout call isn't dressed up as a
    # coin flip.
    import math as _math_ss

    def _phi(z):
        return 0.5 * (1.0 + _math_ss.erf(z / _math_ss.sqrt(2.0)))

    def _sigma_of(p):
        c = p.get("consistency") or {}
        s = c.get("std")
        if s and float(s) > 0:
            return float(s)
        return max(float(p.get("proj_pts") or 0.0) * 0.5, 4.0)

    def _win_prob(a, b):
        ma = float(a.get("proj_pts") or 0.0)
        mb = float(b.get("proj_pts") or 0.0)
        sa, sb = _sigma_of(a), _sigma_of(b)
        denom = _math_ss.sqrt(sa * sa + sb * sb) or 1.0
        return round(_phi((ma - mb) / denom), 2)

    for _pos in ("QB", "RB", "WR", "TE"):
        _arr = [p for p in positions_out[_pos] if not p["on_bye"]]
        _ns = lineup_requirements.get(_pos, 1)
        if _ns >= 1 and len(_arr) > _ns:
            _starter, _bench = _arr[_ns - 1], _arr[_ns]
            _starter["close_call"] = {
                "vs_name": _bench["name"],
                "vs_player_id": _bench["player_id"],
                "win_prob": _win_prob(_starter, _bench),
            }

    # ── Optimal-lineup advice: compare the auto-optimal skill lineup to the
    # viewer's actual current starters — the points left on the bench, plus the
    # specific swaps to fix it. Covers the QB/RB/WR/TE we model. ───────────────
    _proj_by_pid, _name_by_pid, _pos_by_pid = {}, {}, {}
    for _pos in positions_out:
        for _p in positions_out[_pos]:
            _proj_by_pid[_p["player_id"]] = _p["proj_pts"]
            _name_by_pid[_p["player_id"]] = _p["name"]
            _pos_by_pid[_p["player_id"]] = _pos
    _optimal_ids = {_p["player_id"] for _pos in positions_out for _p in positions_out[_pos] if _p.get("start")}
    _current_ids = {str(x) for x in (viewer_roster.get("starters") or []) if str(x) not in ("0", "")}
    _current_skill = {pid for pid in _current_ids if pid in _proj_by_pid}
    _optimal_pts = round(sum(_proj_by_pid.get(pid, 0.0) for pid in _optimal_ids), 1)
    _current_pts = round(sum(_proj_by_pid.get(pid, 0.0) for pid in _current_skill), 1)
    _to_start = sorted(_optimal_ids - _current_ids, key=lambda pid: _proj_by_pid.get(pid, 0.0), reverse=True)
    _to_sit = sorted(_current_skill - _optimal_ids, key=lambda pid: _proj_by_pid.get(pid, 0.0))
    _swaps = []
    for _in_pid, _out_pid in zip(_to_start, _to_sit):
        _swaps.append({
            "start": {"player_id": _in_pid, "name": _name_by_pid.get(_in_pid),
                      "position": _pos_by_pid.get(_in_pid), "proj": _proj_by_pid.get(_in_pid)},
            "sit": {"player_id": _out_pid, "name": _name_by_pid.get(_out_pid),
                    "position": _pos_by_pid.get(_out_pid), "proj": _proj_by_pid.get(_out_pid)},
            "gain": round(_proj_by_pid.get(_in_pid, 0.0) - _proj_by_pid.get(_out_pid, 0.0), 1),
        })
    lineup_advice = {
        "has_current": bool(_current_skill),
        "optimal_pts": _optimal_pts,
        "current_pts": _current_pts,
        "delta": round(_optimal_pts - _current_pts, 1),
        "swaps": _swaps,
    }

    for pos in positions_out:
        for p in positions_out[pos]:
            del p["_score"]

    return jsonify({
        "positions": positions_out,
        "lineup_requirements": lineup_requirements,
        "flex_slots": flex_slots,
        "sflex_slots": sflex_slots,
        "current_week": current_week,
        "lineup_advice": lineup_advice,
    })


@app.route("/<platform>/<int:season>/<league_id>/weekly")
def page_weekly(platform: str, season: int, league_id: str):
    ctx = get_league_ctx_from_cache(platform, league_id, season)

    if not has_draft_ended(league_id, platform, season):
        body = """
        <div class="card central">
          <div class="card-header"><h2>Weekly Hub Unavailable</h2></div>
          <div class="card-body">
            <p>The Weekly Hub becomes active once your league draft has completed.</p>
            <p>Use the dashboard, teams, activity, and trade tools for pre-draft planning.</p>
          </div>
        </div>
        """
    else:
        ensure_weekly_bits(ctx)
        body = build_weekly_hub_body(ctx)

    return render_page("BR Fantasy Weekly Hub", league_id, "weekly", body, platform, season)


# ─── BR Redzone ────────────────────────────────────────────────────────────────

_RZ_BOX_CACHE: dict = {}   # game_id -> (ts, boxscore)
_RZ_BOX_TTL = 15.0


def _redzone_boxscore(game_id: str) -> dict:
    """Fetch a Tank01 boxscore with a short shared TTL cache (bounds API calls)."""
    if not game_id:
        return {}
    now = time.time()
    hit = _RZ_BOX_CACHE.get(game_id)
    if hit and (now - hit[0]) < _RZ_BOX_TTL:
        return hit[1]
    try:
        from dashboard_services.api import fetch_tank_boxscore
        box = fetch_tank_boxscore(game_id) or {}
    except Exception:
        box = {}
    _RZ_BOX_CACHE[game_id] = (now, box)
    return box


_RZ_PROJ_CACHE: dict = {}
_RZ_PROJ_TTL = 900.0  # 15 min


def _rz_get_projections(season: int, week: int) -> dict:
    """Return {pid: projected_pts_ppr} for the week, cached 15 min."""
    key = f"{season}:{week}"
    entry = _RZ_PROJ_CACHE.get(key)
    if entry and time.time() - entry["ts"] < _RZ_PROJ_TTL:
        return entry["data"]
    data: dict = {}
    try:
        from utils.utils import fetch_week_from_sleeper
        raw = fetch_week_from_sleeper(season, week) or {}
        for pid, v in raw.items():
            if isinstance(v, dict):
                data[str(pid)] = float(v.get("ppr") or v.get("half_ppr") or 0)
    except Exception:
        logger.debug("suppressed exception", exc_info=True)
    _RZ_PROJ_CACHE[key] = {"ts": time.time(), "data": data}
    return data


