# ── Demo mode ──────────────────────────────────────────────────────────────────
# Time-parameterised sample data so the live play feed can be exercised any time
# (e.g. off-season). Stat lines accumulate as a function of the simulated game
# clock `t`; polling advances `t`, the client diffs stat lines between polls and
# renders the individual plays (targets / catches / carries / TDs) that occurred.

_RZ_DEMO_START = 150     # sim seconds the page-load snapshot is built at

# The deterministic play-by-play simulation lives in utils/redzone_demo.py so
# it can be unit-tested; re-exported here under the original names.
from utils.redzone_demo import (  # noqa: E402
    DEMO_GAME_SECONDS as _RZ_DEMO_GAME,
    DEMO_SCORING as _RZ_DEMO_SCORING,
    demo_fold as _rz_demo_fold,
    demo_pts as _rz_demo_pts,
    demo_rng as _rz_demo_rng,
    demo_script as _rz_demo_script,
)


# Flat points for K / DEF (no play-by-play scripting)
_RZ_DEMO_KDEF = {
    "d_em": 12.0, "d_sfd": 6.8, "d_jt": 9.0, "d_dad": 3.0,
    "d_kcd": 7.0, "d_bufd": 4.0,
}


def _redzone_demo_data(t: float = _RZ_DEMO_START, scope: str = "league"):
    """Time-parameterised live-game sample data for the Redzone demo.

    scope="league": one league, all four teams.
    scope="user":   the viewer's team across three different leagues.
    """
    t = max(0.0, min(float(t), _RZ_DEMO_GAME))
    _now = time.time()
    _g = lambda away, apts, home, hpts, code, gtime=0.0, clock="", qtr="": {
        "game_status": "In Progress" if code == "1" else ("Final" if code == "2" else "Upcoming"),
        "game_code": code, "home": home, "away": away,
        "home_pts": str(hpts), "away_pts": str(apts),
        "game_time_epoch": gtime,
        "game_clock": clock, "game_quarter": qtr,
    }
    GAMES = {
        "BAL_HOU": _g("BAL", 21, "HOU", 14, "1", clock="4:32", qtr="Q3"),
        "TEN_IND": _g("TEN", 28, "IND", 17, "2"),
        "DET_CHI": _g("DET", 24, "CHI",  7, "1", clock="2:14", qtr="Q4"),
        "DAL_NYG": _g("DAL", 35, "NYG", 10, "2"),
        "JAX_MIA": _g("JAX", 10, "MIA", 17, "1", clock="7:45", qtr="Q2"),
        "KC_LV":   _g("KC",  31, "LV",   3, "1", clock="4:32", qtr="Q3"),
        "CIN_PIT": _g("CIN", 24, "PIT", 13, "2"),
        "SF_ARI":  _g("SF",  31, "ARI",  6, "2"),
        "ATL_NO":  _g("ATL", 17, "NO",  10, "1", clock="5:51", qtr="Q2"),
        "LAR_SEA": _g("LAR", 21, "SEA", 14, "1", clock="11:22", qtr="Q3"),
        "PHI_WAS": _g("PHI", 17, "WAS", 10, "1", clock="8:05", qtr="Q1"),
        # Upcoming game (kicks off ~40 min out) to showcase the "on deck" strip
        "BUF_NYJ": _g("BUF",  0, "NYJ",  0, "0", gtime=_now + 40 * 60),
    }
    def pi(name, pos, team, gk, inj="", clock="", qtr=""):
        game = GAMES.get(gk, {})
        d = {"name": name, "pos": pos, "team": team,
             "game_id": "demo_" + gk, **game,
             "injury_status": inj, "stat_line": None}
        if clock:
            d["game_clock"] = clock
        if qtr:
            d["game_quarter"] = qtr
        return d
    PLAYERS = {
        "d_lj":  pi("L. Jackson",   "QB",  "BAL", "BAL_HOU"),
        "d_dh":  pi("D. Henry",     "RB",  "TEN", "TEN_IND", inj="Q"),
        "d_jg":  pi("J. Gibbs",     "RB",  "DET", "DET_CHI"),
        "d_cdl": pi("CeeDee Lamb",  "WR",  "DAL", "DAL_NYG"),
        "d_mn":  pi("M. Nabers",    "WR",  "NYG", "DAL_NYG", inj="Q"),
        "d_tk":  pi("T. Kelce",     "TE",  "KC",  "KC_LV"),
        "d_bt":  pi("B. Thomas",    "WR",  "JAX", "JAX_MIA", inj="D"),
        "d_em":  pi("E. McPherson", "K",   "CIN", "CIN_PIT"),
        "d_sfd": pi("SF Defense",   "DEF", "SF",  "SF_ARI"),
        "d_tp":  pi("T. Pollard",   "RB",  "TEN", "TEN_IND"),
        "d_jb":  pi("J. Burrow",    "QB",  "CIN", "CIN_PIT"),
        "d_br":  pi("B. Robinson",  "RB",  "ATL", "ATL_NO"),
        "d_rs":  pi("R. Stevenson", "RB",  "TEN", "TEN_IND"),
        "d_jj":  pi("J. Jefferson", "WR",  "LAR", "LAR_SEA"),
        "d_da":  pi("D. Adams",     "WR",  "LV",  "KC_LV"),
        "d_sl":  pi("S. LaPorta",   "TE",  "DET", "DET_CHI"),
        "d_pn":  pi("P. Nacua",     "WR",  "LAR", "LAR_SEA"),
        "d_jt":  pi("J. Tucker",    "K",   "BAL", "BAL_HOU"),
        "d_dad": pi("DAL Defense",  "DEF", "DAL", "DAL_NYG"),
        "d_gp":  pi("G. Pickens",   "WR",  "PIT", "CIN_PIT"),
        "d_jh":  pi("J. Hurts",     "QB",  "PHI", "PHI_WAS"),
        "d_av":  pi("A. Jones",     "RB",  "LAR", "LAR_SEA"),
        "d_th":  pi("T. Hill",      "WR",  "MIA", "JAX_MIA"),
        "d_jc":  pi("J. Chase",     "WR",  "CIN", "CIN_PIT"),
        "d_ma":  pi("M. Andrews",   "TE",  "BAL", "BAL_HOU"),
        "d_kcd": pi("KC Defense",   "DEF", "KC",  "KC_LV"),
        "d_gs":  pi("G. Smith",     "QB",  "SEA", "LAR_SEA"),
        "d_dm":  pi("D. Montgomery","RB",  "DET", "DET_CHI"),
        "d_sd":  pi("S. Diggs",     "WR",  "TEN", "TEN_IND"),
        "d_dw":  pi("D. Waller",    "TE",  "NYG", "DAL_NYG"),
        "d_bufd":pi("BUF Defense",  "DEF", "PHI", "PHI_WAS"),
        "d_me":  pi("M. Evans",     "WR",  "JAX", "JAX_MIA"),
        "d_ja":  pi("J. Allen",     "QB",  "BUF", "BUF_NYJ"),  # upcoming game (on-deck demo)
    }

    # Demo injury-status flips over the simulated clock so the live injury
    # feed events (Q→Out etc.) are exercisable in the demo.
    if t >= 300:
        PLAYERS["d_dh"]["injury_status"] = "O"   # D. Henry: Q → Out
    if t >= 450 and "d_jg" in PLAYERS:
        PLAYERS["d_jg"]["injury_status"] = "Q"   # J. Gibbs: healthy → Q

    # Demo DEF and K stat lines (time-scaled from flat totals)
    _DEMO_DEF_SCRIPT = {
        "d_sfd":  [{"t": 80,  "k": "sack"}, {"t": 160, "k": "def_int"}, {"t": 320, "k": "def_td"}, {"t": 500, "k": "sack"}],
        "d_dad":  [{"t": 100, "k": "sack"}, {"t": 250, "k": "fum_rec"}, {"t": 440, "k": "sack"}],
        "d_kcd":  [{"t": 60,  "k": "sack"}, {"t": 200, "k": "def_int"}, {"t": 380, "k": "sack"}],
        "d_bufd": [{"t": 90,  "k": "sack"}, {"t": 300, "k": "def_int"}, {"t": 450, "k": "def_td"}],
    }
    _DEMO_K_SCRIPT = {
        "d_em": [{"t": 110, "k": "fgm", "dist": 38}, {"t": 240, "k": "xpm"}, {"t": 390, "k": "fgm", "dist": 51}, {"t": 520, "k": "xpm"}],
        "d_jt": [{"t": 130, "k": "fgm", "dist": 45}, {"t": 270, "k": "xpm"}, {"t": 410, "k": "fgm", "dist": 33}],
    }

    def _demo_def_line(pid, t_eff):
        script = _DEMO_DEF_SCRIPT.get(pid, [])
        L = {"sacks": 0, "def_int": 0, "fum_rec": 0, "def_td": 0}
        for p in script:
            if p["t"] <= t_eff:
                L[p["k"]] = L.get(p["k"], 0) + 1
        return L

    def _demo_k_line(pid, t_eff):
        script = _DEMO_K_SCRIPT.get(pid, [])
        L = {"fgm": 0, "fg_long": 0, "xpm": 0}
        for p in script:
            if p["t"] <= t_eff:
                if p["k"] == "fgm":
                    L["fgm"] += 1
                    if p.get("dist", 0) > L["fg_long"]:
                        L["fg_long"] = p["dist"]
                elif p["k"] == "xpm":
                    L["xpm"] += 1
        return L

    pts = {}
    for pid, info in PLAYERS.items():
        pos  = info["pos"]
        code = info.get("game_code", "")
        if code == "0":          # upcoming game: no stats / points yet
            info["stat_line"] = None
            pts[pid] = 0.0
            continue
        t_eff = _RZ_DEMO_GAME if code == "2" else t
        if pos == "DEF":
            line = _demo_def_line(pid, t_eff)
            info["stat_line"] = line
            pts[pid] = _RZ_DEMO_KDEF.get(pid, 0.0)
        elif pos == "K":
            line = _demo_k_line(pid, t_eff)
            info["stat_line"] = line
            pts[pid] = _RZ_DEMO_KDEF.get(pid, 0.0)
        else:
            line = _rz_demo_fold(_rz_demo_script(pid, pos), t_eff)
            info["stat_line"] = line
            pts[pid] = _rz_demo_pts(line)

    def mk(rid, mid, starters, bench, league_name=None):
        players = starters + bench
        pp = {p: pts.get(p, 0.0) for p in players}
        m = {"roster_id": rid, "matchup_id": mid,
             "points": round(sum(pts.get(p, 0.0) for p in starters), 2),
             "projected_pts": round(sum(pts.get(p, 0.0) for p in starters) + 15.0, 2),
             "starters": starters, "players": players, "players_points": pp}
        if league_name:
            m["league_name"] = league_name
        return m

    base = {
        "week": 14, "season": 2024, "platform": "sleeper", "league_id": "demo",
        "player_info": PLAYERS,
        "scoring": dict(_RZ_DEMO_SCORING),
        "updated_at": time.time(),
        "is_demo": True,
        "demo_t": t,
    }

    # Map the demo's internal keys (d_lj …) to real Sleeper player IDs so
    # headshots load and the player modal can pull real player data. DEF uses
    # the team abbreviation as its Sleeper ID (that's how Sleeper IDs defenses).
    _RZ_DEMO_PID = {
        "d_lj": "4881",  "d_dh": "3198",  "d_jg": "9221",  "d_cdl": "6786",
        "d_mn": "11632", "d_tk": "1466",  "d_bt": "11631", "d_em": "7839",
        "d_sfd": "SF",   "d_tp": "5967",  "d_jb": "6770",  "d_br": "9509",
        "d_rs": "7611",  "d_jj": "6794",  "d_da": "2133",  "d_sl": "10859",
        "d_pn": "9493",  "d_jt": "1264",  "d_dad": "DAL",  "d_gp": "8137",
        "d_jh": "6904",  "d_av": "4199",  "d_th": "3321",  "d_jc": "7564",
        "d_ma": "5012",  "d_kcd": "KC",   "d_gs": "1373",  "d_dm": "5892",
        "d_sd": "2449",  "d_dw": "2505",  "d_bufd": "BUF", "d_me": "2216",
        "d_ja": "4984",
    }

    def _apply_real_ids(d):
        M = _RZ_DEMO_PID
        d["player_info"] = {M.get(k, k): v for k, v in (d.get("player_info") or {}).items()}
        for m in d.get("matchups", []):
            m["starters"] = [M.get(p, p) for p in m.get("starters", [])]
            m["players"]  = [M.get(p, p) for p in m.get("players", [])]
            m["players_points"] = {M.get(k, k): v for k, v in (m.get("players_points") or {}).items()}
        for r in d.get("rosters", []):
            r["starters"] = [M.get(p, p) for p in r.get("starters", [])]
            r["players"]  = [M.get(p, p) for p in r.get("players", [])]
        return d

    if scope == "user":
        # Viewer ("My Squad") across three leagues, each vs a different opponent.
        LG = [
            ("Dynasty Warriors", "u1",
             ["d_lj","d_dh","d_jg","d_cdl","d_mn","d_tk","d_bt","d_em","d_sfd"], ["d_tp","d_ja"],
             "u2", "TD Tyrones",
             ["d_jb","d_br","d_rs","d_jj","d_da","d_sl","d_pn","d_jt","d_dad"], ["d_gp"]),
            ("The Gauntlet", "u1",
             ["d_jh","d_av","d_jj","d_th","d_ma","d_sl","d_jc","d_em","d_kcd"], ["d_gp"],
             "u5", "Audibles",
             ["d_gs","d_dm","d_cdl","d_pn","d_dw","d_tk","d_me","d_jt","d_sfd"], ["d_tp"]),
            ("Money League", "u1",
             ["d_lj","d_br","d_dm","d_da","d_jc","d_ma","d_th","d_jt","d_dad"], [],
             "u6", "Last Place Larry",
             ["d_jb","d_av","d_jg","d_mn","d_pn","d_sl","d_bt","d_em","d_kcd"], []),
        ]
        matchups, rosters, users, leagues = [], [], [], []
        viewer_rids = []
        seen_users = {}
        for li, (lname, vown, vst, vbn, oown, onm, ost, obn) in enumerate(LG):
            ns = f"{li}:"
            vr, opr = ns + "1", ns + "2"
            mid = ns + "1"
            matchups.append(mk(vr,  mid, vst, vbn, lname))
            matchups.append(mk(opr, mid, ost, obn, lname))
            rosters.append({"roster_id": vr,  "owner_id": vown, "starters": vst, "players": vst + vbn})
            rosters.append({"roster_id": opr, "owner_id": oown, "starters": ost, "players": ost + obn})
            seen_users.setdefault(vown, "My Squad")
            seen_users[oown] = onm
            viewer_rids.append(vr)
            leagues.append({"league_id": f"demo{li}", "name": lname})
        users = [{"user_id": uid, "display_name": nm} for uid, nm in seen_users.items()]
        base.update({
            "scope": "user",
            "matchups": matchups,
            "rosters": rosters,
            "users": users,
            "leagues": leagues,
            "viewer_roster_id": viewer_rids[0],
            "viewer_roster_ids": viewer_rids,
        })
        return _apply_real_ids(base)

    # league scope (single league, four teams)
    r1 = ["d_lj","d_dh","d_jg","d_cdl","d_mn","d_tk","d_bt","d_em","d_sfd"]
    r1b = ["d_tp","d_ja"]
    r2 = ["d_jb","d_br","d_rs","d_jj","d_da","d_sl","d_pn","d_jt","d_dad"]
    r3 = ["d_jh","d_av","d_th","d_jc","d_ma","d_kcd","d_gs","d_dm","d_sd"]
    r4 = ["d_dw","d_me","d_bufd","d_sd","d_dm","d_gs","d_th","d_av","d_jh"]
    base.update({
        "scope": "league",
        "matchups": [
            mk(1, 1, r1, r1b),
            mk(2, 1, r2, ["d_gp"]),
            mk(3, 2, r3, []),
            mk(4, 2, r4, []),
        ],
        "rosters": [
            {"roster_id": 1, "owner_id": "u1", "starters": r1, "players": r1 + r1b},
            {"roster_id": 2, "owner_id": "u2", "starters": r2, "players": r2 + ["d_gp"]},
            {"roster_id": 3, "owner_id": "u3", "starters": r3, "players": r3},
            {"roster_id": 4, "owner_id": "u4", "starters": r4, "players": r4},
        ],
        "users": [
            {"user_id": "u1", "display_name": "My Squad"},
            {"user_id": "u2", "display_name": "TD Tyrones"},
            {"user_id": "u3", "display_name": "Gridiron Gurus"},
            {"user_id": "u4", "display_name": "Bench Warmers"},
        ],
        "leagues": [{"league_id": "demo", "name": "Dynasty Warriors"}],
        "viewer_roster_id": "1",
        "viewer_roster_ids": ["1"],
    })
    return _apply_real_ids(base)


def _redzone_collect(platform, league_id, season, week):
    """Build the raw per-league Redzone pieces (no top-level wrapper)."""
    from dashboard_services.api import (
        get_nfl_scores_for_date, build_team_game_lookup,
        get_nfl_players, get_effective_scoring_settings, get_league,
    )
    from dashboard_services.platform_api import (
        get_matchups as _pm, get_rosters as _pr, get_users as _pu,
    )
    matchups = _pm(platform, league_id, week, season) or []
    rosters  = _pr(platform, league_id, season) or []
    users    = _pu(platform, league_id, season) or []

    nfl_players  = get_nfl_players() if platform == "sleeper" else {}
    today_str    = date.today().strftime("%Y%m%d")
    scores_body  = get_nfl_scores_for_date(today_str) or {}
    team_game    = build_team_game_lookup(scores_body)
    try:
        # Load this league's scoring into the request-scoped state so the live
        # point math (feed deltas, stat breakdowns) uses the league's real
        # settings rather than falling back to generic defaults. get_league
        # populates scoring_settings via set_league_globals (Sleeper).
        if platform == "sleeper":
            get_league(league_id)
        scoring = get_effective_scoring_settings() or {}
    except Exception:
        scoring = {}

    all_pids = set()
    for m in matchups:
        all_pids.update(m.get("players") or [])
        all_pids.update(m.get("starters") or [])
    all_pids.discard("0")

    player_info = {}
    for pid in all_pids:
        p  = nfl_players.get(pid, {})
        tm = p.get("team") or ""
        gd = team_game.get(tm, {}) if tm else {}
        raw_inj = str(p.get("injury_status") or p.get("status") or "").strip()
        inj = "" if raw_inj.lower() in ("", "active", "act") else raw_inj
        ls  = gd.get("lineScore") or {}
        player_info[pid] = {
            "name":          p.get("full_name") or p.get("last_name") or pid,
            "pos":           p.get("position") or "?",
            "team":          tm,
            "game_id":       gd.get("gameID") or "",
            "game_status":   gd.get("gameStatus") or "",
            "game_code":     str(gd.get("gameStatusCode") or ""),
            "game_clock":    gd.get("gameClock") or "",
            "game_quarter":  ls.get("period") or "",
            "home":          gd.get("home") or "",
            "away":          gd.get("away") or "",
            "home_pts":      str(gd.get("homePts") or gd.get("homeScore") or ""),
            "away_pts":      str(gd.get("awayPts") or gd.get("awayScore") or ""),
            "game_time_epoch": _rz_safe_epoch(gd.get("gameTime_epoch") or gd.get("gameTimeEpoch")),
            "injury_status": inj,
        }

    # Attach per-player stat lines from Tank01 boxscores (Sleeper only).
    if platform == "sleeper":
        games_to_pids: dict = {}
        for pid, info in player_info.items():
            gid  = info.get("game_id")
            code = info.get("game_code")
            if gid and code in ("1", "2"):
                games_to_pids.setdefault(gid, []).append(pid)
        for gid, pids in games_to_pids.items():
            box = _redzone_boxscore(gid)
            pstats = box.get("playerStats") or {}
            tstats = box.get("teamStats") or {}
            if isinstance(pstats, dict) and pstats:
                name_map = {}
                for _, ps in pstats.items():
                    ln = (ps.get("longName") or "").lower()
                    if ln:
                        name_map[ln] = ps
                for pid in pids:
                    pi = player_info[pid]
                    pos = pi.get("pos", "")
                    if pos == "DEF":
                        # Match team defense to boxscore teamStats
                        team = pi.get("team", "")
                        home = pi.get("home", "")
                        away = pi.get("away", "")
                        side = "home" if team == home else ("away" if team == away else None)
                        if side and isinstance(tstats.get(side), dict):
                            pi["stat_line"] = _rz_def_stat_line(tstats[side])
                    else:
                        full = (nfl_players.get(pid, {}).get("full_name") or "").lower()
                        ps = name_map.get(full)
                        if ps:
                            pi["stat_line"] = _rz_stat_line_from_ps(ps)

    # Projected points per matchup (PPR, cached 15 min)
    proj_pts: dict = {}
    try:
        proj_pts = _rz_get_projections(season, week)
    except Exception:
        logger.debug("suppressed exception", exc_info=True)

    matchups_out = []
    for m in matchups:
        proj_total = float(m.get("points") or 0)
        for pid in (m.get("starters") or []):
            if pid == "0":
                continue
            code = (player_info.get(pid) or {}).get("game_code", "0")
            if code not in ("1", "2"):  # not live/final → add remaining projection
                proj_total += float(proj_pts.get(str(pid), 0))
        matchups_out.append({**m, "projected_pts": round(proj_total, 2)})

    return {
        "matchups": matchups_out,
        "rosters": [
            {"roster_id": r.get("roster_id"), "owner_id": r.get("owner_id"),
             "starters": r.get("starters") or [], "players": r.get("players") or []}
            for r in rosters
        ],
        "users": [
            {"user_id": u.get("user_id"),
             "display_name": u.get("display_name") or u.get("username") or "Team"}
            for u in users
        ],
        "player_info": player_info,
        "scoring": scoring,
    }


def _redzone_fetch(platform, league_id, season, week=None, scope="league"):
    """Return live Redzone payload. scope='league' (all teams in this league)
    or scope='user' (the viewer's team across all their leagues)."""
    from dashboard_services.api import get_nfl_state
    state  = get_nfl_state() or {}
    season = int(season or state.get("season") or date.today().year)
    week   = int(week or state.get("week") or 1)
    # Whether a game is actually scheduled today (drives client live polling).
    gt = _games_scheduled_today(season, week)

    if scope == "user":
        try:
            d = _redzone_fetch_user(platform, league_id, season, week)
            d["games_today"] = gt
            return d
        except Exception as _e:
            logger.warning("[redzone] user-scope fetch failed: %s", _e)
            # fall through to league scope

    d = _redzone_collect(platform, league_id, season, week)
    vrid = str(session.get("viewer_roster_id") or "")
    d.update({
        "week": week, "season": season, "platform": platform, "league_id": league_id,
        "scope": "league",
        "leagues": [{"league_id": league_id, "name": ""}],
        "viewer_roster_id": vrid,
        "viewer_roster_ids": [vrid] if vrid else [],
        "games_today": gt,
        "updated_at": time.time(),
    })
    return d


def _redzone_fetch_user(platform, league_id, season, week):
    """Aggregate the viewer's matchup across every league they belong to (Sleeper)."""
    from dashboard_services.api import get_sleeper_user_leagues
    viewer_uid = str(session.get("viewer_user_id") or "")
    if platform != "sleeper" or not viewer_uid:
        raise ValueError("user scope requires a signed-in Sleeper viewer")

    leagues_raw = get_sleeper_user_leagues(viewer_uid, season) or []
    leagues_raw = leagues_raw[:12]

    matchups, rosters, users, leagues = [], [], [], []
    player_info: dict = {}
    scoring: dict = {}
    scoring_by_league: dict = {}   # league_id -> that league's scoring settings
    pid_league: dict = {}          # pid -> league_id (so each player scores by its league)
    viewer_rids = []
    seen_users = set()

    for li, lg in enumerate(leagues_raw):
        lid   = str(lg.get("league_id") or "")
        lname = lg.get("name") or f"League {li + 1}"
        if not lid:
            continue
        try:
            d = _redzone_collect(platform, lid, season, week)
        except Exception:
            continue
        if not scoring:
            scoring = d.get("scoring") or {}
        scoring_by_league[lid] = d.get("scoring") or {}
        vr = next((r for r in d["rosters"] if str(r.get("owner_id")) == viewer_uid), None)
        if not vr:
            continue
        vrid = str(vr.get("roster_id"))
        vmid = next((str(m.get("matchup_id")) for m in d["matchups"]
                     if str(m.get("roster_id")) == vrid), None)
        if vmid is not None:
            pair = [m for m in d["matchups"] if str(m.get("matchup_id")) == vmid]
        else:
            pair = [m for m in d["matchups"] if str(m.get("roster_id")) == vrid]
        if not pair:
            continue
        ns = f"{li}:"
        pair_rids = {str(m.get("roster_id")) for m in pair}
        for m in pair:
            m2 = dict(m)
            m2["roster_id"]    = ns + str(m.get("roster_id"))
            m2["matchup_id"]   = ns + str(m.get("matchup_id"))
            m2["league_name"]  = lname
            m2["league_id"]    = lid
            matchups.append(m2)
            for _pid in (m.get("players") or []):
                pid_league[str(_pid)] = lid
        for r in d["rosters"]:
            if str(r.get("roster_id")) in pair_rids:
                r2 = dict(r)
                r2["roster_id"] = ns + str(r.get("roster_id"))
                rosters.append(r2)
        for u in d["users"]:
            uid = u.get("user_id")
            if uid not in seen_users:
                seen_users.add(uid)
                users.append(u)
        player_info.update(d["player_info"])
        viewer_rids.append(ns + vrid)
        leagues.append({"league_id": lid, "name": lname})

    return {
        "week": week, "season": season, "platform": platform, "league_id": league_id,
        "scope": "user",
        "matchups": matchups,
        "rosters": rosters,
        "users": users,
        "leagues": leagues,
        "player_info": player_info,
        "scoring": scoring,
        "scoring_by_league": scoring_by_league,
        "pid_league": pid_league,
        "viewer_roster_id": viewer_rids[0] if viewer_rids else "",
        "viewer_roster_ids": viewer_rids,
        "updated_at": time.time(),
    }


@app.route("/<platform>/<int:season>/<league_id>/redzone")
def page_redzone(platform: str, season: int, league_id: str):
    scope = "user" if request.args.get("scope") == "user" else "league"
    # Redzone's live player feed is Sleeper-only; show an honest note instead of
    # an empty, name-less live view when an ESPN/Yahoo user deep-links here.
    if (platform or "").lower() != "sleeper" and request.args.get("demo") != "1":
        body = (
            "<div class='card central' style='max-width:560px;margin:32px auto;'>"
            "<div class='card-body' style='padding:28px 24px;text-align:center;'>"
            "<h2 style='margin:0 0 8px;'>Redzone is Sleeper-only for now</h2>"
            "<p style='color:var(--text-muted);font-size:14px;line-height:1.6;margin:0;'>"
            "Live Redzone tracking uses Sleeper's real-time player feed, which isn't "
            "available for ESPN or Yahoo leagues yet. Everything else - your matchups, "
            "scores, and the rest of the tools — works normally on this platform."
            "</p></div></div>"
        )
        return render_page("BR Redzone", league_id, "redzone", body, platform, season)
    if request.args.get("demo") == "1":
        data = _redzone_demo_data(scope=scope)
    else:
        try:
            data = _redzone_fetch(platform, league_id, season, scope=scope)
        except Exception as _e:
            logger.warning("[redzone] initial fetch failed: %s", _e)
            data = {"matchups": [], "rosters": [], "users": [], "player_info": {},
                    "week": 1, "season": season, "viewer_roster_id": "", "scoring": {},
                    "platform": platform, "league_id": league_id, "updated_at": time.time()}

    body = (
        '<div id="rz-root" class="rz-page"><div class="rz-boot-spinner">Loading...</div></div>'
        f'<script>window.__rz__={json.dumps(data)};</script>'
        # The Redzone live module is split out of app.js so it only loads here.
        # `defer` runs it after the page's blocking app.js, so the shared helpers
        # (openPlayerModal, window._rzBuildLiveHtml/_rzSyncTabLive) are defined.
        f'<script src="/static/redzone.js?v={_REDZONE_JS_V}" defer></script>'
    )
    return render_page("BR Redzone", league_id, "redzone", body, platform, season)


@app.route("/api/<platform>/<int:season>/<league_id>/redzone-data")
def api_redzone_data(platform: str, season: int, league_id: str):
    scope = "user" if request.args.get("scope") == "user" else "league"
    if request.args.get("demo") == "1":
        try:
            _t = float(request.args.get("t", _RZ_DEMO_START))
        except (TypeError, ValueError):
            _t = _RZ_DEMO_START
        return jsonify(_redzone_demo_data(_t, scope=scope))
    week = request.args.get("week")
    try:
        return jsonify(_redzone_fetch(platform, league_id, season, week=week, scope=scope))
    except Exception as _e:
        logger.warning("[redzone] api fetch failed: %s", _e)
        return jsonify({"error": str(_e)}), 500


@app.route("/api/<platform>/<int:season>/<league_id>/redzone-player")
def api_redzone_player(platform: str, season: int, league_id: str):
    """Return Tank01 boxscore stats for a single player, tagged with fantasy pts."""
    from dashboard_services.api import (
        get_nfl_players, fetch_tank_boxscore, get_effective_scoring_settings,
    )
    pid     = request.args.get("pid", "")
    game_id = request.args.get("game_id", "")
    if not pid:
        return jsonify({}), 400

    try:
        nfl_players = get_nfl_players() if platform == "sleeper" else {}
        player      = nfl_players.get(pid, {})
        pos         = (player.get("position") or "").upper()

        stats = {}
        if game_id:
            box = fetch_tank_boxscore(game_id) or {}
            player_stats = box.get("playerStats") or {}
            if isinstance(player_stats, dict):
                for _, ps in player_stats.items():
                    if (ps.get("longName") or "").lower() == (player.get("full_name") or "").lower():
                        stats = ps
                        break

        scoring = get_effective_scoring_settings() or {}

        def _pts(stat_key, score_key, multiplier=1):
            val = float(stats.get(stat_key) or 0) * multiplier
            rate = float(scoring.get(score_key) or 0)
            return round(val * rate, 2) if rate else 0

        breakdown = {}
        if pos == "QB":
            passing = stats.get("Passing") or {}
            rushing = stats.get("Rushing") or {}
            breakdown = {
                "pass_yds": float(passing.get("passYds") or 0),
                "pass_tds":  float(passing.get("passTD") or 0),
                "ints":      float(passing.get("int") or 0),
                "rush_yds": float(rushing.get("rushYds") or 0),
                "rush_tds":  float(rushing.get("rushTD") or 0),
            }
        elif pos in ("RB", "WR", "TE"):
            rushing  = stats.get("Rushing") or {}
            receiving = stats.get("Receiving") or {}
            breakdown = {
                "rush_yds":  float(rushing.get("rushYds") or 0),
                "rush_tds":  float(rushing.get("rushTD") or 0),
                "receptions": float(receiving.get("receptions") or 0),
                "rec_yds":   float(receiving.get("recYds") or 0),
                "rec_tds":   float(receiving.get("recTD") or 0),
            }

        return jsonify({"pos": pos, "scoring": scoring, "breakdown": breakdown})
    except Exception as _e:
        logger.warning("[redzone] player fetch %s: %s", pid, _e)
        return jsonify({}), 500


_ACTIVITY_BUILDING: set = set()
_ACTIVITY_BUILDING_LOCK = threading.Lock()


def _background_build_activity(platform: str, league_id: str, season: int) -> None:
    """Build the activity page HTML off the request thread and cache it.

    Labeling traded draft picks pulls prior-season league contexts and playoff
    brackets, which can be slow on a cold cache; doing it here lets the request
    return a skeleton immediately (same pattern as the teams page).
    """
    import logging as _log
    _logger = _log.getLogger(__name__)
    build_key = f"{platform}:{season}:{league_id}"
    fail_key = f"activity:{platform}:{season}:{league_id}"
    try:
        t0 = time.time()
        ctx = get_league_ctx_from_cache(platform, league_id, season)
        body_html = build_activity_body(ctx)
        store_page_html(platform, season, league_id, "activity", body_html)
        with _PAGE_BG_LOCK:
            _PAGE_BG_FAILED.discard(fail_key)
        _logger.info("Activity build complete in %.1fs", time.time() - t0)
    except Exception as exc:  # noqa: BLE001
        _logger.error("Background activity build failed: %s", exc, exc_info=True)
        with _PAGE_BG_LOCK:
            _PAGE_BG_FAILED.add(fail_key)
    finally:
        with _ACTIVITY_BUILDING_LOCK:
            _ACTIVITY_BUILDING.discard(build_key)


def _build_activity_skeleton(platform: str, season: int, league_id: str) -> str:
    """Lightweight shimmer placeholder shown while the feed builds in the background."""
    def _row() -> str:
        return (
            "<div class='card' style='padding:14px 16px;margin-bottom:10px;'>"
            "<div style='display:flex;align-items:center;gap:10px;'>"
            "<div class='sk-shimmer' style='width:34px;height:34px;border-radius:50%;flex-shrink:0;'></div>"
            "<div style='flex:1;min-width:0;'>"
            "<div class='sk-shimmer' style='width:45%;height:13px;border-radius:4px;margin-bottom:7px;'></div>"
            "<div class='sk-shimmer' style='width:70%;height:11px;border-radius:4px;opacity:.7;'></div>"
            "</div>"
            "<div class='sk-shimmer' style='width:52px;height:22px;border-radius:6px;flex-shrink:0;'></div>"
            "</div></div>"
        )
    rows = "".join(_row() for _ in range(6))
    return f"""
    <div class="activity-page">
      <div class="teams-loading-indicator" id="brPageLoad" style="margin-bottom:14px;">
        <div class="loading-spinner" style="width:14px;height:14px;"></div>
        <span>Loading league activity&hellip;</span>
      </div>
      {rows}
    </div>
    """ + _bg_poll_script(
        f"/api/activity-ready?platform={platform}&league_id={league_id}&season={season}"
    )


@app.route("/api/activity-ready")
def api_activity_ready():
    platform  = request.args.get("platform", "sleeper")
    league_id = request.args.get("league_id", "")
    try:
        season = int(request.args.get("season", datetime.now().year))
    except (TypeError, ValueError):
        season = datetime.now().year
    if get_page_html_from_cache(platform, season, league_id, "activity"):
        return jsonify({"ready": True})
    with _PAGE_BG_LOCK:
        failed = f"activity:{platform}:{season}:{league_id}" in _PAGE_BG_FAILED
    return jsonify({"ready": False, "failed": failed})


@app.route("/<platform>/<int:season>/<league_id>/activity")
def page_activity(platform: str, season: int, league_id: str):
    cached = get_page_html_from_cache(platform, season, league_id, "activity")
    if cached:
        return render_page("BR Fantasy Activity", league_id, "activity", cached, platform, season)

    # If the league context is already warm (user came from another page), build
    # synchronously - it's quick once the ctx is cached and avoids the poll round-trip.
    ctx_entry = DASHBOARD_CACHE.get(_cache_key(platform, season, league_id))
    if ctx_entry and (time.time() - ctx_entry.get("ts", 0) <= CACHE_TTL):
        try:
            body = build_activity_body(ctx_entry["ctx"])
            store_page_html(platform, season, league_id, "activity", body)
            return render_page("BR Fantasy Activity", league_id, "activity", body, platform, season)
        except Exception as exc:  # noqa: BLE001
            import logging as _log
            _log.getLogger(__name__).error("Sync activity build failed: %s", exc, exc_info=True)

    # Cold load - kick off a background build and show a skeleton while it runs.
    build_key = f"{platform}:{season}:{league_id}"
    with _ACTIVITY_BUILDING_LOCK:
        if build_key not in _ACTIVITY_BUILDING:
            _ACTIVITY_BUILDING.add(build_key)
            with _PAGE_BG_LOCK:
                _PAGE_BG_FAILED.discard(f"activity:{platform}:{season}:{league_id}")
            threading.Thread(
                target=_background_build_activity,
                args=(platform, league_id, season),
                daemon=True,
            ).start()

    skeleton = _build_activity_skeleton(platform, season, league_id)
    resp = make_response(render_page("BR Fantasy Activity", league_id, "activity", skeleton, platform, season))
    resp.headers["Cache-Control"] = "no-store"
    return resp


# ── Tour mock data helpers ─────────────────────────────────────────────────

_TOUR_MOCK_TEAMS = [
    "Dynasty Kings", "Gridiron Ghosts", "Blitz Brigade",
    "Redzone Rebels", "Endzone Elite", "Pocket Protectors",
]

def _build_tour_mock_df_weekly() -> pd.DataFrame:
    """Seeded, deterministic weekly scores for 6 mock teams over 13 weeks."""
    import random as _rand
    rng = _rand.Random(42)
    rows = []
    for week in range(1, 14):
        pairs = [(0, 1), (2, 3), (4, 5)] if week % 2 == 0 else [(0, 2), (1, 4), (3, 5)]
        for mid, (a, b) in enumerate(pairs, start=week * 10):
            rows += [
                {
                    "week": week, "matchup_id": mid,
                    "owner": _TOUR_MOCK_TEAMS[a],
                    "points": round(rng.gauss(98, 12), 2),
                    "finalized": True,
                },
                {
                    "week": week, "matchup_id": mid,
                    "owner": _TOUR_MOCK_TEAMS[b],
                    "points": round(rng.gauss(95, 11), 2),
                    "finalized": True,
                },
            ]
    return pd.DataFrame(rows)


def _build_tour_mock_graphs_ctx() -> dict:
    """Minimal ctx for build_graphs_body with pre-computed team_stats."""
    df = _build_tour_mock_df_weekly()
    mock_league: dict = {"settings": {"playoff_week_start": 14}}
    team_stats = build_regular_season_team_stats(df, mock_league)
    team_stats = sort_team_stats(team_stats)

    if not team_stats.empty and "PF" in team_stats.columns:
        pf_z = (team_stats["PF"] - team_stats["PF"].mean()) / max(float(team_stats["PF"].std()), 1.0)
        win_z = (team_stats["Win%"] - team_stats["Win%"].mean()) / max(float(team_stats["Win%"].std()), 1.0)
        avg_z = (team_stats["AVG"] - team_stats["AVG"].mean()) / max(float(team_stats["AVG"].std()), 1.0)
        team_stats["PowerScore"] = 0.30 * pf_z + 0.40 * win_z + 0.30 * avg_z
        # Z-score columns required by z_better_outward
        for col in ["PF", "PA", "MAX", "MIN", "AVG", "STD"]:
            zc = f"Z_{col}"
            if col in team_stats.columns:
                col_vals = team_stats[col]
                std_val = float(col_vals.std())
                team_stats[zc] = (col_vals - col_vals.mean()) / max(std_val, 1.0)

    return {"team_stats": team_stats, "df_weekly": df}


def _build_tour_mock_history_ctx() -> dict:
    """Minimal history context for build_history_body."""
    df = _build_tour_mock_df_weekly()
    return {
        "platform": "sleeper",
        "season": 2024,
        "league_id": "tour_mock",
        "resolved_league_id": "tour_mock",
        "league": {
            "name": "Demo League",
            "league_id": "tour_mock",
            "settings": {"playoff_week_start": 14},
        },
        "df_weekly": df,
        "roster_map": {},
        "users": {},
        "rosters": [],
        "offseason_mode": False,
    }


def _render_graphs_html(platform: str, season: int, league_id: str, view: str, members: str) -> str:
    """Build the graphs page body for a given view ("career" or a season) and
    member filter. Pure of request args (view/members are passed in) so the
    heavy career view - which aggregates every past season - can build in a
    background thread on a cold cache."""
    ctx = get_league_ctx_from_cache(platform, league_id, season)
    offseason = bool(ctx.get("offseason_mode"))
    available_seasons = get_available_history_seasons(platform, league_id, season)

    # Current members = current rosters' owner names. roster_map is populated even
    # in the offseason (team_stats can be empty then), so prefer it; the career
    # aggregate is keyed by these same owner names.
    current_owners = set()
    _rmap = ctx.get("roster_map") or {}
    if _rmap:
        current_owners = {str(v) for v in _rmap.values() if v}
    if not current_owners:
        _cur_ts = ctx.get("team_stats")
        if _cur_ts is not None and not _cur_ts.empty and "owner" in _cur_ts.columns:
            current_owners = {str(o) for o in _cur_ts["owner"].tolist()}

    # Build the season-selector dropdown (navigate via URL query param)
    graphs_base_url = url_for("page_graphs", platform=platform, season=season, league_id=league_id)
    selector_opts = []
    selector_opts.append(
        f"<option value='{graphs_base_url}?view=career' "
        f"{'selected' if view == 'career' else ''}>Career (all seasons)</option>"
    )
    if not offseason:
        selector_opts.append(
            f"<option value='{graphs_base_url}?view={season}' "
            f"{'selected' if view == str(season) else ''}>{season} (current)</option>"
        )
    for s in available_seasons:
        selector_opts.append(
            f"<option value='{graphs_base_url}?view={s}' "
            f"{'selected' if view == str(s) else ''}>{s}</option>"
        )

    # Current-vs-all-time member toggle (only meaningful for the career view,
    # where former members would otherwise appear across every chart).
    members_toggle_html = ""
    if view == "career":
        _cur_url = f"{graphs_base_url}?view=career&members=current"
        _all_url = f"{graphs_base_url}?view=career&members=all"
        members_toggle_html = f"""
        <div class="members-toggle" role="group" aria-label="Member filter">
          <a class="members-toggle-btn {'active' if members == 'current' else ''}" href="{_cur_url}">Current members</a>
          <a class="members-toggle-btn {'active' if members == 'all' else ''}" href="{_all_url}">All-time</a>
        </div>"""

    season_selector_html = f"""
    <div class="graphs-season-selector">
      <label class="graphs-season-label">View:</label>
      <select class="graphs-season-select" onchange="window.location.href=this.value">
        {"".join(selector_opts)}
      </select>
      {members_toggle_html}
    </div>"""

    # ── Render the appropriate graphs ──────────────────────────────────────
    if view == "career":
        if not available_seasons:
            charts_html = """
            <div class="card central">
              <div class="card-body">
                <p style="color:var(--text-muted);">
                  Career graphs appear after your first completed season.
                </p>
              </div>
            </div>"""
        else:
            try:
                # Build career ctx from all available seasons
                career_ctx = _build_career_graphs_ctx_live(
                    platform, league_id, season, available_seasons,
                    only_owners=(current_owners if members == "current" else None),
                )
                charts_html = build_career_graphs_body(career_ctx)

                # The luck + value/age scatters aren't season-aggregates, so the
                # career builder doesn't emit them. Inject them here: value/age
                # from the current rosters, luck from the most recent completed
                # season's weekly results.
                try:
                    from dashboard_services.pages.graphs_page import _luck_and_value_age_cards, owner_color_map
                    _co = None
                    _cts = career_ctx.get("team_stats")
                    if _cts is not None and not _cts.empty and "owner" in _cts.columns:
                        _co = owner_color_map(_cts["owner"].tolist())
                    _luck_df = None
                    _latest = max(available_seasons)
                    _lrid = resolve_league_id_for_season(platform, league_id, season, _latest)
                    _lctx = get_league_ctx_from_cache(platform, _lrid, _latest)
                    _ldf = _lctx.get("df_weekly")
                    if _ldf is not None and not _ldf.empty and "finalized" in _ldf.columns:
                        _luck_df = _ldf[_ldf["finalized"] == True]
                        if members == "current" and current_owners and "owner" in _luck_df.columns:
                            _luck_df = _luck_df[_luck_df["owner"].astype(str).isin(current_owners)]
                    # Use the live value table (the ctx copy can be stale/empty),
                    # so the dynasty-value-vs-age scatter always has real values.
                    _val_ctx = {**ctx, "model_value_table": (get_model_value_table_cached() or ctx.get("model_value_table") or [])}
                    _svg_cards = _luck_and_value_age_cards(_val_ctx, _luck_df, _co)
                    if _svg_cards and '<div class="graphs-page">' in charts_html:
                        charts_html = charts_html.replace(
                            '<div class="graphs-page">',
                            '<div class="graphs-page">' + _svg_cards, 1,
                        )
                except Exception:
                    logger.debug("career graphs scatter injection failed", exc_info=True)
            except Exception as exc:
                import traceback; traceback.print_exc()
                charts_html = (
                    f"<div class='card central'><div class='card-body'>"
                    f"<p>Career graphs unavailable: {exc}</p></div></div>"
                )
    else:
        target_season = int(view) if view.isdigit() else season
        if target_season == season and not offseason:
            season_ctx = ctx
        else:
            rid = resolve_league_id_for_season(platform, league_id, season, target_season)
            season_ctx = get_league_ctx_from_cache(platform, rid, target_season)

        if season_ctx.get("offseason_mode") or season_ctx.get("df_weekly", pd.DataFrame()).empty:
            charts_html = f"""
            <div class="card central">
              <div class="card-body">
                <p style="color:var(--text-muted);">
                  No weekly data available for {target_season}.
                  Select another season or choose Career view.
                </p>
              </div>
            </div>"""
        else:
            charts_html = build_graphs_body(season_ctx)

    return season_selector_html + charts_html


@app.route("/<platform>/<int:season>/<league_id>/graphs")
def page_graphs(platform: str, season: int, league_id: str):
    # Tour preview: render with mock data, bypass real league fetch
    if request.args.get("tour"):
        try:
            mock_ctx = _build_tour_mock_graphs_ctx()
            body_html = build_graphs_body(mock_ctx)
        except Exception as exc:
            body_html = (
                f"<div class='card central'><div class='card-body'>"
                f"<p>Graphs preview unavailable: {exc}</p></div></div>"
            )
        return render_page("BR Fantasy Graphs", league_id, "graphs", body_html, platform, season)

    # Determining the default view needs the (shared) league context; the heavy,
    # graphs-specific work is the career aggregation, deferred below.
    ctx = get_league_ctx_from_cache(platform, league_id, season)
    default_view = "career" if bool(ctx.get("offseason_mode")) else str(season)
    view = request.args.get("view", default_view)
    members = "all" if str(request.args.get("members", "current")).lower() == "all" else "current"

    # Career view aggregates every past season (slow on a cold cache) -> build in
    # the background and show a skeleton. Season views are a single, light league
    # context, so render them inline.
    if view == "career":
        return _serve_cached_or_background(
            platform, season, league_id, f"graphs:career:{members}",
            "BR Fantasy Graphs", "graphs",
            lambda: _render_graphs_html(platform, season, league_id, "career", members),
            "Building career graphs",
        )

    body_html = _render_graphs_html(platform, season, league_id, view, members)
    return render_page("BR Fantasy Graphs", league_id, "graphs", body_html, platform, season)


def _build_career_graphs_ctx_live(
    platform: str, league_id: str, season: int, available_seasons: list,
    only_owners: set = None,
) -> dict:
    """Aggregate team_stats and df_weekly across all completed seasons for career
    graphs. When ``only_owners`` is a non-empty set of owner names, the career
    aggregate is restricted to those members (used by the current-vs-all-time
    toggle to drop owners no longer in the league)."""
    career: dict = {}  # owner -> {Wins, Losses, Ties, PF, PA, weekly_pts, season_pf}
    season_pf_rows: list = []  # rows for per-season bar chart: {season, owner, pf}

    for hist_s in available_seasons:
        rid = resolve_league_id_for_season(platform, league_id, season, hist_s)
        try:
            hctx = get_league_ctx_from_cache(platform, rid, hist_s)
        except Exception:
            continue

        df = hctx.get("df_weekly", pd.DataFrame())
        if df.empty or "owner" not in df.columns:
            continue

        mock_lg = hctx.get("league") or {}
        ts = build_regular_season_team_stats(df, mock_lg)

        for _, row in ts.iterrows():
            owner = str(row.get("owner", "?"))
            if owner not in career:
                career[owner] = {
                    "Wins": 0, "Losses": 0, "Ties": 0,
                    "PF": 0.0, "PA": 0.0, "weekly_pts": [],
                }
            career[owner]["Wins"]   += int(row.get("Wins", 0))
            career[owner]["Losses"] += int(row.get("Losses", 0))
            career[owner]["Ties"]   += int(row.get("Ties", 0))
            career[owner]["PF"]     += float(row.get("PF", 0))
            career[owner]["PA"]     += float(row.get("PA", 0))
            season_pf_rows.append({"season": hist_s, "owner": owner, "pf": float(row.get("PF", 0))})

        sub = df[df["finalized"] == True] if "finalized" in df.columns else df
        for owner, grp in sub.groupby("owner"):
            career.setdefault(str(owner), {
                "Wins": 0, "Losses": 0, "Ties": 0, "PF": 0.0, "PA": 0.0, "weekly_pts": [],
            })["weekly_pts"].extend(grp["points"].tolist() if "points" in grp else [])

    # Build career team_stats DataFrame
    stat_rows = []
    for owner, d in career.items():
        pts = d["weekly_pts"]
        games = d["Wins"] + d["Losses"] + d["Ties"]
        stat_rows.append({
            "owner": owner,
            "Wins": d["Wins"],
            "Losses": d["Losses"],
            "Ties": d["Ties"],
            "PF": d["PF"],
            "PA": d["PA"],
            "AVG": d["PF"] / games if games > 0 else 0.0,
            "Win%": d["Wins"] / games if games > 0 else 0.0,
            "MAX": max(pts) if pts else 0.0,
            "MIN": min(pts) if pts else 0.0,
            "STD": float(pd.Series(pts).std()) if len(pts) > 1 else 0.0,
        })

    team_stats = pd.DataFrame(stat_rows) if stat_rows else pd.DataFrame()

    if not team_stats.empty and "PF" in team_stats.columns:
        # Approximate PowerScore for career (win% + avg PF rank)
        pf_z  = (team_stats["PF"]  - team_stats["PF"].mean())  / max(float(team_stats["PF"].std()),  1.0)
        win_z = (team_stats["Win%"]- team_stats["Win%"].mean()) / max(float(team_stats["Win%"].std()), 1.0)
        avg_z = (team_stats["AVG"] - team_stats["AVG"].mean())  / max(float(team_stats["AVG"].std()),  1.0)
        team_stats["PowerScore"] = 0.30 * pf_z + 0.40 * win_z + 0.30 * avg_z
        for col in ["PF", "PA", "MAX", "MIN", "AVG", "STD"]:
            if col in team_stats.columns:
                cv = team_stats[col]
                sd = max(float(cv.std()), 1.0)
                team_stats[f"Z_{col}"] = (cv - cv.mean()) / sd

    # Combined df_weekly (with season column) for box/line charts
    combined_dfs = []
    for hist_s in available_seasons:
        rid = resolve_league_id_for_season(platform, league_id, season, hist_s)
        try:
            hctx = get_league_ctx_from_cache(platform, rid, hist_s)
            df = hctx.get("df_weekly", pd.DataFrame()).copy()
            if not df.empty and "owner" in df.columns:
                df["season"] = hist_s
                combined_dfs.append(df)
        except Exception:
            continue

    df_combined = pd.concat(combined_dfs, ignore_index=True) if combined_dfs else pd.DataFrame()
    season_pf_df = pd.DataFrame(season_pf_rows) if season_pf_rows else pd.DataFrame()

    # Restrict to current members when the toggle asks for it.
    if only_owners:
        _keep = {str(o) for o in only_owners}
        if not team_stats.empty and "owner" in team_stats.columns:
            team_stats = team_stats[team_stats["owner"].astype(str).isin(_keep)].reset_index(drop=True)
        if not df_combined.empty and "owner" in df_combined.columns:
            df_combined = df_combined[df_combined["owner"].astype(str).isin(_keep)].reset_index(drop=True)
        if not season_pf_df.empty and "owner" in season_pf_df.columns:
            season_pf_df = season_pf_df[season_pf_df["owner"].astype(str).isin(_keep)].reset_index(drop=True)

    return {
        "team_stats": team_stats,
        "df_weekly": df_combined,
        "season_pf_df": season_pf_df,
        "is_career": True,
    }




def _rankings_ssr_content(limit: int = 150):
    """Server-render the top-N dynasty rankings as real HTML rows + JSON-LD.

    The rankings table is otherwise hydrated entirely client-side (rankings.js
    fetches /api/league-players and fills #prList), so crawlers and the initial
    paint see nothing but a "Loading players…" spinner - which reads to Google /
    AdSense as thin, low-value content on our most SEO-targeted pages
    (/dynasty-trade-value-chart, /rankings/dynasty*). Emitting the top players as
    real markup gives an indexable, content-rich table and a faster first paint.
    rankings.js then does list.innerHTML='' and re-renders #prList identically,
    so there is no visible flash on hydration.

    Uses the default public view (1QB / dynasty / 10-team = the `value` column),
    which is exactly what the client renders on first load. Returns
    (rows_html, jsonld_html); both are '' if the value table is unavailable, in
    which case the page falls back to the spinner-only shell.
    """
    try:
        payload = _build_league_players_payload()
        players = payload.get("players") or []
    except Exception:
        logger.debug("rankings SSR: payload load failed", exc_info=True)
        return "", ""

    # Real NFL players only: exclude draft picks and not-yet-drafted rookies,
    # which carry no standalone content value and clutter the indexable table.
    ranked = [
        p for p in players
        if str(p.get("position") or "").upper() in ("QB", "RB", "WR", "TE")
        and float(p.get("value") or 0) > 0
        and not (p.get("is_rookie") and str(p.get("team") or "") in ("", "FA"))
    ]
    ranked.sort(key=lambda p: float(p.get("value") or 0), reverse=True)
    ranked = ranked[:limit]
    if not ranked:
        return "", ""

    rows = []
    items = []
    for i, p in enumerate(ranked, 1):
        name     = html.escape(str(p.get("name") or "Unknown"))
        team     = html.escape(str(p.get("team") or "–"))
        pos_rank = html.escape(str(p.get("pos_rank_label") or p.get("position") or ""))
        _age_v   = p.get("age")
        try:
            age = f"{float(_age_v):.1f}" if _age_v not in (None, "") else "–"
        except (TypeError, ValueError):
            age = "–"
        _val_v = float(p.get("value") or 0)
        val = f"{_val_v:.1f}" if _val_v > 0 else "-"
        rows.append(
            '<div class="pr-player-row pr-grid-row">'
            f'<span class="pr-rank">#{i}</span>'
            '<span class="pr-arrows"></span>'
            f'<span class="pr-name player-clickable">{name}</span>'
            f'<span class="pr-pos-cell">{pos_rank}</span>'
            f'<span class="pr-age">{age}</span>'
            f'<span class="pr-team">{team}</span>'
            f'<span class="pr-value">{val}</span>'
            '</div>'
        )
        items.append({
            "@type": "ListItem",
            "position": i,
            "item": {"@type": "Thing", "name": str(p.get("name") or "Unknown")},
        })

    ld = {
        "@context": "https://schema.org",
        "@type": "ItemList",
        "name": "Dynasty Fantasy Football Trade Value Rankings",
        "itemListElement": items,
    }
    # Escape '<' so a player name can never break out of the ld+json <script>.
    jsonld = (
        '<script type="application/ld+json">'
        + json.dumps(ld, separators=(",", ":")).replace("<", "\\u003c")
        + '</script>'
    )
    return "".join(rows), jsonld


# Methodology + FAQ copy for the public rankings / trade-value-chart pages.
# One source builds both the on-page accordion and the FAQPage structured data,
# so they can't drift. Answers are plain text (schema-safe); the display markup
# is generated from the same list.
_RANKINGS_FAQ = [
    ("How are dynasty trade values calculated?",
     "They blend consensus market data from real dynasty trades with recent on-field "
     "usage, the positional aging curve, and each player's situation. The result "
     "estimates what your league would give up to acquire him — weighted for long-term "
     "outlook, not just this week's projection. Values refresh daily."),
    ("Why is a younger player valued above an older one who scores more?",
     "Dynasty rosters are held for years, so value prices in the runway a player has "
     "left. A 23-year-old ascending receiver can out-value a 30-year-old running back "
     "who scores more today, because the market pays for future production — and "
     "running backs decline earlier than receivers."),
    ("Should I use 1QB or Superflex values?",
     "Match your league. In Superflex you can start two quarterbacks, so passers are "
     "worth far more. Toggle the format in the settings; reading 1QB values in a "
     "Superflex league is the most common way people misprice a quarterback."),
    ("What's the difference between dynasty and redraft values?",
     "Redraft values only care about this season's expected points, so productive "
     "veterans rank higher. Dynasty values look years ahead and reward youth. Use the "
     "scoring toggle to switch between the two."),
    ("How often is the chart updated?",
     "Daily. Fresh market data and the latest usage roll in every day, and major news "
     "— injuries, trades, depth-chart moves — is reflected within a day."),
]


def _rankings_methodology_faq() -> str:
    """Methodology prose + FAQ accordion (with FAQPage schema) for public pages."""
    details = "".join(
        f'<details class="faq-item"><summary>{q}</summary><p>{a}</p></details>'
        for q, a in _RANKINGS_FAQ
    )
    faq_ld = {
        "@context": "https://schema.org",
        "@type": "FAQPage",
        "mainEntity": [
            {"@type": "Question", "name": q,
             "acceptedAnswer": {"@type": "Answer", "text": a}}
            for q, a in _RANKINGS_FAQ
        ],
    }
    jsonld = (
        '<script type="application/ld+json">'
        + json.dumps(faq_ld, separators=(",", ":")).replace("<", "\\u003c")
        + "</script>"
    )
    return (
        '<div class="static-section" style="max-width:860px;margin:22px auto 0;">'
        '<div class="static-section-title">How these dynasty values are built</div>'
        '<p style="color:var(--text-muted);font-size:14px;line-height:1.75;">'
        "Every number here estimates one thing: <strong>what the rest of your league would "
        "actually give up to acquire a player</strong> — not how many points he'll score this "
        "week. That's what separates a dynasty value from a redraft ranking, and it's why the "
        "two lists never match. Each value blends four inputs: <strong>consensus market data</strong> "
        "from thousands of real dynasty trades, <strong>recent usage and efficiency</strong>, the "
        "<strong>positional aging curve</strong> (running backs are discounted early; receivers and "
        "quarterbacks hold value longer), and each player's <strong>situation</strong> — target share, "
        "depth-chart competition, and offensive context.</p>"
        '<div class="static-section-title">How to use the chart</div>'
        '<ul style="color:var(--text-muted);font-size:14px;line-height:1.8;margin-left:20px;">'
        "<li><strong>Start from the number, then adjust</strong> for your roster's timeline and needs — "
        "a value is a market estimate, not a law.</li>"
        "<li><strong>Match the format toggle to your league.</strong> Superflex makes quarterbacks far "
        "more valuable; reading 1QB values in a Superflex league under-rates every QB.</li>"
        "<li><strong>Compare across positions, not just within one</strong> — the single scale is what "
        'makes "two mid-WRs for one stud RB" a question you can actually answer.</li>'
        "</ul>"
        '<p style="color:var(--text-muted);font-size:14px;line-height:1.75;">New to dynasty values? Start '
        'with <a href="/guides/dynasty-trade-value">How Dynasty Trade Value Works</a>, keep the '
        '<a href="/glossary">glossary</a> handy, then bring a deal to the free '
        '<a href="/trade">Trade Calculator</a>.</p>'
        '<div class="static-section-title">Frequently asked questions</div>'
        + details + jsonld +
        "</div>"
    )


