def _build_recap_preview_df(team_names: list[str]) -> pd.DataFrame:
    """Generates a single week of mock recap data so users can see the
    page layout before any weeks complete."""
    import random as _rand
    rng = _rand.Random(7)
    rows = []
    n = len(team_names)
    if n % 2:
        n -= 1
    pairs = [(team_names[i], team_names[i + 1]) for i in range(0, n, 2)]
    for mid, (a, b) in enumerate(pairs, start=1):
        pa = round(rng.gauss(115, 18), 2)
        pb = round(rng.gauss(108, 18), 2)
        rows += [
            {"week": 1, "matchup_id": mid, "roster_id": str(2 * mid - 1),
             "owner": a, "points": pa, "points_against": pb, "finalized": True},
            {"week": 1, "matchup_id": mid, "roster_id": str(2 * mid),
             "owner": b, "points": pb, "points_against": pa, "finalized": True},
        ]
    return pd.DataFrame(rows)


def _build_next_week_ctx(
    ctx: dict,
    next_week: int,
    playoff_start: int,
    league_id: str,
    season,
    platform: str,
    team_by_rid: dict,
) -> Optional[dict]:
    """Assemble everything the weekly-recap engine needs to pick next week's game
    of the week: the matchup pairings, next-week player projections (for closeness
    and star-impact), the injury index, dynasty values, which NFL teams play that
    week (for byes), playoff framing, and a freshness stamp. Returns None if next
    week's matchups can't be fetched (e.g. a playoff bracket that isn't seeded yet).
    """
    try:
        from dashboard_services.matchups import build_matchup_preview
        matchups = build_matchup_preview(
            league_id=league_id, week=next_week, roster_map=team_by_rid,
            players_map=ctx.get("players") or {}, season=season, platform=platform,
        ) or []
    except Exception:
        matchups = []
    if not matchups:
        return None

    # Next-week projections (Tank01 publishes upcoming weeks ahead of kickoff).
    try:
        bundles = build_projections_by_week(int(season), next_week, ctx.get("raw_scoring_settings"))
        proj_by_pid = (bundles.get(next_week) or {}).get("projections") or {}
    except Exception:
        proj_by_pid = {}

    # NFL teams playing next week — a starter whose team is absent is on bye.
    try:
        from dashboard_services.matchups import build_team_schedule_lookup
        from utils.utils import load_week_schedule
        playing_teams = set(build_team_schedule_lookup(load_week_schedule(int(season), next_week)).keys())
    except Exception:
        playing_teams = set()

    value_by_pid = {
        str(r["id"]): float(r.get("value") or 0)
        for r in (ctx.get("model_value_table") or [])
        if isinstance(r, dict) and r.get("id") is not None
    }

    # Playoff framing (relative to the playoff bracket size).
    is_playoff = bool(playoff_start) and next_week >= playoff_start
    round_label = "Playoff game"
    if is_playoff:
        playoff_teams = int(((ctx.get("league") or {}).get("settings") or {}).get("playoff_teams") or 6)
        rounds = max(1, math.ceil(math.log2(playoff_teams))) if playoff_teams > 1 else 1
        round_idx = next_week - playoff_start
        if round_idx >= rounds - 1:
            round_label = "Championship"
        elif round_idx == rounds - 2:
            round_label = "Semifinal"
        elif round_idx == rounds - 3:
            round_label = "Quarterfinal"
        else:
            round_label = f"Playoff Round {round_idx + 1}"

    return {
        "matchups": matchups,
        "proj_by_pid": proj_by_pid,
        "player_index": ctx.get("players_index") or {},
        "value_by_pid": value_by_pid,
        "playing_teams": playing_teams,
        "is_playoff": is_playoff,
        "playoff_round_label": round_label,
        "as_of": datetime.now().strftime("%a %b %d"),
    }


def build_recap_body(ctx: dict, selected_week: Optional[int] = None) -> str:
    df_weekly  = ctx.get("df_weekly")
    roster_map = ctx.get("roster_map") or {}
    users      = ctx.get("users") or []
    league     = ctx.get("league") or {}
    settings   = league.get("settings") or {}
    playoff_start = int(settings.get("playoff_week_start") or 14)
    _platform  = ctx.get("platform") or "sleeper"
    _season    = ctx.get("season") or ""
    _league_id = ctx.get("league_id") or ""
    history_url = f"/{_platform}/{_season}/{_league_id}/history" if _league_id else ""

    # ── Preview mode: no finalized weeks yet → use mock data ───────────────
    preview_mode = False
    has_real_finalized = (
        df_weekly is not None
        and not df_weekly.empty
        and "finalized" in df_weekly.columns
        and bool((df_weekly["finalized"] == True).any())
    )
    if not has_real_finalized:
        preview_mode = True
        # Build mock data from real team names if available, else defaults
        if roster_map:
            team_names = [str(n) for n in roster_map.values()][:10]
            # Map mock roster_ids to real ones so avatars resolve
            real_rids = list(roster_map.keys())
            df_weekly = _build_recap_preview_df(team_names)
            # Overwrite roster_id with real ones to enable avatar lookup
            for i, rid in enumerate(df_weekly["roster_id"].tolist()):
                if i < len(real_rids):
                    df_weekly.at[i, "roster_id"] = str(real_rids[i % len(real_rids)])
        else:
            team_names = ["Dynasty Kings", "Gridiron Ghosts", "Blitz Brigade",
                          "Redzone Rebels", "Endzone Elite", "Pocket Protectors"]
            df_weekly = _build_recap_preview_df(team_names)
            roster_map = {str(i + 1): n for i, n in enumerate(team_names)}

    # avatar by owner name
    owner_avatar: dict = {}
    for u in users:
        name = u.get("display_name") or u.get("username") or ""
        ava  = u.get("metadata", {}).get("avatar") or u.get("avatar") or ""
        if name and ava:
            if not ava.startswith("http"):
                ava = f"https://sleepercdn.com/avatars/thumbs/{ava}"
            owner_avatar[name] = ava

    # team name by roster_id
    team_by_rid: dict = {str(rid): name for rid, name in roster_map.items()}

    fin_df = df_weekly[df_weekly["finalized"] == True].copy()

    available_weeks = sorted(fin_df["week"].unique().tolist())
    reg_weeks = [w for w in available_weeks if w < playoff_start]
    if not reg_weeks:
        reg_weeks = available_weeks

    if selected_week is None or selected_week not in available_weeks:
        selected_week = reg_weeks[-1]

    week_df = fin_df[fin_df["week"] == selected_week].copy()

    # ── Matchup pairs ──────────────────────────────────────────────────────
    matchups: list[dict] = []
    for _, grp in week_df.groupby("matchup_id"):
        if len(grp) != 2:
            continue
        grp = grp.sort_values("points", ascending=False)
        w_row, l_row = grp.iloc[0], grp.iloc[1]
        margin = float(w_row["points"]) - float(l_row["points"])
        matchups.append({
            "winner": w_row["owner"],
            "loser":  l_row["owner"],
            "w_rid":  str(w_row.get("roster_id", "")),
            "l_rid":  str(l_row.get("roster_id", "")),
            "w_pts":  float(w_row["points"]),
            "l_pts":  float(l_row["points"]),
            "margin": margin,
        })
    matchups.sort(key=lambda x: -x["margin"])

    # ── Highlights ─────────────────────────────────────────────────────────
    high_row = week_df.loc[week_df["points"].idxmax()]
    low_row  = week_df.loc[week_df["points"].idxmin()]
    blowout  = matchups[0] if matchups else None
    closest  = matchups[-1] if matchups else None

    league_avg = float(week_df["points"].mean()) if not week_df.empty else 0
    league_total = float(week_df["points"].sum()) if not week_df.empty else 0

    # Season high/low context
    fin_max = float(fin_df["points"].max())
    season_high = float(high_row["points"]) >= fin_max

    def ava_img(owner_name, rid="", size=32):
        ava = owner_avatar.get(owner_name, "")
        if ava:
            return f"<img src='{ava}' alt='' loading='lazy' decoding='async' style='width:{size}px;height:{size}px;border-radius:50%;object-fit:cover;flex-shrink:0;' onerror=\"this.style.display='none'\">"
        return team_crest(team_by_rid.get(rid) or owner_name or "?", size)

    def team_name(owner, rid=""):
        return html.escape(team_by_rid.get(rid) or owner or "–")

    # ── Week selector ──────────────────────────────────────────────────────
    week_opts = "".join(
        f"<option value='{w}' {'selected' if w == selected_week else ''}>Week {w}</option>"
        for w in reversed(reg_weeks)
    )
    history_banner = ""
    if history_url:
        history_banner = f"""
<div id="historyRecapBanner" style="display:flex;align-items:center;gap:10px;padding:11px 16px;
     margin-bottom:16px;border-radius:8px;background:var(--surface2);border:1px solid var(--border);">
  <i class="fa-solid fa-trophy" style="font-size:13px;color:var(--accent);flex-shrink:0;"></i>
  <span style="font-size:13px;color:var(--text);flex:1;">
    Want the full season breakdown? View it on the
    <a href="{history_url}" style="color:var(--accent);font-weight:600;text-decoration:none;">History page</a>.
  </span>
  <button onclick="this.parentElement.style.display='none'"
          style="background:none;border:none;color:var(--muted);cursor:pointer;padding:0 2px;
                 font-size:16px;line-height:1;flex-shrink:0;" aria-label="Dismiss">&#x2715;</button>
</div>"""

    # Data for the client-drawn shareable recap card (static/app.js paints it
    # onto a canvas and hands it to the native share sheet).
    _card_matchups = sorted(matchups, key=lambda x: -x["w_pts"])[:6]
    _recap_share = {
        "league": str(league.get("name") or "League"),
        "week": int(selected_week),
        "season": str(_season),
        "games": [{"w": m["winner"], "l": m["loser"],
                   "ws": round(m["w_pts"], 1), "ls": round(m["l_pts"], 1)}
                  for m in _card_matchups],
        "top": {"team": str(high_row["owner"]), "pts": round(float(high_row["points"]), 1)},
        "blowout": ({"team": blowout["winner"], "margin": round(blowout["margin"], 1)}
                    if blowout else None),
        "closest": ({"team": closest["winner"], "margin": round(closest["margin"], 1)}
                    if closest else None),
    }
    _recap_share_json = json.dumps(_recap_share).replace("</", "<\\/")

    week_selector = f"""
<div style="display:flex;align-items:center;gap:10px;margin-bottom:20px;flex-wrap:wrap;">
  <h2 style="margin:0;font-size:20px;">Week {selected_week} Recap</h2>
  <select onchange="window.location.search='?week='+this.value"
          style="padding:5px 10px;border-radius:6px;border:1px solid var(--border);
                 background:var(--card);color:var(--text);font-size:13px;cursor:pointer;">
    {week_opts}
  </select>
  <button type="button" id="recapShareBtn"
          style="display:flex;align-items:center;gap:5px;padding:5px 12px;border-radius:6px;
                 border:1px solid var(--border);background:var(--card);color:var(--text);
                 font-size:13px;cursor:pointer;font-weight:600;">
    <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><line x1="8.59" y1="13.51" x2="15.42" y2="17.49"/><line x1="15.41" y1="6.51" x2="8.59" y2="10.49"/></svg> Share
  </button>
  <script type="application/json" id="recapShareData">{_recap_share_json}</script>
</div>"""

    # ── Headline cards ─────────────────────────────────────────────────────
    def _scorer_opp(row):
        """The other team in this scorer's matchup, so the scorer cards can show
        who they beat/lost to (matching the two-row matchup cards) instead of
        leaving the card half-empty."""
        try:
            grp = week_df[week_df["matchup_id"] == row.get("matchup_id")]
            others = grp[grp["owner"] != row["owner"]]
            if others.empty:
                return None
            o = others.iloc[0]
            return {"owner": o["owner"], "rid": str(o.get("roster_id", "")),
                    "pts": float(o["points"])}
        except Exception:
            return None

    def scorer_card(icon, label, name, pts, rid, sub, accent, opp=None, medal_rank=None):
        # The week's HIGH SCORER earns a gold medal (a weekly award); the other
        # cards keep their semantic icon.
        mark = (rank_mark(medal_rank, size=22, wrap=False)
                if medal_rank else
                f'<i class="{icon}" style="font-size:13px;color:{accent};width:16px;text-align:center;"></i>')
        header = f"""
  <div style="display:flex;align-items:center;gap:6px;">
    {mark}
    <span style="font-size:10px;font-weight:700;letter-spacing:.06em;color:var(--muted);">{label}</span>
  </div>"""
        if opp:
            diff = abs(pts - opp["pts"])
            result = f"{'Won' if pts > opp['pts'] else 'Lost'} by {diff:.1f}"
            body = f"""
  <div style="display:flex;flex-direction:column;gap:8px;">
    <div style="display:flex;align-items:center;gap:10px;">
      {ava_img(name, rid, 36)}
      <div style="flex:1;min-width:0;">
        <div style="font-size:14px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">{team_name(name, rid)}</div>
      </div>
      <div style="font-size:24px;font-weight:800;color:{accent};flex-shrink:0;letter-spacing:-.5px;font-variant-numeric:tabular-nums;">{pts:.2f}</div>
    </div>
    <div style="height:1px;background:var(--border);"></div>
    <div style="display:flex;align-items:center;gap:10px;opacity:0.45;">
      {ava_img(opp["owner"], opp["rid"], 36)}
      <div style="flex:1;min-width:0;">
        <div style="font-size:14px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">{team_name(opp["owner"], opp["rid"])}</div>
      </div>
      <div style="font-size:24px;font-weight:800;flex-shrink:0;letter-spacing:-.5px;font-variant-numeric:tabular-nums;">{opp["pts"]:.1f}</div>
    </div>
  </div>
  <div style="font-size:11px;color:var(--muted);font-weight:600;"><span style="color:{accent};">{html.escape(sub)}</span> &middot; {result}</div>"""
        else:
            body = f"""
  <div style="display:flex;align-items:center;justify-content:space-between;gap:12px;">
    <div style="display:flex;align-items:center;gap:10px;min-width:0;">
      {ava_img(name, rid, 44)}
      <div style="min-width:0;">
        <div style="font-weight:700;font-size:15px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">{team_name(name, rid)}</div>
        <div style="font-size:12px;color:var(--muted);">@{html.escape(name)}</div>
      </div>
    </div>
    <div style="text-align:right;flex-shrink:0;">
      <div style="font-size:32px;font-weight:800;color:{accent};letter-spacing:-.5px;line-height:1;font-variant-numeric:tabular-nums;">{pts:.2f}</div>
      <div style="font-size:11px;color:{accent};font-weight:600;margin-top:4px;">{html.escape(sub)}</div>
    </div>
  </div>"""
        return f"""
<div class="card" style="padding:18px 20px;display:flex;flex-direction:column;gap:14px;min-width:0;">{header}{body}
</div>"""

    def matchup_card(icon, label, m):
        w_team = team_name(m["winner"], m["w_rid"])
        l_team = team_name(m["loser"],  m["l_rid"])
        return f"""
<div class="card" style="padding:18px 20px;display:flex;flex-direction:column;gap:14px;min-width:0;">
  <div style="display:flex;align-items:center;gap:6px;">
    <i class="{icon}" style="font-size:13px;color:var(--accent);width:16px;text-align:center;"></i>
    <span style="font-size:10px;font-weight:700;letter-spacing:.06em;color:var(--muted);">{label}</span>
  </div>
  <div style="display:flex;flex-direction:column;gap:8px;">
    <div style="display:flex;align-items:center;gap:10px;">
      {ava_img(m["winner"], m["w_rid"], 36)}
      <div style="flex:1;min-width:0;">
        <div style="font-size:14px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">{w_team}</div>
      </div>
      <div style="font-size:24px;font-weight:800;color:var(--accent);flex-shrink:0;letter-spacing:-.5px;">{m['w_pts']:.1f}</div>
    </div>
    <div style="height:1px;background:var(--border);"></div>
    <div style="display:flex;align-items:center;gap:10px;opacity:0.45;">
      {ava_img(m["loser"], m["l_rid"], 36)}
      <div style="flex:1;min-width:0;">
        <div style="font-size:14px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">{l_team}</div>
      </div>
      <div style="font-size:24px;font-weight:800;flex-shrink:0;letter-spacing:-.5px;">{m['l_pts']:.1f}</div>
    </div>
  </div>
  <div style="font-size:11px;color:var(--muted);font-weight:600;">margin {m['margin']:.1f}</div>
</div>"""

    high_sub = "Season high" if season_high else f"+{float(high_row['points']) - league_avg:.1f} vs avg"
    low_sub  = f"{float(low_row['points']) - league_avg:.1f} vs avg"

    cards_html = f"""
<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px;margin-bottom:20px;">
  {scorer_card("fa-solid fa-fire", "HIGH SCORER", high_row["owner"],
               float(high_row["points"]), str(high_row.get("roster_id","")),
               high_sub, "var(--win)", _scorer_opp(high_row), medal_rank=1)}
  {scorer_card("fa-solid fa-arrow-trend-down", "LOW SCORER", low_row["owner"],
               float(low_row["points"]), str(low_row.get("roster_id","")),
               low_sub, "var(--loss)", _scorer_opp(low_row))}
  {matchup_card("fa-solid fa-trophy", "BIGGEST WIN", blowout) if blowout else ""}
  {matchup_card("fa-solid fa-bolt", "CLOSEST GAME", closest) if closest else ""}
</div>"""

    # ── Scoreboard ─────────────────────────────────────────────────────────
    def matchup_result_row(m):
        w_team = team_name(m["winner"], m["w_rid"])
        l_team = team_name(m["loser"],  m["l_rid"])
        margin_color = "var(--loss)" if m["margin"] > 50 else ("var(--warning)" if m["margin"] > 20 else "var(--win)")
        return f"""
<div style="display:flex;align-items:center;gap:12px;padding:12px 16px;border-bottom:1px solid var(--border);">
  <div style="flex:1;min-width:0;display:flex;align-items:center;gap:8px;">
    {ava_img(m["winner"], m["w_rid"], 30)}
    <div style="min-width:0;">
      <div style="font-weight:700;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">{w_team}</div>
      <div style="font-size:10px;color:var(--muted);">@{html.escape(m["winner"])}</div>
    </div>
  </div>
  <div style="text-align:center;flex-shrink:0;min-width:110px;">
    <div style="font-size:15px;font-weight:800;">{m['w_pts']:.2f} <span style="color:var(--muted);font-weight:400;font-size:12px;">–</span> {m['l_pts']:.2f}</div>
    <div style="font-size:10px;color:{margin_color};font-weight:700;">+{m['margin']:.2f}</div>
  </div>
  <div style="flex:1;min-width:0;display:flex;align-items:center;gap:8px;justify-content:flex-end;">
    <div style="min-width:0;text-align:right;">
      <div style="font-weight:600;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">{l_team}</div>
      <div style="font-size:10px;color:var(--muted);">@{html.escape(m["loser"])}</div>
    </div>
    {ava_img(m["loser"], m["l_rid"], 30)}
  </div>
</div>"""

    scoreboard_rows = "".join(matchup_result_row(m) for m in matchups)
    scoreboard_html = f"""
<div class="card" style="overflow:hidden;">
  <div class="card-header">
    <h3>Scoreboard</h3>
    <span style="font-size:12px;color:var(--muted);">
      Avg: {league_avg:.1f} &nbsp;·&nbsp; Total: {league_total:.1f}
    </span>
  </div>
  {scoreboard_rows}
</div>"""

    # ── Season standings snapshot ──────────────────────────────────────────
    # Compute cumulative wins/losses/PF through selected_week
    cum_df = fin_df[fin_df["week"] <= selected_week].copy()
    cum_df["win"] = cum_df["points"] > cum_df["points_against"]
    standings_rows_data = []
    for rid, grp in cum_df.groupby("roster_id"):
        owner = grp["owner"].iloc[0]
        wins  = int(grp["win"].sum())
        losses = len(grp) - wins
        pf    = float(grp["points"].sum())
        standings_rows_data.append({
            "rid": str(rid), "owner": owner,
            "wins": wins, "losses": losses, "pf": pf,
        })
    standings_rows_data.sort(key=lambda x: (-x["wins"], -x["pf"]))

    def standing_row(rank, s):
        bar_pct = s["pf"] / max(r["pf"] for r in standings_rows_data) * 100 if standings_rows_data else 0
        lead = " lead" if rank == 1 else ""
        return f"""
<div class="st-row">
  <div class="st-rank{lead}">{rank}</div>
  {ava_img(s["owner"], s["rid"], 28)}
  <div class="st-main">
    <div class="st-name">{team_name(s['owner'], s['rid'])}</div>
    <div class="st-bar"><div class="st-fill" style="width:{bar_pct:.0f}%;"></div></div>
  </div>
  <div class="st-rec">
    <div class="wl">{s['wins']}-{s['losses']}</div>
    <div class="pf">{s['pf']:.1f} PF</div>
  </div>
</div>"""

    standing_rows_html = "".join(standing_row(i + 1, s) for i, s in enumerate(standings_rows_data))
    standings_html = f"""
<div class="card" style="overflow:hidden;">
  <div class="card-header">
    <h3>Standings</h3>
    <span style="font-size:12px;color:var(--muted);">Through week {selected_week}</span>
  </div>
  {standing_rows_html}
</div>"""

    # ── AI weekly storyline column + next-week game-of-the-week ────────────
    if preview_mode:
        from dashboard_services.ai.weekly_recap import get_weekly_ai_recap_preview
        ai_column_html, next_week_html = get_weekly_ai_recap_preview()
    else:
        # Build a next-week preview only when this recap is for the latest
        # finalized week overall (so the "upcoming" game is genuinely upcoming and
        # its availability is current), and that next week isn't already played.
        next_week = selected_week + 1
        next_week_ctx = None
        if selected_week == available_weeks[-1] and next_week not in available_weeks:
            next_week_ctx = _build_next_week_ctx(
                ctx, next_week, playoff_start, _league_id, _season, _platform, team_by_rid,
            )

        from dashboard_services.ai.weekly_recap import get_weekly_ai_recap
        ai_column_html, next_week_html = get_weekly_ai_recap(
            df_weekly=df_weekly,
            matchups_by_week=ctx.get("matchups_by_week") or {},
            selected_week=selected_week,
            team_by_rid=team_by_rid,
            league=league,
            league_id=ctx.get("league_id") or "",
            season=ctx.get("season") or "",
            next_week_ctx=next_week_ctx,
        )

    # ── Lineup analysis: busts, sleepers, coaching mistakes ────────────────
    if preview_mode:
        lineup_html = _mock_lineup_analysis_html(team_names)
    else:
        lineup_html = _build_lineup_analysis_html(
            ctx.get("matchups_by_week") or {},
            selected_week,
            team_by_rid,
            owner_avatar,
        )

    preview_banner = ""
    if preview_mode:
        preview_banner = """
<div style="display:flex;align-items:center;gap:10px;padding:12px 16px;margin-bottom:16px;
            border:1px solid var(--accent);border-radius:8px;background:rgba(99,102,241,0.08);">
  <span style="font-size:18px;">👁️</span>
  <div style="font-size:13px;color:var(--text);">
    <strong>Preview</strong> - this is sample data. Your real weekly recap will appear here after Week 1 completes.
  </div>
</div>"""

    scoreboard_and_recap = f"""
<div class="recap-scoreboard-grid" style="display:grid;grid-template-columns:3fr 2fr;gap:16px;margin-bottom:20px;align-items:stretch;">
  {scoreboard_html.replace("margin-bottom:20px;", "")}
  {ai_column_html.replace("margin-bottom:20px;", "")}
</div>"""

    return (preview_banner + history_banner + week_selector + cards_html
            + scoreboard_and_recap + (next_week_html or "") + lineup_html + standings_html)


@app.route("/<platform>/<int:season>/<league_id>/recap")
def page_recap(platform: str, season: int, league_id: str):
    ctx = get_league_ctx_from_cache(platform, league_id, season)
    try:
        week = int(request.args.get("week") or 0) or None
    except (ValueError, TypeError):
        week = None
    body = build_recap_body(ctx, selected_week=week)
    league_name = html.escape((ctx.get("league") or {}).get("name") or "Fantasy League")
    week_label = f"Week {week} Recap" if week else "Weekly Recap"
    page_url = request.url
    base_url = request.host_url.rstrip("/")
    week_param = f"?week={week}" if week else ""
    og_image = f"{base_url}/{platform}/{season}/{league_id}/recap/og.png{week_param}"
    og_tags = (
        f"<meta property='og:title' content='{week_label} - {league_name} | BR Fantasy'>"
        f"<meta property='og:description' content='Weekly fantasy football recap: scoreboard, highlights, and AI analysis.'>"
        f"<meta property='og:image' content='{og_image}'>"
        f"<meta property='og:image:width' content='1200'>"
        f"<meta property='og:image:height' content='630'>"
        f"<meta property='og:type' content='website'>"
        f"<meta property='og:url' content='{html.escape(page_url)}'>"
        f"<meta name='twitter:card' content='summary_large_image'>"
        f"<meta name='twitter:title' content='{week_label} - {league_name} | BR Fantasy'>"
        f"<meta name='twitter:description' content='Weekly fantasy football recap: scoreboard, highlights, and AI analysis.'>"
        f"<meta name='twitter:image' content='{og_image}'>"
    )
    return render_page("Weekly Recap", league_id, "recap", body, platform, season, og_tags=og_tags)


@app.route("/<platform>/<int:season>/<league_id>/recap/og.png")
def recap_og_image(platform: str, season: int, league_id: str):
    """Generate a 1200×630 social-share preview image for the weekly recap."""
    import os as _os
    import io as _io
    try:
        from PIL import Image, ImageDraw, ImageFont
    except ImportError:
        return "", 404

    try:
        week = int(request.args.get("week") or 0) or None
    except (ValueError, TypeError):
        week = None

    try:
        ctx = get_league_ctx_from_cache(platform, league_id, season)
    except Exception:
        ctx = {}
    league      = ctx.get("league") or {}
    df_weekly   = ctx.get("df_weekly")
    roster_map  = ctx.get("roster_map") or {}
    users       = ctx.get("users") or []
    settings    = league.get("settings") or {}
    playoff_start = int(settings.get("playoff_week_start") or 14)
    league_name = (league.get("name") or "Fantasy League")[:32]

    # ── Resolve week and pull stats ────────────────────────────────────────
    high_name, high_pts = "–", 0.0
    low_name,  low_pts  = "–", 0.0
    matchups_display    = []

    if df_weekly is not None and not df_weekly.empty and "finalized" in df_weekly.columns:
        fin_df = df_weekly[df_weekly["finalized"] == True].copy()
        if not fin_df.empty:
            available = sorted(fin_df["week"].unique().tolist())
            reg_weeks = [w for w in available if w < playoff_start] or available
            if week is None or week not in available:
                week = reg_weeks[-1]

            week_df = fin_df[fin_df["week"] == week].copy()
            team_by_rid = {str(rid): name for rid, name in roster_map.items()}

            if not week_df.empty:
                high_row = week_df.loc[week_df["points"].idxmax()]
                low_row  = week_df.loc[week_df["points"].idxmin()]
                high_name = team_by_rid.get(str(high_row.get("roster_id", ""))) or str(high_row["owner"])
                high_pts  = float(high_row["points"])
                low_name  = team_by_rid.get(str(low_row.get("roster_id", ""))) or str(low_row["owner"])
                low_pts   = float(low_row["points"])

                for _, grp in week_df.groupby("matchup_id"):
                    if len(grp) != 2:
                        continue
                    grp = grp.sort_values("points", ascending=False)
                    w_row, l_row = grp.iloc[0], grp.iloc[1]
                    w_team = team_by_rid.get(str(w_row.get("roster_id", ""))) or str(w_row["owner"])
                    l_team = team_by_rid.get(str(l_row.get("roster_id", ""))) or str(l_row["owner"])
                    matchups_display.append({
                        "w": w_team, "w_pts": float(w_row["points"]),
                        "l": l_team, "l_pts": float(l_row["points"]),
                        "margin": float(w_row["points"]) - float(l_row["points"]),
                    })
                matchups_display.sort(key=lambda x: -x["margin"])

    week_label = f"Week {week} Recap" if week else "Weekly Recap"

    # ── Fonts ──────────────────────────────────────────────────────────────
    font_dir   = _os.path.join(_os.path.dirname(__file__), "static", "fonts")
    def _font(name, size):
        path = _os.path.join(font_dir, name)
        try:
            return ImageFont.truetype(path, size)
        except Exception:
            return ImageFont.load_default()

    f_huge   = _font("Inter-Bold.ttf",     78)
    f_large  = _font("Inter-Bold.ttf",     38)
    f_med    = _font("Inter-SemiBold.ttf", 28)
    f_small  = _font("Inter-Regular.ttf",  24)
    f_label  = _font("Inter-Regular.ttf",  20)
    f_pill   = _font("Inter-SemiBold.ttf", 20)  # fallback only

    # ── Colors ─────────────────────────────────────────────────────────────
    C_BG      = (2,   6,   23)   # #020617
    C_SURFACE = (15,  23,  42)   # #0f172a
    C_SURFACE2= (17,  27,  50)
    C_ACCENT  = (56,  189, 248)  # #38bdf8
    C_TEXT    = (229, 231, 235)  # #e5e7eb
    C_MUTED   = (148, 163, 184)  # #94a3b8
    C_SUBTLE  = (71,  85,  105)  # #475569
    C_GREEN   = (34,  197, 94)
    C_RED     = (239, 68,  68)
    C_BORDER  = (31,  41,  55)   # #1f2937

    W, H = 1200, 630
    img  = Image.new("RGB", (W, H), color=C_BG)
    draw = ImageDraw.Draw(img)

    # ── Subtle grid lines ──────────────────────────────────────────────────
    for x in range(0, W, 64):
        draw.line([(x, 0), (x, H)], fill=(15, 23, 42), width=1)
    for y in range(0, H, 64):
        draw.line([(0, y), (W, y)], fill=(15, 23, 42), width=1)

    # ── Top accent bar ─────────────────────────────────────────────────────
    draw.rectangle([0, 0, W, 5], fill=C_ACCENT)

    PAD = 72

    # ── Logo ───────────────────────────────────────────────────────────────
    try:
        logo = Image.open(_os.path.join(_os.path.dirname(__file__), "static", "Website_Logo_dark.png")).convert("RGBA")
        logo_h = 90
        logo_w = int(logo.width * logo_h / logo.height)
        logo = logo.resize((logo_w, logo_h), Image.LANCZOS)
        img.paste(logo, (PAD, 38), logo)
    except Exception:
        draw.text((PAD, 58), "BR Fantasy", fill=C_ACCENT, font=f_pill)

    # ── Week headline ──────────────────────────────────────────────────────
    draw.text((PAD, 152), week_label, fill=C_TEXT, font=f_huge)

    # ── League name ────────────────────────────────────────────────────────
    draw.text((PAD, 256), league_name, fill=C_MUTED, font=f_large)

    # ── Accent rule ────────────────────────────────────────────────────────
    draw.rounded_rectangle([PAD, 314, PAD + 64, 318], radius=2, fill=C_ACCENT)

    # ── Stat callouts ──────────────────────────────────────────────────────
    def stat_row(y, label, name, value, color):
        draw.text((PAD, y),       label,    fill=C_SUBTLE, font=f_label)
        draw.text((PAD, y + 24),  name[:22], fill=C_TEXT,   font=f_med)
        bb = draw.textbbox((0, 0), value, font=f_med)
        vw = bb[2] - bb[0]
        draw.text((580 - vw, y + 24), value, fill=color, font=f_med)

    sy = 336
    stat_row(sy,       "HIGH SCORE",   high_name, f"{high_pts:.2f}",  C_GREEN)
    if matchups_display:
        best = matchups_display[0]
        stat_row(sy + 76,  "BIGGEST WIN",  best["w"], f"+{best['margin']:.1f}", C_ACCENT)
    stat_row(sy + 152, "LOW SCORE",    low_name,  f"{low_pts:.2f}",   C_RED)

    # ── Scoreboard card ────────────────────────────────────────────────────
    CX, CY, CW, CH = 680, 56, 456, 510
    draw.rounded_rectangle([CX, CY, CX + CW, CY + CH], radius=16, fill=C_SURFACE)

    # Card header
    draw.text((CX + 24, CY + 20), "Scoreboard", fill=C_TEXT,  font=f_med)
    draw.text((CX + 24, CY + 52), f"Week {week}", fill=C_MUTED, font=f_label)
    draw.rectangle([CX, CY + 80, CX + CW, CY + 81], fill=C_BORDER)

    # Matchup rows (up to 5)
    ry = CY + 94
    row_h = 82
    for i, m in enumerate(matchups_display[:5]):
        if ry + row_h > CY + CH - 10:
            break

        # Winner
        w_name = m["w"][:18]
        l_name = m["l"][:18]
        draw.text((CX + 20, ry),      w_name, fill=C_TEXT,  font=f_small)
        draw.text((CX + 20, ry + 28), l_name, fill=C_MUTED, font=f_small)

        # Scores right-aligned
        w_str = f"{m['w_pts']:.1f}"
        l_str = f"{m['l_pts']:.1f}"
        bb = draw.textbbox((0, 0), w_str, font=f_small)
        sw = bb[2] - bb[0]
        draw.text((CX + CW - 20 - sw, ry),      w_str, fill=C_GREEN,  font=f_small)
        bb = draw.textbbox((0, 0), l_str, font=f_small)
        sw = bb[2] - bb[0]
        draw.text((CX + CW - 20 - sw, ry + 28), l_str, fill=C_MUTED,  font=f_small)

        # Margin badge
        mg_str = f"+{m['margin']:.1f}"
        draw.text((CX + 20, ry + 54), mg_str, fill=C_ACCENT, font=f_label)

        ry += row_h
        if i < len(matchups_display) - 1 and ry < CY + CH - 10:
            draw.rectangle([CX + 16, ry - 4, CX + CW - 16, ry - 3], fill=C_BORDER)

    # ── Bottom bar ─────────────────────────────────────────────────────────
    draw.rectangle([0, H - 50, W, H], fill=C_SURFACE)
    draw.text((PAD, H - 32), "brfantasyfootball.com", fill=C_MUTED, font=f_label)
    _url_bb = draw.textbbox((0, 0), "brfantasyfootball.com", font=f_label)
    draw.text((PAD + (_url_bb[2] - _url_bb[0]) + 12, H - 32),
              "·  AI-powered weekly recap", fill=C_SUBTLE, font=f_label)

    season_str = f"Season {season}"
    bb = draw.textbbox((0, 0), season_str, font=f_label)
    draw.text((W - PAD - (bb[2] - bb[0]), H - 32), season_str, fill=C_MUTED, font=f_label)

    # ── Render to bytes ────────────────────────────────────────────────────
    buf = _io.BytesIO()
    img.save(buf, format="PNG", optimize=True)
    buf.seek(0)
    return buf.read(), 200, {
        "Content-Type": "image/png",
        "Cache-Control": "public, max-age=3600",
        "X-Content-Type-Options": "nosniff",
    }


# ══════════════════════════════════════════════════════════════════════════════
# COMMISSIONER DASHBOARD
# ══════════════════════════════════════════════════════════════════════════════

_COMMISH_HISTORY_CACHE: dict = {}
_COMMISH_HISTORY_TTL = 6 * 3600  # 6h - prior-season activity barely changes


def _commissioner_history_layer(platform, league_id, season, lookback=3):
    """
    Multi-season league context for the commissioner tool, keyed by owner
    user_id (stable across seasons; roster_id is not). Walks previous_league_id
    for up to `lookback` prior seasons and computes, per prior season, each
    owner's move count + inactivity and the league's total moves/trades.

    Sleeper-only (ESPN has no previous_league_id chain). Cached, and any failure
    returns None so the page degrades to the current-season view.
    """
    import time
    platform = (platform or "sleeper").lower()
    if platform != "sleeper" or not league_id:
        return None

    key = f"{platform}:{league_id}:{season}"
    now = time.time()
    cached = _COMMISH_HISTORY_CACHE.get(key)
    if cached and now - cached["ts"] < _COMMISH_HISTORY_TTL:
        return cached["layer"]

    from dashboard_services.api import build_league_history_map, get_league
    from dashboard_services.platform_api import get_rosters, get_users
    from dashboard_services.service import get_transactions_by_week

    layer = None
    try:
        hist = build_league_history_map(platform, league_id, season) or {}
        prior = sorted(s for s in hist if int(s) < int(season))[-lookback:]
        seasons_out = []
        owners: dict = {}
        for ps in prior:
            lid = hist[ps]
            try:
                rosters = get_rosters(platform, lid, ps) or []
                users   = get_users(platform, lid, ps) or []
                league  = get_league(lid) or {}
            except Exception:
                continue
            playoff_start = int((league.get("settings") or {}).get("playoff_week_start") or 14)
            try:
                txw = get_transactions_by_week(lid, range(1, playoff_start), platform=platform, season=ps) or {}
            except Exception:
                txw = {}

            moves_by_rid: dict = {}
            trades = 0
            for _wk, txns in txw.items():
                for tx in (txns or []):
                    rids = {str(r) for r in (tx.get("roster_ids") or [])}
                    rids |= {str(v) for v in (tx.get("adds") or {}).values()}
                    rids |= {str(v) for v in (tx.get("drops") or {}).values()}
                    if tx.get("type") == "trade":
                        trades += 1
                    for rid in rids:
                        moves_by_rid[rid] = moves_by_rid.get(rid, 0) + 1

            name_by_uid = {u.get("user_id"): (u.get("display_name") or u.get("username") or u.get("user_id"))
                           for u in users}
            season_moves = 0
            inactive_owners = 0
            for r in rosters:
                rid = str(r.get("roster_id"))
                uid = r.get("owner_id")
                if not uid:
                    continue
                st = r.get("settings") or {}
                games = int(st.get("wins") or 0) + int(st.get("losses") or 0)
                mv = moves_by_rid.get(rid, 0)
                season_moves += mv
                inactive = mv == 0 and games > 3
                inactive_owners += 1 if inactive else 0
                o = owners.setdefault(uid, {"name": "Unknown", "seasons_present": 0, "inactive_seasons": 0})
                o["name"] = name_by_uid.get(uid, o["name"])
                o["seasons_present"] += 1
                o["inactive_seasons"] += 1 if inactive else 0

            seasons_out.append({"season": int(ps), "trades": trades,
                                "moves": season_moves, "inactive_owners": inactive_owners,
                                "n_teams": len(rosters)})

        if seasons_out:
            layer = {"seasons": seasons_out, "owners": owners}
    except Exception:
        layer = None

    _COMMISH_HISTORY_CACHE[key] = {"ts": now, "layer": layer}
    return layer


def _render_commissioner_history(layer, current_season, current_moves, current_trades, current_inactive_uids, current_week=0, playoff_start=14):
    """Render the multi-season 'Chronic / Trend' panel. Current season is the
    headline (computed elsewhere); this is diagnosis context, not a blended score."""
    seasons = sorted((layer.get("seasons") or []), key=lambda s: s["season"])
    # Separate prior (completed) data from current in-progress season
    prior_moves_series  = [(s["season"], s["moves"])  for s in seasons]
    prior_trades_series = [(s["season"], s["trades"]) for s in seasons]
    # Season is complete when playoffs have started (or it's a prior year entirely)
    season_complete = int(current_week) >= int(playoff_start)
    moves_series  = prior_moves_series  + [(int(current_season), int(current_moves))]
    trades_series = prior_trades_series + [(int(current_season), int(current_trades))]

    def _dir(series):
        # Trend is always computed from completed seasons only - never compare
        # a partial/preseason year against full seasons.
        completed = prior_moves_series if series is moves_series else prior_trades_series
        vals = [v for _, v in completed]
        if len(vals) < 2:
            return ("→", "var(--muted)", "flat")
        delta = vals[-1] - vals[0]
        thresh = max(2.0, 0.10 * abs(vals[0] or 1))
        if delta > thresh:
            return ("▲", "#22c55e", "up")
        if delta < -thresh:
            return ("▼", "#ef4444", "down")
        return ("→", "var(--muted)", "flat")

    def _series_html(series):
        parts = []
        last_idx = len(series) - 1
        for i, (yr, val) in enumerate(series):
            is_last = i == last_idx
            if is_last and not season_complete:
                # Current season still in progress - muted style with dashed border
                chip_bg = "var(--row,rgba(127,127,127,.08))"
                chip_fg = "var(--muted)"
                chip_border = "var(--muted)"
                border_style = "dashed"
                yr_label = f"{yr} ↻"
            elif is_last:
                chip_bg = "var(--accent,#3b82f6)"
                chip_fg = "#fff"
                chip_border = "transparent"
                border_style = "solid"
                yr_label = str(yr)
            else:
                chip_bg = "var(--row,rgba(127,127,127,.08))"
                chip_fg = "var(--text)"
                chip_border = "var(--border)"
                border_style = "solid"
                yr_label = str(yr)
            parts.append(
                f"<span class='msh-chip' style='background:{chip_bg};color:{chip_fg};"
                f"border-color:{chip_border};border-style:{border_style};'>"
                f"<span class='msh-chip-yr'>{yr_label}</span>"
                f"<span class='msh-chip-val'>{val}</span></span>"
            )
        connector = "<span class='msh-arrow'>›</span>"
        return connector.join(parts)

    m_arrow, m_color, m_dir = _dir(moves_series)
    t_arrow, t_color, t_dir = _dir(trades_series)

    def _trend_badge(arrow, color, direction):
        label = {"up": "Rising", "down": "Falling", "flat": "Steady"}[direction]
        return (
            f"<span class='msh-trend' style='color:{color};background:{color}1a;'>"
            f"{arrow} {label}</span>"
        )

    owners = layer.get("owners") or {}
    chronic = []
    for uid, o in owners.items():
        windows = o["seasons_present"] + 1  # + current
        inact = o["inactive_seasons"] + (1 if uid in current_inactive_uids else 0)
        if inact >= 2:
            chronic.append((o["name"], inact, windows))
    chronic.sort(key=lambda x: -x[1])

    chronic_rows = "".join(
        f"<div class='msh-chronic-row'>"
        f"<span class='msh-chronic-name'>{name}</span>"
        f"<span class='msh-chronic-flag'>inactive {inact} of last {windows}</span></div>"
        for name, inact, windows in chronic
    ) or (
        "<div class='msh-chronic-ok'>"
        "<span class='msh-chronic-ok-icon'>✓</span>"
        "No chronic inactivity - owners stay engaged across seasons.</div>"
    )

    n_prior = len(seasons)
    return f"""
<style>
  .msh-card {{ padding:20px; margin-bottom:20px; }}
  .msh-head {{ display:flex; align-items:baseline; gap:8px; margin-bottom:18px; }}
  .msh-head-title {{ font-size:12px; font-weight:800; letter-spacing:.06em; color:var(--text); text-transform:uppercase; }}
  .msh-head-sub {{ font-size:12px; color:var(--muted); }}
  .msh-grid {{ display:grid; grid-template-columns:repeat(auto-fit,minmax(260px,1fr)); gap:14px; margin-bottom:18px; }}
  .msh-stat {{ border:1px solid var(--border); border-radius:14px; padding:14px 16px; background:var(--row,rgba(127,127,127,.03)); }}
  .msh-stat-head {{ display:flex; align-items:center; justify-content:space-between; margin-bottom:12px; }}
  .msh-stat-label {{ font-size:11px; font-weight:700; letter-spacing:.04em; color:var(--muted); text-transform:uppercase; }}
  .msh-trend {{ font-size:11px; font-weight:700; padding:3px 9px; border-radius:999px; white-space:nowrap; }}
  .msh-series {{ display:flex; align-items:center; flex-wrap:wrap; gap:2px; }}
  .msh-chip {{ display:inline-flex; flex-direction:column; align-items:center; gap:1px; padding:5px 11px; border-radius:10px; border:1px solid; line-height:1.1; }}
  .msh-chip-yr {{ font-size:10px; font-weight:600; opacity:.75; }}
  .msh-chip-val {{ font-size:15px; font-weight:800; }}
  .msh-arrow {{ color:var(--muted); font-size:16px; font-weight:700; padding:0 2px; opacity:.5; }}
  .msh-chronic-label {{ font-size:11px; font-weight:700; letter-spacing:.04em; color:var(--muted); text-transform:uppercase; margin-bottom:8px; }}
  .msh-chronic-row {{ display:flex; align-items:center; justify-content:space-between; padding:9px 12px; border-radius:10px; background:rgba(239,68,68,.06); border:1px solid rgba(239,68,68,.18); margin-bottom:6px; font-size:13px; }}
  .msh-chronic-name {{ font-weight:600; color:var(--text); }}
  .msh-chronic-flag {{ color:#ef4444; font-weight:700; font-size:12px; }}
  .msh-chronic-ok {{ display:flex; align-items:center; gap:8px; padding:11px 14px; border-radius:10px; background:rgba(34,197,94,.07); border:1px solid rgba(34,197,94,.2); color:var(--text); font-size:13px; }}
  .msh-chronic-ok-icon {{ display:inline-flex; align-items:center; justify-content:center; width:18px; height:18px; border-radius:50%; background:#22c55e; color:#fff; font-size:11px; font-weight:800; flex-shrink:0; }}
</style>
<div class="card msh-card">
  <div class="msh-head">
    <span class="msh-head-title">Multi-Season Health</span>
    <span class="msh-head-sub">last {n_prior} prior season{'s' if n_prior != 1 else ''}</span>
  </div>
  <div class="msh-grid">
    <div class="msh-stat">
      <div class="msh-stat-head">
        <span class="msh-stat-label">Total Moves / Season</span>
        {_trend_badge(m_arrow, m_color, m_dir)}
      </div>
      <div class="msh-series">{_series_html(moves_series)}</div>
    </div>
    <div class="msh-stat">
      <div class="msh-stat-head">
        <span class="msh-stat-label">Trades / Season</span>
        {_trend_badge(t_arrow, t_color, t_dir)}
      </div>
      <div class="msh-series">{_series_html(trades_series)}</div>
    </div>
  </div>
  <div class="msh-chronic-label">Chronic Inactivity</div>
  {chronic_rows}
</div>"""


def build_commissioner_body(ctx):
    from dashboard_services.service import get_transactions_by_week

    platform   = ctx.get("platform") or "sleeper"
    season     = ctx.get("season") or datetime.now().year
    league_id  = ctx.get("league_id") or ""
    rosters    = ctx.get("rosters") or []
    users      = ctx.get("users") or []
    roster_map = ctx.get("roster_map") or {}
    traded     = ctx.get("traded") or []
    # current_week is on ctx directly; ctx has no "state" key (see build_optimal_body).
    current_week = int(ctx.get("current_week") or 0)
    settings   = (ctx.get("league") or {}).get("settings") or {}
    playoff_start = int(settings.get("playoff_week_start") or 14)
    model_vals  = ctx.get("model_value_table") or get_model_value_table_cached() or []
    is_sf = any(str(s).upper() in {"SUPER_FLEX", "SFLEX"} for s in (ctx.get("roster_positions") or []))
    val_key = "sf_value" if is_sf else "value"
    val_by_pid = {str(p.get("id") or ""): float(p.get(val_key) or p.get("value") or 0)
                  for p in model_vals if p.get("id")}

    owner_by_rid = {}
    for u in users:
        uid = u.get("user_id")
        name = u.get("display_name") or u.get("username") or uid
        for r in rosters:
            if r.get("owner_id") == uid:
                owner_by_rid[str(r.get("roster_id"))] = name

    # ── 1. Fetch full-season transactions for real activity data ──────────
    reg_season_weeks = min(current_week or playoff_start - 1, playoff_start - 1)
    tx_by_week: dict = {}
    try:
        tx_by_week = get_transactions_by_week(
            league_id, range(1, max(reg_season_weeks + 1, 2)), platform=platform, season=season
        ) or {}
    except Exception:
        logger.debug("suppressed exception", exc_info=True)

    # Per-roster move counts from actual transactions (not roster snapshot)
    txn_by_rid: dict = {}
    trade_count_by_rid: dict = {}
    for wk, txns in tx_by_week.items():
        for tx in (txns or []):
            rids = {str(r) for r in (tx.get("roster_ids") or [])}
            rids |= {str(v) for v in (tx.get("adds") or {}).values()}
            rids |= {str(v) for v in (tx.get("drops") or {}).values()}
            for rid in rids:
                if tx.get("type") == "trade":
                    trade_count_by_rid[rid] = trade_count_by_rid.get(rid, 0) + 1
                else:
                    txn_by_rid[rid] = txn_by_rid.get(rid, 0) + 1

    # ── 2. Roster values & activity ───────────────────────────────────────
    roster_infos = []
    for r in rosters:
        rid   = str(r.get("roster_id"))
        pids  = [str(p) for p in (r.get("players") or [])]
        val   = sum(val_by_pid.get(pid, 0) for pid in pids)
        r_st  = r.get("settings") or {}
        wins  = r_st.get("wins", 0)
        losses = r_st.get("losses", 0)
        # Prefer transaction-API counts; fall back to roster snapshot
        txns  = txn_by_rid.get(rid) or int(r_st.get("total_moves") or 0)
        trades = trade_count_by_rid.get(rid, 0)
        games_played = wins + losses
        inactive = txns == 0 and games_played > 3
        roster_infos.append({
            "rid": rid, "name": roster_map.get(rid, f"Team {rid}"),
            "owner": owner_by_rid.get(rid, "Unknown"),
            "wins": wins, "losses": losses,
            "value": round(val, 0), "txns": txns, "trades": trades,
            "inactive": inactive,
        })

    # Value share % relative to league total (matches teams page display)
    league_val_total = sum(r["value"] for r in roster_infos) or 1.0
    fair_share = 100.0 / max(len(roster_infos), 1)
    for r in roster_infos:
        r["value_pct"] = round(r["value"] / league_val_total * 100, 1)
    roster_infos.sort(key=lambda x: -x["value_pct"])

    def _val_bar(pct: float) -> str:
        width = min(pct / (fair_share * 2) * 100, 100)
        color = "var(--accent)" if pct >= fair_share else "var(--text-muted)"
        return (f'<div style="height:6px;border-radius:3px;background:var(--border);width:100%;min-width:60px;">'
                f'<div style="height:6px;border-radius:3px;background:{color};width:{width:.1f}%"></div></div>')

    # ── 3. Trade fairness ─────────────────────────────────────────────────
    # Use the same pick value table and logic as the activity page.
    # In Sleeper draft_picks: owner_id = receiver, previous_owner_id = sender,
    # roster_id = original pick owner (not always the sender).
    _pick_tbl = load_pick_value_table() or {}
    _standings_map = ctx.get("standings_map") or {}
    _num_teams = len(rosters) or 10

    def _pick_val_comm(pick: dict) -> float:
        year = int(pick.get("season") or 0)
        rnd  = int(pick.get("round") or 0)
        if not year or not rnd:
            return 0.0
        exact_slot = resolve_exact_pick_slot(
            platform=platform, root_league_id=league_id,
            current_season=season, pick=pick,
        )
        if exact_slot is not None:
            k = f"{year}_{rnd}_{exact_slot:02d}"
            if k in _pick_tbl:
                return float(_pick_tbl[k])
        prev = pick.get("previous_owner_id")
        seed = None
        try:
            if prev is not None:
                seed = _standings_map.get(int(prev))
        except Exception:
            logger.debug("suppressed exception", exc_info=True)
        if seed is not None:
            if 1 <= seed <= 3:
                bucket = "early"
            elif seed <= 7:
                bucket = "mid"
            else:
                bucket = "late"
            k = f"{year}_{rnd}_{bucket}"
            if k in _pick_tbl:
                return float(_pick_tbl[k])
        for b in ("mid", "early", "late"):
            k = f"{year}_{rnd}_{b}"
            if k in _pick_tbl:
                return float(_pick_tbl[k])
        k = f"{year}_{rnd}"
        return float(_pick_tbl[k]) if k in _pick_tbl else 0.0

    trade_txns = [tx for txns in tx_by_week.values() for tx in (txns or [])
                  if tx.get("type") == "trade"]
    trade_rows = []
    seen_txn_ids: set = set()
    for tx in trade_txns:
        tx_id = tx.get("transaction_id") or tx.get("id")
        if tx_id:
            if tx_id in seen_txn_ids:
                continue
            seen_txn_ids.add(tx_id)
        adds = tx.get("adds") or {}
        draft_picks = tx.get("draft_picks") or []
        # involved = teams who sent or received something (not the original pick owner)
        involved = {str(rid) for rid in adds.values()}
        for pick in draft_picks:
            for key in ("owner_id", "previous_owner_id"):
                v = str(pick.get(key) or "")
                if v and v != "0":
                    involved.add(v)
        if len(involved) < 2:
            continue
        # Value received by each team: player adds + picks (owner_id = receiver)
        received: dict = {rid: 0.0 for rid in involved}
        for pid, rid in adds.items():
            received[str(rid)] = received.get(str(rid), 0) + val_by_pid.get(str(pid), 0)
        for pick in draft_picks:
            rid = str(pick.get("owner_id") or "")
            if rid and rid in received:
                received[rid] = received.get(rid, 0) + _pick_val_comm(pick)
        vals = sorted(received.items(), key=lambda x: -x[1])
        if len(vals) >= 2:
            (r1, v1), (r2, v2) = vals[0], vals[1]
            diff = abs(v1 - v2)
            trade_rows.append({
                "team_a": roster_map.get(r1, f"Team {r1}"),
                "team_b": roster_map.get(r2, f"Team {r2}"),
                "val_a": round(v1, 0), "val_b": round(v2, 0),
                "diff": round(diff, 0), "lopsided": diff > 75,
            })
    trade_rows.sort(key=lambda x: -x["diff"])

    # ── 4. League health (based on full season activity) ──────────────────
    n = len(roster_infos) or 1
    inactive_count = sum(1 for r in roster_infos if r["inactive"])
    lopsided_count = sum(1 for t in trade_rows if t["lopsided"])
    total_txns     = sum(r["txns"] for r in roster_infos)
    total_trades   = sum(r["trades"] for r in roster_infos) // 2  # each trade counted per team
    avg_txns = total_txns / n

    # Score: penalise inactive teams, lopsided trades; reward activity
    activity_score = 100
    activity_score -= inactive_count / n * 40
    activity_score -= lopsided_count * 4
    activity_score -= max(0, 5 - avg_txns) * 5  # penalise low avg moves
    activity_score  = round(max(0, min(100, activity_score)), 0)
    score_color = "#22c55e" if activity_score >= 80 else ("#f59e0b" if activity_score >= 60 else "#ef4444")
    score_label = "Healthy" if activity_score >= 80 else ("Watch" if activity_score >= 60 else "At Risk")

    # Composite card matching the Multi-Season Health treatment below: one card
    # with a bold uppercase header + muted subtitle and the stats as nested,
    # bordered/rounded tiles, instead of five separate floating cards.
    health_html = f"""
<style>
  .lh-card {{ padding:20px; margin-bottom:20px; }}
  .lh-head {{ display:flex; align-items:baseline; gap:8px; margin-bottom:18px; }}
  .lh-head-title {{ font-size:12px; font-weight:800; letter-spacing:.06em; color:var(--text); text-transform:uppercase; }}
  .lh-head-sub {{ font-size:12px; color:var(--muted); }}
  .lh-grid {{ display:grid; grid-template-columns:repeat(auto-fit,minmax(150px,1fr)); gap:14px; }}
  .lh-stat {{ border:1px solid var(--border); border-radius:14px; padding:16px; background:var(--row,rgba(127,127,127,.03)); text-align:center; }}
  .lh-stat-num {{ font-size:28px; font-weight:800; line-height:1; }}
  .lh-stat-label {{ font-size:11px; font-weight:700; letter-spacing:.04em; color:var(--muted); text-transform:uppercase; margin-top:6px; }}
  .lh-stat-sub {{ font-size:13px; font-weight:600; margin-top:3px; }}
</style>
<div class="card lh-card">
  <div class="lh-head">
    <span class="lh-head-title">League Health</span>
    <span class="lh-head-sub">this season</span>
  </div>
  <div class="lh-grid">
    <div class="lh-stat">
      <div class="lh-stat-num" style="color:{score_color};">{int(activity_score)}</div>
      <div class="lh-stat-label">Health Score</div>
      <div class="lh-stat-sub" style="color:{score_color};">{score_label}</div>
    </div>
    <div class="lh-stat">
      <div class="lh-stat-num" style="color:{'#ef4444' if inactive_count else '#22c55e'};">{inactive_count}</div>
      <div class="lh-stat-label">Inactive Teams</div>
    </div>
    <div class="lh-stat">
      <div class="lh-stat-num" style="color:var(--text);">{total_trades}</div>
      <div class="lh-stat-label">Trades This Season</div>
    </div>
    <div class="lh-stat">
      <div class="lh-stat-num" style="color:{'#f59e0b' if lopsided_count else '#22c55e'};">{lopsided_count}</div>
      <div class="lh-stat-label">Lopsided Trades</div>
    </div>
    <div class="lh-stat">
      <div class="lh-stat-num" style="color:var(--text);">{total_txns}</div>
      <div class="lh-stat-label">Total Moves</div>
    </div>
  </div>
</div>"""

    # ── Roster table with value bar ───────────────────────────────────────
    roster_rows = ""
    for r in roster_infos:
        inactive_badge = (" <span style='background:#ef444420;color:#ef4444;font-size:10px;"
                          "padding:2px 5px;border-radius:4px;'>INACTIVE</span>") if r["inactive"] else ""
        roster_rows += f"""
<tr style="border-bottom:1px solid var(--border);">
  <td style="padding:10px 14px;">
    <div style="font-weight:600;">{html.escape(r['name'])}{inactive_badge}</div>
    <div style="font-size:11px;color:var(--muted);">{html.escape(r['owner'])}</div>
  </td>
  <td style="padding:10px 14px;text-align:center;">{r['wins']}-{r['losses']}</td>
  <td style="padding:10px 14px;min-width:140px;">
    <div style="display:flex;align-items:center;gap:8px;">
      {_val_bar(r['value_pct'])}
      <span style="font-size:12px;font-weight:700;min-width:38px;text-align:right;">{r['value_pct']:.1f}%</span>
    </div>
  </td>
  <td style="padding:10px;text-align:center;">{r['txns']}</td>
  <td style="padding:10px;text-align:center;">{r['trades']}</td>
</tr>"""

    roster_table = f"""
<div class="card" style="overflow:auto;margin-bottom:20px;">
  <div class="card-header"><h3>Team Overview</h3></div>
  <table style="width:100%;border-collapse:collapse;">
    <thead><tr style="border-bottom:2px solid var(--border);">
      <th style="padding:10px 14px;text-align:left;font-size:12px;color:var(--muted);">TEAM</th>
      <th style="padding:10px;text-align:center;font-size:12px;color:var(--muted);">RECORD</th>
      <th style="padding:10px 14px;text-align:left;font-size:12px;color:var(--muted);">ROSTER VALUE SHARE</th>
      <th style="padding:10px;text-align:center;font-size:12px;color:var(--muted);">MOVES</th>
      <th style="padding:10px;text-align:center;font-size:12px;color:var(--muted);">TRADES</th>
    </tr></thead>
    <tbody>{roster_rows}</tbody>
  </table>
</div>"""

    # ── Trade fairness ────────────────────────────────────────────────────
    if trade_rows:
        trade_items = ""
        for t in trade_rows[:25]:
            diff_color = "#ef4444" if t["lopsided"] else ("#f59e0b" if t["diff"] > 40 else "#22c55e")
            diff_label = "LOPSIDED" if t["lopsided"] else ("UNEVEN" if t["diff"] > 40 else "FAIR")
            max_val = max(t["val_a"], t["val_b"], 1)
            pct_a = t["val_a"] / max_val * 100
            pct_b = t["val_b"] / max_val * 100
            trade_items += f"""
<div style="display:flex;align-items:center;gap:12px;padding:14px 16px;border-bottom:1px solid var(--border);border-left:3px solid {diff_color};">
  <div style="flex:1;min-width:0;">
    <div style="font-size:10px;color:var(--muted);font-weight:600;letter-spacing:.04em;margin-bottom:3px;">SIDE A</div>
    <div style="font-weight:700;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">{html.escape(t['team_a'])}</div>
    <div style="font-size:22px;font-weight:800;color:var(--text);line-height:1.15;margin:2px 0;">{int(t['val_a']):,}</div>
    <div style="height:3px;background:var(--border);border-radius:2px;overflow:hidden;">
      <div style="height:3px;background:var(--accent);border-radius:2px;width:{pct_a:.0f}%;"></div>
    </div>
  </div>
  <div style="text-align:center;flex-shrink:0;">
    <div style="font-size:15px;color:var(--muted);margin-bottom:5px;">&#8644;</div>
    <div style="background:{diff_color}22;color:{diff_color};font-size:12px;font-weight:700;padding:3px 10px;border-radius:10px;white-space:nowrap;">&#177;{int(t['diff']):,}</div>
    <div style="font-size:9px;color:{diff_color};margin-top:3px;font-weight:700;letter-spacing:.06em;">{diff_label}</div>
  </div>
  <div style="flex:1;min-width:0;text-align:right;">
    <div style="font-size:10px;color:var(--muted);font-weight:600;letter-spacing:.04em;margin-bottom:3px;">SIDE B</div>
    <div style="font-weight:700;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">{html.escape(t['team_b'])}</div>
    <div style="font-size:22px;font-weight:800;color:var(--text);line-height:1.15;margin:2px 0;">{int(t['val_b']):,}</div>
    <div style="height:3px;background:var(--border);border-radius:2px;overflow:hidden;display:flex;justify-content:flex-end;">
      <div style="height:3px;background:var(--accent);border-radius:2px;width:{pct_b:.0f}%;"></div>
    </div>
  </div>
</div>"""
        trade_card = f"""
<div class="card" style="overflow:hidden;">
  <div class="card-header">
    <h3>Trade Fairness Log</h3>
    <span style="font-size:12px;color:var(--muted);">Received value per side &middot; &#177;75 = lopsided</span>
  </div>
  {trade_items}
</div>"""
    else:
        trade_card = ("<div class='card'><div class='card-body' style='padding:20px;color:var(--muted);'>"
                      "No trades recorded yet.</div></div>")

    # ── 5. Multi-season layer (chronic inactivity + engagement trend) ─────
    # Current season stays the headline; history is diagnosis, not a blend.
    history_panel = ""
    try:
        layer = _commissioner_history_layer(platform, league_id, season)
        if layer:
            rid_to_uid = {str(r.get("roster_id")): r.get("owner_id") for r in rosters}
            inactive_uids_now = {
                rid_to_uid.get(r["rid"]) for r in roster_infos
                if r["inactive"] and rid_to_uid.get(r["rid"])
            }
            history_panel = _render_commissioner_history(
                layer, current_season=season,
                current_moves=total_txns, current_trades=total_trades,
                current_inactive_uids=inactive_uids_now,
                current_week=current_week, playoff_start=playoff_start,
            )
    except Exception:
        history_panel = ""

    return health_html + history_panel + roster_table + trade_card


