# /api/advanced-metrics/seasons extracted to routes/misc_api_bp.py


@app.route("/api/advanced-metrics/config")
def api_advanced_metrics_config():
    """Return a lightweight version of LEADERBOARD_METRICS for frontend rendering.

    Strips large internal-only keys (min_vol, computed_sql, computed_null, etc.)
    and returns only what the frontend needs: label, category, positions,
    lower_better, pct, pct_frac, efficiency, integer, weeklyCapable.
    Cached with a long TTL since the config only changes with deploys.
    """
    from data_building.advanced_metrics import LEADERBOARD_METRICS, ADV_WEEKLY_METRIC_KEYS
    from data_building.advanced_metrics import _WEEKLY_METRICS  # noqa: F401 — weekly_capable check
    weekly_keys = {*_WEEKLY_METRICS.keys(), *ADV_WEEKLY_METRIC_KEYS}
    out = {}
    for key, spec in LEADERBOARD_METRICS.items():
        if spec.get("hidden"):
            continue
        out[key] = {
            "label":       spec.get("label", key),
            "category":    spec.get("category", ""),
            "positions":   spec.get("positions", []),
            "lower_better": bool(spec.get("lower_better")),
            "pct":         bool(spec.get("pct")),
            "pct_frac":    bool(spec.get("pct_frac")),
            "efficiency":  bool(spec.get("efficiency")),
            "integer":     bool(spec.get("integer")),
            "weeklyCapable": key in weekly_keys,
            "desc":        spec.get("desc", ""),
        }
    resp = jsonify({"metrics": out})
    resp.headers["Cache-Control"] = "public, max-age=3600"
    return resp


def _displayed_value_map(league_type: str) -> dict:
    """player_id -> the value shown everywhere else on the site.

    get_model_value_table_cached() is the single source the app renders from:
    it applies market calibration AND zeroes players not tracked by
    FantasyCalc/DynastyProcess (washed-up vets). Passing this into get_top_movers
    keeps the movers board consistent with those displayed values, so a player
    whose raw model-history value is briefly inflated (while an anchor correction
    unwinds) but who reads as ~0 everywhere else never surfaces as a mover.
    """
    use_sf = str(league_type).strip().lower() == "sf"
    out: dict = {}
    try:
        for p in (get_model_value_table_cached() or []):
            pid = str(p.get("id") or "")
            if not pid:
                continue
            v = p.get("sf_value") if use_sf else p.get("value")
            try:
                out[pid] = float(v or 0)
            except (TypeError, ValueError):
                out[pid] = 0.0
    except Exception:
        logger.debug("[movers] displayed-value map failed", exc_info=True)
    return out


@app.route("/api/value-movers")
def api_value_movers():
    try:
        days = int(request.args.get("days", 7))
    except (TypeError, ValueError):
        days = 7

    try:
        limit = int(request.args.get("limit", 5))
    except (TypeError, ValueError):
        limit = 5

    league_type = str(request.args.get("league_type", "1qb")).strip().lower()

    try:
        league_size = int(request.args.get("league_size", 10))
        # Validate league size is one of the supported sizes
        if league_size not in [8, 10, 12, 14]:
            league_size = 10
    except (TypeError, ValueError):
        league_size = 10

    payload = get_top_movers(days=max(days, 1), limit=max(limit, 1), league_type=league_type,
                             league_size=league_size, min_baseline_value=10,
                             min_current_value=20.0,
                             current_values=_displayed_value_map(league_type)) or {}

    if isinstance(payload, list):
        movers = payload
        risers = [m for m in movers if float(m.get("delta") or 0) > 0]
        fallers = [m for m in movers if float(m.get("delta") or 0) < 0]

        risers.sort(key=lambda x: float(x.get("delta") or 0), reverse=True)
        fallers.sort(key=lambda x: float(x.get("delta") or 0))

        payload = {
            "used_days": days,
            "risers": risers[:limit],
            "fallers": fallers[:limit],
        }
    else:
        payload = {
            "used_days": payload.get("used_days", days),
            "risers": payload.get("risers", [])[:limit],
            "fallers": payload.get("fallers", [])[:limit],
        }

    return jsonify(payload)


@app.route("/api/player-deltas")
def api_player_deltas():
    """
    Return recent 7-day deltas for all players in a compact format.
    Used for showing delta badges in the trade calculator.
    """
    try:
        days = int(request.args.get("days", 7))
    except (TypeError, ValueError):
        days = 7

    league_type = str(request.args.get("league_type", "1qb")).strip().lower()

    try:
        league_size = int(request.args.get("league_size", 10))
        if league_size not in [8, 10, 12, 14]:
            league_size = 10
    except (TypeError, ValueError):
        league_size = 10

    # Get top movers data which includes deltas
    movers_data = get_top_movers(days=days, limit=1000, league_type=league_type, league_size=league_size) or {}

    # Build a simple player_id -> delta map
    deltas = {}
    for player in movers_data.get("risers", []) + movers_data.get("fallers", []):
        pid = str(player.get("player_id", ""))
        delta = player.get("delta")
        if pid and delta is not None:
            deltas[pid] = float(delta)

    return jsonify(deltas)


# A 7-day dynasty-value swing at or beyond this (in value points) is worth
# surfacing as a watchlist alert. Tunable in one place.
WATCHLIST_VALUE_ALERT_THRESHOLD = 150.0


@app.route("/api/watchlist-alerts")
def api_watchlist_alerts():
    """Alert data for a set of watched player ids (client passes ?ids=a,b,c).

    Returns {player_id: {name, position, team, value, delta7, injury, alert}}
    where ``alert`` is True when the player moved at least
    WATCHLIST_VALUE_ALERT_THRESHOLD in value over the last 7 days or carries a
    real injury designation. Player attributes are global (the watchlist itself
    is device-local), so no league context is required."""
    ids_raw = str(request.args.get("ids", ""))
    ids = [s.strip() for s in ids_raw.split(",") if s.strip()][:80]
    if not ids:
        return jsonify({})

    league_type = str(request.args.get("league_type", "1qb")).strip().lower()
    is_sf = league_type == "sf"
    try:
        league_size = int(request.args.get("league_size", 10))
        if league_size not in (8, 10, 12, 14):
            league_size = 10
    except (TypeError, ValueError):
        league_size = 10

    # One (cached) movers board gives 7-day deltas for essentially every player.
    delta_map: dict = {}
    try:
        movers = get_top_movers(days=7, limit=2000, league_type=league_type, league_size=league_size) or {}
        for p in (movers.get("risers", []) + movers.get("fallers", [])):
            pid = str(p.get("player_id", ""))
            d = p.get("delta")
            if pid and d is not None:
                delta_map[pid] = float(d)
    except Exception:
        logger.debug("watchlist-alerts movers lookup failed", exc_info=True)

    vmap = {str(p.get("id")): p for p in (get_model_value_table_cached() or []) if p.get("id")}
    pidx = get_players_index_global() or {}

    def _name(meta):
        n = meta.get("full_name") or meta.get("name")
        if not n:
            fn, ln = meta.get("first_name") or "", meta.get("last_name") or ""
            n = (fn + " " + ln).strip()
        return n or ""

    out: dict = {}
    for pid in ids:
        meta = pidx.get(pid) or {}
        vrow = vmap.get(pid) or {}
        value = vrow.get("sf_value") if (is_sf and vrow.get("sf_value") is not None) else vrow.get("value")
        try:
            value = round(float(value or 0), 1)
        except (TypeError, ValueError):
            value = 0.0
        delta = delta_map.get(pid)
        delta7 = round(delta, 1) if delta is not None else None
        injury = str(meta.get("injury_status") or "").strip()
        injury_active = bool(injury) and injury.upper() not in ("ACTIVE", "HEALTHY", "NA")
        value_alert = delta is not None and abs(delta) >= WATCHLIST_VALUE_ALERT_THRESHOLD
        # Compute a precise decimal age from the birthday (the players index
        # reliably carries bDay everywhere). The value table's age column is a
        # whole-number age in production, so fall back to it only if there's no
        # birthday. Mirrors the age_from_bday pattern used across the app.
        _age = age_from_bday(meta.get("bDay"))
        if _age is None:
            _age_src = vrow.get("age")
            if _age_src in (None, ""):
                _age_src = meta.get("age")
            try:
                _age = float(_age_src) if _age_src not in (None, "") else None
            except (TypeError, ValueError):
                _age = None
        out[pid] = {
            "name": _name(meta),
            "position": meta.get("position") or meta.get("pos") or "",
            "team": meta.get("team") or "",
            "age": _age,
            "value": value,
            "delta7": delta7,
            "injury": injury if injury_active else "",
            "alert": bool(value_alert or injury_active),
        }
    return jsonify(out)


@app.route("/api/since-last-visit")
def api_since_last_visit():
    """Powers the dashboard "Since your last visit" digest. Returns:

      - trades/waivers/items: league activity newer than the client's ``since``
        timestamp (ms); only computed when a real last-visit baseline exists.
      - roster: a snapshot of the viewer's roster (value + injury per player)
        so the client can diff it against its own stored snapshot to surface
        value moves and new injuries since the last visit.

    The last-visit time and the roster snapshot are both tracked client-side in
    localStorage, keeping this a true per-visit diff rather than a rolling feed."""
    result = {"trades": 0, "waivers": 0, "items": [], "latest_ts": 0, "roster": []}
    platform = request.args.get("platform", "sleeper")
    league_id = request.args.get("league_id")
    if not league_id:
        return jsonify(result)
    try:
        season = int(request.args.get("season") or datetime.now().year)
    except (TypeError, ValueError):
        season = datetime.now().year
    try:
        since_ms = int(request.args.get("since") or 0)
    except (TypeError, ValueError):
        since_ms = 0
    roster_id = str(request.args.get("roster_id") or "").strip()
    is_sf = str(request.args.get("league_type", "1qb")).strip().lower() == "sf"

    try:
        ctx = get_league_ctx_from_cache(platform, league_id, season)
    except Exception:
        logger.debug("since-last-visit ctx failed", exc_info=True)
        return jsonify(result)

    # Trades + waiver adds newer than the last visit (needs a real baseline).
    if since_ms > 0:
        try:
            adf = ctx.get("activity_df")
            if adf is not None and not adf.empty and "ts" in adf.columns:
                rows = adf[adf["ts"].notna()].copy()
                if not rows.empty:
                    def _ms(ts):
                        try:
                            return int(ts.timestamp() * 1000)
                        except Exception:
                            return 0

                    rows["ts_ms"] = rows["ts"].map(_ms)
                    rows = rows[rows["ts_ms"] > since_ms]
                    if not rows.empty:
                        rows = rows.sort_values("ts_ms", ascending=False)
                        result["trades"] = int((rows["kind"] == "trade").sum())
                        result["waivers"] = int((rows["kind"] == "waiver").sum())
                        result["latest_ts"] = int(rows["ts_ms"].iloc[0])
                        for _, r in rows.head(8).iterrows():
                            data = r["data"] or {}
                            if r["kind"] == "trade":
                                names = [str(t.get("name") or "?") for t in (data.get("teams") or [])]
                                text = "Trade: " + " and ".join(names[:2]) + (" +more" if len(names) > 2 else "")
                            else:
                                nm = str(data.get("name") or "?")
                                adds = data.get("adds") or []
                                who = ", ".join(str(p.get("name") or "?") for p in adds[:2])
                                if len(adds) > 2:
                                    who += f" +{len(adds) - 2}"
                                text = f"{nm} added {who}" if who else f"{nm} made a move"
                            result["items"].append(
                                {"kind": r["kind"], "text": text, "ts": int(r["ts_ms"]), "week": int(r["week"])}
                            )
        except Exception:
            logger.debug("since-last-visit activity failed", exc_info=True)

    # Viewer roster snapshot (value + injury) for the client to diff.
    if roster_id:
        try:
            roster = next(
                (r for r in (ctx.get("rosters") or []) if str(r.get("roster_id")) == roster_id),
                None,
            )
            if roster:
                vmap = {str(p.get("id")): p for p in (get_model_value_table_cached() or []) if p.get("id")}
                pidx = get_players_index_global() or {}
                snap = []
                for pid in (roster.get("players") or []):
                    spid = str(pid)
                    meta = pidx.get(spid) or {}
                    vrow = vmap.get(spid) or {}
                    value = vrow.get("sf_value") if (is_sf and vrow.get("sf_value") is not None) else vrow.get("value")
                    try:
                        value = round(float(value or 0), 1)
                    except (TypeError, ValueError):
                        value = 0.0
                    name = meta.get("full_name") or meta.get("name") or (
                        (str(meta.get("first_name") or "") + " " + str(meta.get("last_name") or "")).strip()
                    )
                    injury = str(meta.get("injury_status") or "").strip()
                    inj_active = bool(injury) and injury.upper() not in ("ACTIVE", "HEALTHY", "NA")
                    snap.append({
                        "pid": spid,
                        "name": name or spid,
                        "pos": meta.get("position") or meta.get("pos") or "",
                        "value": value,
                        "injury": injury if inj_active else "",
                    })
                result["roster"] = snap
        except Exception:
            logger.debug("since-last-visit roster snapshot failed", exc_info=True)

    return jsonify(result)


@app.route("/api/player-indicators")
def api_player_indicators():
    """
    Return rookie and breakout indicators for players.
    Returns: {
      "rookies": ["player_id1", "player_id2", ...],
      "breakouts": ["player_id3", "player_id4", ...]
    }
    """
    try:
        from datetime import datetime

        league_type = str(request.args.get("league_type", "1qb")).strip().lower()

        try:
            league_size = int(request.args.get("league_size", 10))
            if league_size not in [8, 10, 12, 14]:
                league_size = 10
        except (TypeError, ValueError):
            league_size = 10

        # Get current NFL state
        nfl_state = get_nfl_state() or {}
        current_season = int(nfl_state.get("season") or datetime.now().year)

        # Load all players to check for rookies (years_exp 0 or 1 = first two seasons)
        players_index = load_players_index() or {}
        rookies = []

        for player_id, player_data in players_index.items():
            years_exp = player_data.get("years_exp")
            rookie_year = player_data.get("rookie_year")

            if years_exp in (0, 1, "0", "1"):
                rookies.append(str(player_id))
            elif rookie_year and int(rookie_year) == current_season:
                rookies.append(str(player_id))

        # Get breakouts from the same source as the Breakout Engine page,
        # using the same season resolution so modal tabs match the page exactly.
        breakouts = []
        try:
            from dashboard_services.breakout_api import (
                get_breakout_candidates as _get_bo_indicators,
                _resolve_bo_season as _resolve_bo,
            )
            _bo_season = _resolve_bo(current_season)
            _bo_result = _get_bo_indicators(season=_bo_season, min_score=50, limit=15)
            breakouts = [str(c["player_id"]) for c in (_bo_result.get("candidates") or [])]
        except Exception as e:
            logger.info(f"[player-indicators] Breakout candidates unavailable: {e}")

        # Get elites based on positional rank cutoffs (12-man PPR dynasty)
        elites = []

        # Load model value table to get current player values
        value_table = get_model_value_table_cached() or []
        value_map = {str(p.get("id")): p for p in value_table}

        # Top-N positional rank cutoffs (shared with the consolidate/distribute
        # engine so the ELITE chip and trade suggestions never disagree).
        from utils.tier_thresholds import ELITE_RANK_CUTOFFS as elite_rank_cutoffs

        from collections import defaultdict as _defaultdict
        pos_players: dict = _defaultdict(list)
        for player_id, player_data in value_map.items():
            pos = str(player_data.get("position", "")).upper()
            val = float(player_data.get("value", 0) or 0)
            if val > 0 and pos in elite_rank_cutoffs:
                pos_players[pos].append((val, str(player_id)))

        for pos, cutoff in elite_rank_cutoffs.items():
            for _, pid in sorted(pos_players[pos], reverse=True)[:cutoff]:
                elites.append(pid)

        # Prospects = only pre-draft class players (is_rookie=True in cached table)
        prospects = []
        try:
            model_tbl = get_model_value_table_cached() or []
            for entry in model_tbl:
                if entry.get("is_rookie") is True:
                    pid = str(entry.get("id") or "")
                    if pid:
                        prospects.append(pid)
        except Exception as _pe:
            logger.info(f"[player-indicators] prospects skipped: {_pe}")

        return jsonify({
            "rookies": rookies,
            "breakouts": breakouts,
            "elites": elites,
            "prospects": prospects
        })

    except Exception as e:
        logger.info(f"[player-indicators] Error: {e}")
        return jsonify({"rookies": [], "breakouts": [], "elites": [], "prospects": []})


@app.route("/api/prospect/<player_id>")
def api_prospect_profile(player_id: str):
    """Return full prospect profile data for a single pre-draft player."""
    try:
        from data_building.rookie_pipeline.pipeline import get_rookie_rankings_from_db, get_active_rookie_class
        draft_year = get_active_rookie_class()
        rows = get_rookie_rankings_from_db(draft_year)
        player_id = str(player_id).strip()
        for r in rows:
            if str(r.get("player_id") or "") == player_id:
                d = dict(r)
                d["draft_capital_label"] = (
                    f"Round {d['projected_round']} · Pick #{d['projected_pick']}"
                    if d.get("projected_round") and d.get("projected_pick") else None
                )
                return jsonify(_sanitize_for_json(d))
        return jsonify({"error": "not found"}), 404
    except Exception as e:
        logger.info(f"[api/prospect] {e}")
        return _api_err("Request failed", e)


@app.route("/api/breakout-candidates")
def api_breakout_candidates():
    """
    Get breakout candidates - automatically switches between offseason and in-season detection.
    Returns full candidate objects with stats, not just IDs.
    """
    league_id = request.args.get("league_id")
    platform = request.args.get("platform", "sleeper")
    if not has_premium_for_viewer(session.get("viewer_username"), session.get("viewer_user_id"),
                                  league_id, platform, request.args.get("season")):
        return jsonify({"paywall": True, "error": "Premium required"}), 403

    try:
        from datetime import datetime
        from utils.utils import load_players_index, load_model_value_table

        min_score = float(request.args.get("min_score", 40))  # Selective threshold
        limit = int(request.args.get("limit", 20))

        # Get current NFL state
        nfl_state = get_nfl_state() or {}
        current_season = int(nfl_state.get("season") or datetime.now().year)
        season_type = str(nfl_state.get("season_type", "")).lower().strip()
        is_offseason = season_type == "off"

        candidates = []

        if is_offseason:
            # Use offseason opportunity-based detection (FAST - uses database)
            try:
                from data_building.offseason_opportunity import get_offseason_breakout_candidates
                candidates = get_offseason_breakout_candidates(
                    current_season,
                    min_score=min_score,
                    limit=limit * 5,  # Get more initially for filtering
                    max_per_team_position=2
                )
                logger.info(f"[breakout-candidates] Offseason mode: {len(candidates)} candidates")
            except Exception as e:
                logger.info(f"[breakout-candidates] Offseason detection error: {e}")
        else:
            # Use in-season breakout detection with enrichment
            try:
                from data_building.advanced_metrics import detect_breakout_candidates

                breakout_ids = detect_breakout_candidates(lookback_days=14)

                # Enrich with full player data
                players_index = load_players_index() or {}
                value_table = get_model_value_table_cached() or []
                values_by_id = {str(p.get("id")): p for p in value_table}

                for b in breakout_ids:
                    player_id = str(b.get("player_id", ""))
                    player_meta = players_index.get(player_id, {})
                    player_value = values_by_id.get(player_id, {})

                    candidates.append({
                        "player_id": player_id,
                        "name": player_meta.get("name", "Unknown"),
                        "team": player_meta.get("team"),
                        "position": player_meta.get("pos"),
                        "age": player_value.get("age"),
                        "value": player_value.get("value", 0),
                        "sf_value": player_value.get("sf_value", player_value.get("value", 0)),
                        "pos_rank": player_value.get("pos_rank"),
                        "pos_rank_label": player_value.get("pos_rank_label"),
                        "breakout_score": b.get("score", 0),
                    })

                logger.info(f"[breakout-candidates] In-season mode: {len(candidates)} candidates")
            except Exception as e:
                logger.info(f"[breakout-candidates] In-season detection error: {e}")
                # Fallback to value movers
                movers_data = get_top_movers(days=7, limit=100) or {}
                players_index = load_players_index() or {}
                value_table = list(get_model_value_table_cached() or [])
                values_by_id = {str(p.get("id")): p for p in value_table}

                for player in movers_data.get("risers", []):
                    delta = player.get("delta", 0)
                    position = player.get("position", "")
                    threshold = 100 if position == "TE" else 75

                    if delta >= threshold:
                        player_id = str(player.get("player_id", ""))
                        player_meta = players_index.get(player_id, {})
                        player_value = values_by_id.get(player_id, {})

                        candidates.append({
                            "player_id": player_id,
                            "name": player.get("name", "Unknown"),
                            "team": player_meta.get("team"),
                            "position": position,
                            "age": player_value.get("age"),
                            "value": player.get("value", 0),
                            "sf_value": player.get("sf_value", player.get("value", 0)),
                            "pos_rank": player_value.get("pos_rank"),
                            "pos_rank_label": player_value.get("pos_rank_label"),
                            "breakout_score": delta,
                        })

        # Sort by breakout score and limit
        candidates.sort(key=lambda x: x.get("breakout_score", 0), reverse=True)
        return jsonify(candidates[:limit])

    except Exception as e:
        logger.exception("[breakout-candidates] Error")
        import traceback
        traceback.print_exc()
        return jsonify([])


# /api/nfl-state extracted to routes/misc_api_bp.py




@app.route("/api/advanced-metrics/top-role-players")
def api_top_role_players():
    """
    Get players with highest role scores (usage + efficiency composite).

    Query params:
        position: Filter by position (QB/RB/WR/TE) or omit for all
        limit: Max number of players (default 50)

    Returns:
        [
            {
                "player_id": "123",
                "position": "RB",
                "role_score": 78.5,
                "snap_share": 0.82,
                "opportunity_share": 18.3,
                ...
            },
            ...
        ]
    """
    try:
        global _ROLE_PLAYERS_CACHE, _ROLE_PLAYERS_CACHE_TS
        from data_building.advanced_metrics import get_top_role_players

        position = request.args.get("position")
        if position:
            position = position.upper().strip()
            if position not in ("QB", "RB", "WR", "TE"):
                position = None

        try:
            limit = int(request.args.get("limit", 50))
            limit = max(1, min(limit, 200))  # Clamp between 1-200
        except (TypeError, ValueError):
            limit = 50

        cache_key = (position, limit)
        now = time.time()
        if cache_key in _ROLE_PLAYERS_CACHE and now - _ROLE_PLAYERS_CACHE_TS.get(cache_key, 0) < _ADVANCED_METRICS_TTL:
            return jsonify(_ROLE_PLAYERS_CACHE[cache_key])

        players = get_top_role_players(position=position, limit=limit)

        # Clean up internal fields
        for player in players:
            player.pop("id", None)
            # Convert decimals to floats
            for k, v in player.items():
                if v is not None and k not in ("player_id", "position", "as_of_date"):
                    player[k] = float(v)

        _ROLE_PLAYERS_CACHE[cache_key] = players
        _ROLE_PLAYERS_CACHE_TS[cache_key] = now
        return jsonify(players)

    except Exception as e:
        logger.exception("[top-role-players] Error")
        import traceback
        traceback.print_exc()
        return jsonify([])


@app.route("/api/advanced-metrics/breakout-candidates")
def api_advanced_metrics_breakout_candidates():
    """
    Get breakout candidates using multi-factor analysis.

    Query params:
        lookback_days: Days to analyze trends (default 14)
        min_games: Minimum games played (default 2)

    Returns:
        [
            {
                "player_id": "456",
                "name": "Player Name",
                "position": "WR",
                "age": 23.5,
                "breakout_score": 67.3,
                "score_components": {
                    "snap_increase": 15.2,
                    "opportunity_increase": 22.5,
                    "efficiency_gains": 12.1,
                    ...
                },
                "value_delta": 125.0
            },
            ...
        ]
    """
    try:
        global _BREAKOUT_CACHE, _BREAKOUT_CACHE_TS
        from data_building.advanced_metrics import detect_breakout_candidates

        try:
            lookback_days = int(request.args.get("lookback_days", 14))
            lookback_days = max(7, min(lookback_days, 90))  # Clamp 7-90 days
        except (TypeError, ValueError):
            lookback_days = 14

        try:
            min_games = int(request.args.get("min_games", 2))
            min_games = max(1, min(min_games, 10))
        except (TypeError, ValueError):
            min_games = 2

        now = time.time()
        if _BREAKOUT_CACHE is not None and now - _BREAKOUT_CACHE_TS < _ADVANCED_METRICS_TTL:
            return jsonify(_BREAKOUT_CACHE)

        candidates = detect_breakout_candidates(
            lookback_days=lookback_days,
            min_games=min_games,
        )

        _BREAKOUT_CACHE = candidates
        _BREAKOUT_CACHE_TS = now
        return jsonify(candidates)

    except Exception as e:
        logger.exception("[breakout-candidates] Error")
        import traceback
        traceback.print_exc()
        return jsonify([])


@app.route("/api/offseason-breakout-candidates")
def api_offseason_breakout_candidates():
    """
    Get offseason breakout candidates based on roster changes and vacated opportunity.

    PREMIUM FEATURE - Requires active subscription.

    Identifies players who will benefit from departed teammates (FA, trades, retirements).
    Examples:
    - Mike Evans leaves TB -> Egbuka gets targets
    - Second-year WR moves up depth chart
    - Backup RB becomes lead back

    Query params:
        season: Season year (default: current year)
        min_score: Minimum breakout score (default: 40)
        position: Filter by position (QB/RB/WR/TE)
        max_per_team_position: Max candidates per team+position (default: 2, range: 1-5)

    Returns:
        [
            {
                "player_id": "789",
                "name": "Emeka Egbuka",
                "team": "TB",
                "position": "WR",
                "age": 23,
                "years_exp": 1,
                "breakout_score": 65.5,
                "projection_factors": {
                    "absolute_opportunity_increase": 25.0,
                    "relative_opportunity_increase": 18.5,
                    "team_vacancy_size": 14.0,
                    "youth_experience_bonus": 15.0
                },
                "previous_season": {
                    "targets": 45,
                    "carries": 0,
                    "snap_share": 0.42
                },
                "projected": {
                    "targets": 120,
                    "carries": 0,
                    "snap_share": 0.75
                },
                "increases": {
                    "targets": 75,
                    "carries": 0,
                    "snap_share": 0.33
                },
                "departed_players": ["Mike Evans"],
                "context": "Benefits from Mike Evans departure"
            },
            ...
        ]
    """
    try:
        from datetime import datetime
        from data_building.offseason_opportunity import get_offseason_breakout_candidates

        # Breakout candidates are now available to all users (no premium check)

        # Get season (default to current year)
        nfl_state = get_nfl_state() or {}
        default_season = int(nfl_state.get("season") or datetime.now().year)

        try:
            season = int(request.args.get("season", default_season))
        except (TypeError, ValueError):
            season = default_season

        # Get min score threshold (default 40 for selectivity)
        try:
            min_score = float(request.args.get("min_score", 40))
            min_score = max(0, min(min_score, 100))
        except (TypeError, ValueError):
            min_score = 40

        # Get max per team/position (default 2, range 1-5)
        try:
            max_per_team_position = int(request.args.get("max_per_team_position", 2))
            max_per_team_position = max(1, min(max_per_team_position, 5))
        except (TypeError, ValueError):
            max_per_team_position = 2

        # Get position filter
        position = request.args.get("position")
        if position:
            position = position.upper().strip()
            if position not in ("QB", "RB", "WR", "TE"):
                position = None

        # Get candidates (FAST - uses database queries, no artificial filtering)
        candidates = get_offseason_breakout_candidates(
            season,
            min_score=min_score,
            max_per_team_position=max_per_team_position
        )

        # Filter by position if requested
        if position:
            candidates = [c for c in candidates if c.get("position") == position]

        # Filter out elite players (they shouldn't be breakout candidates)
        # Load model values to check elite thresholds
        model_values = get_model_value_table_cached() or []
        values_by_id = {str(p["id"]): p for p in model_values if isinstance(p, dict) and p.get("id")}

        # Position-specific elite thresholds
        elite_thresholds = {
            'RB': 650, 'WR': 650, 'TE': 550, 'QB': 400, 'K': 9999, 'DEF': 9999
        }

        filtered_candidates = []
        for candidate in candidates:
            player_id = str(candidate.get("player_id", ""))
            pos = candidate.get("position", "")
            threshold = elite_thresholds.get(pos, 750)

            # Get player value
            player_value = values_by_id.get(player_id, {})
            value = float(player_value.get("value", 0)) if player_value.get("value") else 0

            # Only include if not elite
            if value < threshold:
                filtered_candidates.append(candidate)

        candidates = filtered_candidates

        return jsonify(candidates)

    except Exception as e:
        logger.info(f"[offseason-breakout-candidates] Error: {e}")
        import traceback
        traceback.print_exc()
        return jsonify([])


@app.route("/api/calculate-breakout-scores")
def api_calculate_breakout_scores():
    """
    Calculate and save breakout scores for all players.

    This is an admin endpoint that runs the unified breakout engine
    and saves results to the database.

    Query params:
        season: Season year (default: current year)
        min_score: Minimum score to save (default: 30)

    Returns:
        {
            "success": true,
            "candidates_calculated": 150,
            "candidates_saved": 150,
            "phase": "post_free_agency",
            "season": 2026
        }
    """
    try:
        from datetime import datetime
        from data_building.breakout_engine import BreakoutEngine
        from utils.utils import load_players_index, load_usage_table

        # Get season
        nfl_state = get_nfl_state() or {}
        default_season = int(nfl_state.get("season") or datetime.now().year)

        try:
            season = int(request.args.get("season", default_season))
        except (TypeError, ValueError):
            season = default_season

        # Get min score
        try:
            min_score = float(request.args.get("min_score", 30))
        except (TypeError, ValueError):
            min_score = 30

        # Initialize engine
        engine = BreakoutEngine(season=season)

        # Get all players from usage table or players_index
        # This is a simplified version - in production you'd filter to relevant players
        usage_table = load_usage_table() or []
        players_index = load_players_index() or {}

        # Build player list (top 600 by value/relevance)
        player_list = []
        for player in usage_table[:600]:  # Limit to top 600
            player_id = player.get('player_id') or player.get('id')
            if not player_id:
                continue

            # Get additional metadata from players_index
            player_meta = players_index.get(player_id, {})

            player_list.append({
                'player_id': player_id,
                'player_name': player.get('name') or player_meta.get('full_name'),
                'team': player.get('team') or player_meta.get('team'),
                'position': player.get('position') or player_meta.get('pos'),
                'age': player_meta.get('age'),
                'years_exp': player_meta.get('years_exp', 0)
            })

        # Calculate scores
        candidates = engine.calculate_breakout_scores(player_list, min_score=min_score)

        # Save to database
        saved_count = engine.save_scores(candidates)

        return jsonify({
            "success": True,
            "candidates_calculated": len(candidates),
            "candidates_saved": saved_count,
            "phase": engine.phase,
            "season": season
        })

    except Exception as e:
        logger.info(f"[calculate-breakout-scores] Error: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({"error": str(e), "success": False}), 500




# ── Compare page: positional-tier baselines (Avg WR1, WR2, ...) ──────────────
_COMPARE_BASELINES_CACHE = None
_COMPARE_BASELINES_TS = 0.0
_COMPARE_BASELINES_TTL = 300
_COMPARE_TIER_SIZE = 12
_COMPARE_MAX_TIERS = 2


def _compute_compare_baselines():
    """Positional-tier average "players" for the compare page, ranked by FANTASY
    production: WR1 = the mean of the top 12 WRs by total fantasy points (the
    season positional finish), WR2 = ranks 13-24, and so on for each position.
    Each entry is shaped like /api/player-details (id / name / position / stats)
    so the compare UI can treat a tier average as an opponent. Points use half-PPR
    from the most recent season with usage data; dynasty value / SF value are
    averaged across each tier's players from the model value table."""
    global _COMPARE_BASELINES_CACHE, _COMPARE_BASELINES_TS
    now = time.time()
    if _COMPARE_BASELINES_CACHE is not None and now - _COMPARE_BASELINES_TS < _COMPARE_BASELINES_TTL:
        return _COMPARE_BASELINES_CACHE

    # Dynasty / SF value per player id (an averaged stat per tier, not the ranker).
    val_by_id = {}
    for p in (get_model_value_table_cached() or []):
        pid = str(p.get("id") or "")
        if pid:
            val_by_id[pid] = p

    # Fantasy points per player from the most recent season with usage data.
    # players_by_pos: position -> list of {id, ppg, total} with >= 4 games played.
    players_by_pos, ppg_season = {}, None
    try:
        _season = int((get_nfl_state() or {}).get("season") or 0)
    except Exception:
        _season = 0
    # Candidate seasons newest-first: the live season when known, then recent
    # calendar years as a fallback so this still resolves if nfl-state is
    # unavailable. First season with a usage file wins.
    _cands, _seen = [], set()
    import datetime as _dt
    for _c in ([_season, _season - 1] if _season > 0 else []) + \
              [_dt.datetime.now().year - _o for _o in range(0, 4)]:
        if _c > 0 and _c not in _seen:
            _seen.add(_c)
            _cands.append(_c)
    for _s in _cands:
        _ud = _load_usage_rows_cached(_s)
        if not _ud:
            continue
        _acc = {}
        for _p in _ud:
            _u = _p.get("usage") or {}
            _g = int(_u.get("games") or 0)
            if _g < 4:
                continue
            _pos = str(_p.get("position") or "").upper()
            if _pos not in ("QB", "RB", "WR", "TE"):
                continue
            # Standardize on full PPR so the tiers are a fixed, recognizable
            # benchmark regardless of the viewer's league scoring.
            _pp = _u.get("ppr_ppg")
            if _pp is None:
                _pp = _u.get("half_ppr_ppg") or _u.get("std_scoring_ppg") or _u.get("std_ppg")
            _pid = str(_p.get("id") or "")
            if _pp is None or not _pid:
                continue
            try:
                _pp = round(float(_pp), 1)
            except (TypeError, ValueError):
                continue
            _acc.setdefault(_pos, []).append(
                {"id": _pid, "ppg": _pp, "total": round(_pp * _g, 1)})
        if _acc:
            players_by_pos = _acc
            ppg_season = _s
            break

    def _mean(vals):
        vals = [v for v in vals if v is not None]
        return round(sum(vals) / len(vals), 1) if vals else None

    def _val(pid, key):
        # 12-team basis: prefer the 12-team value column, fall back to the default.
        row = val_by_id.get(pid) or {}
        v = row.get(key + "_12")
        if v is None:
            v = row.get(key)
        try:
            return float(v) if v else None
        except (TypeError, ValueError):
            return None

    # Build tier definitions first, then bulk-fetch every tier player's advanced
    # metrics in ONE query (not one per player) so the Advanced Metrics tab can
    # show a tier average. Degrades to no metrics if the DB is unavailable.
    tiers = []          # (pos, t, chunk, ids, lo, hi)
    all_ids = set()
    for pos in ("QB", "RB", "WR", "TE"):
        # Rank the position by total fantasy points - the season finish that
        # "top 12 WRs" actually means.
        ranked = sorted(players_by_pos.get(pos, []), key=lambda r: r["total"], reverse=True)
        for t in range(1, _COMPARE_MAX_TIERS + 1):
            chunk = ranked[(t - 1) * _COMPARE_TIER_SIZE : t * _COMPARE_TIER_SIZE]
            if len(chunk) < 6:   # don't emit a tiny trailing tier
                break
            ids = [r["id"] for r in chunk]
            all_ids.update(ids)
            lo = (t - 1) * _COMPARE_TIER_SIZE + 1
            tiers.append((pos, t, chunk, ids, lo, lo + len(chunk) - 1))

    metrics_by_id = {}
    if all_ids and ppg_season:
        try:
            from data_building.advanced_metrics import get_players_metrics_by_season
            metrics_by_id = get_players_metrics_by_season(sorted(all_ids), int(ppg_season)) or {}
        except Exception:
            metrics_by_id = {}

    _skip_metric = {"season", "player_id", "week", "games", "as_of_date"}

    def _avg_tier_metrics(ids):
        acc = {}
        for pid in ids:
            for k, v in (metrics_by_id.get(str(pid)) or {}).items():
                if k in _skip_metric or v is None or isinstance(v, bool):
                    continue
                # Postgres NUMERIC columns arrive as Decimal, which isn't an
                # int/float - coerce numerically and skip anything non-numeric
                # (names, dates) so a whole tier's metrics aren't silently dropped.
                try:
                    acc.setdefault(k, []).append(float(v))
                except (TypeError, ValueError):
                    continue
        avg = {k: round(sum(vs) / len(vs), 3) for k, vs in acc.items() if vs}
        try:
            from data_building.advanced_metrics import strip_premium_metrics
            avg = strip_premium_metrics(avg) or {}
        except Exception:
            pass
        return avg

    out = []
    for pos, t, chunk, ids, lo, hi in tiers:
        _tier_vals = [v for v in (_val(i, "value") for i in ids) if v is not None]
        out.append({
            "player_id": f"avg-{pos}-{t}",
            "name": f"Avg {pos}{t}",
            "position": pos,
            "team": "TIER",
            "is_baseline": True,
            "tier_range": f"{pos}{lo}-{pos}{hi}",
            # Dynasty-value spread across the tier, so the compare chart can draw
            # the tier as a shaded band rather than a single flat line.
            "value_band": [round(min(_tier_vals)), round(max(_tier_vals))] if _tier_vals else None,
            "espnHeadshot": "",
            "stats": {
                "value": _mean([_val(i, "value") for i in ids]),
                "sf_value": _mean([_val(i, "sf_value") for i in ids]),
                "pos_rank": None, "pos_rank_label": f"{pos}{t}",
                "sf_pos_rank": None, "sf_pos_rank_label": f"{pos}{t}",
                "value_ovr_rank": None, "sf_value_ovr_rank": None,
                "ppg": _mean([r["ppg"] for r in chunk]),
                "ppg_rank": None, "ppg_ovr_rank": None, "ppg_season": ppg_season,
                "total_pts": _mean([r["total"] for r in chunk]),
                "total_pts_rank": None, "total_pts_ovr_rank": None,
            },
            "value_history": [],
            "metrics": _avg_tier_metrics(ids),
        })

    _COMPARE_BASELINES_CACHE = out
    _COMPARE_BASELINES_TS = now
    return out


@app.route("/api/compare-baselines")
def api_compare_baselines():
    """Selectable tier-average opponents for the compare page (Avg WR1, RB2, ...)."""
    try:
        return jsonify({"baselines": _compute_compare_baselines()})
    except Exception:
        logger.exception("[api_compare_baselines] error")
        return jsonify({"baselines": []}), 200


@app.route("/api/player-details/<player_id>")
def api_player_details(player_id: str):
    """Get comprehensive player details for modal display."""
    try:
        from utils.utils import load_relevant_index, load_model_value_table
        from dashboard_services.api import get_effective_scoring_settings
        from dashboard_services.platform_api import sync_league_globals
        import json
        import os
        import glob
        import re

        # Get league context
        league_id = request.args.get("league_id")
        platform = request.args.get("platform", "sleeper")
        season = int(request.args.get("season", datetime.now().year))
        _modal_lt = str(request.args.get("league_type", "1qb")).strip().lower()
        try:
            _modal_ls = int(request.args.get("league_size", 10))
            if _modal_ls not in (8, 10, 12, 14):
                _modal_ls = 10
        except (TypeError, ValueError):
            _modal_ls = 10

        # Sync league globals if league_id provided
        if league_id:
            # sync_league_globals is a no-op for Sleeper — get_league() is what
            # populates the request-scoped scoring globals (incl. bonus_rec_te,
            # which TE-premium scaling reads). Without this the modal sees bare
            # defaults and never applies the TE premium.
            if platform == "sleeper":
                from dashboard_services.api import get_league as _get_league
                _get_league(league_id)
            else:
                sync_league_globals(platform, league_id, season)
            scoring_settings = get_effective_scoring_settings()
        else:
            # Default scoring settings if no league context
            scoring_settings = {
                "passYards": 0.04,
                "passTD": 4.0,
                "passInterceptions": -2.0,
                "rushYards": 0.1,
                "rushTD": 6.0,
                "pointsPerReception": 1.0,
                "receivingYards": 0.1,
                "receivingTD": 6.0,
                "fumbles": -2.0
            }

        players_index = load_relevant_index() or {}
        player_meta = players_index.get(player_id, {})

        # Fall back to full players index if not found in relevant index
        if not player_meta:
            players_index_full = load_players_index() or {}
            player_meta = players_index_full.get(player_id, {})

        if not player_meta:
            return jsonify({"error": "Player not found"}), 404

        player_team = player_meta.get("team", "")

        # Get value data (use cache so FC/DP corrections are applied)
        value_table = get_model_value_table_cached() or []
        player_value = next((p for p in value_table if str(p.get("id")) == str(player_id)), {})

        # Get FULL value history from database (not just 90 days)
        value_history = get_player_value_history(
            player_id, days=365,
            league_type=_modal_lt, league_size=_modal_ls,
        )

        # Scale history to match FC/DP-corrected current values.
        # The history function returns value_1qb and value_sf separately;
        # the chart uses those fields (not value), so all three must be scaled.
        if value_history and player_value:
            _corr_1qb = float(player_value.get("value") or 0)
            _corr_sf  = float(player_value.get("sf_value") or _corr_1qb)
            _last_h   = value_history[-1]
            _raw_1qb  = float(_last_h.get("value_1qb") or _last_h.get("value") or 0)
            _raw_sf   = float(_last_h.get("value_sf")  or _last_h.get("value") or 0)
            _ratio_1qb = (_corr_1qb / _raw_1qb) if _raw_1qb > 0 and abs(_corr_1qb - _raw_1qb) > 1.0 else 1.0
            _ratio_sf  = (_corr_sf  / _raw_sf)  if _raw_sf  > 0 and abs(_corr_sf  - _raw_sf)  > 1.0 else 1.0
            if _ratio_1qb != 1.0 or _ratio_sf != 1.0:
                _is_sf = _modal_lt == "sf"
                for _h in value_history:
                    if _h.get("value_1qb") is not None:
                        _h["value_1qb"] = round(_h["value_1qb"] * _ratio_1qb, 1)
                    if _h.get("value_sf") is not None:
                        _h["value_sf"] = round(_h["value_sf"] * _ratio_sf, 1)
                    # Keep primary value in sync with whichever series the league uses
                    _h["value"] = _h["value_sf"] if _is_sf else _h["value_1qb"]
                    if _h.get("delta_from_prev") is not None:
                        _ratio_primary = _ratio_sf if _is_sf else _ratio_1qb
                        _h["delta_from_prev"] = round(_h["delta_from_prev"] * _ratio_primary, 1)

        # Game logs are lazy-loaded by the Stats tab via /api/player-game-logs, so
        # we deliberately DON'T build them here — doing so read ~100 MB of per-week
        # JSON on every modal open just to power a single "has any game logs"
        # boolean (rookie badge). Instead derive that boolean cheaply from the
        # per-season usage_rows files (one ~2 MB file per season, cached), which
        # also feed the PPG ranks below.
        game_logs_by_year = {}
        has_game_logs = False
        prospect_data = None
        for _hs in (season, season - 1, season - 2):
            _hu = _load_usage_rows_cached(_hs)
            if not _hu:
                continue
            _he = next(
                (p for p in _hu
                 if str(p.get("id")) == str(player_id)
                 or str(p.get("player_id")) == str(player_id)),
                None,
            )
            if _he and int((_he.get("usage") or {}).get("games") or 0) >= 1:
                has_game_logs = True
                break

        # Try to attach prospect data when the player has no NFL game history
        # (has_game_logs was determined cheaply above from usage_rows).
        if not has_game_logs:
            try:
                import re as _re
                from dashboard_services.rookie_api import _cache as _rookie_cache
                from data_building.rookie_pipeline.pipeline import get_active_rookie_class
                from data_building.rookie_pipeline.value_translation import format_draft_capital

                active_year = get_active_rookie_class()
                found_row = None
                for check_year in [active_year, active_year - 1]:
                    if check_year not in _rookie_cache:
                        from data_building.rookie_pipeline.pipeline import get_rookie_rankings_from_db
                        _rookie_cache[check_year] = get_rookie_rankings_from_db(check_year)
                    for r in _rookie_cache.get(check_year, []):
                        if str(r.get("sleeper_id") or "") == str(player_id):
                            found_row = r
                            break
                    if found_row:
                        break

                # Fallback: match by name from players_index when sleeper_id not yet linked
                if not found_row:
                    def _norm_name(n):
                        n = n.lower()
                        n = _re.sub(r"['\.\-]", "", n)
                        n = _re.sub(r"\b(jr|sr|ii|iii|iv)\b", "", n)
                        return _re.sub(r"\s+", " ", n).strip()

                    players_idx = get_players_index_global() or {}
                    idx_entry = players_idx.get(str(player_id)) or {}
                    idx_name = idx_entry.get("name", "")
                    if idx_name:
                        norm_target = _norm_name(idx_name)
                        for check_year in [active_year, active_year - 1]:
                            for r in _rookie_cache.get(check_year, []):
                                if _norm_name(r.get("name", "")) == norm_target:
                                    found_row = r
                                    # Cache the link so future calls use sleeper_id
                                    r["sleeper_id"] = str(player_id)
                                    break
                            if found_row:
                                break

                if found_row:
                    def _sf(v):
                        try:
                            return float(v) if v is not None else None
                        except (TypeError, ValueError):
                            return None

                    prospect_data = {
                        "player_id":                     found_row.get("player_id"),
                        "draft_class_year":              found_row.get("draft_class_year"),
                        "school":                        found_row.get("school"),
                        "prospect_score":                _sf(found_row.get("prospect_score")),
                        "tier":                          found_row.get("tier"),
                        "tier_label":                    found_row.get("tier_label"),
                        "overall_rank":                  found_row.get("overall_rank"),
                        "position_rank":                 found_row.get("position_rank"),
                        "production_score":              _sf(found_row.get("production_score")),
                        "efficiency_score":              _sf(found_row.get("efficiency_score")),
                        "age_score":                     _sf(found_row.get("age_score")),
                        "breakout_profile_score":        _sf(found_row.get("breakout_profile_score")),
                        "athleticism_score":             _sf(found_row.get("athleticism_score")),
                        "competition_score":             _sf(found_row.get("competition_score")),
                        "projected_draft_capital_score": _sf(found_row.get("projected_draft_capital_score")),
                        "confidence_score":              _sf(found_row.get("confidence_score")),
                        "key_reasons":                   found_row.get("key_reasons"),
                        "rookie_value":                  _sf(found_row.get("rookie_value")),
                        "rookie_sf_value":               _sf(found_row.get("rookie_sf_value")),
                        "projected_round":               found_row.get("projected_round"),
                        "projected_pick":                found_row.get("projected_pick"),
                        "num_mocks_used":                found_row.get("num_mocks_used"),
                        "height_inches":                 found_row.get("height_inches"),
                        "weight_lbs":                    found_row.get("weight_lbs"),
                        "forty_yard":                    _sf(found_row.get("forty_yard")),
                        "ras_score":                     _sf(found_row.get("ras_score")),
                        "draft_capital_label":           format_draft_capital(
                            found_row.get("projected_round"),
                            found_row.get("projected_pick"),
                            found_row.get("projected_pick_low"),
                            found_row.get("projected_pick_high"),
                        ),
                    }
            except Exception as pe:
                logger.info(f"[api_player_details] prospect lookup error: {pe}")

        # ── Fantasy team ownership (only when league context is provided) ──
        fantasy_team = None
        fantasy_team_owner = None
        if league_id:
            try:
                from dashboard_services.service import fantasy_team_and_roster_for_player as _ft_lookup
                _ctx = get_league_ctx_from_cache(platform, league_id, season)
                _rosters = _ctx.get("rosters") or []
                _users   = _ctx.get("users")   or []
                _rmap    = _build_roster_map(_users, _rosters)
                _team_name, _rid = _ft_lookup(str(player_id), _rosters, _rmap)
                if _team_name and _team_name != "Free Agent":
                    fantasy_team = _team_name
                    # Find the owner's username for the sub-label
                    _roster_obj = next((r for r in _rosters if str(r.get("roster_id")) == _rid), None)
                    if _roster_obj:
                        _owner_id = _roster_obj.get("owner_id")
                        _user = next((u for u in _users if u.get("user_id") == _owner_id), None)
                        fantasy_team_owner = (_user or {}).get("display_name") or (_user or {}).get("username")
            except Exception as _fe:
                logger.debug("[api_player_details] roster lookup failed: %s", _fe)

        # Compute PPG and positional scoring rank from usage cache
        _ppg = None
        _ppg_rank = None
        _ppg_ovr_rank = None
        _ppg_games = None
        _ppg_season_used = None
        _total_pts = None
        _total_pts_rank = None
        _total_pts_ovr_rank = None
        try:
            import os as _os, json as _json2
            _ppr_val = scoring_settings.get("pointsPerReception", 0.5)
            def _pick_ppg(u):
                if _ppr_val >= 1.0:
                    return u.get("ppr_ppg")
                if _ppr_val <= 0:
                    return u.get("std_scoring_ppg") or u.get("std_ppg")
                return u.get("half_ppr_ppg")

            for _ppg_s in [season, season - 1]:
                _ud = _load_usage_rows_cached(_ppg_s)
                if not _ud:
                    continue
                _pe = next((p for p in _ud if str(p.get("id")) == str(player_id)), None)
                if not _pe:
                    continue
                _pu = _pe.get("usage") or {}
                _pg = int(_pu.get("games") or 0)
                if _pg < 4:
                    continue
                _ppg = _pick_ppg(_pu)
                if _ppg is None:
                    continue
                _ppg = round(float(_ppg), 1)
                _total_pts = round(_ppg * _pg, 1)
                _ppg_games = _pg
                _ppg_season_used = _ppg_s
                # Scoring rank within position (min 4 games)
                _pos_str = player_meta.get("pos", "")
                if _pos_str:
                    _pos_players = [
                        p for p in _ud
                        if p.get("position") == _pos_str
                        and int((p.get("usage") or {}).get("games") or 0) >= 4
                        and _pick_ppg(p.get("usage") or {}) is not None
                    ]
                    _all_ppg = sorted(
                        [round(float(_pick_ppg(p.get("usage") or {})), 1) for p in _pos_players],
                        reverse=True,
                    )
                    try:
                        _ppg_rank = _all_ppg.index(_ppg) + 1
                    except ValueError:
                        _ppg_rank = None
                    # Total points rank - round ppg before multiplying so values match
                    _all_total = sorted(
                        [round(round(float(_pick_ppg(p.get("usage") or {})), 1) * int((p.get("usage") or {}).get("games") or 0), 1)
                         for p in _pos_players],
                        reverse=True,
                    )
                    try:
                        _total_pts_rank = _all_total.index(_total_pts) + 1
                    except ValueError:
                        _total_pts_rank = None

                # Overall rank across all skill positions
                _ppg_ovr_rank = None
                _total_pts_ovr_rank = None
                _ovr_positions = {"QB", "RB", "WR", "TE"}
                _ovr_players = [
                    p for p in _ud
                    if p.get("position") in _ovr_positions
                    and int((p.get("usage") or {}).get("games") or 0) >= 4
                    and _pick_ppg(p.get("usage") or {}) is not None
                ]
                _all_ppg_ovr = sorted(
                    [round(float(_pick_ppg(p.get("usage") or {})), 1) for p in _ovr_players],
                    reverse=True,
                )
                try:
                    _ppg_ovr_rank = _all_ppg_ovr.index(_ppg) + 1
                except ValueError:
                    _ppg_ovr_rank = None
                _all_total_ovr = sorted(
                    [round(round(float(_pick_ppg(p.get("usage") or {})), 1) * int((p.get("usage") or {}).get("games") or 0), 1)
                     for p in _ovr_players],
                    reverse=True,
                )
                try:
                    _total_pts_ovr_rank = _all_total_ovr.index(_total_pts) + 1
                except ValueError:
                    _total_pts_ovr_rank = None
                break
        except Exception:
            logger.debug("suppressed exception", exc_info=True)

        # TE-premium leagues make tight ends worth more. Scale a TE's value (and its
        # whole value history) so the modal shows the value as it counts in THIS
        # league — consistent with the trade calculator / activity feed. No-op for
        # non-TEs and non-TE-premium leagues. (player_value is the cached table row,
        # so we never mutate it — the multiplier is applied as values are read out.)
        _modal_tep = te_premium_from_settings(scoring_settings)
        _modal_pos = str(player_meta.get("pos") or "").upper()
        _te_mult = (1.0 + _modal_tep * 0.20) if (_modal_tep and _modal_pos == "TE") else 1.0
        if _te_mult != 1.0:
            for _h in (value_history or []):
                for _k in ("value_1qb", "value_sf", "value"):
                    if _h.get(_k) is not None:
                        _h[_k] = round(float(_h[_k]) * _te_mult, 1)

        _modal_age = age_from_bday(player_meta.get("bDay")) or player_value.get("age") or player_meta.get("age")

        # Sleeper ADP - the same feed the player rankings page uses (Sleeper's
        # projections API, cached daily by fetch_sleeper_adp, so this is a cheap
        # dict lookup on modal open). Surface all four flavors (dynasty/redraft x
        # 1QB/SF); each is None when Sleeper has no value for it, and the whole
        # object is None when none are present, so the modal degrades cleanly.
        # ADP from every source we can resolve for this player, so the modal can
        # show more than one. Sleeper covers dynasty+redraft x 1QB/SF; the BR
        # Fantasy draft-crawler covers dynasty only (redraft isn't crawled). Each
        # cell is None when that source has no value; a source is only included
        # when it has at least one value, and _adp is None when nothing is found,
        # so the modal degrades cleanly. Yahoo is skipped here (needs a league
        # token the modal doesn't carry).
        # Only the cheap Sleeper source is built inline (a dict lookup on a feed
        # cached daily) so the modal opens fast. The BR Fantasy / Consensus
        # sources need per-player draft-crawler DB queries, so the modal fetches
        # those separately from /api/player-adp and merges them in as they land.
        _adp = None
        try:
            from dashboard_services.adp_service import fetch_sleeper_adp
            _adp_row = (fetch_sleeper_adp(int(season)) or {}).get(str(player_id)) or {}

            def _adp_pick(*keys):
                for _k in keys:
                    _v = _adp_row.get(_k)
                    if _v is not None:
                        try:
                            return round(float(_v), 1)
                        except (TypeError, ValueError):
                            pass
                return None

            _sleeper_vals = {
                "dynasty_1qb": _adp_pick("adp_dynasty_ppr", "adp_dynasty_half_ppr", "adp_dynasty_std"),
                "dynasty_sf":  _adp_pick("adp_dynasty_2qb"),
                "redraft_1qb": _adp_pick("adp_ppr", "adp_half_ppr", "adp_std"),
                "redraft_sf":  _adp_pick("adp_2qb"),
            }
            if any(v is not None for v in _sleeper_vals.values()):
                # Keep the flat Sleeper keys for backward compatibility, and add
                # the multi-source list the modal renders from.
                _adp = dict(_sleeper_vals)
                _adp["sources"] = [{"label": "Sleeper", "vals": _sleeper_vals}]
        except Exception:
            logger.debug("[api_player_details] ADP lookup skipped", exc_info=True)

        # ── Injury designation (from the full Sleeper players feed) ──────────
        # Injury fields live only on the full feed, not the compact index. Best
        # effort: on any failure the modal simply shows no injury chip.
        injury = None
        try:
            _full_players = get_players_global() or {}
            _fp = _full_players.get(str(player_id)) or {}
            _raw_inj = str(_fp.get("injury_status") or "").strip()
            if _raw_inj and _raw_inj.lower() not in ("active", "act"):
                injury = {
                    "status": _raw_inj,
                    "body_part": (_fp.get("injury_body_part") or "").strip(),
                    "notes": (_fp.get("injury_notes") or "").strip(),
                }
        except Exception:
            logger.debug("[api_player_details] injury lookup skipped", exc_info=True)

        # ── Playoff strength-of-schedule (fantasy weeks 15-17) ───────────────
        # A rest-of-season buy/sell cue: how the player's team ranks for their
        # position over the championship weeks. Cached; best-effort.
        playoff_sos = None
        try:
            _sos = _playoff_sos_for(season, player_meta.get("team"), player_meta.get("pos"))
            if _sos:
                _sr, _st, _se = _sos
                playoff_sos = {"rank": _sr, "total": _st, "ease": _se}
        except Exception:
            logger.debug("[api_player_details] playoff SoS skipped", exc_info=True)

        response = {
            "player_id": player_id,
            "name": player_meta.get("name", "Unknown"),
            "position": player_meta.get("pos"),
            "team": player_meta.get("team"),
            "age": _modal_age,
            "te_premium": _modal_tep,
            "pos_rank": player_value.get("pos_rank"),
            "pos_rank_label": player_value.get("pos_rank_label"),
            "espnHeadshot": player_meta.get("espnHeadshot"),
            "fantasy_team": fantasy_team,
            "fantasy_team_owner": fantasy_team_owner,
            "injury": injury,
            "playoff_sos": playoff_sos,
            "stats": {
                "value": round(float(player_value.get("value", 0)) * _te_mult, 1) if player_value.get("value") else None,
                "sf_value": round(float(player_value.get("sf_value", 0)) * _te_mult, 1) if player_value.get("sf_value") else None,
                "pos_rank": player_value.get("pos_rank"),
                "pos_rank_label": player_value.get("pos_rank_label"),
                "sf_pos_rank": player_value.get("sf_pos_rank"),
                "sf_pos_rank_label": player_value.get("sf_pos_rank_label"),
                "value_ovr_rank": next((i + 1 for i, p in enumerate(sorted(
                    [x for x in (value_table or []) if x.get("position") not in ("K", "DEF", "PICK") and float(x.get("value") or 0) > 0],
                    key=lambda x: float(x.get("value") or 0), reverse=True
                )) if str(p.get("id")) == str(player_id)), None),
                "sf_value_ovr_rank": next((i + 1 for i, p in enumerate(sorted(
                    [x for x in (value_table or []) if x.get("position") not in ("K", "DEF", "PICK") and float(x.get("sf_value") or 0) > 0],
                    key=lambda x: float(x.get("sf_value") or 0), reverse=True
                )) if str(p.get("id")) == str(player_id)), None),
                "years_exp": player_meta.get("years_exp"),
                "ppg": _ppg,
                "ppg_rank": _ppg_rank,
                "ppg_ovr_rank": _ppg_ovr_rank,
                "ppg_season": _ppg_season_used,
                "ppg_games": _ppg_games,
                "total_pts": _total_pts,
                "total_pts_rank": _total_pts_rank,
                "total_pts_ovr_rank": _total_pts_ovr_rank,
                "adp": _adp,
            },
            "value_history": value_history,
            "game_logs_by_year": game_logs_by_year,
            "has_game_logs": has_game_logs,
            "prospect_data": prospect_data,
        }

        return jsonify(response)

    except Exception as e:
        logger.exception("[api_player_details] Error")
        import traceback
        traceback.print_exc()
        return _api_err("Request failed", e)


@app.route("/api/player-adp/<player_id>")
def api_player_adp(player_id: str):
    """Market-source ADP (BR Fantasy + Consensus) for a single player.

    Split out of /api/player-details so the modal can open immediately on the
    cheap Sleeper feed and pull these in afterward — each source needs a
    draft-crawler DB query (cached in adp_service), which we don't want on the
    modal's critical path. Returns {"sources": [{label, vals}]}, only including
    sources that have at least one value for this player."""
    try:
        from dashboard_services.adp_service import resolve_market_adp

        season = int(request.args.get("season", datetime.now().year))
        _mkt_cache: dict = {}

        def _market_pick(_source, _scoring, _is_sf):
            _key = (_source, _scoring, _is_sf)
            if _key not in _mkt_cache:
                try:
                    # Match the rankings page: re-rank BR Fantasy (ordered by its
                    # raw avg_pick) to a clean 1..N board so it tops out at 1
                    # instead of the ~3 mean-pick floor.
                    _mkt_cache[_key] = resolve_market_adp(
                        int(season), _is_sf, _scoring, source=_source,
                        as_rank=(_source == "brfantasy")) or {}
                except Exception:
                    _mkt_cache[_key] = {}
            _v = _mkt_cache[_key].get(str(player_id))
            try:
                return round(float(_v), 1) if _v is not None else None
            except (TypeError, ValueError):
                return None

        _by_source = {
            "BR Fantasy": {
                "dynasty_1qb": _market_pick("brfantasy", "dynasty", False),
                "dynasty_sf":  _market_pick("brfantasy", "dynasty", True),
                "redraft_1qb": _market_pick("brfantasy", "redraft", False),
                "redraft_sf":  _market_pick("brfantasy", "redraft", True),
            },
            "Consensus": {
                "dynasty_1qb": _market_pick("consensus", "dynasty", False),
                "dynasty_sf":  _market_pick("consensus", "dynasty", True),
                "redraft_1qb": _market_pick("consensus", "redraft", False),
                "redraft_sf":  _market_pick("consensus", "redraft", True),
            },
        }
        _sources = [
            {"label": _label, "vals": _vals}
            for _label, _vals in _by_source.items()
            if any(v is not None for v in _vals.values())
        ]
        return jsonify({"sources": _sources})
    except Exception as e:
        logger.debug("[api_player_adp] failed", exc_info=True)
        return jsonify({"sources": []})


# Short-TTL cache of computed game logs, keyed by player + season + scoring
# settings. The Stats tab globs and parses many per-week stat/schedule/projection
# files across every season on each call; caching the result lets the modal's
# prefetch and any repeat opens skip all of that disk work. TTL is short so new
# weekly stats and updated projections still surface.
_GAME_LOGS_CACHE: Dict[str, tuple] = {}
_GAME_LOGS_CACHE_TTL = 300      # seconds
_GAME_LOGS_CACHE_MAX = 1500     # entries; evict oldest when exceeded


def _game_logs_cache_key(player_id: str, season: int, scoring_settings: dict) -> str:
    try:
        ss = hashlib.md5(
            json.dumps(scoring_settings, sort_keys=True, default=str).encode("utf-8")
        ).hexdigest()[:12]
    except Exception:
        ss = "0"
    return f"{player_id}|{season}|{ss}"


@app.route("/api/player-game-logs/<player_id>")
def api_player_game_logs(player_id: str):
    """Game logs for the Stats tab -- lazy-loaded separately from player-details."""
    try:
        import glob
        from utils.utils import load_relevant_index
        from dashboard_services.api import get_effective_scoring_settings
        from dashboard_services.platform_api import sync_league_globals

        league_id = request.args.get("league_id")
        platform  = request.args.get("platform", "sleeper")
        season    = int(request.args.get("season", datetime.now().year))

        if league_id:
            # sync_league_globals is a no-op for Sleeper - must call get_league explicitly
            from dashboard_services.api import SCORING_DEFAULTS as _SD
            if platform == "sleeper":
                from dashboard_services.api import get_league as _get_league
                _league_data = _get_league(league_id) or {}
                _raw_ss = _league_data.get("scoring_settings") or {}
                scoring_settings = {**_SD, **_raw_ss}
            else:
                sync_league_globals(platform, league_id, season)
                scoring_settings = get_effective_scoring_settings()
        else:
            scoring_settings = {
                "pass_yd": 0.04, "pass_td": 4.0, "pass_int": -2.0,
                "rush_yd": 0.1,  "rush_td": 6.0, "rec": 1.0,
                "rec_yd": 0.1,   "rec_td": 6.0,  "fum_lost": -2.0,
            }

        # Serve a recent identical computation straight from cache, skipping all
        # the per-week file globbing/parsing below.
        _cache_key = _game_logs_cache_key(player_id, season, scoring_settings)
        _cached = _GAME_LOGS_CACHE.get(_cache_key)
        if _cached and time.time() - _cached[0] < _GAME_LOGS_CACHE_TTL:
            return jsonify({"game_logs_by_year": _cached[1]})

        players_index = load_relevant_index() or {}
        player_meta = players_index.get(player_id) or {}
        if not player_meta:
            players_index_full = load_players_index() or {}
            player_meta = players_index_full.get(player_id) or {}
        player_team = player_meta.get("team", "")

        # Reuse the years cache
        global _PLAYER_DETAIL_YEARS_CACHE, _PLAYER_DETAIL_YEARS_CACHE_TS
        now = time.time()
        if not _PLAYER_DETAIL_YEARS_CACHE or now - _PLAYER_DETAIL_YEARS_CACHE_TS > _PLAYER_DETAIL_YEARS_TTL:
            stats_files = glob.glob(os.path.join(CACHE_DIR, "sleeper_stats", "sleeper_stats_*.json"))
            _fresh_years: set = set()
            for sf in stats_files:
                bn = os.path.basename(sf)
                if bn.startswith("sleeper_stats_s"):
                    m = re.match(r'sleeper_stats_s(\d+)_w(\d+)', bn)
                    if m:
                        _fresh_years.add(int(m.group(1)))
            _PLAYER_DETAIL_YEARS_CACHE = _fresh_years
            _PLAYER_DETAIL_YEARS_CACHE_TS = now
        available_years = _PLAYER_DETAIL_YEARS_CACHE

        game_logs_by_year: dict = {}

        for season_year in sorted(available_years, reverse=True):
            game_logs = []

            schedule_by_week: dict = {}
            for schedule_file in glob.glob(os.path.join("cache", "schedule", f"schedule_s{season_year}_w*.json")):
                try:
                    fn = os.path.basename(schedule_file)
                    week_num = int(fn.split('_w')[1].split('_')[0].split('.')[0])
                    with open(schedule_file) as f:
                        games = json.load(f)
                    if isinstance(games, list) and week_num not in schedule_by_week:
                        schedule_by_week[week_num] = games
                except Exception:
                    continue

            stats_by_week: dict = {}
            for week_file in glob.glob(os.path.join(CACHE_DIR, "sleeper_stats", f"sleeper_stats_s{season_year}_w*.json")):
                try:
                    m = re.match(r'sleeper_stats_s(\d+)_w(\d+)', os.path.basename(week_file))
                    if m:
                        with open(week_file) as f:
                            stats_by_week[int(m.group(2))] = json.load(f)
                except Exception:
                    continue

            if not any(player_id in ws for ws in stats_by_week.values()):
                continue

            def _calc_pts(s):
                return round(_score_stats(s, scoring_settings), 2)

            def _stats_dict(s):
                return {k: s.get(k) for k in ["pass_yd","pass_td","pass_int","rush_att","rush_yd","rush_td","rec","rec_tgt","rec_yd","rec_td","fum_lost"]}

            if schedule_by_week:
                # Full path: schedule available - include opponent and date.
                # Resolve the team the player was actually on THIS season/week
                # (handles trades) rather than their current team, which would
                # otherwise show the current team's opponents for past seasons.
                from data_building.external_data.player_team_history import team_for_week
                for week_num in sorted(schedule_by_week.keys()):
                    games = schedule_by_week[week_num]
                    if not isinstance(games, list):
                        continue
                    wk_team = team_for_week(player_id, season_year, week_num) or player_team
                    opponent = ""
                    is_away  = False
                    game_date = ""
                    for game in games:
                        if not isinstance(game, dict):
                            continue
                        home_team = game.get("home", "")
                        away_team = game.get("away", "")
                        if wk_team and wk_team == home_team:
                            opponent = away_team; is_away = False; game_date = game.get("gameDate", ""); break
                        elif wk_team and wk_team == away_team:
                            opponent = home_team; is_away = True;  game_date = game.get("gameDate", ""); break
                    stats = (stats_by_week.get(week_num) or {}).get(player_id)
                    # Bye week: no game found for this team and no stats
                    if not opponent and not game_date and stats is None:
                        # Grab the date from any game that week so it sorts correctly
                        any_game = next((g for g in games if isinstance(g, dict) and g.get("gameDate")), None)
                        bye_date = any_game.get("gameDate", "") if any_game else ""
                        game_logs.append({"week": week_num, "date": bye_date,
                            "opponent": "BYE", "fantasy_pts": None, "stats": None, "is_bye": True})
                        continue
                    if stats:
                        game_logs.append({"week": week_num, "date": game_date,
                            "opponent": f"@{opponent}" if is_away else opponent,
                            "fantasy_pts": _calc_pts(stats), "stats": _stats_dict(stats)})
                    else:
                        game_logs.append({"week": week_num, "date": game_date,
                            "opponent": f"@{opponent}" if is_away else opponent,
                            "fantasy_pts": None, "stats": None})
            else:
                # Fallback: no schedule files - show stats without opponent/date
                for week_num in sorted(stats_by_week.keys()):
                    stats = stats_by_week[week_num].get(player_id)
                    if stats:
                        game_logs.append({"week": week_num, "date": "",
                            "opponent": "", "fantasy_pts": _calc_pts(stats),
                            "stats": _stats_dict(stats)})
                    else:
                        game_logs.append({"week": week_num, "date": "",
                            "opponent": "", "fantasy_pts": None, "stats": None})

            if game_logs:
                game_logs.sort(key=lambda g: g.get("date", "") or "")
                game_logs_by_year[season_year] = game_logs

        # ── Upcoming projected season ─────────────────────────────────────────
        # Use the request `season` param as the upcoming year.  We do NOT use
        # max(available_years)+1 because sleeper_stats files may already exist
        # for the current season (e.g. 2026), pushing the calculation to 2027.
        _upcoming = season  # season already parsed from request.args above
        # Rookies drafted after the league's season year (e.g. 2026 draftees in
        # a 2025 league) have no stats and no projections for `season`, only for
        # `season+1`. Detect this and shift _upcoming so their projections show.
        if not game_logs_by_year:
            try:
                from utils.utils import path_week_proj
                import json as _pj_json
                # Read the week-1 file only if it already exists on disk
                # (no network fetch - just a cheap cache peek).
                def _peek_proj(yr: int) -> dict:
                    p = path_week_proj(yr, 1)
                    if not os.path.exists(p):
                        return {}
                    try:
                        with open(p) as _pf:
                            return _pj_json.load(_pf) or {}
                    except Exception:
                        return {}
                if not _peek_proj(_upcoming).get(player_id) and _peek_proj(_upcoming + 1).get(player_id):
                    _upcoming = _upcoming + 1
            except Exception:
                logger.debug("suppressed exception", exc_info=True)
        # Weeks already covered by actual stats - skip those when projecting
        _actual_weeks = {
            g.get("week") for g in (game_logs_by_year.get(_upcoming) or [])
            if not g.get("is_projection")
        }
        # Show projections if: no actual data yet (pre-season) OR some weeks
        # are still in the future (active season - fill the remaining weeks).
        if _upcoming not in game_logs_by_year or _actual_weeks:
            try:
                from utils.utils import pick_proj_variant, load_week_projection
                from statistics import median as _med_fn
                _variant = pick_proj_variant(scoring_settings)

                _proj_vals: dict = {}
                for _w in range(1, 19):
                    _wd = load_week_projection(_upcoming, _w) or {}
                    _v = _wd.get(player_id)
                    if isinstance(_v, dict):
                        _fv = float(_v.get(_variant) or _v.get("ppr") or 0)
                    elif isinstance(_v, (int, float)):
                        _fv = float(_v)
                    else:
                        _fv = 0.0
                    if _fv > 0.5:
                        _proj_vals[_w] = round(_fv, 2)

                # FP PPG fallback if no Tank01 weekly files
                if not _proj_vals:
                    _fp_path = os.path.join("cache", f"fp_projections_{_upcoming}_ppr.json")
                    try:
                        with open(_fp_path) as _fp_f:
                            _fp_data = json.load(_fp_f)
                        _fp_e = _fp_data.get(player_id)
                        if _fp_e:
                            _ppg = float(_fp_e.get("ppg") or 0)
                            if _ppg > 0:
                                for _w in range(1, 19):
                                    _proj_vals[_w] = round(_ppg, 2)
                    except FileNotFoundError:
                        logger.debug("suppressed exception", exc_info=True)

                if _proj_vals:
                    _mv = list(_proj_vals.values())
                    _med = _med_fn(_mv) if _mv else 0

                    # Load upcoming season schedule for opponent lookup
                    _sched: dict = {}
                    for _sf in glob.glob(os.path.join("cache", "schedule", f"schedule_s{_upcoming}_w*.json")):
                        try:
                            _fn = os.path.basename(_sf)
                            _wn = int(_fn.split('_w')[1].split('_')[0].split('.')[0])
                            with open(_sf) as _sff:
                                _sg = json.load(_sff)
                            if isinstance(_sg, list) and _wn not in _sched:
                                _sched[_wn] = _sg
                        except Exception:
                            logger.debug("suppressed exception", exc_info=True)

                    _proj_logs = []
                    for _w in range(1, 19):
                        if _w in _actual_weeks:
                            continue  # already have real stats for this week
                        _pv = _proj_vals.get(_w, _med if _med > 0 else None)
                        if _pv and _med > 0 and _pv < _med * 0.5:
                            _pv = _med

                        # Resolve opponent from schedule
                        _opp = "–"
                        _game_date = ""
                        for _g in (_sched.get(_w) or []):
                            if not isinstance(_g, dict):
                                continue
                            if player_team and player_team == _g.get("home"):
                                _opp = _g.get("away", "–")
                                _game_date = _g.get("gameDate", "")
                                break
                            elif player_team and player_team == _g.get("away"):
                                _opp = f"@{_g.get('home', '–')}"
                                _game_date = _g.get("gameDate", "")
                                break

                        _proj_logs.append({
                            "week": _w,
                            "date": _game_date or f"Wk {_w}",
                            "opponent": _opp,
                            "fantasy_pts": round(_pv, 2) if _pv else None,
                            "stats": None,
                            "is_projection": True,
                        })
                    if any(g["fantasy_pts"] for g in _proj_logs):
                        existing = game_logs_by_year.get(_upcoming) or []
                        # Merge: keep real games, append future projected weeks
                        combined = sorted(
                            existing + _proj_logs,
                            key=lambda g: g.get("week") or 0
                        )
                        game_logs_by_year[_upcoming] = combined
            except Exception as _proj_err:
                logger.debug(f"[game_logs] upcoming season projection failed: {_proj_err}")

        # ── Matchup difficulty per game ───────────────────────────────────────
        # Tag each game with the opponent defense's rank vs this position
        # (1 = easiest, same SoS-adjusted table the Schedule Assistant uses), so
        # the game log can show why a score was high or low. Only skill positions
        # have ratings; seasons without a table (or projections for a future
        # year) simply get no tag, leaving those rows uncolored.
        # Only annotate seasons that have a precomputed ratings file so we never
        # trigger the expensive fpts-against fallback in this per-request path;
        # _load_matchup_ratings is a cheap cached JSON read.
        _mpos = (player_meta.get("pos") or "").upper()
        if _mpos in ("QB", "RB", "WR", "TE"):
            from utils.schedule_ease import norm_sched_team as _norm_sched_team
            for _yr, _logs in game_logs_by_year.items():
                if not _load_matchup_ratings(int(_yr)):
                    continue
                try:
                    _rmap, _total, _info, _isz = _matchup_rank_table(int(_yr), _mpos)
                except Exception:
                    _rmap, _total = {}, 0
                if not _rmap or not _total:
                    continue
                for _g in _logs:
                    if _g.get("is_bye"):
                        continue
                    _opp = (_g.get("opponent") or "").lstrip("@").strip()
                    if not _opp or _opp == "BYE":
                        continue
                    _rk = _rmap.get(_norm_sched_team(_opp))
                    if _rk:
                        _g["opp_rank"] = _rk
                        _g["opp_total"] = _total

        # Cache the fully-computed result (bounded; evict oldest when full).
        if len(_GAME_LOGS_CACHE) >= _GAME_LOGS_CACHE_MAX:
            for _k in sorted(_GAME_LOGS_CACHE, key=lambda k: _GAME_LOGS_CACHE[k][0])[:_GAME_LOGS_CACHE_MAX // 10]:
                _GAME_LOGS_CACHE.pop(_k, None)
        _GAME_LOGS_CACHE[_cache_key] = (time.time(), game_logs_by_year)

        return jsonify({"game_logs_by_year": game_logs_by_year})
    except Exception as e:
        logger.exception("[api_player_game_logs] error")
        return _api_err("Request failed", e)


# Same sanitizer as _sanitize_for_json (utils/json_sanitize.py). This name
# previously only replaced NaN; it now also nulls infinities, which json.dumps
# would otherwise emit as invalid-JSON Infinity literals.
clean_nan_for_json = _sanitize_for_json


def _spark_svg(values, width: int = 132, height: int = 36, up=None) -> str:
    """Inline SVG sparkline from a list of numbers. ``up`` True=green, False=red,
    None=accent. Returns '' with fewer than two points."""
    pts = [float(v) for v in values if v is not None]
    if len(pts) < 2:
        return ""
    lo, hi = min(pts), max(pts)
    span = (hi - lo) or 1.0
    n = len(pts)
    pad = 3

    def _x(i):
        return pad + i * (width - 2 * pad) / (n - 1)

    def _y(v):
        return height - pad - (v - lo) / span * (height - 2 * pad)

    line = " ".join(f"{'M' if i == 0 else 'L'}{_x(i):.1f} {_y(v):.1f}"
                    for i, v in enumerate(pts))
    area = f"{line} L{_x(n - 1):.1f} {height} L{_x(0):.1f} {height} Z"
    cls = "up" if up is True else ("down" if up is False else "")
    ex, ey = _x(n - 1), _y(pts[-1])
    return (
        f"<svg class='tm-spark {cls}' width='{width}' height='{height}' "
        f"viewBox='0 0 {width} {height}' aria-hidden='true'>"
        f"<path class='tm-spark-fill' d='{area}'/>"
        f"<path class='tm-spark-line' d='{line}'/>"
        f"<circle class='tm-spark-cap' cx='{ex:.1f}' cy='{ey:.1f}' r='2.6'/></svg>"
    )


def _luck_series_for(df_weekly, owner) -> list:
    """[(week, cumulative luck_delta)] for one owner across finalized weeks."""
    try:
        fin = df_weekly[df_weekly["finalized"] == True]
        if fin.empty:
            return []
        weeks = sorted(int(w) for w in fin["week"].unique())
        from utils.all_play import all_play_analysis
        out = []
        for wk in weeks:
            sub = fin[fin["week"] <= wk]
            ws, aw = {}, {}
            for _, r in sub.iterrows():
                w = int(r["week"]); o = str(r["owner"])
                ws.setdefault(w, {})[o] = float(r["points"] or 0)
                aw[o] = aw.get(o, 0.0) + float(r["win"] or 0)
            ap = all_play_analysis(ws, aw)
            ld = (ap.get(str(owner)) or {}).get("luck_delta")
            if ld is not None:
                out.append((wk, float(ld)))
        return out
    except Exception:
        logger.debug("[team-trends] luck series failed", exc_info=True)
        return []


def _tm_delta_chip(delta, unit: str = "", up_is_good: bool = True) -> str:
    """Small ▲/▼ chip for a numeric week-over-week delta. '' when None/zero."""
    if delta is None:
        return ""
    try:
        d = float(delta)
    except (TypeError, ValueError):
        return ""
    if abs(d) < 0.05:
        return "<span class='tm-tr-chip flat'>&ndash;</span>"
    good = (d > 0) if up_is_good else (d < 0)
    cls = "up" if good else "down"
    arrow = "&#9650;" if d > 0 else "&#9660;"
    val = f"{abs(d):.1f}".rstrip("0").rstrip(".")
    return f"<span class='tm-tr-chip {cls}'>{arrow}{val}{unit}</span>"


def _build_team_trends_html(league_id, season, week, roster_id, owner,
                            df_weekly, total_value) -> str:
    """Trends block for the team modal's Graphs tab: seed movement this week,
    playoff-odds trend, roster-value trend, and luck trend. Every tile is
    independently best-effort and omitted when it has no data; returns '' when
    nothing is available."""
    tiles = []

    # #3 — seed movement this week (from the weekly results df; no snapshot).
    try:
        seed_mv = _standings_movement(df_weekly).get(str(owner))
        if seed_mv:
            chip = _tm_delta_chip(seed_mv, unit="", up_is_good=True)
            tiles.append(
                "<div class='tm-trend-tile'>"
                "<div class='tm-tr-label'>Seed this week</div>"
                f"<div class='tm-tr-lead'>{'Climbed' if seed_mv > 0 else 'Slipped'} "
                f"{abs(int(seed_mv))} {'spot' if abs(int(seed_mv)) == 1 else 'spots'} {chip}</div>"
                "</div>"
            )
    except Exception:
        logger.debug("[team-trends] seed movement failed", exc_info=True)

    # #1 — playoff-odds trend (read the weekly snapshots we now record).
    try:
        from dashboard_services.playoff_odds_history import get_series as _po_series
        po = _po_series(league_id, season, roster_id)
        if po["series"]:
            spark = _spark_svg([p["pct"] for p in po["series"]],
                               up=(po["delta"] or 0) >= 0)
            cur = po["current"]
            chip = _tm_delta_chip(po["delta"], unit=" pts", up_is_good=True)
            tiles.append(
                "<div class='tm-trend-tile'>"
                "<div class='tm-tr-label'>Playoff odds</div>"
                f"<div class='tm-tr-big'>{cur:.0f}%{chip}</div>"
                f"<div class='tm-tr-spark'>{spark}</div>"
                "</div>"
            )
    except Exception:
        logger.debug("[team-trends] playoff trend failed", exc_info=True)

    # #4 — roster value over time (snapshot the current week, read the series).
    try:
        from dashboard_services.team_value_history import record_and_series
        tv = record_and_series(league_id, season, week, roster_id,
                               total_value, write=(int(week or 0) >= 1))
        if tv["series"]:
            spark = _spark_svg([s["value"] for s in tv["series"]],
                               up=(tv["delta"] or 0) >= 0)
            chip = _tm_delta_chip(tv["delta"], unit="", up_is_good=True)
            tiles.append(
                "<div class='tm-trend-tile'>"
                "<div class='tm-tr-label'>Roster value</div>"
                f"<div class='tm-tr-big'>{tv['current']:,.0f}{chip}</div>"
                f"<div class='tm-tr-spark'>{spark}</div>"
                "</div>"
            )
    except Exception:
        logger.debug("[team-trends] value trend failed", exc_info=True)

    # #5 — luck trend (cumulative actual-minus-expected wins, from the df).
    try:
        luck_pts = _luck_series_for(df_weekly, owner)
        if len(luck_pts) >= 2:
            vals = [v for _w, v in luck_pts]
            spark = _spark_svg(vals, up=(vals[-1] >= 0))
            cur = vals[-1]
            sign = "+" if cur > 0 else ""
            tiles.append(
                "<div class='tm-trend-tile'>"
                "<div class='tm-tr-label'>Luck</div>"
                f"<div class='tm-tr-big'>{sign}{cur:.1f}<span class='tm-tr-unit'>wins</span></div>"
                f"<div class='tm-tr-spark'>{spark}</div>"
                "</div>"
            )
    except Exception:
        logger.debug("[team-trends] luck trend failed", exc_info=True)

    if not tiles:
        return ""
    return (
        "<div class='team-modal-section tm-trends'>"
        "<h3>Trends</h3>"
        "<div class='tm-trend-grid'>" + "".join(tiles) + "</div>"
        "</div>"
    )


@app.route("/api/team-details/<roster_id>")
def api_team_details(roster_id: str):
    """Get comprehensive team details for modal display."""
    try:
        from utils.utils import load_players_index, load_model_value_table
        from dashboard_services.api import get_nfl_state

        # Get league context
        league_id = request.args.get("league_id")
        platform = request.args.get("platform", "sleeper")
        season = request.args.get("season")

        if not league_id:
            return jsonify({"error": "league_id required"}), 400

        if not season:
            nfl_state = get_nfl_state()
            season = str(nfl_state.get("season") or datetime.now().year)

        season = int(season)

        # Get league data
        league = get_league(platform, league_id, season)
        rosters = get_rosters(platform, league_id, season) or []
        users = get_users(platform, league_id, season) or []
        _tep = te_premium_from_settings((league or {}).get("scoring_settings"))

        # Find the specific roster
        roster = next((r for r in rosters if str(r.get("roster_id")) == str(roster_id)), None)
        if not roster:
            return jsonify({"error": "Roster not found"}), 404

        # Get owner info
        owner_id = roster.get("owner_id")
        user = next((u for u in users if u.get("user_id") == owner_id), None)

        username = user.get("display_name") if user else None
        team_name = user.get("metadata", {}).get("team_name") if user else username
        avatar = avatar_from_users(platform, users, owner_id)
        if team_name is None:
            team_name = username

        # Get record
        settings = roster.get("settings") or {}
        wins = settings.get("wins", 0)
        losses = settings.get("losses", 0)
        ties = settings.get("ties", 0)

        record_str = f"{wins}-{losses}"
        if ties:
            record_str += f"-{ties}"

        # Get players with values
        players_index = load_players_index() or {}
        value_table = list(get_model_value_table_cached() or [])
        values_by_id = {str(row["id"]): row for row in value_table if isinstance(row, dict) and row.get("id")}

        player_ids = roster.get("players") or []
        starters = roster.get("starters") or []

        # Build roster with values
        roster_players = []
        total_value = 0.0

        ages_found = 0
        ages_missing = 0
        for pid in player_ids:
            pid_str = str(pid)
            player_meta = players_index.get(pid_str, {})
            value_row = values_by_id.get(pid_str, {})

            value = value_row.get("value", 0) or 0

            position = player_meta.get("pos") or ""
            if position == "PK":
                position = "K"
            elif position in ["DST", "D/ST"]:
                position = "DEF"

            # Special handling for defense players (team abbreviations as IDs)
            player_name = player_meta.get("name", "Unknown")
            player_team = player_meta.get("team")

            # If player_id is a team abbreviation and no metadata found, treat as defense
            if len(pid_str) == 3 and pid_str.isupper() and player_name == "Unknown":
                # This is likely a defense player with team ID
                full_team_name = get_team_full_name(pid_str)
                player_name = f"{full_team_name} Defense"
                position = "DEF"
                player_team = pid_str

            # Apply the league's TE premium now that position is finalized.
            value = apply_te_premium(value, position, _tep)
            total_value += float(value)

            # Compute precise decimal age from birthday (bDay) when available;
            # fall back to value table integer only when birthday is absent.
            age = age_from_bday(player_meta.get("bDay")) or value_row.get("age") or player_meta.get("age")
            if age is not None:
                ages_found += 1
            else:
                ages_missing += 1

            roster_players.append({
                "player_id": pid_str,
                "name": player_name,
                "position": position,
                "team": player_team,
                "age": age,
                "years_exp": player_meta.get("years_exp"),
                "value": round(float(value), 1) if value else None,
                "pos_rank_label": value_row.get("pos_rank_label"),
                "is_starter": pid_str in starters
            })

        # Sort by position order (QB, RB, WR, TE, K, DEF), then by value within position
        pos_order = {"QB": 0, "RB": 1, "WR": 2, "TE": 3, "K": 4, "DEF": 5}
        roster_players.sort(key=lambda p: (pos_order.get(p["position"], 99), -(p["value"] or 0)))

        # Get draft picks
        traded_picks = get_traded_picks(platform, league_id, season)
        num_rounds = int((league.get("settings") or {}).get("draft_rounds", 4))
        current_season = int(league.get("season") or season)
        _modal_draft_ended = has_draft_ended(league_id, platform, season)
        _modal_pick_start = 1 if _modal_draft_ended else 0

        # Build picks
        all_picks = []
        for offset in range(_modal_pick_start, _modal_pick_start + 3):  # Next 3 years
            year = current_season + offset
            for rnd in range(1, num_rounds + 1):

                # Collect all picks this team owns for this year/round
                owned_picks = []

                # First check: All picks this team acquired from other teams
                for tp in traded_picks:
                    try:
                        if (int(tp.get("season")) == year and
                                int(tp.get("round")) == rnd and
                                int(tp.get("owner_id")) == int(roster_id)):
                            # This team acquired this pick from another team
                            owned_picks.append({
                                "current_owner": int(tp.get("owner_id")),
                                "original_owner": int(tp.get("roster_id")),
                                "previous_owner": int(tp.get("previous_owner_id")),
                                "trade_data": tp
                            })
                    except Exception:
                        logger.debug("suppressed exception", exc_info=True)

                # Second check: This team's own draft position pick (only if not already found as acquired)
                own_position_found = any(p["original_owner"] == int(roster_id) for p in owned_picks)
                if not own_position_found:
                    for tp in traded_picks:
                        try:
                            if (int(tp.get("season")) == year and
                                    int(tp.get("round")) == rnd and
                                    int(tp.get("roster_id")) == int(roster_id)):
                                # This pick belongs to this roster's draft position
                                owned_picks.append({
                                    "current_owner": int(tp.get("owner_id")),
                                    "original_owner": int(tp.get("roster_id")),
                                    "previous_owner": int(tp.get("previous_owner_id")),
                                    "trade_data": tp
                                })
                                break
                        except Exception:
                            logger.debug("suppressed exception", exc_info=True)

                # If no traded picks found, check if this team owns their own pick by default
                # BUT also check if we should add the default pick in addition to acquired picks
                own_position_as_acquired = any(p["original_owner"] == int(roster_id) for p in owned_picks)

                if not own_position_as_acquired:
                    # This team owns their own pick unless it was traded away
                    pick_traded_away = False
                    for tp in traded_picks:
                        try:
                            if (int(tp.get("season")) == year and
                                    int(tp.get("round")) == rnd and
                                    int(tp.get("roster_id")) == int(roster_id) and
                                    int(tp.get("owner_id")) != int(roster_id)):
                                pick_traded_away = True
                                break
                        except Exception:
                            logger.debug("suppressed exception", exc_info=True)

                    if not pick_traded_away:
                        owned_picks.append({
                            "current_owner": int(roster_id),
                            "original_owner": int(roster_id),
                            "previous_owner": None,
                            "trade_data": None
                        })

                # Add all owned picks to the list
                for pick_info in owned_picks:
                    if pick_info["current_owner"] == int(roster_id):
                        via = None
                        original_owner = pick_info["original_owner"]

                        if original_owner != int(roster_id):
                            # Always show the team whose draft slot this pick originates from.
                            # Using previous_owner (last trader) was wrong when a pick changes
                            # hands more than once - multiple picks could share the same
                            # previous_owner while having different original owners.
                            via_roster = next((r for r in rosters if r.get("roster_id") == original_owner), None)
                            if via_roster:
                                via_owner_id = via_roster.get("owner_id")
                                via_user = next((u for u in users if u.get("user_id") == via_owner_id), None)
                                via = via_user.get("display_name") if via_user else f"Team {original_owner}"

                        all_picks.append({
                            "year": year,
                            "round": rnd,
                            "via": via,
                            "original_owner": pick_info["original_owner"],
                        })

        # Sort picks by year then round
        all_picks.sort(key=lambda p: (p["year"], p["round"]))

        # Add pick values to total (match offseason snapshot calculation)
        try:
            from dashboard_services.picks import load_pick_value_table
            pick_by_key = load_pick_value_table() or {}
            picks_for_value = [
                {"season": p["year"], "round": p["round"], "original_owner": p.get("original_owner")}
                for p in all_picks
            ]
            total_value += _team_pick_value(picks_for_value, pick_by_key, platform=platform,
                                            league_id=league_id, season=season)
        except Exception:
            logger.debug("suppressed exception", exc_info=True)

        # Get graph data for team modal
        graphs_data = {}
        try:
            from utils.utils import z_better_outward
            import pandas as pd
            from dashboard_services.api import get_nfl_state

            # Check if we're in offseason and should use previous season data
            nfl_state = get_nfl_state() or {}
            current_nfl_season = int(nfl_state.get("season", current_season))
            season_type = str(nfl_state.get("season_type", "")).lower().strip()

            # Determine which season to use for graphs
            graph_season = current_season
            if current_nfl_season > int(season) and season_type in {"offseason", "pre"}:
                # We're in offseason before current season has started, use previous season data
                graph_season = int(season) - 1
            elif current_nfl_season == int(season) and season_type == "offseason":
                # Current season is over, use completed season data
                graph_season = int(season)
            elif season_type in {"offseason", "pre"}:
                # We're in some form of offseason, try previous season
                graph_season = int(season) - 1


            # Get league context for graphs
            ctx = get_league_ctx_from_cache(platform, league_id, graph_season)
            team_stats = ctx.get("team_stats")
            df_weekly = ctx.get("df_weekly")

            if df_weekly is not None and not df_weekly.empty:
                logger.info(f"[api_team_details] df_weekly shape: {df_weekly.shape}")

            # If we don't have weekly data for the chosen season, try previous season
            if (df_weekly is None or df_weekly.empty) and graph_season > 2025:
                fallback_season = graph_season - 1

                # Resolve correct league_id for fallback season
                from dashboard_services.api import resolve_league_id_for_season
                fallback_league_id = resolve_league_id_for_season(
                    platform=platform,
                    league_id=league_id,
                    current_season=current_season,
                    target_season=fallback_season
                )

                ctx = get_league_ctx_from_cache(platform, fallback_league_id, fallback_season)
                team_stats = ctx.get("team_stats")
                df_weekly = ctx.get("df_weekly")
                graph_season = fallback_season
                if df_weekly is not None and not df_weekly.empty:
                    logger.info(f"[api_team_details] Fallback df_weekly shape: {df_weekly.shape}")

            # Remove debug prints for cleaner logs
            if team_stats is not None and df_weekly is not None and not df_weekly.empty:
                # Filter to finalized weeks only (if finalized column exists)
                if "finalized" in df_weekly.columns:
                    df_weekly = df_weekly[df_weekly["finalized"] == True].copy()

                # Only build graphs if we have data after filtering
                if not df_weekly.empty:
                    # Get weekly scores for this team
                    team_weekly = df_weekly[df_weekly["owner"] == team_name] if team_name is not None else pd.DataFrame()
                    weekly_scores = []
                    if not team_weekly.empty:
                        for _, row in team_weekly.sort_values("week").iterrows():
                            weekly_scores.append({
                                "week": int(row["week"]),
                                "points": round(float(row["points"]), 1)
                            })

                    # Get league average weekly scores
                    league_avg = df_weekly.groupby("week")["points"].mean().reset_index()
                    league_avg_scores = []
                    for _, row in league_avg.iterrows():
                        league_avg_scores.append({
                            "week": int(row["week"]),
                            "points": round(float(row["points"]), 1)
                        })

                    # League-wide SVG scatters (same renderers as the Graphs
                    # page), highlighting this team. Server-rendered so the modal
                    # can inject them directly without loading Plotly.
                    league_luck_svg = ""
                    league_value_age_svg = ""
                    # Shared per-team colors so the two modal scatters agree.
                    _oc = {}
                    try:
                        from dashboard_services.pages.graphs_page import owner_color_map
                        _rmap = ctx.get("roster_map") or {}
                        _oc = owner_color_map([
                            str(_rmap.get(str(r.get("roster_id"))) or f"Roster {r.get('roster_id')}")
                            for r in rosters
                        ])
                    except Exception:
                        _rmap = ctx.get("roster_map") or {}

                    # Luck: from the resolved season's finalized weeks.
                    try:
                        from utils.standings_viz import luck_quadrant_svg
                        from utils.all_play import all_play_analysis
                        _ws: dict = {}
                        _aw: dict = {}
                        for _, _r in df_weekly.iterrows():
                            _wk = int(_r["week"])
                            _o = str(_r["owner"])
                            _ws.setdefault(_wk, {})[_o] = float(_r["points"] or 0)
                            _aw[_o] = _aw.get(_o, 0.0) + float(_r.get("win") or 0)
                        league_luck_svg = luck_quadrant_svg(all_play_analysis(_ws, _aw), team_name or "", _oc)
                    except Exception:
                        logger.warning("team-modal luck scatter failed", exc_info=True)

                    # Value/age: current rosters + live value table (the graph
                    # season's ctx can carry a stale or empty value table).
                    try:
                        from utils.standings_viz import value_age_svg
                        from dashboard_services.ai.context_builders import team_value_age_rows
                        _val_ctx = {
                            "rosters": rosters,
                            "roster_map": _rmap,
                            "model_value_table": get_model_value_table_cached() or ctx.get("model_value_table") or [],
                            "players_index": ctx.get("players_index") or (get_players_index_global() or {}),
                            "players_map": ctx.get("players_map") or {},
                            "roster_positions": ctx.get("roster_positions") or (league or {}).get("roster_positions") or [],
                        }
                        league_value_age_svg = value_age_svg(team_value_age_rows(_val_ctx), team_name or "", _oc)
                    except Exception:
                        logger.warning("team-modal value/age scatter failed", exc_info=True)

                    # Get z-scores for radar chart
                    metrics = ["PF", "PA", "MAX", "MIN", "AVG", "STD"]
                    Z = z_better_outward(team_stats, metrics)

                    # Find this team's row in team_stats
                    if team_stats is not None:
                        available_teams = team_stats["owner"].tolist() if "owner" in team_stats.columns else []

                    # Try exact match first
                    team_row = team_stats[team_stats["owner"] == team_name] if team_name is not None else pd.DataFrame()

                    # If no exact match, try fuzzy matching for team name variations
                    if team_row.empty and available_teams and team_name is not None:
                        # Try case-insensitive match
                        team_row = team_stats[team_stats["owner"].str.lower() == team_name.lower()]

                        # If still no match, try partial matching (handle team name changes)
                        if team_row.empty:
                            for available_team in available_teams:
                                # Remove special characters and convert to lowercase for comparison
                                clean_available = ''.join(c.lower() for c in available_team if c.isalnum())
                                clean_target = ''.join(c.lower() for c in team_name if c.isalnum())

                                if clean_available in clean_target or clean_target in clean_available:
                                    team_row = team_stats[team_stats["owner"] == available_team]
                                    break

                    if not team_row.empty:
                        team_idx = team_row.index[0]
                        z_scores = Z.iloc[team_idx].values.astype(float).tolist()

                        # Get raw stats too
                        raw_stats = {}
                        for metric in metrics:
                            raw_stats[metric] = round(float(team_row[metric].iloc[0]), 1)

                        graphs_data = {
                            "weekly_scores": weekly_scores,
                            "league_avg_scores": league_avg_scores,
                            "radar": {
                                "metrics": metrics,
                                "z_scores": z_scores,
                                "raw_stats": raw_stats
                            },
                            "luck_svg": league_luck_svg,
                            "value_age_svg": league_value_age_svg,
                            "season_used": graph_season  # Add info about which season data was used
                        }
                    else:
                        logger.info(f"[api_team_details] No graphs generated - team_row is empty for team_name='{team_name}'") if team_name is not None else logger.info("[api_team_details] No graphs generated - team_row is empty for team_name='None'")
                else:
                    logger.info(f"[api_team_details] No graphs generated - df_weekly is empty after filtering")
            else:
                print(
                    f"[api_team_details] No graphs generated - team_stats: {team_stats is not None}, df_weekly: {df_weekly is not None and not df_weekly.empty}")
        except Exception as graph_err:
            logger.warning("[api_team_details] Error getting graph data: %s", graph_err)
            import traceback
            traceback.print_exc()
            # Continue without graph data

        # Team trends for the Graphs tab (seed movement, playoff odds, roster
        # value, luck). Only in-season — when the graphs fell back to a prior
        # season, "this week" movement isn't meaningful. Best-effort throughout.
        trends_html = ""
        try:
            _dfw = locals().get("df_weekly")
            _gseason = int(locals().get("graph_season", season) or season)
            if _dfw is not None and not _dfw.empty and _gseason == int(season):
                _tw = 0
                if "finalized" in _dfw.columns:
                    _ff = _dfw[_dfw["finalized"] == True]
                    if not _ff.empty:
                        _tw = int(_ff["week"].max())
                trends_html = _build_team_trends_html(
                    league_id, int(season), _tw, roster_id, team_name,
                    _dfw, total_value)
        except Exception:
            logger.debug("[api_team_details] trends skipped", exc_info=True)

        response = {
            "roster_id": roster_id,
            "team_name": team_name,
            "username": username,
            "avatar": avatar,
            "record": record_str,
            "wins": wins,
            "losses": losses,
            "ties": ties,
            "total_value": round(total_value, 1),
            "roster": roster_players,
            "picks": all_picks,
            "graphs": graphs_data,
            "trends_html": trends_html,
        }

        # Clean NaN values before JSON serialization
        cleaned_response = clean_nan_for_json(response)
        return jsonify(cleaned_response)

    except Exception as e:
        logger.exception("[api_team_details] Error")
        import traceback
        traceback.print_exc()
        return _api_err("Request failed", e)



@app.route("/api/team-trades/<roster_id>")
def api_team_trades(roster_id: str):
    """Return all trades for a specific team in the current league season."""
    try:
        from dashboard_services.service import get_transactions_by_week
        from utils.utils import load_players_index

        league_id = request.args.get("league_id")
        platform = request.args.get("platform", "sleeper")
        season = int(request.args.get("season") or datetime.now().year)

        if not league_id:
            return jsonify({"error": "league_id required"}), 400

        players_index = load_players_index() or {}

        weeks = list(range(1, 19))
        tx_by_week = get_transactions_by_week(league_id, weeks, platform=platform, season=season) or {}

        def _pinfo(pid):
            meta = players_index.get(str(pid)) or {}
            return {
                "player_id": str(pid),
                "name": meta.get("name") or str(pid),
                "position": meta.get("pos") or "",
            }

        trades = []
        for week in sorted(tx_by_week):
            for t in (tx_by_week[week] or []):
                if t.get("type") != "trade":
                    continue

                adds = t.get("adds") or {}
                drops = t.get("drops") or {}
                draft_picks = t.get("draft_picks") or []
                base_rids = set(str(r) for r in (t.get("roster_ids") or []))
                all_rids = base_rids | {str(v) for v in adds.values()} | {str(v) for v in drops.values()}

                if str(roster_id) not in all_rids:
                    continue

                ts_raw = t.get("status_updated") or t.get("created")
                date_str = ""
                if ts_raw:
                    from datetime import timezone as _tz
                    _dt = datetime.fromtimestamp(ts_raw / 1000.0, tz=_tz.utc)
                    date_str = _dt.strftime("%-m/%-d/%y")

                my_gets = [_pinfo(pid) for pid, to_rid in adds.items() if str(to_rid) == str(roster_id)]
                my_sends = [_pinfo(pid) for pid, from_rid in drops.items() if str(from_rid) == str(roster_id)]
                my_pick_gets = [p for p in draft_picks if str(p.get("owner_id")) == str(roster_id)]
                my_pick_sends = [p for p in draft_picks if str(p.get("previous_owner_id")) == str(roster_id)]

                trades.append({
                    "week": week,
                    "date": date_str,
                    "my_gets": my_gets,
                    "my_sends": my_sends,
                    "my_pick_gets": my_pick_gets,
                    "my_pick_sends": my_pick_sends,
                })

        trades.sort(key=lambda x: x["week"], reverse=True)
        return jsonify({"trades": trades, "total": len(trades)})

    except Exception as e:
        import traceback; traceback.print_exc()
        return _api_err("Request failed", e)


@app.route("/api/draft-needs")
def api_draft_needs():
    """
    Returns positional needs for a team relative to league averages.
    Uses the same weighted positional strength + z-score approach as the Teams page.
    Need levels: -2 stacked, -1 depth, 0 neutral, 1 need, 2 major need.
    """
    try:
        from utils.utils import load_players_index, load_model_value_table
        league_id = request.args.get("league_id")
        platform  = request.args.get("platform", "sleeper")
        season    = int(request.args.get("season") or datetime.now().year)
        roster_id = request.args.get("roster_id") or ""

        # Fall back to the session viewer when roster_id is absent or the sentinel
        if not roster_id or roster_id == "viewer":
            roster_id = session.get("viewer_roster_id") or ""

        if not league_id or not roster_id:
            return jsonify({"error": "league_id and roster_id required"}), 400

        rosters = get_rosters(platform, league_id, season) or []
        league  = get_league(platform, league_id, season) or {}
        players_index = load_players_index() or {}
        value_table   = list(get_model_value_table_cached() or [])

        roster_positions = (league.get("roster_positions") or [])
        is_sf  = any(str(s).upper() in {"SUPER_FLEX", "SFLEX"} for s in roster_positions)
        vfield = "sf_value" if is_sf else "value"

        values_by_id = {str(r["id"]): r for r in value_table if isinstance(r, dict) and r.get("id")}

        CORE = ("QB", "RB", "WR", "TE")

        # Count roster slots for _weighted_pos_strength
        slot_counts: dict[str, int] = {}
        for rp in roster_positions:
            rp_str = str(rp).upper()
            slot_counts[rp_str] = slot_counts.get(rp_str, 0) + 1

        # Build per-roster positional value lists (same as teams page)
        roster_pos_vals: dict[str, dict[str, list]] = {}
        for r in rosters:
            rid = str(r.get("roster_id", ""))
            pv: dict[str, list] = {p: [] for p in CORE}
            for pid in (r.get("players") or []):
                meta = players_index.get(str(pid)) or {}
                pos  = str(meta.get("pos") or "").upper()
                if pos not in CORE:
                    continue
                vrow = values_by_id.get(str(pid)) or {}
                val  = float(vrow.get(vfield) or vrow.get("value") or 0)
                pv[pos].append(val)
            roster_pos_vals[rid] = pv

        if not roster_pos_vals:
            return jsonify({"needs": {}, "league_type": "sf" if is_sf else "1qb"})

        # Compute weighted positional strength per roster (mirrors _weighted_pos_strength)
        roster_strength: dict[str, dict[str, float]] = {}
        for rid, pv in roster_pos_vals.items():
            roster_strength[rid] = {
                pos: _weighted_pos_strength(pv[pos], pos, slot_counts)
                for pos in CORE
            }

        # League avg + std per position
        import math
        n = len(roster_strength)
        league_avg = {pos: sum(rv[pos] for rv in roster_strength.values()) / n for pos in CORE}
        league_std = {}
        for pos in CORE:
            variance = sum((rv[pos] - league_avg[pos]) ** 2 for rv in roster_strength.values()) / n
            league_std[pos] = math.sqrt(variance) if variance > 0 else 1.0

        viewer = roster_strength.get(str(roster_id), {p: 0.0 for p in CORE})

        needs: dict = {}
        for pos in CORE:
            mu    = league_avg[pos]
            sigma = league_std[pos]
            z     = (viewer[pos] - mu) / sigma if sigma > 0 else 0.0
            # Map z-score to need level (same thresholds as teams page z-score usage)
            if   z >= 1.0:  level = -2   # stacked
            elif z >= 0.35: level = -1   # depth
            elif z >= -0.35:level =  0   # neutral
            elif z >= -1.0: level =  1   # need
            else:           level =  2   # major need
            needs[pos]              = level
            needs[f"{pos}_count"]   = len(roster_pos_vals.get(str(roster_id), {}).get(pos, []))
            needs[f"{pos}_value"]   = round(viewer[pos], 1)
            needs[f"{pos}_avg"]     = round(league_avg[pos], 1)

        return jsonify({
            "needs": needs,
            "league_type": "sf" if is_sf else "1qb",
            "league_size": len(rosters),
        })

    except Exception as e:
        import traceback; traceback.print_exc()
        return _api_err("Request failed", e)


