@app.route("/api/rivalry/<platform>/<int:season>/<league_id>")
def api_rivalry(platform: str, season: int, league_id: str):
    """All-time head-to-head record between two managers (by user_id).

    Scans every available historical season plus the current one, pairs
    finalized matchup rows by (week, matchup_id), and returns the full
    meeting list so the frontend can render record, streaks, and blowouts.
    """
    a = (request.args.get("a") or "").strip()
    b = (request.args.get("b") or "").strip()
    if not a or not b or a == b:
        return jsonify({"error": "Pick two different managers."}), 400

    try:
        available = get_available_history_seasons(platform, league_id, season) or []
    except Exception:
        available = []
    seasons_to_scan = sorted(set(int(s) for s in available) | {int(season)})

    games = []
    for hist_s in seasons_to_scan:
        try:
            rid = resolve_league_id_for_season(platform, league_id, season, hist_s)
            ctx = get_league_ctx_from_cache(platform, rid, hist_s)
        except Exception:
            continue

        df = ctx.get("df_weekly", pd.DataFrame())
        if df.empty or "matchup_id" not in df.columns or "roster_id" not in df.columns:
            continue

        roster_to_uid = {
            str(r.get("roster_id")): str(r.get("owner_id") or "")
            for r in (ctx.get("rosters") or [])
        }

        d = df.copy()
        if "finalized" in d.columns:
            d = d[d["finalized"] == True]  # noqa: E712
        d["__uid"] = d["roster_id"].astype(str).map(roster_to_uid)
        sub = d[d["__uid"].isin([a, b])]
        if sub.empty:
            continue

        for (wk, mid), grp in sub.groupby(["week", "matchup_id"]):
            if pd.isna(mid) or len(grp) != 2:
                continue
            if set(grp["__uid"]) != {a, b}:
                continue
            row_a = grp[grp["__uid"] == a].iloc[0]
            row_b = grp[grp["__uid"] == b].iloc[0]
            pts_a = float(row_a.get("points") or 0)
            pts_b = float(row_b.get("points") or 0)
            if pts_a == 0 and pts_b == 0:
                continue  # unplayed/empty matchup
            games.append({
                "season": int(hist_s),
                "week": int(wk),
                "a_pts": round(pts_a, 2),
                "b_pts": round(pts_b, 2),
            })

    games.sort(key=lambda g: (g["season"], g["week"]))
    wins_a = sum(1 for g in games if g["a_pts"] > g["b_pts"])
    wins_b = sum(1 for g in games if g["b_pts"] > g["a_pts"])
    return jsonify({
        "games": games,
        "wins_a": wins_a,
        "wins_b": wins_b,
        "ties": len(games) - wins_a - wins_b,
        "pts_a": round(sum(g["a_pts"] for g in games), 2),
        "pts_b": round(sum(g["b_pts"] for g in games), 2),
    })


@app.route("/api/espn-validate-league")
def api_espn_validate_league():
    """
    Validate an ESPN league ID and return basic league info.
    Used by the landing page ESPN flow.
    """
    league_id = (request.args.get("league_id") or "").strip()
    if not league_id or not league_id.isdigit():
        return jsonify({"ok": False, "error": "Invalid ESPN league ID. Must be a number."}), 400

    nfl_state = get_nfl_state() or {}
    season = int(request.args.get("season") or nfl_state.get("season") or datetime.now().year)

    try:
        from dashboard_services.providers.espn_api import get_league as espn_get_league
        info = espn_get_league(season, league_id)
        return jsonify({
            "ok": True,
            "league": {
                "league_id": info.get("league_id"),
                "name": info.get("name") or f"ESPN League {league_id}",
                "season": info.get("season"),
            },
        })
    except Exception as e:
        # Map the espn_api library's typed errors to clear, actionable messages.
        # ESPNAccessDenied = 401 (private league + missing/wrong/expired cookies);
        # ESPNInvalidLeague = 404 (league id or season not found).
        from dashboard_services.providers.espn_api import espn_diagnostics
        diag = espn_diagnostics()
        creds_present = diag["espn_s2_present"] and diag["espn_swid_present"]
        name = type(e).__name__

        if name == "ESPNAccessDenied":
            if not creds_present:
                err = ("This is a private ESPN league, but the server has no "
                       "ESPN_S2 / ESPN_SWID set. Add them as environment variables "
                       "and redeploy.")
            else:
                err = ("ESPN rejected the ESPN_S2 / ESPN_SWID cookies. They may be "
                       "for a different ESPN account, expired, or copied with extra "
                       "characters — re-copy both from espn.com and update the env "
                       "vars.")
            return jsonify({"ok": False, "error": err, "diagnostics": diag}), 403

        if name == "ESPNInvalidLeague":
            err = (f"ESPN couldn't find league {league_id} for {season}. Check the "
                   f"league ID, and that the {season} season exists for this league "
                   f"(it may not have rolled over yet).")
            return jsonify({"ok": False, "error": err, "diagnostics": diag}), 404

        return jsonify({
            "ok": False,
            "error": f"Could not load ESPN league: {e}",
            "diagnostics": diag,
        }), 500


@app.route("/api/espn-debug")
def api_espn_debug():
    """Read-only diagnostics for a 'my private ESPN league won't load' report.

    Reports whether the server can see ESPN_S2 / ESPN_SWID (presence + length
    only — never the values) and, if a league_id is given, the exact result of
    trying to load it. Hit /api/espn-debug?league_id=<id>[&season=<yr>].
    """
    from dashboard_services.providers.espn_api import espn_diagnostics
    out = {"diagnostics": espn_diagnostics()}

    league_id = (request.args.get("league_id") or "").strip()
    if league_id.isdigit():
        nfl_state = get_nfl_state() or {}
        season = int(request.args.get("season") or nfl_state.get("season") or datetime.now().year)
        try:
            from dashboard_services.providers.espn_api import get_league as espn_get_league
            info = espn_get_league(season, league_id)
            out["league_load"] = {"ok": True, "season": season, "name": info.get("name")}
        except Exception as e:
            out["league_load"] = {
                "ok": False,
                "season": season,
                "error_type": type(e).__name__,
                "error": str(e)[:300],
            }
    return jsonify(out)


@app.route("/api/beat-the-market")
def api_beat_the_market():
    """
    For each roster in a league, compute the sum of 30-day player value deltas
    and compare it to the league-average delta over the same window.

    A positive 'vs_avg' means the roster gained more value than a typical roster.

    Query params: platform, league_id, season, days (default 30), league_type, league_size
    """
    platform = (request.args.get("platform") or "sleeper").strip().lower()
    league_id = (request.args.get("league_id") or "").strip()
    if not league_id:
        return jsonify({"error": "league_id required"}), 400

    nfl_state = get_nfl_state() or {}
    try:
        season = int(request.args.get("season") or nfl_state.get("season") or datetime.now().year)
    except (TypeError, ValueError):
        season = datetime.now().year

    try:
        days = max(1, int(request.args.get("days", 30)))
    except (TypeError, ValueError):
        days = 30

    league_type = str(request.args.get("league_type", "1qb")).strip().lower()
    try:
        league_size = int(request.args.get("league_size", 10))
        if league_size not in [8, 10, 12, 14]:
            league_size = 10
    except (TypeError, ValueError):
        league_size = 10

    try:
        # Determine the right value field
        if league_type == "sf" and league_size != 10:
            value_expr = f"COALESCE(sf_value_{league_size}, sf_value, value)"
        elif league_type == "sf":
            value_expr = "COALESCE(sf_value, value)"
        elif league_size != 10:
            value_expr = f"COALESCE(value_{league_size}, value)"
        else:
            value_expr = "value"

        from data_building.player_value_history import init_value_history_db, get_latest_snapshot_date
        from dashboard_services.db import get_conn
        from datetime import timedelta as _td

        init_value_history_db()
        latest_date = get_latest_snapshot_date(source="model")
        if not latest_date:
            return jsonify({"error": "No value history available"}), 404

        from datetime import date as _date
        if isinstance(latest_date, _date):
            latest_date_obj = latest_date
        else:
            latest_date_obj = _date.fromisoformat(str(latest_date))

        # Find the closest baseline date within the requested window
        from dashboard_services.db import get_conn
        baseline_date = None
        with get_conn() as conn:
            for candidate_days in range(days, 0, -1):
                target = latest_date_obj - _td(days=candidate_days)
                row = conn.execute(
                    "SELECT MAX(as_of_date) AS d FROM player_value_history "
                    "WHERE source = 'model' AND as_of_date <= %s",
                    (target,)
                ).fetchone()
                if row and row["d"] and row["d"] < latest_date_obj:
                    baseline_date = row["d"]
                    break

        if not baseline_date:
            return jsonify({"error": "Insufficient history for requested window"}), 404

        # Fetch deltas for all players in one query
        with get_conn() as conn:
            rows = conn.execute(
                f"""
                WITH latest AS (
                    SELECT DISTINCT ON (player_id) player_id,
                           {value_expr} AS val
                    FROM player_value_history
                    WHERE source = 'model' AND as_of_date = %s
                    ORDER BY player_id, as_of_date DESC
                ),
                baseline AS (
                    SELECT DISTINCT ON (player_id) player_id,
                           {value_expr} AS val
                    FROM player_value_history
                    WHERE source = 'model' AND as_of_date = %s
                    ORDER BY player_id, as_of_date DESC
                )
                SELECT l.player_id,
                       ROUND((l.val - b.val)::numeric, 1) AS delta
                FROM latest l
                JOIN baseline b ON b.player_id = l.player_id
                """,
                (latest_date_obj, baseline_date)
            ).fetchall()

        delta_by_pid = {str(r["player_id"]): float(r["delta"]) for r in rows}

        # Fetch rosters
        rosters = get_rosters(platform, league_id, season) or []
        roster_map = _build_roster_map(
            get_users(platform, league_id, season) or [],
            rosters
        )

        # Aggregate per roster (only QB/RB/WR/TE players, ignore picks/K/DEF)
        CORE_POS = {"QB", "RB", "WR", "TE"}
        players_index = load_players_index() or {}

        roster_totals: dict = {}
        for r in rosters:
            rid = str(r.get("roster_id", ""))
            players_on_roster = r.get("players") or []
            total_delta = 0.0
            player_deltas = []
            for pid in players_on_roster:
                meta = players_index.get(str(pid), {})
                pos = str(meta.get("pos", "")).upper()
                if pos not in CORE_POS:
                    continue
                d = delta_by_pid.get(str(pid), 0.0)
                total_delta += d
                if abs(d) >= 5:
                    player_deltas.append({
                        "player_id": str(pid),
                        "name": meta.get("name", str(pid)),
                        "position": pos,
                        "delta": d,
                    })
            player_deltas.sort(key=lambda x: abs(x["delta"]), reverse=True)
            roster_totals[rid] = {
                "roster_id": rid,
                "team_name": roster_map.get(rid, f"Roster {rid}"),
                "total_delta": round(total_delta, 1),
                "top_movers": player_deltas[:5],
            }

        # Compute league average delta
        all_deltas = [v["total_delta"] for v in roster_totals.values()]
        avg_delta = round(sum(all_deltas) / len(all_deltas), 1) if all_deltas else 0.0

        # Add vs_avg
        results = []
        for rid, entry in roster_totals.items():
            results.append({
                **entry,
                "vs_avg": round(entry["total_delta"] - avg_delta, 1),
            })

        results.sort(key=lambda x: x["vs_avg"], reverse=True)

        def _iso(d) -> str:
            return d.isoformat() if hasattr(d, "isoformat") else str(d)

        return jsonify({
            "latest_date": _iso(latest_date_obj),
            "baseline_date": _iso(baseline_date),
            "league_avg_delta": avg_delta,
            "rosters": results,
        })

    except Exception:
        logger.exception("[beat-the-market] Unexpected error")
        return jsonify({"error": "Internal error"}), 500


@app.route("/api/schedule-strength")
def api_schedule_strength():
    """
    Compute schedule strength remaining for each team in a league.

    For each team's future matchups (weeks > current_week), look up their
    opponent's average points scored this season. The team with the hardest
    remaining schedule faces the highest-scoring opponents on average.

    Query params: platform, league_id, season
    """
    platform = (request.args.get("platform") or "sleeper").strip().lower()
    league_id = (request.args.get("league_id") or "").strip()
    if not league_id:
        return jsonify({"error": "league_id required"}), 400

    nfl_state = get_nfl_state() or {}
    try:
        season = int(request.args.get("season") or nfl_state.get("season") or datetime.now().year)
    except (TypeError, ValueError):
        season = datetime.now().year

    current_week = int(nfl_state.get("leg") or nfl_state.get("week") or 0)
    season_type = str(nfl_state.get("season_type") or "").lower()
    FULL_SEASON_WEEKS = 17  # safe scan cap; loop breaks on empty weeks

    try:
        from dashboard_services.platform_api import get_matchups as pf_get_matchups

        rosters = get_rosters(platform, league_id, season) or []
        users = get_users(platform, league_id, season) or []
        roster_map = _build_roster_map(users, rosters)

        # Build per-roster average points from completed weeks
        avg_pts_by_rid: dict[str, float] = {}
        weekly_pts: dict[str, list] = {str(r.get("roster_id")): [] for r in rosters}

        for w in range(1, current_week + 1):
            try:
                week_data = pf_get_matchups(platform, league_id, w, season) or []
            except Exception:
                continue
            for m in week_data:
                rid = str(m.get("roster_id", ""))
                pts = float(m.get("points") or 0.0)
                if rid in weekly_pts:
                    weekly_pts[rid].append(pts)

        for rid, pts_list in weekly_pts.items():
            avg_pts_by_rid[rid] = round(sum(pts_list) / len(pts_list), 2) if pts_list else 0.0

        # When no games have been played, fall back to power rankings (roster value) as proxy
        games_played = sum(1 for pts in avg_pts_by_rid.values() if pts > 0)
        if games_played == 0:
            try:
                ctx = get_league_ctx_from_cache(platform, league_id, season)
                model_vals = ctx.get("model_value_table") or []
                picks_by_roster = ctx.get("picks_by_roster") or {}
                values_by_id = {str(p["id"]): float(p.get("value") or 0) for p in model_vals if p.get("id")}
                pick_values = load_pick_value_table() or {}
                standings_map = ctx.get("standings_map") or {}
                for r in rosters:
                    rid = str(r.get("roster_id", ""))
                    player_ids = [str(pid) for pid in (r.get("players") or [])]
                    roster_val = sum(values_by_id.get(pid, 0.0) for pid in player_ids)
                    # Normalize to a "projected points" scale (~100-160 range) for display consistency
                    avg_pts_by_rid[rid] = round(100.0 + roster_val / 50.0, 2)
            except Exception:
                logger.debug("suppressed exception", exc_info=True)

        # Build future matchups map: rid -> list of opponent roster_ids
        future_opponents: dict[str, list] = {str(r.get("roster_id")): [] for r in rosters}

        for w in range(current_week + 1, FULL_SEASON_WEEKS + 1):
            try:
                week_data = pf_get_matchups(platform, league_id, w, season) or []
            except Exception:
                continue
            if not week_data:
                break
            # Group by matchup_id
            by_mid: dict = {}
            for m in week_data:
                mid = m.get("matchup_id")
                if mid is None:
                    continue
                by_mid.setdefault(mid, []).append(str(m.get("roster_id", "")))
            for mid, rids in by_mid.items():
                if len(rids) == 2:
                    future_opponents[rids[0]].append(rids[1])
                    future_opponents[rids[1]].append(rids[0])

        results = []
        for r in rosters:
            rid = str(r.get("roster_id", ""))
            opp_rids = future_opponents.get(rid, [])
            opp_avgs = [avg_pts_by_rid.get(o, 0.0) for o in opp_rids]
            avg_opp = round(sum(opp_avgs) / len(opp_avgs), 2) if opp_avgs else 0.0
            results.append({
                "roster_id": rid,
                "team_name": roster_map.get(rid, f"Roster {rid}"),
                "games_remaining": len(opp_rids),
                "avg_opp_points": avg_opp,
                "my_avg_points": avg_pts_by_rid.get(rid, 0.0),
            })

        results.sort(key=lambda x: x["avg_opp_points"], reverse=True)

        return jsonify({
            "current_week": current_week,
            "weeks_remaining": max(len(v) for v in future_opponents.values()) if future_opponents else 0,
            "teams": results,
            "using_power_rankings": games_played == 0,
        })

    except Exception:
        logger.exception("[schedule-strength] Unexpected error")
        return jsonify({"error": "Internal error"}), 500


@app.route("/api/playoff-odds")
def api_playoff_odds():
    """
    Run Monte Carlo playoff odds simulation for a league.

    In-season: simulates remaining regular-season games (10 000 runs) using
    each team's historical scoring distribution and returns probabilities.
    Offseason / complete: returns 100 / 0 based on final standings.

    Query params: platform, league_id, season
    """
    platform  = (request.args.get("platform") or "sleeper").strip().lower()
    league_id = (request.args.get("league_id") or "").strip()
    season_s  = (request.args.get("season") or "").strip()

    if not league_id or not season_s:
        return jsonify({"error": "missing params"}), 400
    try:
        season = int(season_s)
    except ValueError:
        return jsonify({"error": "invalid season"}), 400

    try:
        ctx = get_league_ctx_from_cache(platform, league_id, season)
        if not ctx:
            return jsonify({"error": "league not found"}), 404

        from data_building.simulate_playoff_odds import simulate_playoff_odds
        _sim_key2 = (platform, str(league_id), season)
        _sim_cached2 = _PLAYOFF_SIM_CACHE.get(_sim_key2)
        if _sim_cached2 and time.time() - _sim_cached2["ts"] < _PLAYOFF_SIM_CACHE_TTL:
            odds = _sim_cached2["data"]
            _fresh_sim = False
        else:
            odds = simulate_playoff_odds(ctx, platform=platform)
            _PLAYOFF_SIM_CACHE[_sim_key2] = {"data": odds, "ts": time.time()}
            _fresh_sim = True

        settings           = ctx.get("league_settings") or {}
        playoff_week_start = int(settings.get("playoff_week_start") or 15)
        playoff_teams      = int(settings.get("playoff_teams") or 6)
        current_week       = int(ctx.get("current_week") or 0)
        is_complete        = bool(odds and odds[0].get("is_complete"))

        # Week-over-week movement in the odds ranking. Snapshot the current week
        # only when we actually re-ran the sim (throttled by the 1h cache) so the
        # table isn't written on every view; movement itself is a cheap read.
        # Skipped for a finished season (the table shows Made/Missed, not ranks).
        movement: dict = {}
        if not is_complete and current_week >= 1:
            try:
                from dashboard_services.playoff_odds_history import record_and_movement
                movement = record_and_movement(
                    league_id, season, current_week, odds, write=_fresh_sim)
            except Exception:
                logger.debug("[playoff-odds] movement skipped", exc_info=True)

        return jsonify({
            "odds":                odds,
            "movement":            movement,
            "season":              season,
            "current_week":        current_week,
            "playoff_week_start":  playoff_week_start,
            "playoff_teams":       playoff_teams,
            "is_complete":         is_complete,
        })
    except Exception as exc:
        logger.exception("[playoff-odds] %s", exc)
        return jsonify({"error": "Internal error"}), 500


@app.route("/api/playoff-scenarios")
def api_playoff_scenarios():
    """Exact clinch / elimination picture for the final regular-season weeks.

    Complements /api/playoff-odds (probabilities) with the deterministic
    "what do I need" answer: who has clinched, who is eliminated, who controls
    their own destiny, magic numbers, and one-game "win and you're in" swings.
    Enumerates every remaining-game outcome, so it is only exact inside the
    end-of-season window (few enough games); otherwise it returns exact=false
    and the UI falls back to the odds.

    Query params: platform, league_id, season
    """
    platform  = (request.args.get("platform") or "sleeper").strip().lower()
    league_id = (request.args.get("league_id") or "").strip()
    season_s  = (request.args.get("season") or "").strip()

    if not league_id or not season_s:
        return jsonify({"error": "missing params"}), 400
    try:
        season = int(season_s)
    except ValueError:
        return jsonify({"error": "invalid season"}), 400

    try:
        ctx = get_league_ctx_from_cache(platform, league_id, season)
        if not ctx:
            return jsonify({"error": "league not found"}), 404

        from data_building.simulate_playoff_odds import build_sim_state, _n_byes
        from data_building.playoff_scenarios import compute_scenarios, scenario_summary

        settings      = ctx.get("league_settings") or {}
        current_week  = int(ctx.get("current_week") or 0)
        divisions     = int(settings.get("divisions") or 0) >= 2

        state = build_sim_state(ctx, platform)
        if not state:
            # Season complete or no schedule data — no live race to describe.
            return jsonify({
                "exact": False, "reason": "not_in_season",
                "current_week": current_week, "teams": [],
            })

        playoff_teams = int(state.get("playoff_teams") or 6)
        n_byes        = _n_byes(playoff_teams)
        sim_teams     = state.get("teams") or []
        scen_teams    = [
            {"roster_id": t["roster_id"], "wins": t.get("wins", 0),
             "ties": t.get("ties", 0), "pf": t.get("pf", 0.0)}
            for t in sim_teams
        ]
        scen = compute_scenarios(
            scen_teams, state.get("matchups") or {}, playoff_teams,
            n_byes=n_byes, divisions=divisions,
        )

        name_by_rid = {int(t["roster_id"]): t.get("name") for t in sim_teams}
        rec_by_rid  = {int(t["roster_id"]): (t.get("wins", 0), t.get("losses", 0),
                                             t.get("ties", 0)) for t in sim_teams}
        teams_out = []
        for rid, entry in (scen.get("teams") or {}).items():
            w, l, ti = rec_by_rid.get(int(rid), (0, 0, 0))
            teams_out.append({
                "roster_id":   int(rid),
                "name":        name_by_rid.get(int(rid)),
                "record":      f"{w}-{l}" + (f"-{ti}" if ti else ""),
                "summary":     scenario_summary(entry),
                **entry,
            })
        teams_out.sort(key=lambda x: (x.get("best_seed") or 99, x.get("worst_seed") or 99))

        return jsonify({
            "show":           scen.get("show", False),
            "mode":           scen.get("mode"),
            "exact":          scen.get("exact", False),
            "remaining_games": scen.get("remaining_games", 0),
            "remaining_weeks": scen.get("remaining_weeks", 0),
            "playoff_teams":  playoff_teams,
            "n_byes":         n_byes,
            "current_week":   current_week,
            "teams":          teams_out,
        })
    except Exception as exc:
        logger.exception("[playoff-scenarios] %s", exc)
        return jsonify({"error": "Internal error"}), 500


