# ── Shareable trade short URLs (/t/<share_id>) ────────────────────────────────

_SHARE_TABLE_INIT = False

def _init_shared_trades_table():
    global _SHARE_TABLE_INIT
    if _SHARE_TABLE_INIT:
        return
    try:
        from dashboard_services.db import get_conn
        with get_conn() as conn:
            conn.execute("""
                CREATE TABLE IF NOT EXISTS shared_trades (
                    share_id   TEXT PRIMARY KEY,
                    params     TEXT NOT NULL,
                    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
                )
            """)
            conn.commit()
        _SHARE_TABLE_INIT = True
    except Exception as exc:
        logger.warning("[shared_trades] table init failed: %s", exc)


@app.route("/api/save-trade", methods=["POST"])
@limiter.limit("60 per minute")
def api_save_trade():
    """Save trade params; return a short share_id for the /t/<id> short URL."""
    import secrets
    import json as _json
    data   = request.get_json(force=True) or {}
    pi_raw = str(data.get("pi") or "")[:4096]
    params = _json.dumps({
        "a":         data.get("a", ""),
        "b":         data.get("b", ""),
        "ap":        data.get("ap", ""),
        "bp":        data.get("bp", ""),
        "t1":        str(data.get("t1") or "")[:40],
        "t2":        str(data.get("t2") or "")[:40],
        "league_id": str(data.get("league_id") or "")[:64],
        "season":    str(data.get("season") or "")[:8],
        "roster_id": str(data.get("roster_id") or "")[:16],
        "platform":  str(data.get("platform") or "")[:16],
        "pi":        pi_raw,
        "eff_a":     float(data.get("eff_a") or 0),
        "eff_b":     float(data.get("eff_b") or 0),
    })
    share_id = secrets.token_urlsafe(6)
    _init_shared_trades_table()
    try:
        from dashboard_services.db import get_conn
        import random as _random
        with get_conn() as conn:
            conn.execute(
                "INSERT INTO shared_trades (share_id, params) VALUES (%s, %s) "
                "ON CONFLICT (share_id) DO NOTHING",
                (share_id, params),
            )
            # Probabilistic cleanup: prune shares older than 5 days (~10% of saves)
            if _random.random() < 0.10:
                conn.execute(
                    "DELETE FROM shared_trades WHERE created_at < NOW() - INTERVAL '5 days'"
                )
            conn.commit()
    except Exception as exc:
        logger.warning("[save-trade] DB error: %s", exc)
        return jsonify({"error": "Could not save trade"}), 500
    return jsonify({"ok": True, "share_id": share_id})


@app.route("/t/<share_id>")
def shared_trade_page(share_id: str):
    """Redirect a short trade share URL to /trade with its params."""
    _init_shared_trades_table()
    import json as _json
    row = None
    try:
        from dashboard_services.db import get_conn
        with get_conn() as conn:
            row = conn.execute(
                "SELECT params FROM shared_trades WHERE share_id = %s", (share_id,)
            ).fetchone()
    except Exception as _e:
        logger.warning("[shared_trade] lookup error for %s: %s", share_id, _e)
    if not row:
        # Render a friendly page instead of a bare 404
        body = """
        <div style="max-width:520px;margin:60px auto;text-align:center;padding:0 16px;">
          <div style="font-size:48px;margin-bottom:16px;">🏈</div>
          <h2 style="font-size:22px;font-weight:700;margin:0 0 8px;">Trade link not found</h2>
          <p style="color:var(--text-muted);margin:0 0 24px;">This link may have expired or the trade was never saved.</p>
          <a href="/trade" style="display:inline-block;padding:10px 24px;background:var(--accent,#3b82f6);color:#fff;border-radius:8px;text-decoration:none;font-weight:600;">Open Trade Calculator</a>
        </div>"""
        from app import render_page
        return render_page("Trade Not Found | BR Fantasy", None, "trade", body), 404
    try:
        p = _json.loads(row["params"] if hasattr(row, "__getitem__") else row[0])
    except Exception:
        abort(404)
    from urllib.parse import urlencode
    from flask import redirect as _redirect
    # Player/pick params that should always survive the redirect
    _PLAY_KEYS = {"a", "b", "ap", "bp", "t1", "t2", "roster_id"}
    play_qs = urlencode({k: v for k, v in p.items() if k in _PLAY_KEYS and v})
    # If the shared trade has full league context, go straight to the league URL
    # so logged-in users don't hit a second redirect that strips the player params.
    _plt = p.get("platform") or ""
    _lid = p.get("league_id") or ""
    _ssn = p.get("season") or ""
    if _plt and _lid and _ssn:
        return _redirect(f"/{_plt}/{_ssn}/{_lid}/trade?{play_qs}", 302)
    _ALL_KEYS = _PLAY_KEYS | {"league_id", "season", "platform"}
    all_qs = urlencode({k: v for k, v in p.items() if k in _ALL_KEYS and v})
    return _redirect(f"/trade?{all_qs}", 302)


@app.route("/trade-card/<share_id>")
def page_trade_card(share_id: str):
    """Standalone visual trade card for sharing."""
    _init_shared_trades_table()
    import json as _json
    row = None
    try:
        from dashboard_services.db import get_conn
        with get_conn() as conn:
            row = conn.execute(
                "SELECT params, created_at FROM shared_trades WHERE share_id = %s", (share_id,)
            ).fetchone()
    except Exception as _e:
        logger.warning("[trade-card] lookup error for %s: %s", share_id, _e)
    if not row:
        return ("<style>" + _BRAND_FACES_MINI + "</style>"
                "<h2 style='font-family:\"Archivo\",sans-serif;padding:40px'>Trade not found.</h2>"), 404
    try:
        _row = row if hasattr(row, "__getitem__") else {"params": row[0], "created_at": row[1]}
        p = _json.loads(_row["params"])
        _created_at = _row.get("created_at") if hasattr(_row, "get") else row[1]
    except Exception:
        abort(404)

    # Format shared date
    try:
        from datetime import timezone as _tz
        _dt = _created_at
        if hasattr(_dt, "astimezone"):
            _dt = _dt.astimezone(_tz.utc)
        shared_date = _dt.strftime("%-m/%-d/%y") if _dt else ""
    except Exception:
        shared_date = ""

    from utils.utils import load_players_index
    players_index = load_players_index() or {}
    value_table = list(get_model_value_table_cached() or [])
    values_by_id = {str(r["id"]): r for r in value_table if isinstance(r, dict) and r.get("id")}

    # Detect if any team has SF value (best-effort)
    vfield = "value"

    def _fmt_pick(id_str):
        parts = id_str.split("_")
        if len(parts) < 3:
            return id_str.replace("_", " ")
        year = parts[0]
        try:
            rnd = int(parts[1])
        except (ValueError, IndexError):
            return id_str.replace("_", " ")
        third = "_".join(parts[2:])
        sfx = {1: "st", 2: "nd", 3: "rd"}.get(rnd, "th")
        buckets = {"early": "Early", "mid": "Mid", "late": "Late"}
        if third in buckets:
            return f"{year} {rnd}{sfx} ({buckets[third]})"
        try:
            return f"{year} {rnd}.{str(int(third)).zfill(2)}"
        except ValueError:
            return id_str.replace("_", " ")

    def _resolve_players(ids_str):
        result = []
        for pid in (ids_str or "").split(","):
            pid = pid.strip()
            if not pid:
                continue
            meta = players_index.get(pid) or {}
            vrow = values_by_id.get(pid) or {}
            pos = str(meta.get("pos") or vrow.get("position") or "").upper()
            val = float(vrow.get(vfield) or 0)
            result.append({
                "name": meta.get("full_name") or meta.get("name") or pid,
                "pos": pos,
                "val": round(val, 1),
            })
        return result

    def _resolve_picks(ids_str):
        pick_tbl: dict = {}
        try:
            from dashboard_services.picks import load_pick_value_table as _lpvt
            pick_tbl = _lpvt() or {}
        except Exception:
            logger.debug("suppressed exception", exc_info=True)
        result = []
        for pid in (ids_str or "").split(","):
            pid = pid.strip()
            if not pid:
                continue
            val = float(pick_tbl.get(pid) or 0)
            if not val:
                # Try fallback: just year+round without slot
                parts = pid.split("_")
                if len(parts) >= 2:
                    base_key = f"{parts[0]}_{parts[1]}_mid"
                    val = float(pick_tbl.get(base_key) or 0)
            result.append({"name": _fmt_pick(pid), "val": round(val, 1)})
        return result

    pos_colors = {"QB": "#6366f1", "RB": "#10b981", "WR": "#3b82f6", "TE": "#f59e0b"}

    side_a = _resolve_players(p.get("a", ""))
    side_b = _resolve_players(p.get("b", ""))
    picks_a = _resolve_picks(p.get("ap", ""))
    picks_b = _resolve_picks(p.get("bp", ""))

    total_a = sum(pl["val"] for pl in side_a) + sum(pk["val"] for pk in picks_a)
    total_b = sum(pl["val"] for pl in side_b) + sum(pk["val"] for pk in picks_b)
    diff = total_a - total_b

    t1 = p.get("t1") or "Team 1"
    t2 = p.get("t2") or "Team 2"

    def _og_assets(players, picks, limit=2):
        parts = []
        for pl in players[:limit]:
            name = pl["name"]
            # Last name only keeps it short; full name if single word
            words = name.split()
            parts.append(words[-1] if len(words) > 1 else name)
        remaining = limit - len(players)
        for pk in picks[:max(0, remaining)]:
            # Shorten "2028 1st (Mid)" → "2028 1st"
            parts.append(pk["name"].split(" (")[0])
        return " & ".join(parts) if parts else "Assets"
    og_title = f'{_og_assets(side_a, picks_a)} for {_og_assets(side_b, picks_b)} | BR Fantasy Trade'

    # Use depth-adjusted effective totals if saved, otherwise fall back to raw totals
    eff_a = float(p.get("eff_a") or 0) or float(total_a)
    eff_b = float(p.get("eff_b") or 0) or float(total_b)
    eff_diff = eff_a - eff_b

    baseline = max(eff_a, eff_b, 1.0)
    if baseline >= 600:
        _fair_pct = 0.05
    elif baseline >= 300:
        _fair_pct = 0.07
    else:
        _fair_pct = 0.10
    fair_band = max(baseline * _fair_pct, 25.0)

    if abs(eff_diff) <= fair_band:
        verdict = "Fair Trade"
        verdict_color = "#4ade80"
    elif eff_diff > 0:
        pct = round(abs(eff_diff) / max(eff_b, 1) * 100)
        verdict = f"{t1} favored +{abs(eff_diff):.1f} ({pct}%)"
        verdict_color = "#60a5fa"
    else:
        pct = round(abs(eff_diff) / max(eff_a, 1) * 100)
        verdict = f"{t2} favored +{abs(eff_diff):.1f} ({pct}%)"
        verdict_color = "#f97316"
    max_side = max(abs(eff_a), abs(eff_b), 1.0)
    normalized_diff = max(-1.0, min(1.0, eff_diff / max_side))
    # leftPct: 50% = center (fair), <50 = Team 1 favored, >50 = Team 2 favored
    indicator_left = round(((1.0 - normalized_diff) / 2.0) * 100.0, 2)
    fair_zone_width = round(min(100.0, (fair_band / max_side) * 100.0), 2)
    fair_zone_left = round(50.0 - fair_zone_width / 2.0, 2)

    def _asset_html(players, picks):
        rows = []
        for pl in players:
            col = pos_colors.get(pl["pos"], "#64748b")
            pos_tag = (f'<span class="asset-pos" style="background:{col}22;color:{col}">{pl["pos"]}</span>'
                       if pl["pos"] else "")
            val_str = f'{pl["val"]:,.1f}' if pl["val"] else ""
            rows.append(
                f'<div class="asset-row">'
                f'{pos_tag}'
                f'<span class="asset-name">{pl["name"]}</span>'
                f'<span class="asset-val">{val_str}</span>'
                f'</div>'
            )
        for pk in picks:
            pk_val_str = f'{pk["val"]:,.1f}' if pk.get("val") else ""
            rows.append(
                f'<div class="asset-row">'
                f'<span class="asset-pos" style="background:rgba(139,92,246,.2);color:#a78bfa">PICK</span>'
                f'<span class="asset-name">{pk["name"]}</span>'
                f'<span class="asset-val">{pk_val_str}</span>'
                f'</div>'
            )
        if not rows:
            rows.append('<div class="empty-side">No assets</div>')
        return "".join(rows)

    side_a_html = _asset_html(side_a, picks_a)
    side_b_html = _asset_html(side_b, picks_b)
    # Show depth-adjusted totals in headers when available (matches what the calc showed)
    total_a_str = f"{eff_a:,.1f}" if eff_a else (f"{total_a:,.1f}" if total_a else "0")
    total_b_str = f"{eff_b:,.1f}" if eff_b else (f"{total_b:,.1f}" if total_b else "0")
    is_embed = request.args.get('embed') == '1'
    # og=1 is the render mode used by /trade-card/<id>/og.png: a fixed 1200x630
    # dark canvas with the card centered, used to rasterize the social preview.
    is_og = request.args.get('og') == '1'
    if is_og:
        is_embed = True  # hide toolbar/footer chrome for the screenshot
    copy_link_style = 'display:none' if is_embed else ''
    body_pad = '0' if is_embed else '16px'
